INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-1', 'en', 'Bài 1: Giáo dục & Trường học - CEFR C2', 'CEFR C2', 'C2 · Giáo dục', '11 từ vựng Tiếng Anh CEFR C2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6001, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treatise', 'en-c2-1', 'treatise', '/ˈtriːtɪs/', 'C2', 'bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu', 'n.', NULL, 'Đồng nghĩa: dissertation, monograph', 'Thường đi với cụm a treatise on, dùng để chỉ một công trình nghiên cứu hệ thống, chi tiết chứ không phải bài viết ngắn.', 'I found a dusty treatise on gardening upstairs.', NULL, 'Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu.', '{"wordId":"treatise","ukIpa":"/ˈtriːtɪs/","usIpa":"/ˈtriːtɪs/","cefr":"C2","topic":"education","senses":[{"pos":"n.","en":"a long, detailed piece of writing about a particular subject","vi":"bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu"}],"examples":[{"en":"I found a dusty treatise on gardening upstairs.","vi":"Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu.","audioKind":"ex"},{"en":"The philosopher''s treatise on education argues that practical experience should play a central role in learning.","vi":"Cuốn chuyên khảo về giáo dục của triết gia này lập luận rằng kinh nghiệm thực tế nên đóng vai trò cốt lõi trong quá trình học tập.","audioKind":"ex2"}],"collocations":[{"en":"a treatise on","vi":"một bài chuyên khảo về..."},{"en":"write a treatise","vi":"viết một bài chuyên khảo"},{"en":"a philosophical treatise","vi":"một tác phẩm khảo cứu triết học"}],"wordFamily":[],"synonyms":["dissertation","monograph"],"antonyms":[],"tipVi":"Thường đi với cụm a treatise on, dùng để chỉ một công trình nghiên cứu hệ thống, chi tiết chứ không phải bài viết ngắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lexicographer', 'en-c2-1', 'lexicographer', '/ˌleksɪˈkɑːɡrəfər/', 'C2', 'người biên soạn hoặc biên tập từ điển', 'n.', 'lexicography (n.), lexicographic (adj.), lexicographical (adj.)', NULL, 'Chỉ người viết hoặc sửa từ điển, không dùng để chỉ chung các nhà ngôn ngữ học.', 'My aunt works as a lexicographer for a small publisher.', NULL, 'Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ.', '{"wordId":"lexicographer","ukIpa":"/ˌleksɪˈkɒɡrəfə/","usIpa":"/ˌleksɪˈkɑːɡrəfər/","cefr":"C2","topic":"education","senses":[{"pos":"n.","en":"someone who writes or edits dictionaries","vi":"người biên soạn hoặc biên tập từ điển"}],"examples":[{"en":"My aunt works as a lexicographer for a small publisher.","vi":"Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ.","audioKind":"ex"},{"en":"A lexicographer examines authentic language use to ensure that dictionary definitions reflect contemporary meanings accurately.","vi":"Một nhà biên soạn từ điển nghiên cứu việc sử dụng ngôn ngữ thực tế để đảm bảo rằng các định nghĩa trong từ điển phản ánh chính xác ý nghĩa đương đại.","audioKind":"ex2"}],"collocations":[{"en":"work as a lexicographer","vi":"làm việc như một nhà biên soạn từ điển"},{"en":"a team of lexicographers","vi":"một đội ngũ biên soạn từ điển"},{"en":"a bilingual lexicographer","vi":"một nhà biên soạn từ điển song ngữ"}],"wordFamily":["lexicography (n.)","lexicographic (adj.)","lexicographical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người viết hoặc sửa từ điển, không dùng để chỉ chung các nhà ngôn ngữ học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foregoing', 'en-c2-1', 'foregoing', '/ˈfɔːrɡoʊɪŋ/', 'C2', 'được đề cập hoặc trình bày trước đó trong một văn bản', 'adj.', NULL, 'Đồng nghĩa: preceding, aforementioned · Trái nghĩa: following', 'Thuộc văn phong văn bản trang trọng, thường dùng the foregoing để bổ nghĩa cho danh từ đứng sau.', 'The foregoing advice helped me fix my bike.', NULL, 'Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.', '{"wordId":"foregoing","ukIpa":"/ˈfɔːɡəʊɪŋ/","usIpa":"/ˈfɔːrɡoʊɪŋ/","cefr":"C2","topic":"education","senses":[{"pos":"adj.","en":"Mentioned or presented earlier in a piece of writing.","vi":"được đề cập hoặc trình bày trước đó trong một văn bản"}],"examples":[{"en":"The foregoing advice helped me fix my bike.","vi":"Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.","audioKind":"ex"},{"en":"The foregoing analysis suggests that investment in early education can reduce social inequality over time.","vi":"Phân tích trên cho thấy việc đầu tư vào giáo dục mầm non có thể làm giảm bất bình đẳng xã hội theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"the foregoing discussion","vi":"cuộc thảo luận vừa nêu"},{"en":"the foregoing analysis","vi":"phân tích trên đây"},{"en":"the foregoing remarks","vi":"những nhận xét trước đó"}],"wordFamily":[],"synonyms":["preceding","aforementioned"],"antonyms":["following"],"tipVi":"Thuộc văn phong văn bản trang trọng, thường dùng the foregoing để bổ nghĩa cho danh từ đứng sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_componential', 'en-c2-1', 'componential', '/ˌkɑːm.pəˈnen.ʃəl/', 'C2', 'thuộc về thành tố; mang tính phân tích thành phần', 'adj.', 'component (n.)', NULL, 'Tính từ chuyên ngành, phổ biến trong thuật ngữ ngôn ngữ học componential analysis.', 'Our tutor used componential analysis to compare similar words.', NULL, 'Gia sư của chúng tôi đã sử dụng phương pháp phân tích thành phần để so sánh các từ có nghĩa tương tự.', '{"wordId":"componential","ukIpa":"/ˌkɒm.pəˈnen.ʃəl/","usIpa":"/ˌkɑːm.pəˈnen.ʃəl/","cefr":"C2","topic":"education","senses":[{"pos":"adj.","en":"Relating to the separate parts that make up a whole","vi":"thuộc về thành tố; mang tính phân tích thành phần"}],"examples":[{"en":"Our tutor used componential analysis to compare similar words.","vi":"Gia sư của chúng tôi đã sử dụng phương pháp phân tích thành phần để so sánh các từ có nghĩa tương tự.","audioKind":"ex"},{"en":"In linguistics, componential analysis examines word meanings by breaking them down into smaller, shared semantic features.","vi":"Trong ngôn ngữ học, phương pháp phân tích thành phần nghiên cứu nghĩa của từ bằng cách chia nhỏ chúng thành các đặc điểm ngữ nghĩa chung nhỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"componential analysis","vi":"phân tích thành phần nghĩa"},{"en":"componential approach","vi":"tiếp cận theo phân tích thành tố"}],"wordFamily":["component (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ chuyên ngành, phổ biến trong thuật ngữ ngôn ngữ học componential analysis.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rubric', 'en-c2-1', 'rubric', '/ˈruːbrɪk/', 'C2', 'tiêu chí chấm điểm; thang điểm; hướng dẫn làm bài; chỉ dẫn; đề mục; loại', 'n.', NULL, NULL, 'Trong giáo dục, từ này thường chỉ thang điểm hoặc tiêu chí chấm bài, đôi khi dùng để chỉ phần hướng dẫn làm bài thi.', 'Our teacher explained the rubric before we started writing.', NULL, 'Giáo viên đã giải thích các tiêu chí chấm điểm trước khi chúng tôi bắt đầu viết.', '{"wordId":"rubric","ukIpa":"/ˈruːbrɪk/","usIpa":"/ˈruːbrɪk/","cefr":"C2","topic":"education","senses":[{"pos":"n.","en":"A set of criteria used to assess work.","vi":"tiêu chí chấm điểm; thang điểm"},{"pos":"n.","en":"Instructions explaining how to complete a task or examination.","vi":"hướng dẫn làm bài; chỉ dẫn"},{"pos":"n.","en":"A heading or category under which something is grouped.","vi":"đề mục; loại"}],"examples":[{"en":"Our teacher explained the rubric before we started writing.","vi":"Giáo viên đã giải thích các tiêu chí chấm điểm trước khi chúng tôi bắt đầu viết.","audioKind":"ex"},{"en":"A clear assessment rubric helps students understand expectations and enables teachers to grade assignments more consistently.","vi":"Bộ tiêu chí đánh giá rõ ràng giúp học sinh hiểu rõ kỳ vọng và giúp giáo viên chấm bài nhất quán hơn.","audioKind":"ex2"}],"collocations":[{"en":"an assessment rubric","vi":"tiêu chí đánh giá"},{"en":"a scoring rubric","vi":"tiêu chí chấm điểm"},{"en":"under the rubric of","vi":"được xếp vào mục...; quy về loại..."}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong giáo dục, từ này thường chỉ thang điểm hoặc tiêu chí chấm bài, đôi khi dùng để chỉ phần hướng dẫn làm bài thi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herein', 'en-c2-1', 'herein', '/ˌhɪrˈɪn/', 'C2', 'trong tài liệu này; ở đây; trong này', 'adv.', NULL, NULL, 'Thuật ngữ mang tính trang trọng hoặc pháp lý, thường dùng để chỉ "trong văn bản này".', 'The rental rules herein apply to all tenants.', NULL, 'Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.', '{"wordId":"herein","ukIpa":"/ˌhɪərˈɪn/","usIpa":"/ˌhɪrˈɪn/","cefr":"C2","topic":"education","senses":[{"pos":"adv.","en":"In this document, statement, or situation.","vi":"trong tài liệu này; ở đây; trong này"}],"examples":[{"en":"The rental rules herein apply to all tenants.","vi":"Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.","audioKind":"ex"},{"en":"The evidence presented herein suggests that affordable public transport can improve access to employment.","vi":"Bằng chứng được trình bày trong tài liệu này cho thấy hệ thống giao thông công cộng giá rẻ có thể cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"contained herein","vi":"có trong tài liệu này"},{"en":"described herein","vi":"được mô tả trong này"},{"en":"herein lies the problem","vi":"vấn đề nằm ở chỗ đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ mang tính trang trọng hoặc pháp lý, thường dùng để chỉ \"trong văn bản này\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peruse', 'en-c2-1', 'peruse', '/pəˈruːz/', 'C2', 'đọc hoặc xem xét kỹ lưỡng', 'v.', 'perusal (n.)', 'Đồng nghĩa: read, examine, study', 'Từ vựng trang trọng; dùng trực tiếp với đối tượng được đọc, danh từ tương ứng là perusal.', 'Please peruse the rental agreement before you sign it.', NULL, 'Vui lòng đọc kỹ hợp đồng thuê nhà trước khi bạn ký nó.', '{"wordId":"peruse","ukIpa":"/pəˈruːz/","usIpa":"/pəˈruːz/","cefr":"C2","topic":"education","senses":[{"pos":"v.","en":"To read or examine something carefully","vi":"đọc hoặc xem xét kỹ lưỡng"}],"examples":[{"en":"Please peruse the rental agreement before you sign it.","vi":"Vui lòng đọc kỹ hợp đồng thuê nhà trước khi bạn ký nó.","audioKind":"ex"},{"en":"Students should peruse the assessment criteria carefully before preparing their final research projects for submission.","vi":"Sinh viên nên xem xét kỹ các tiêu chuẩn đánh giá trước khi chuẩn bị nộp bài nghiên cứu cuối kỳ.","audioKind":"ex2"}],"collocations":[{"en":"peruse a document","vi":"xem xét tài liệu"},{"en":"peruse a report","vi":"đọc kỹ báo cáo"},{"en":"peruse carefully","vi":"nghiên cứu kỹ lưỡng"}],"wordFamily":["perusal (n.)"],"synonyms":["read","examine","study"],"antonyms":[],"tipVi":"Từ vựng trang trọng; dùng trực tiếp với đối tượng được đọc, danh từ tương ứng là perusal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lexicography', 'en-c2-1', 'lexicography', '/ˌleksɪˈkɑːɡrəfi/', 'C2', 'ngành từ điển học; việc biên soạn từ điển', 'n.', 'lexicographer (n.), lexicographic (adj.), lexicographical (adj.)', NULL, 'Chỉ từ điển học hoặc việc biên soạn từ điển, thường là danh từ không đếm được.', 'My aunt works in lexicography and loves discussing words.', NULL, 'Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ.', '{"wordId":"lexicography","ukIpa":"/ˌleksɪˈkɒɡrəfi/","usIpa":"/ˌleksɪˈkɑːɡrəfi/","cefr":"C2","topic":"education","senses":[{"pos":"n.","en":"The practice or study of writing and editing dictionaries.","vi":"ngành từ điển học; việc biên soạn từ điển"}],"examples":[{"en":"My aunt works in lexicography and loves discussing words.","vi":"Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ.","audioKind":"ex"},{"en":"Digital lexicography allows dictionary editors to track changes in language through large collections of authentic examples.","vi":"Ngành từ điển học kỹ thuật số cho phép các biên tập viên từ điển theo dõi sự thay đổi của ngôn ngữ thông qua các bộ sưu tập lớn các ví dụ thực tế.","audioKind":"ex2"}],"collocations":[{"en":"digital lexicography","vi":"từ điển học kỹ thuật số"},{"en":"practical lexicography","vi":"thực tiễn biên soạn từ điển"},{"en":"a career in lexicography","vi":"sự nghiệp trong ngành từ điển học"}],"wordFamily":["lexicographer (n.)","lexicographic (adj.)","lexicographical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ từ điển học hoặc việc biên soạn từ điển, thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_learned', 'en-c2-1', 'learned', '/ˈlɝːnɪd/', 'C2', 'uy bác; có học thức sâu rộng; mang tính học thuật', 'adj.', 'learn (v.), learner (n.), learning (n.)', 'Đồng nghĩa: scholarly, erudite', 'Đọc thành hai âm tiết khi mang nghĩa "uy bác"; đọc thành một âm tiết khi là dạng quá khứ của learn.', 'Our learned neighbour can explain almost any historical mystery.', NULL, 'Người hàng xóm uy bác của chúng tôi có thể giải thích hầu như mọi bí ẩn lịch sử.', '{"wordId":"learned","ukIpa":"/ˈlɜːnɪd/","usIpa":"/ˈlɝːnɪd/","cefr":"C2","topic":"education","senses":[{"pos":"adj.","en":"having or showing knowledge gained through extensive study","vi":"uy bác; có học thức sâu rộng; mang tính học thuật"}],"examples":[{"en":"Our learned neighbour can explain almost any historical mystery.","vi":"Người hàng xóm uy bác của chúng tôi có thể giải thích hầu như mọi bí ẩn lịch sử.","audioKind":"ex"},{"en":"Learned societies play an important role in sharing research findings and encouraging debate across academic disciplines.","vi":"Các hội học thuật đóng vai trò quan trọng trong việc chia sẻ kết quả nghiên cứu và thúc đẩy tranh luận giữa các ngành học.","audioKind":"ex2"}],"collocations":[{"en":"a learned scholar","vi":"một học giả uy bác"},{"en":"a learned society","vi":"hội học thuật"},{"en":"a learned journal","vi":"tạp chí chuyên khảo học thuật"}],"wordFamily":["learn (v.)","learner (n.)","learning (n.)"],"synonyms":["scholarly","erudite"],"antonyms":[],"tipVi":"Đọc thành hai âm tiết khi mang nghĩa \"uy bác\"; đọc thành một âm tiết khi là dạng quá khứ của learn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antonymous', 'en-c2-1', 'antonymous', '/ænˈtɑːnɪməs/', 'C2', 'trái nghĩa; có nghĩa đối lập', 'adj.', 'antonym (n.), antonymy (n.)', 'Trái nghĩa: synonymous', 'Đây là thuật ngữ ngôn ngữ học, trong đời thường người ta thường nói opposite in meaning hơn.', 'Our teacher used pictures to explain several antonymous pairs.', NULL, 'Giáo viên của chúng tôi đã dùng tranh ảnh để giải thích vài cặp từ trái nghĩa.', '{"wordId":"antonymous","ukIpa":"/ænˈtɒnɪməs/","usIpa":"/ænˈtɑːnɪməs/","cefr":"C2","topic":"education","senses":[{"pos":"adj.","en":"Having opposite meanings, as two words do.","vi":"trái nghĩa; có nghĩa đối lập"}],"examples":[{"en":"Our teacher used pictures to explain several antonymous pairs.","vi":"Giáo viên của chúng tôi đã dùng tranh ảnh để giải thích vài cặp từ trái nghĩa.","audioKind":"ex"},{"en":"Learning antonymous adjectives together can help language students distinguish contrasting meanings and expand their descriptive vocabulary.","vi":"Việc học các tính từ trái nghĩa cùng nhau có thể giúp học viên ngoại ngữ phân biệt các ý nghĩa đối lập và mở rộng vốn từ vựng miêu tả.","audioKind":"ex2"}],"collocations":[{"en":"antonymous pairs","vi":"cặp từ trái nghĩa"},{"en":"antonymous adjectives","vi":"tính từ trái nghĩa"},{"en":"antonymous meanings","vi":"ý nghĩa trái ngược"}],"wordFamily":["antonym (n.)","antonymy (n.)"],"synonyms":[],"antonyms":["synonymous"],"tipVi":"Đây là thuật ngữ ngôn ngữ học, trong đời thường người ta thường nói opposite in meaning hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coinage', 'en-c2-1', 'coinage', '/ˈkɔɪnɪdʒ/', 'C2', 'từ mới sáng tạo; việc đặt từ mới; tiền xu; việc đúc tiền', 'n.', 'coin (n.), coin (v.)', NULL, 'Chỉ một từ mới sáng tạo thì đếm được; chỉ quá trình đặt từ hoặc đúc tiền thì không đếm được.', 'Her playful coinage quickly became popular among her friends.', NULL, 'Từ mới đầy tính sáng tạo của cô ấy nhanh chóng trở nên phổ biến trong số bạn bè.', '{"wordId":"coinage","ukIpa":"/ˈkɔɪnɪdʒ/","usIpa":"/ˈkɔɪnɪdʒ/","cefr":"C2","topic":"education","senses":[{"pos":"n.","en":"a newly invented word, or the creation of new words","vi":"từ mới sáng tạo; việc đặt từ mới"},{"pos":"n.","en":"coins used in a country, or the process of making them","vi":"tiền xu; việc đúc tiền"}],"examples":[{"en":"Her playful coinage quickly became popular among her friends.","vi":"Từ mới đầy tính sáng tạo của cô ấy nhanh chóng trở nên phổ biến trong số bạn bè.","audioKind":"ex"},{"en":"The rapid growth of digital technology encourages the coinage of terms for previously unfamiliar experiences.","vi":"Sự phát triển nhanh chóng của công nghệ kỹ thuật số khuyến khích việc tạo ra các thuật ngữ mới để mô tả những trải nghiệm trước đây vốn xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"a recent coinage","vi":"một từ mới gần đây"},{"en":"the coinage of new words","vi":"sự sáng tạo từ mới"},{"en":"decimal coinage","vi":"hệ thống tiền tệ thập phân"}],"wordFamily":["coin (n.)","coin (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ một từ mới sáng tạo thì đếm được; chỉ quá trình đặt từ hoặc đúc tiền thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_1_1', 'en-c2-1', 'Cách dùng “treatise” (n.) — bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu', 'a treatise on  ·  write a treatise  ·  a philosophical treatise', 'Thường đi với cụm a treatise on, dùng để chỉ một công trình nghiên cứu hệ thống, chi tiết chứ không phải bài viết ngắn.', 'Đồng nghĩa: dissertation, monograph', '[{"hanzi":"I found a dusty treatise on gardening upstairs.","pinyin":"","meaning":"Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu."},{"hanzi":"The philosopher''s treatise on education argues that practical experience should play a central role in learning.","pinyin":"","meaning":"Cuốn chuyên khảo về giáo dục của triết gia này lập luận rằng kinh nghiệm thực tế nên đóng vai trò cốt lõi trong quá trình học tập."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_1_2', 'en-c2-1', 'Cách dùng “rubric” (n.) — tiêu chí chấm điểm; thang điểm', 'an assessment rubric  ·  a scoring rubric  ·  under the rubric of', 'Trong giáo dục, từ này thường chỉ thang điểm hoặc tiêu chí chấm bài, đôi khi dùng để chỉ phần hướng dẫn làm bài thi.', NULL, '[{"hanzi":"Our teacher explained the rubric before we started writing.","pinyin":"","meaning":"Giáo viên đã giải thích các tiêu chí chấm điểm trước khi chúng tôi bắt đầu viết."},{"hanzi":"A clear assessment rubric helps students understand expectations and enables teachers to grade assignments more consistently.","pinyin":"","meaning":"Bộ tiêu chí đánh giá rõ ràng giúp học sinh hiểu rõ kỳ vọng và giúp giáo viên chấm bài nhất quán hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_1_3', 'en-c2-1', 'Cách dùng “learned” (adj.) — uy bác; có học thức sâu rộng; mang tính học thuật', 'a learned scholar  ·  a learned society  ·  a learned journal', 'Đọc thành hai âm tiết khi mang nghĩa "uy bác"; đọc thành một âm tiết khi là dạng quá khứ của learn.', 'Họ từ (Word Family): learn (v.), learner (n.), learning (n.) | Đồng nghĩa: scholarly, erudite', '[{"hanzi":"Our learned neighbour can explain almost any historical mystery.","pinyin":"","meaning":"Người hàng xóm uy bác của chúng tôi có thể giải thích hầu như mọi bí ẩn lịch sử."},{"hanzi":"Learned societies play an important role in sharing research findings and encouraging debate across academic disciplines.","pinyin":"","meaning":"Các hội học thuật đóng vai trò quan trọng trong việc chia sẻ kết quả nghiên cứu và thúc đẩy tranh luận giữa các ngành học."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_1_4', 'en-c2-1', 'Cách dùng “foregoing” (adj.) — được đề cập hoặc trình bày trước đó trong một văn bản', 'the foregoing discussion  ·  the foregoing analysis  ·  the foregoing remarks', 'Thuộc văn phong văn bản trang trọng, thường dùng the foregoing để bổ nghĩa cho danh từ đứng sau.', 'Đồng nghĩa: preceding, aforementioned · Trái nghĩa: following', '[{"hanzi":"The foregoing advice helped me fix my bike.","pinyin":"","meaning":"Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình."},{"hanzi":"The foregoing analysis suggests that investment in early education can reduce social inequality over time.","pinyin":"","meaning":"Phân tích trên cho thấy việc đầu tư vào giáo dục mầm non có thể làm giảm bất bình đẳng xã hội theo thời gian."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_1_1', 'en-c2-1', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_1', 'ten_c2_1_1', 'treatise', 'I found a dusty treatise on gardening upstairs.', 'I found a dusty treatise on gardening upstairs.', '/ˈtriːtɪs/', 'Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_2', 'ten_c2_1_1', 'lexicographer', 'My aunt works as a lexicographer for a small publisher.', 'My aunt works as a lexicographer for a small publisher.', '/ˌleksɪˈkɑːɡrəfər/', 'Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_3', 'ten_c2_1_1', 'foregoing', 'The foregoing advice helped me fix my bike.', 'The foregoing advice helped me fix my bike.', '/ˈfɔːrɡoʊɪŋ/', 'Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_4', 'ten_c2_1_1', 'componential', 'Our tutor used componential analysis to compare similar words.', 'Our tutor used componential analysis to compare similar words.', '/ˌkɑːm.pəˈnen.ʃəl/', 'Gia sư của chúng tôi đã sử dụng phương pháp phân tích thành phần để so sánh các từ có nghĩa tương tự.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_5', 'ten_c2_1_1', 'rubric', 'Our teacher explained the rubric before we started writing.', 'Our teacher explained the rubric before we started writing.', '/ˈruːbrɪk/', 'Giáo viên đã giải thích các tiêu chí chấm điểm trước khi chúng tôi bắt đầu viết.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_6', 'ten_c2_1_1', 'herein', 'The rental rules herein apply to all tenants.', 'The rental rules herein apply to all tenants.', '/ˌhɪrˈɪn/', 'Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
