INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_1_8', 'ten_c2_1_1', 'lexicography', 'My aunt works in lexicography and loves discussing words.', 'My aunt works in lexicography and loves discussing words.', '/ˌleksɪˈkɑːɡrəfi/', 'Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_1_1_1', 'en-c2-1', 'ten_c2_1_1', 'listening', 'listening', 'I found a dusty treatise on gardening upstairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ.","Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu.","Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.","Giáo viên của chúng tôi đã dùng tranh ảnh để giải thích vài cặp từ trái nghĩa."]'::jsonb, 1, 'I found a dusty treatise on gardening upstairs. → Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_1_1_2', 'en-c2-1', 'ten_c2_1_1', 'listening', 'listening', 'My aunt works as a lexicographer for a small publisher.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Từ mới đầy tính sáng tạo của cô ấy nhanh chóng trở nên phổ biến trong số bạn bè.","Giáo viên của chúng tôi đã dùng tranh ảnh để giải thích vài cặp từ trái nghĩa.","Người hàng xóm uy bác của chúng tôi có thể giải thích hầu như mọi bí ẩn lịch sử.","Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ."]'::jsonb, 3, 'My aunt works as a lexicographer for a small publisher. → Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_1_1_3', 'en-c2-1', 'ten_c2_1_1', 'listening', 'listening', 'The foregoing advice helped me fix my bike.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.","Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.","Vui lòng đọc kỹ hợp đồng thuê nhà trước khi bạn ký nó.","Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu."]'::jsonb, 0, 'The foregoing advice helped me fix my bike. → Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_1_2', 'en-c2-1', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_2_1', 'ten_c2_1_2', 'treatise', 'The philosopher''s treatise on education argues that practical experience should play a central role in learning.', 'The philosopher''s treatise on education argues that practical experience should play a central role in learning.', '/ˈtriːtɪs/', 'Cuốn chuyên khảo về giáo dục của triết gia này lập luận rằng kinh nghiệm thực tế nên đóng vai trò cốt lõi trong quá trình học tập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_2_2', 'ten_c2_1_2', 'lexicographer', 'A lexicographer examines authentic language use to ensure that dictionary definitions reflect contemporary meanings accurately.', 'A lexicographer examines authentic language use to ensure that dictionary definitions reflect contemporary meanings accurately.', '/ˌleksɪˈkɑːɡrəfər/', 'Một nhà biên soạn từ điển nghiên cứu việc sử dụng ngôn ngữ thực tế để đảm bảo rằng các định nghĩa trong từ điển phản ánh chính xác ý nghĩa đương đại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_2_3', 'ten_c2_1_2', 'foregoing', 'The foregoing analysis suggests that investment in early education can reduce social inequality over time.', 'The foregoing analysis suggests that investment in early education can reduce social inequality over time.', '/ˈfɔːrɡoʊɪŋ/', 'Phân tích trên cho thấy việc đầu tư vào giáo dục mầm non có thể làm giảm bất bình đẳng xã hội theo thời gian.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_2_4', 'ten_c2_1_2', 'componential', 'In linguistics, componential analysis examines word meanings by breaking them down into smaller, shared semantic features.', 'In linguistics, componential analysis examines word meanings by breaking them down into smaller, shared semantic features.', '/ˌkɑːm.pəˈnen.ʃəl/', 'Trong ngôn ngữ học, phương pháp phân tích thành phần nghiên cứu nghĩa của từ bằng cách chia nhỏ chúng thành các đặc điểm ngữ nghĩa chung nhỏ hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_2_5', 'ten_c2_1_2', 'rubric', 'A clear assessment rubric helps students understand expectations and enables teachers to grade assignments more consistently.', 'A clear assessment rubric helps students understand expectations and enables teachers to grade assignments more consistently.', '/ˈruːbrɪk/', 'Bộ tiêu chí đánh giá rõ ràng giúp học sinh hiểu rõ kỳ vọng và giúp giáo viên chấm bài nhất quán hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_1_2_6', 'ten_c2_1_2', 'herein', 'The evidence presented herein suggests that affordable public transport can improve access to employment.', 'The evidence presented herein suggests that affordable public transport can improve access to employment.', '/ˌhɪrˈɪn/', 'Bằng chứng được trình bày trong tài liệu này cho thấy hệ thống giao thông công cộng giá rẻ có thể cải thiện khả năng tiếp cận việc làm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_1_2_1', 'en-c2-1', 'ten_c2_1_2', 'listening', 'listening', 'The philosopher''s treatise on education argues that practical experience should play a central role in learning.', NULL, 'Trong câu vừa nghe, từ “treatise” mang nghĩa nào sau đây?', '["nguyên tố ra-đi; chất ra-đi","bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu","chuyển tải; trung chuyển hàng hóa","đã nói ở trên; kể trên; trước đó"]'::jsonb, 1, '“treatise” (/ˈtriːtɪs/): bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu. Câu đầy đủ: The philosopher''s treatise on education argues that practical experience should play a central role in learning.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_1_2_2', 'en-c2-1', 'ten_c2_1_2', 'listening', 'listening', 'A lexicographer examines authentic language use to ensure that dictionary definitions reflect contemporary meanings accurately.', NULL, 'Trong câu vừa nghe, từ “lexicographer” mang nghĩa nào sau đây?', '["vui vẻ; hoạt bát","ảo tưởng; đánh lừa; làm sai lệch thực tế","người biên soạn hoặc biên tập từ điển","nhão; mềm nhão (cơ bắp)"]'::jsonb, 2, '“lexicographer” (/ˌleksɪˈkɑːɡrəfər/): người biên soạn hoặc biên tập từ điển. Câu đầy đủ: A lexicographer examines authentic language use to ensure that dictionary definitions reflect contemporary meanings accurately.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
