INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_1', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'treatise', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự đền bù; thù lao","bản sao chính xác; bản in y hệt","bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu","đã nói ở trên; kể trên; trước đó"]'::jsonb, 2, 'treatise (/ˈtriːtɪs/) → bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_2', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'My aunt works as a lexicographer for a small publisher.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ.","Giáo viên đã giải thích các tiêu chí chấm điểm trước khi chúng tôi bắt đầu viết.","Những lời khuyên vừa rồi đã giúp tôi sửa chiếc xe đạp của mình.","Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu."]'::jsonb, 0, 'My aunt works as a lexicographer for a small publisher. → Dì của tôi làm nghề biên soạn từ điển cho một nhà xuất bản nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_3', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'foregoing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["được đề cập hoặc trình bày trước đó trong một văn bản","không thể đảo ngược; không thể thay đổi hoặc rút lại","cưng chiều; âu yếm; chăm sóc quá kỹ","trong tài liệu này; ở đây; trong này"]'::jsonb, 0, 'foregoing (/ˈfɔːrɡoʊɪŋ/) → được đề cập hoặc trình bày trước đó trong một văn bản', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_4', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'Our tutor used componential analysis to compare similar words.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người hàng xóm uy bác của chúng tôi có thể giải thích hầu như mọi bí ẩn lịch sử.","Từ mới đầy tính sáng tạo của cô ấy nhanh chóng trở nên phổ biến trong số bạn bè.","Tôi tìm thấy một cuốn sách chuyên khảo về làm vườn đã bám đầy bụi ở trên lầu.","Gia sư của chúng tôi đã sử dụng phương pháp phân tích thành phần để so sánh các từ có nghĩa tương tự."]'::jsonb, 3, 'Our tutor used componential analysis to compare similar words. → Gia sư của chúng tôi đã sử dụng phương pháp phân tích thành phần để so sánh các từ có nghĩa tương tự.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_5', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'rubric', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["uốn lượn; nhấp nhô; dập dờn","tiêu chí chấm điểm; thang điểm","đồ đạc lỉnh kỉnh, toàn bộ dụng cụ cần thiết cho một hoạt động cụ thể","sự tiếp tục; sự duy trì"]'::jsonb, 1, 'rubric (/ˈruːbrɪk/) → tiêu chí chấm điểm; thang điểm; hướng dẫn làm bài; chỉ dẫn; đề mục; loại', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_6', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'The rental rules herein apply to all tenants.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.","Giáo viên đã giải thích các tiêu chí chấm điểm trước khi chúng tôi bắt đầu viết.","Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ.","Từ mới đầy tính sáng tạo của cô ấy nhanh chóng trở nên phổ biến trong số bạn bè."]'::jsonb, 0, 'The rental rules herein apply to all tenants. → Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_7', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'peruse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bọc nệm ghế; làm ghế nệm","lan tỏa; bao trùm; thấm đượm khắp nơi","đọc hoặc xem xét kỹ lưỡng","sự tiếp tục; sự duy trì"]'::jsonb, 2, 'peruse (/pəˈruːz/) → đọc hoặc xem xét kỹ lưỡng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_8', 'en-c2-1', NULL, 'comprehensive_test', 'listening', 'My aunt works in lexicography and loves discussing words.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vui lòng đọc kỹ hợp đồng thuê nhà trước khi bạn ký nó.","Các quy định cho thuê nhà trong văn bản này áp dụng cho tất cả người thuê.","Gia sư của chúng tôi đã sử dụng phương pháp phân tích thành phần để so sánh các từ có nghĩa tương tự.","Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ."]'::jsonb, 3, 'My aunt works in lexicography and loves discussing words. → Cô tôi làm việc trong ngành biên soạn từ điển và rất thích thảo luận về các từ ngữ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
