INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_18', 'en-c2-1', NULL, 'comprehensive_test', 'reading', NULL, 'The philosopher''s treatise on education argues that practical experience should play a central role in learning.', 'Dựa vào câu trên, từ “treatise” có nghĩa phù hợp nhất là gì?', '["bao quanh; lượn lờ; bao phủ","rùng rợn; kinh dị (do có liên quan đến cái chết)","cần thiết; thiết yếu","bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu"]'::jsonb, 3, 'treatise: bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu. Dịch cả câu: Cuốn chuyên khảo về giáo dục của triết gia này lập luận rằng kinh nghiệm thực tế nên đóng vai trò cốt lõi trong quá trình học tập.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_19', 'en-c2-1', NULL, 'comprehensive_test', 'reading', NULL, 'A lexicographer examines authentic language use to ensure that dictionary definitions reflect contemporary meanings accurately.', 'Dựa vào câu trên, từ “lexicographer” có nghĩa phù hợp nhất là gì?', '["vươn; vắt; ép (nhất là để loại bỏ nước)","trả thù; rửa hận; phục thù","tiêu chí chấm điểm; thang điểm","người biên soạn hoặc biên tập từ điển"]'::jsonb, 3, 'lexicographer: người biên soạn hoặc biên tập từ điển. Dịch cả câu: Một nhà biên soạn từ điển nghiên cứu việc sử dụng ngôn ngữ thực tế để đảm bảo rằng các định nghĩa trong từ điển phản ánh chính xác ý nghĩa đương đại.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_20', 'en-c2-1', NULL, 'comprehensive_test', 'reading', NULL, 'The foregoing analysis suggests that investment in early education can reduce social inequality over time.', 'Dựa vào câu trên, từ “foregoing” có nghĩa phù hợp nhất là gì?', '["được đề cập hoặc trình bày trước đó trong một văn bản","làm phấn chấn; làm hưng phấn; làm vui sướng","gây thiệt hại nặng nề; phá sản","đồng ý; ưng thuận (đề nghị, yêu cầu)"]'::jsonb, 0, 'foregoing: được đề cập hoặc trình bày trước đó trong một văn bản. Dịch cả câu: Phân tích trên cho thấy việc đầu tư vào giáo dục mầm non có thể làm giảm bất bình đẳng xã hội theo thời gian.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_21', 'en-c2-1', NULL, 'comprehensive_test', 'reading', NULL, 'In linguistics, componential analysis examines word meanings by breaking them down into smaller, shared semantic features.', 'Dựa vào câu trên, từ “componential” có nghĩa phù hợp nhất là gì?', '["xen kẽ, điểm xuyết, rải rác những thứ khác vào khoảng giữa","thuộc về thành tố; mang tính phân tích thành phần","trơn trượt; trườn uốn lượn","dẻo quánh; dính"]'::jsonb, 1, 'componential: thuộc về thành tố; mang tính phân tích thành phần. Dịch cả câu: Trong ngôn ngữ học, phương pháp phân tích thành phần nghiên cứu nghĩa của từ bằng cách chia nhỏ chúng thành các đặc điểm ngữ nghĩa chung nhỏ hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_22', 'en-c2-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “uy bác; có học thức sâu rộng; mang tính học thuật”', '["learned","delusive","foregoing","telefax"]'::jsonb, 0, 'uy bác; có học thức sâu rộng; mang tính học thuật → learned (/ˈlɝːnɪd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_23', 'en-c2-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trái nghĩa; có nghĩa đối lập”', '["therewith","antonymous","tetrad","ostensible"]'::jsonb, 1, 'trái nghĩa; có nghĩa đối lập → antonymous (/ænˈtɑːnɪməs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_1_24', 'en-c2-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “từ mới sáng tạo; việc đặt từ mới”', '["reflexion","coinage","ingenuous","malleable"]'::jsonb, 1, 'từ mới sáng tạo; việc đặt từ mới → coinage (/ˈkɔɪnɪdʒ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-2', 'en', 'Bài 2: Xã hội & Cộng đồng (1) - CEFR C2', 'CEFR C2', 'C2 · Xã hội', '19 từ vựng Tiếng Anh CEFR C2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6002, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bestow', 'en-c2-2', 'bestow', '/bɪˈstoʊ/', 'C2', 'ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)', 'v.', 'bestowal (n.)', 'Đồng nghĩa: confer, grant', 'Đây là từ trang trọng, đi theo cấu trúc: bestow sth on/upon sb.', 'The club bestowed a special award on our coach.', NULL, 'Câu lạc bộ đã trao một giải thưởng đặc biệt cho huấn luyện viên của chúng tôi.', '{"wordId":"bestow","ukIpa":"/bɪˈstəʊ/","usIpa":"/bɪˈstoʊ/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To formally give someone an honour, gift, or benefit.","vi":"ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)"}],"examples":[{"en":"The club bestowed a special award on our coach.","vi":"Câu lạc bộ đã trao một giải thưởng đặc biệt cho huấn luyện viên của chúng tôi.","audioKind":"ex"},{"en":"Universities often bestow honorary degrees on individuals who have made outstanding contributions to society.","vi":"Các trường đại học thường trao học vị danh dự cho những cá nhân đã có đóng góp xuất sắc cho xã hội.","audioKind":"ex2"}],"collocations":[{"en":"bestow an honour on","vi":"trao tặng vinh dự cho"},{"en":"bestow a gift on","vi":"ban tặng quà cho"},{"en":"bestow a title upon","vi":"phong tước hiệu cho"}],"wordFamily":["bestowal (n.)"],"synonyms":["confer","grant"],"antonyms":[],"tipVi":"Đây là từ trang trọng, đi theo cấu trúc: bestow sth on/upon sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deplore', 'en-c2-2', 'deplore', '/dɪˈplɔːr/', 'C2', 'kịch liệt phản đối; vô cùng đau xót', 'v.', 'deplorable (adj.), deplorably (adv.)', 'Đồng nghĩa: condemn, lament · Trái nghĩa: approve', 'Đây là ngoại động từ trang trọng, đi trực tiếp với sự việc bị lên án hoặc tiếc nuối.', 'Our neighbours deplore the dumping of rubbish beside the river.', NULL, 'Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.', '{"wordId":"deplore","ukIpa":"/dɪˈplɔː/","usIpa":"/dɪˈplɔːr/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To strongly disapprove of something or deeply regret it","vi":"kịch liệt phản đối; vô cùng đau xót"}],"examples":[{"en":"Our neighbours deplore the dumping of rubbish beside the river.","vi":"Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.","audioKind":"ex"},{"en":"Many educators deplore funding cuts that limit access to music and art lessons in public schools.","vi":"Nhiều nhà giáo dục kịch liệt phản đối việc cắt giảm ngân sách vốn làm hạn chế cơ hội tiếp cận các bài học âm nhạc và mỹ thuật tại các trường công lập.","audioKind":"ex2"}],"collocations":[{"en":"deplore violence","vi":"kịch liệt lên án bạo lực"},{"en":"deplore the lack of","vi":"vô cùng tiếc nuối vì thiếu vắng..."},{"en":"deplore the decision","vi":"kịch liệt phản đối quyết định"}],"wordFamily":["deplorable (adj.)","deplorably (adv.)"],"synonyms":["condemn","lament"],"antonyms":["approve"],"tipVi":"Đây là ngoại động từ trang trọng, đi trực tiếp với sự việc bị lên án hoặc tiếc nuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nicety', 'en-c2-2', 'nicety', '/ˈnaɪsəti/', 'C2', 'chi tiết tinh vi; điểm tế nhị; phép tắc xã giao; quy tắc lịch sự', 'n.', 'nice (adj.), nicely (adv.)', 'Đồng nghĩa: subtlety, fine point', 'Thường dùng ở dạng số nhiều niceties, không nên dịch đơn thuần là "điều hay đẹp".', 'I am still learning the niceties of formal dining.', NULL, 'Tôi vẫn đang học các quy tắc ứng xử trong những bữa tiệc trang trọng.', '{"wordId":"nicety","ukIpa":"/ˈnaɪsəti/","usIpa":"/ˈnaɪsəti/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"A small detail or distinction requiring careful understanding","vi":"chi tiết tinh vi; điểm tế nhị"},{"pos":"n.","en":"A small convention of polite social behaviour","vi":"phép tắc xã giao; quy tắc lịch sự"}],"examples":[{"en":"I am still learning the niceties of formal dining.","vi":"Tôi vẫn đang học các quy tắc ứng xử trong những bữa tiệc trang trọng.","audioKind":"ex"},{"en":"Understanding the niceties of legal language is essential when translating international agreements that affect trade and environmental protection.","vi":"Việc hiểu rõ những sắc thái tinh tế của ngôn ngữ pháp lý là điều cốt yếu khi dịch các hiệp định quốc tế ảnh hưởng đến thương mại và bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"the niceties of","vi":"các chi tiết tinh tế của..."},{"en":"social niceties","vi":"phép tắc giao tiếp xã hội"},{"en":"legal niceties","vi":"sự khác biệt tinh tế về mặt pháp lý"},{"en":"to a nicety","vi":"một cách hoàn hảo; chính xác đến từng chi tiết"}],"wordFamily":["nice (adj.)","nicely (adv.)"],"synonyms":["subtlety","fine point"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều niceties, không nên dịch đơn thuần là \"điều hay đẹp\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pervert', 'en-c2-2', 'pervert', '/pɚˈvɝːt/', 'C2', 'bóp méo; xuyên tạc; làm bại hoại', 'v.', 'perversion (n.), perverted (adj.)', 'Đồng nghĩa: distort, corrupt', 'Trọng âm ở động từ rơi vào âm tiết thứ hai; nếu là danh từ, trọng âm ở âm tiết đầu và thường mang nghĩa tiêu cực.', 'The coach perverted fair competition by secretly changing the rules.', NULL, 'Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc.', '{"wordId":"pervert","ukIpa":"/pəˈvɜːt/","usIpa":"/pɚˈvɝːt/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"to distort something good or proper for harmful purposes","vi":"bóp méo; xuyên tạc; làm bại hoại"}],"examples":[{"en":"The coach perverted fair competition by secretly changing the rules.","vi":"Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc.","audioKind":"ex"},{"en":"Political pressure can pervert scientific research when funding depends on producing results that support existing policies.","vi":"Áp lực chính trị có thể bóp méo nghiên cứu khoa học khi nguồn kinh phí phụ thuộc vào việc tạo ra kết quả ủng hộ các chính sách hiện hành.","audioKind":"ex2"}],"collocations":[{"en":"pervert the course of justice","vi":"cản trở công lý; làm sai lệch hướng đi của công lý"},{"en":"pervert the truth","vi":"xuyên tạc sự thật"}],"wordFamily":["perversion (n.)","perverted (adj.)"],"synonyms":["distort","corrupt"],"antonyms":[],"tipVi":"Trọng âm ở động từ rơi vào âm tiết thứ hai; nếu là danh từ, trọng âm ở âm tiết đầu và thường mang nghĩa tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_virile', 'en-c2-2', 'virile', '/ˈvɪrəl/', 'C2', 'có khí phách đàn ông; cường tráng; mạnh mẽ', 'adj.', 'virility (n.)', 'Đồng nghĩa: masculine, manly', 'Không chỉ có nghĩa là "thuộc về nam giới"; từ này nhấn mạnh sức mạnh và sự năng động truyền thống của phái mạnh.', 'The sculpture portrays a virile athlete lifting a discus.', NULL, 'Bức tượng khắc họa một vận động viên vạm vỡ đang vung đĩa tạ.', '{"wordId":"virile","ukIpa":"/ˈvɪraɪl/","usIpa":"/ˈvɪrəl/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"showing strength and energy traditionally associated with men","vi":"có khí phách đàn ông; cường tráng; mạnh mẽ"}],"examples":[{"en":"The sculpture portrays a virile athlete lifting a discus.","vi":"Bức tượng khắc họa một vận động viên vạm vỡ đang vung đĩa tạ.","audioKind":"ex"},{"en":"Advertisements often present a virile male ideal, which may reinforce narrow expectations about men''s appearance and behaviour.","vi":"Các quảng cáo thường thể hiện hình mẫu nam giới lý tưởng đầy nam tính, điều này có thể củng cố những định kiến hẹp hòi về diện mạo và hành vi của đàn ông.","audioKind":"ex2"}],"collocations":[{"en":"virile image","vi":"hình ảnh nam tính mạnh mẽ"},{"en":"virile young man","vi":"thanh niên cường tráng"},{"en":"virile masculinity","vi":"nam tính vạm vỡ"}],"wordFamily":["virility (n.)"],"synonyms":["masculine","manly"],"antonyms":[],"tipVi":"Không chỉ có nghĩa là \"thuộc về nam giới\"; từ này nhấn mạnh sức mạnh và sự năng động truyền thống của phái mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ostentation', 'en-c2-2', 'ostentation', '/ˌɑːstenˈteɪʃən/', 'C2', 'sự phô trương; sự khoe khoang; tính chưng diện', 'n.', 'ostentatious (adj.), ostentatiously (adv.)', 'Đồng nghĩa: showiness, flashiness · Trái nghĩa: modesty, restraint', 'Là danh từ không đếm được, thường mang nghĩa tiêu cực, nhấn mạnh việc cố tình trưng bày để gây chú ý.', 'Their wedding was warm and cheerful, without any ostentation.', NULL, 'Đám cưới của họ ấm cúng và vui vẻ, hoàn toàn không có sự phô trương nào.', '{"wordId":"ostentation","ukIpa":"/ˌɒstenˈteɪʃən/","usIpa":"/ˌɑːstenˈteɪʃən/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"An excessive display of wealth or importance to impress others.","vi":"sự phô trương; sự khoe khoang; tính chưng diện"}],"examples":[{"en":"Their wedding was warm and cheerful, without any ostentation.","vi":"Đám cưới của họ ấm cúng và vui vẻ, hoàn toàn không có sự phô trương nào.","audioKind":"ex"},{"en":"The ostentation associated with luxury consumption can intensify social pressure to display wealth rather than save responsibly.","vi":"Thói phô trương gắn liền với tiêu dùng xa xỉ có thể làm gia tăng áp lực xã hội, khiến người ta phải trưng diện tài sản thay vì tiết kiệm một cách khôn ngoan.","audioKind":"ex2"}],"collocations":[{"en":"without ostentation","vi":"không phô trương"},{"en":"an air of ostentation","vi":"vẻ phô trương"},{"en":"wealth and ostentation","vi":"sự giàu có và phô trương"}],"wordFamily":["ostentatious (adj.)","ostentatiously (adv.)"],"synonyms":["showiness","flashiness"],"antonyms":["modesty","restraint"],"tipVi":"Là danh từ không đếm được, thường mang nghĩa tiêu cực, nhấn mạnh việc cố tình trưng bày để gây chú ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insolent', 'en-c2-2', 'insolent', '/ˈɪnsələnt/', 'C2', 'hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền', 'adj.', 'insolence (n.), insolently (adv.)', 'Đồng nghĩa: rude, disrespectful, impudent · Trái nghĩa: respectful, polite', 'Thường được dùng làm tính từ trong tiếng hiện đại; danh từ tương ứng là ''insolence''.', 'The waiter remained calm despite the customer''s insolent tone.', NULL, 'Người phục vụ vẫn giữ được bình tĩnh bất chấp thái độ xấc láo của vị khách hàng.', '{"wordId":"insolent","ukIpa":"/ˈɪnsələnt/","usIpa":"/ˈɪnsələnt/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Rude and disrespectful, especially towards someone in authority.","vi":"hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền"}],"examples":[{"en":"The waiter remained calm despite the customer''s insolent tone.","vi":"Người phục vụ vẫn giữ được bình tĩnh bất chấp thái độ xấc láo của vị khách hàng.","audioKind":"ex"},{"en":"Schools should address insolent behaviour firmly while helping students learn respectful ways to express disagreement.","vi":"Các trường học nên kiên quyết xử lý các hành vi vô lễ đồng thời giúp học sinh học cách thể hiện sự bất đồng một cách tôn trọng.","audioKind":"ex2"}],"collocations":[{"en":"insolent behaviour","vi":"hành vi xấc láo"},{"en":"insolent tone","vi":"giọng điệu hỗn láo"},{"en":"insolent reply","vi":"câu trả lời xấc láo"}],"wordFamily":["insolence (n.)","insolently (adv.)"],"synonyms":["rude","disrespectful","impudent"],"antonyms":["respectful","polite"],"tipVi":"Thường được dùng làm tính từ trong tiếng hiện đại; danh từ tương ứng là ''insolence''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jeer', 'en-c2-2', 'jeer', '/dʒɪr/', 'C2', 'la ó, chế nhạo hoặc cười nhạo ai đó theo cách ác ý; tiếng la ó hoặc lời nói ác ý nhằm chế giễu ai đó', 'v.', 'jeering (n.)', 'Đồng nghĩa: mock, taunt, ridicule · Trái nghĩa: cheer', 'Động từ thường đi với cấu trúc ''jeer at someone''; danh từ thường ở dạng số nhiều.', 'A few spectators jeered when the player missed again.', NULL, 'Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.', '{"wordId":"jeer","ukIpa":"/dʒɪə/","usIpa":"/dʒɪr/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To shout or laugh at someone in an unkind way.","vi":"la ó, chế nhạo hoặc cười nhạo ai đó theo cách ác ý"},{"pos":"n.","en":"An unkind shout or remark intended to ridicule someone.","vi":"tiếng la ó hoặc lời nói ác ý nhằm chế giễu ai đó"}],"examples":[{"en":"A few spectators jeered when the player missed again.","vi":"Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.","audioKind":"ex"},{"en":"When spectators jeer at inexperienced players, they create an atmosphere that discourages participation in community sport.","vi":"Khi khán giả la ó những cầu thủ thiếu kinh nghiệm, họ tạo ra một bầu không khí làm nản lòng việc tham gia các hoạt động thể thao cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"jeer at someone","vi":"chế nhạo ai đó"},{"en":"jeers from the crowd","vi":"tiếng la ó từ đám đông"},{"en":"a chorus of jeers","vi":"một tràng tiếng la ó"}],"wordFamily":["jeering (n.)"],"synonyms":["mock","taunt","ridicule"],"antonyms":["cheer"],"tipVi":"Động từ thường đi với cấu trúc ''jeer at someone''; danh từ thường ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furor', 'en-c2-2', 'furor', '/ˈfjʊrɔːr/', 'C2', 'sự phẫn nộ; sự náo động; sự xôn xao', 'n.', NULL, 'Đồng nghĩa: uproar, outcry, commotion', 'Mỹ thường dùng furor, Anh thường dùng furore; thường chỉ phản ứng mạnh mẽ từ công chúng.', 'The sudden closure of the playground caused a furor.', NULL, 'Việc sân chơi đột ngột đóng cửa đã gây ra làn sóng phẫn nộ mạnh mẽ.', '{"wordId":"furor","ukIpa":"/ˈfjʊərɔː/","usIpa":"/ˈfjʊrɔːr/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"A strong public reaction of anger or excitement.","vi":"sự phẫn nộ; sự náo động; sự xôn xao"}],"examples":[{"en":"The sudden closure of the playground caused a furor.","vi":"Việc sân chơi đột ngột đóng cửa đã gây ra làn sóng phẫn nộ mạnh mẽ.","audioKind":"ex"},{"en":"The proposed increase in university fees sparked a furor among students and their families.","vi":"Việc đề xuất tăng học phí đại học đã châm ngòi cho một làn sóng bất bình lớn trong sinh viên và gia đình họ.","audioKind":"ex2"}],"collocations":[{"en":"cause a furor","vi":"gây ra làn sóng phản đối dữ dội"},{"en":"spark a furor","vi":"châm ngòi cho sự phẫn nộ"},{"en":"a furor over something","vi":"một cuộc tranh cãi lớn về vấn đề gì"}],"wordFamily":[],"synonyms":["uproar","outcry","commotion"],"antonyms":[],"tipVi":"Mỹ thường dùng furor, Anh thường dùng furore; thường chỉ phản ứng mạnh mẽ từ công chúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vernacular', 'en-c2-2', 'vernacular', '/vərˈnækjələr/', 'C2', 'tiếng địa phương; ngôn ngữ thường ngày; thuộc tiếng địa phương; mang phong cách bản xứ', 'n.', NULL, NULL, 'Nhấn mạnh ngôn ngữ hàng ngày của địa phương, không đồng nghĩa với "thuộc về quốc gia".', 'Our guide chatted with market traders in the local vernacular.', NULL, 'Hướng dẫn viên của chúng tôi trò chuyện với những tiểu thương ở chợ bằng tiếng địa phương.', '{"wordId":"vernacular","ukIpa":"/vəˈnækjələ/","usIpa":"/vərˈnækjələr/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"The everyday language spoken by people in a particular place.","vi":"tiếng địa phương; ngôn ngữ thường ngày"},{"pos":"adj.","en":"Using local everyday language or traditional local building styles.","vi":"thuộc tiếng địa phương; mang phong cách bản xứ"}],"examples":[{"en":"Our guide chatted with market traders in the local vernacular.","vi":"Hướng dẫn viên của chúng tôi trò chuyện với những tiểu thương ở chợ bằng tiếng địa phương.","audioKind":"ex"},{"en":"Teaching in the vernacular can help young children understand lessons while maintaining connections with their cultural heritage.","vi":"Việc giảng dạy bằng tiếng địa phương có thể giúp trẻ nhỏ hiểu bài học đồng thời duy trì sự gắn kết với di sản văn hóa của các em.","audioKind":"ex2"}],"collocations":[{"en":"the local vernacular","vi":"ngôn ngữ thường ngày ở địa phương"},{"en":"in the vernacular","vi":"bằng tiếng địa phương"},{"en":"vernacular architecture","vi":"kiến trúc bản địa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh ngôn ngữ hàng ngày của địa phương, không đồng nghĩa với \"thuộc về quốc gia\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profane', 'en-c2-2', 'profane', '/prəˈfeɪn/', 'C2', 'báng bổ; xúc phạm thần linh; thô tục; làm ô uế; xúc phạm', 'adj.', 'profanity (n.), profanation (n.)', 'Đồng nghĩa: blasphemous, irreverent', 'Tính từ thường bổ nghĩa cho từ "language"; động từ chỉ hành động báng bổ các sự vật thiêng liêng.', 'The coach apologised for his profane language after the match.', NULL, 'Huấn luyện viên đã xin lỗi vì những lời lẽ thô tục của mình sau trận đấu.', '{"wordId":"profane","ukIpa":"/prəˈfeɪn/","usIpa":"/prəˈfeɪn/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Showing disrespect for religion, or using offensive language.","vi":"báng bổ; xúc phạm thần linh; thô tục"},{"pos":"v.","en":"To treat something sacred with serious disrespect.","vi":"báng bổ; làm ô uế; xúc phạm"}],"examples":[{"en":"The coach apologised for his profane language after the match.","vi":"Huấn luyện viên đã xin lỗi vì những lời lẽ thô tục của mình sau trận đấu.","audioKind":"ex"},{"en":"Museums should explain why objects considered ordinary by outsiders may be sacred, making careless treatment seem profane.","vi":"Các viện bảo tàng nên giải thích lý do tại sao những đồ vật bị người ngoài coi là bình thường lại có thể mang tính linh thiêng, khiến cho việc đối xử bất cẩn trở thành hành vi báng bổ.","audioKind":"ex2"}],"collocations":[{"en":"profane language","vi":"ngôn từ thô tục"},{"en":"profane remarks","vi":"những lời lẽ báng bổ"},{"en":"profane a sacred place","vi":"xúc phạm chốn linh thiêng"}],"wordFamily":["profanity (n.)","profanation (n.)"],"synonyms":["blasphemous","irreverent"],"antonyms":[],"tipVi":"Tính từ thường bổ nghĩa cho từ \"language\"; động từ chỉ hành động báng bổ các sự vật thiêng liêng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_multifarious', 'en-c2-2', 'multifarious', '/ˌmʌltɪˈferiəs/', 'C2', 'đa dạng; phong phú', 'adj.', NULL, 'Đồng nghĩa: diverse, varied, manifold · Trái nghĩa: uniform', 'Từ trang trọng, nhấn mạnh số lượng chủng loại lớn; trong đời thường thường dùng varied hoặc diverse.', 'The market''s multifarious offerings included spices, pottery, and handmade toys.', NULL, 'Các mặt hàng phong phú của khu chợ bao gồm gia vị, đồ gốm và đồ chơi thủ công.', '{"wordId":"multifarious","ukIpa":"/ˌmʌltɪˈfeəriəs/","usIpa":"/ˌmʌltɪˈferiəs/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"having many different kinds or aspects","vi":"đa dạng; phong phú"}],"examples":[{"en":"The market''s multifarious offerings included spices, pottery, and handmade toys.","vi":"Các mặt hàng phong phú của khu chợ bao gồm gia vị, đồ gốm và đồ chơi thủ công.","audioKind":"ex"},{"en":"Urban planners must consider the multifarious needs of residents when designing accessible and inclusive public spaces.","vi":"Các nhà quy hoạch đô thị phải cân nhắc nhu cầu đa dạng của cư dân khi thiết kế các không gian công cộng dễ tiếp cận và bao trùm.","audioKind":"ex2"}],"collocations":[{"en":"multifarious activities","vi":"nhiều hoạt động đa dạng"},{"en":"multifarious needs","vi":"nhu cầu đa dạng"},{"en":"multifarious responsibilities","vi":"trách nhiệm đa dạng, phức tạp"}],"wordFamily":[],"synonyms":["diverse","varied","manifold"],"antonyms":["uniform"],"tipVi":"Từ trang trọng, nhấn mạnh số lượng chủng loại lớn; trong đời thường thường dùng varied hoặc diverse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ingenuous', 'en-c2-2', 'ingenuous', '/ɪnˈdʒenjuəs/', 'C2', 'chân chất; ngây thơ; thật thà', 'adj.', 'ingenuously (adv.), ingenuousness (n.), disingenuous (adj.)', 'Đồng nghĩa: naive, innocent, artless · Trái nghĩa: disingenuous', 'Đừng nhầm lẫn với ingenious (tài tình, khéo léo); từ này nhấn mạnh tính cách chân chất, ngây thơ.', 'Her ingenuous question made everyone smile at the dinner table.', NULL, 'Câu hỏi ngây thơ hồn nhiên của cô ấy làm mọi người bật cười bên bàn ăn.', '{"wordId":"ingenuous","ukIpa":"/ɪnˈdʒenjuəs/","usIpa":"/ɪnˈdʒenjuəs/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Honest and trusting, often through a lack of worldly experience.","vi":"chân chất; ngây thơ; thật thà"}],"examples":[{"en":"Her ingenuous question made everyone smile at the dinner table.","vi":"Câu hỏi ngây thơ hồn nhiên của cô ấy làm mọi người bật cười bên bàn ăn.","audioKind":"ex"},{"en":"An ingenuous belief that technology solves every problem may prevent policymakers from considering its social costs.","vi":"Niềm tin ngây thơ cho rằng công nghệ giải quyết được mọi vấn đề có thể ngăn cản các nhà hoạch định chính sách nhìn nhận các chi phí xã hội của nó.","audioKind":"ex2"}],"collocations":[{"en":"an ingenuous smile","vi":"nụ cười trong sáng ngây thơ"},{"en":"an ingenuous question","vi":"câu hỏi ngây thơ chân chất"},{"en":"ingenuous optimism","vi":"sự lạc quan ngây thơ"}],"wordFamily":["ingenuously (adv.)","ingenuousness (n.)","disingenuous (adj.)"],"synonyms":["naive","innocent","artless"],"antonyms":["disingenuous"],"tipVi":"Đừng nhầm lẫn với ingenious (tài tình, khéo léo); từ này nhấn mạnh tính cách chân chất, ngây thơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_matrimony', 'en-c2-2', 'matrimony', '/ˈmætrɪmoʊni/', 'C2', 'đời sống vợ chồng; tình trạng hôn nhân', 'n.', 'matrimonial (adj.)', 'Đồng nghĩa: marriage, wedlock', 'Đây là từ mang tính trang trọng hoặc dùng trong ngôn ngữ tôn giáo; trong giao tiếp hàng ngày, từ marriage phổ biến hơn nhiều.', 'The couple were joined in matrimony last spring.', NULL, 'Cặp đôi đã kết hôn vào mùa xuân năm ngoái.', '{"wordId":"matrimony","ukIpa":"/ˈmætrɪməni/","usIpa":"/ˈmætrɪmoʊni/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"The state of being married, especially in formal or religious language.","vi":"đời sống vợ chồng; tình trạng hôn nhân"}],"examples":[{"en":"The couple were joined in matrimony last spring.","vi":"Cặp đôi đã kết hôn vào mùa xuân năm ngoái.","audioKind":"ex"},{"en":"Although attitudes towards matrimony vary across cultures, marriage continues to carry legal and social responsibilities.","vi":"Mặc dù quan điểm về hôn nhân khác nhau giữa các nền văn hóa, hôn nhân vẫn mang theo các trách nhiệm pháp lý và xã hội.","audioKind":"ex2"}],"collocations":[{"en":"joined in matrimony","vi":"kết duyên vợ chồng"},{"en":"holy matrimony","vi":"hôn nhân thiêng liêng"},{"en":"the bonds of matrimony","vi":"dây tơ hồng; ràng buộc hôn nhân"}],"wordFamily":["matrimonial (adj.)"],"synonyms":["marriage","wedlock"],"antonyms":[],"tipVi":"Đây là từ mang tính trang trọng hoặc dùng trong ngôn ngữ tôn giáo; trong giao tiếp hàng ngày, từ marriage phổ biến hơn nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repute', 'en-c2-2', 'repute', '/rɪˈpjuːt/', 'C2', 'danh tiếng; tiếng tăm; cho là; coi là; đánh giá', 'n.', 'reputation (n.), reputed (adj.), reputable (adj.)', 'Đồng nghĩa: reputation, standing', 'Động từ thường dùng ở dạng bị động be reputed to be, mang nghĩa là "được cho là".', 'The workshop hired a violin maker of considerable repute.', NULL, 'Xưởng mộc đã thuê một thợ làm đàn vĩ cầm có tiếng tăm lừng lẫy.', '{"wordId":"repute","ukIpa":"/rɪˈpjuːt/","usIpa":"/rɪˈpjuːt/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"the general opinion people have of someone or something","vi":"danh tiếng; tiếng tăm"},{"pos":"v.","en":"to consider someone or something to have a particular quality","vi":"cho là; coi là; đánh giá"}],"examples":[{"en":"The workshop hired a violin maker of considerable repute.","vi":"Xưởng mộc đã thuê một thợ làm đàn vĩ cầm có tiếng tăm lừng lẫy.","audioKind":"ex"},{"en":"Research institutions of international repute often attract talented students and substantial investment from overseas.","vi":"Các viện nghiên cứu có uy tín quốc tế thường thu hút được những sinh viên tài năng và nguồn vốn đầu tư khổng lồ từ nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"of international repute","vi":"có uy tín quốc tế"},{"en":"of good repute","vi":"có danh tiếng tốt"},{"en":"be reputed to be","vi":"được cho là"}],"wordFamily":["reputation (n.)","reputed (adj.)","reputable (adj.)"],"synonyms":["reputation","standing"],"antonyms":[],"tipVi":"Động từ thường dùng ở dạng bị động be reputed to be, mang nghĩa là \"được cho là\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unaccommodating', 'en-c2-2', 'unaccommodating', '/ˌʌnəˈkɑːmədeɪtɪŋ/', 'C2', 'không khoan nhượng; không chịu linh động; không hợp tác', 'adj.', 'accommodate (v.), accommodating (adj.), accommodation (n.)', 'Đồng nghĩa: unhelpful, inflexible · Trái nghĩa: accommodating, helpful', 'Chỉ thái độ không muốn giúp đỡ hoặc nhượng bộ người khác, không mang nghĩa là không có chỗ ở.', 'The unaccommodating host refused to provide an extra chair.', NULL, 'Người chủ nhà không chịu linh động ấy đã từ chối cung cấp thêm một chiếc ghế.', '{"wordId":"unaccommodating","ukIpa":"/ˌʌnəˈkɒmədeɪtɪŋ/","usIpa":"/ˌʌnəˈkɑːmədeɪtɪŋ/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Unwilling to help others or adjust to their needs.","vi":"không khoan nhượng; không chịu linh động; không hợp tác"}],"examples":[{"en":"The unaccommodating host refused to provide an extra chair.","vi":"Người chủ nhà không chịu linh động ấy đã từ chối cung cấp thêm một chiếc ghế.","audioKind":"ex"},{"en":"Unaccommodating employers may struggle to retain skilled workers who need flexible schedules to manage family responsibilities.","vi":"Những người chủ sử dụng lao động không chịu linh động có thể gặp khó khăn trong việc giữ chân những lao động lành nghề, những người cần thời gian biểu linh hoạt để lo liệu việc gia đình.","audioKind":"ex2"}],"collocations":[{"en":"an unaccommodating attitude","vi":"thái độ không chịu linh động"},{"en":"an unaccommodating employer","vi":"một người chủ không hợp tác"}],"wordFamily":["accommodate (v.)","accommodating (adj.)","accommodation (n.)"],"synonyms":["unhelpful","inflexible"],"antonyms":["accommodating","helpful"],"tipVi":"Chỉ thái độ không muốn giúp đỡ hoặc nhượng bộ người khác, không mang nghĩa là không có chỗ ở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catholic', 'en-c2-2', 'catholic', '/ˈkæθəlɪk/', 'C2', 'có sở thích rộng rãi; bao quát; phong phú; thuộc về Giáo hội Công giáo Rô-ma; tín đồ Công giáo', 'adj.', 'Catholicism (n.), catholicity (n.)', 'Đồng nghĩa: wide-ranging', 'Viết chữ thường chỉ sự bao quát, rộng rãi; viết hoa Catholic khi chỉ đạo Công giáo hoặc tín đồ của giáo hội này.', 'Her catholic tastes include jazz, pottery, hiking, and opera.', NULL, 'Gu thẩm mỹ phong phú của cô ấy bao gồm nhạc jazz, nghệ thuật gốm sứ, đi bộ đường dài và opera.', '{"wordId":"catholic","ukIpa":"/ˈkæθəlɪk/","usIpa":"/ˈkæθəlɪk/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Including or appreciating a wide variety of things.","vi":"có sở thích rộng rãi; bao quát; phong phú"},{"pos":"adj.","en":"Relating to the Christian church led by the Pope.","vi":"thuộc về Giáo hội Công giáo Rô-ma"},{"pos":"n.","en":"A member of the Christian church led by the Pope.","vi":"tín đồ Công giáo"}],"examples":[{"en":"Her catholic tastes include jazz, pottery, hiking, and opera.","vi":"Gu thẩm mỹ phong phú của cô ấy bao gồm nhạc jazz, nghệ thuật gốm sứ, đi bộ đường dài và opera.","audioKind":"ex"},{"en":"A catholic approach to reading exposes students to diverse perspectives across literature, science, and history.","vi":"Cách tiếp cận bao quát đối với việc đọc sách giúp học sinh tiếp cận với nhiều góc nhìn đa dạng trong văn học, khoa học và lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"catholic tastes","vi":"sở thích phong phú đa dạng"},{"en":"Catholic Church","vi":"Giáo hội Công giáo"},{"en":"a practising Catholic","vi":"một tín đồ Công giáo thuần thành"}],"wordFamily":["Catholicism (n.)","catholicity (n.)"],"synonyms":["wide-ranging"],"antonyms":[],"tipVi":"Viết chữ thường chỉ sự bao quát, rộng rãi; viết hoa Catholic khi chỉ đạo Công giáo hoặc tín đồ của giáo hội này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idiosyncrasy', 'en-c2-2', 'idiosyncrasy', '/ˌɪdiəˈsɪŋkrəsi/', 'C2', 'đặc tính; thói quen kỳ quặc riêng biệt', 'n.', 'idiosyncratic (adj.), idiosyncratically (adv.)', 'Đồng nghĩa: quirk, peculiarity', 'Là danh từ đếm được, số nhiều là "idiosyncrasies", thường chỉ thói quen độc đáo.', 'One of his idiosyncrasies is sorting socks by colour.', NULL, 'Một trong những thói quen kỳ quặc của anh ấy là phân loại tất cả tất theo màu sắc.', '{"wordId":"idiosyncrasy","ukIpa":"/ˌɪdiəˈsɪŋkrəsi/","usIpa":"/ˌɪdiəˈsɪŋkrəsi/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"an unusual habit or feature particular to someone or something","vi":"đặc tính; thói quen kỳ quặc riêng biệt"}],"examples":[{"en":"One of his idiosyncrasies is sorting socks by colour.","vi":"Một trong những thói quen kỳ quặc của anh ấy là phân loại tất cả tất theo màu sắc.","audioKind":"ex"},{"en":"Effective teachers recognise individual idiosyncrasies and adapt their methods without discouraging students from expressing their personalities.","vi":"Những giáo viên giỏi nhận ra nét cá tính riêng của từng học sinh và điều chỉnh phương pháp dạy mà không làm mất đi sự biểu đạt cá nhân của các em.","audioKind":"ex2"}],"collocations":[{"en":"personal idiosyncrasies","vi":"thói quen cá nhân độc đáo"},{"en":"individual idiosyncrasies","vi":"đặc điểm cá nhân riêng biệt"},{"en":"linguistic idiosyncrasies","vi":"đặc điểm ngôn ngữ độc đáo"}],"wordFamily":["idiosyncratic (adj.)","idiosyncratically (adv.)"],"synonyms":["quirk","peculiarity"],"antonyms":[],"tipVi":"Là danh từ đếm được, số nhiều là \"idiosyncrasies\", thường chỉ thói quen độc đáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repudiate', 'en-c2-2', 'repudiate', '/rɪˈpjuːdieɪt/', 'C2', 'bác bỏ; từ chối; từ chối thực hiện; từ chối trả nợ', 'v.', 'repudiation (n.)', 'Đồng nghĩa: reject, disavow · Trái nghĩa: accept, endorse', 'Là động từ trang trọng, không phải danh từ; dạng danh từ là repudiation.', 'She firmly repudiated the rumour that she had cheated.', NULL, 'Cô ấy kiên quyết bác bỏ tin đồn rằng mình đã gian lận.', '{"wordId":"repudiate","ukIpa":"/rɪˈpjuːdieɪt/","usIpa":"/rɪˈpjuːdieɪt/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To firmly reject a claim, belief, or association.","vi":"bác bỏ; từ chối"},{"pos":"v.","en":"To refuse to honour an agreement or pay a debt.","vi":"từ chối thực hiện; từ chối trả nợ"}],"examples":[{"en":"She firmly repudiated the rumour that she had cheated.","vi":"Cô ấy kiên quyết bác bỏ tin đồn rằng mình đã gian lận.","audioKind":"ex"},{"en":"Professional associations should repudiate misleading claims that undermine public confidence in established medical treatments.","vi":"Các hiệp hội nghề nghiệp nên bác bỏ những tuyên bố sai lệch làm suy yếu lòng tin của công chúng đối với các phương pháp điều trị y tế đã được công nhận.","audioKind":"ex2"}],"collocations":[{"en":"repudiate an allegation","vi":"bác bỏ một cáo buộc"},{"en":"repudiate a claim","vi":"bác bỏ một tuyên bố"},{"en":"repudiate a contract","vi":"hủy bỏ hợp đồng"},{"en":"repudiate a debt","vi":"từ chối trả nợ"}],"wordFamily":["repudiation (n.)"],"synonyms":["reject","disavow"],"antonyms":["accept","endorse"],"tipVi":"Là động từ trang trọng, không phải danh từ; dạng danh từ là repudiation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_2_1', 'en-c2-2', 'Cách dùng “matrimony” (n.) — đời sống vợ chồng; tình trạng hôn nhân', 'joined in matrimony  ·  holy matrimony  ·  the bonds of matrimony', 'Đây là từ mang tính trang trọng hoặc dùng trong ngôn ngữ tôn giáo; trong giao tiếp hàng ngày, từ marriage phổ biến hơn nhiều.', 'Họ từ (Word Family): matrimonial (adj.) | Đồng nghĩa: marriage, wedlock', '[{"hanzi":"The couple were joined in matrimony last spring.","pinyin":"","meaning":"Cặp đôi đã kết hôn vào mùa xuân năm ngoái."},{"hanzi":"Although attitudes towards matrimony vary across cultures, marriage continues to carry legal and social responsibilities.","pinyin":"","meaning":"Mặc dù quan điểm về hôn nhân khác nhau giữa các nền văn hóa, hôn nhân vẫn mang theo các trách nhiệm pháp lý và xã hội."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_2_2', 'en-c2-2', 'Cách dùng “pervert” (v.) — bóp méo; xuyên tạc; làm bại hoại', 'pervert the course of justice  ·  pervert the truth', 'Trọng âm ở động từ rơi vào âm tiết thứ hai; nếu là danh từ, trọng âm ở âm tiết đầu và thường mang nghĩa tiêu cực.', 'Họ từ (Word Family): perversion (n.), perverted (adj.) | Đồng nghĩa: distort, corrupt', '[{"hanzi":"The coach perverted fair competition by secretly changing the rules.","pinyin":"","meaning":"Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc."},{"hanzi":"Political pressure can pervert scientific research when funding depends on producing results that support existing policies.","pinyin":"","meaning":"Áp lực chính trị có thể bóp méo nghiên cứu khoa học khi nguồn kinh phí phụ thuộc vào việc tạo ra kết quả ủng hộ các chính sách hiện hành."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_2_3', 'en-c2-2', 'Cách dùng “virile” (adj.) — có khí phách đàn ông; cường tráng; mạnh mẽ', 'virile image  ·  virile young man  ·  virile masculinity', 'Không chỉ có nghĩa là "thuộc về nam giới"; từ này nhấn mạnh sức mạnh và sự năng động truyền thống của phái mạnh.', 'Họ từ (Word Family): virility (n.) | Đồng nghĩa: masculine, manly', '[{"hanzi":"The sculpture portrays a virile athlete lifting a discus.","pinyin":"","meaning":"Bức tượng khắc họa một vận động viên vạm vỡ đang vung đĩa tạ."},{"hanzi":"Advertisements often present a virile male ideal, which may reinforce narrow expectations about men''s appearance and behaviour.","pinyin":"","meaning":"Các quảng cáo thường thể hiện hình mẫu nam giới lý tưởng đầy nam tính, điều này có thể củng cố những định kiến hẹp hòi về diện mạo và hành vi của đàn ông."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_2_4', 'en-c2-2', 'Cách dùng “catholic” (adj.) — có sở thích rộng rãi; bao quát; phong phú', 'catholic tastes  ·  Catholic Church  ·  a practising Catholic', 'Viết chữ thường chỉ sự bao quát, rộng rãi; viết hoa Catholic khi chỉ đạo Công giáo hoặc tín đồ của giáo hội này.', 'Họ từ (Word Family): Catholicism (n.), catholicity (n.) | Đồng nghĩa: wide-ranging', '[{"hanzi":"Her catholic tastes include jazz, pottery, hiking, and opera.","pinyin":"","meaning":"Gu thẩm mỹ phong phú của cô ấy bao gồm nhạc jazz, nghệ thuật gốm sứ, đi bộ đường dài và opera."},{"hanzi":"A catholic approach to reading exposes students to diverse perspectives across literature, science, and history.","pinyin":"","meaning":"Cách tiếp cận bao quát đối với việc đọc sách giúp học sinh tiếp cận với nhiều góc nhìn đa dạng trong văn học, khoa học và lịch sử."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_2_1', 'en-c2-2', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_1', 'ten_c2_2_1', 'bestow', 'The club bestowed a special award on our coach.', 'The club bestowed a special award on our coach.', '/bɪˈstoʊ/', 'Câu lạc bộ đã trao một giải thưởng đặc biệt cho huấn luyện viên của chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_2', 'ten_c2_2_1', 'deplore', 'Our neighbours deplore the dumping of rubbish beside the river.', 'Our neighbours deplore the dumping of rubbish beside the river.', '/dɪˈplɔːr/', 'Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_3', 'ten_c2_2_1', 'nicety', 'I am still learning the niceties of formal dining.', 'I am still learning the niceties of formal dining.', '/ˈnaɪsəti/', 'Tôi vẫn đang học các quy tắc ứng xử trong những bữa tiệc trang trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_4', 'ten_c2_2_1', 'pervert', 'The coach perverted fair competition by secretly changing the rules.', 'The coach perverted fair competition by secretly changing the rules.', '/pɚˈvɝːt/', 'Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_5', 'ten_c2_2_1', 'virile', 'The sculpture portrays a virile athlete lifting a discus.', 'The sculpture portrays a virile athlete lifting a discus.', '/ˈvɪrəl/', 'Bức tượng khắc họa một vận động viên vạm vỡ đang vung đĩa tạ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_6', 'ten_c2_2_1', 'ostentation', 'Their wedding was warm and cheerful, without any ostentation.', 'Their wedding was warm and cheerful, without any ostentation.', '/ˌɑːstenˈteɪʃən/', 'Đám cưới của họ ấm cúng và vui vẻ, hoàn toàn không có sự phô trương nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_7', 'ten_c2_2_1', 'insolent', 'The waiter remained calm despite the customer''s insolent tone.', 'The waiter remained calm despite the customer''s insolent tone.', '/ˈɪnsələnt/', 'Người phục vụ vẫn giữ được bình tĩnh bất chấp thái độ xấc láo của vị khách hàng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_1_8', 'ten_c2_2_1', 'jeer', 'A few spectators jeered when the player missed again.', 'A few spectators jeered when the player missed again.', '/dʒɪr/', 'Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_2_1_1', 'en-c2-2', 'ten_c2_2_1', 'listening', 'listening', 'The club bestowed a special award on our coach.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Câu lạc bộ đã trao một giải thưởng đặc biệt cho huấn luyện viên của chúng tôi.","Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.","Việc sân chơi đột ngột đóng cửa đã gây ra làn sóng phẫn nộ mạnh mẽ.","Một trong những thói quen kỳ quặc của anh ấy là phân loại tất cả tất theo màu sắc."]'::jsonb, 0, 'The club bestowed a special award on our coach. → Câu lạc bộ đã trao một giải thưởng đặc biệt cho huấn luyện viên của chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_2_1_2', 'en-c2-2', 'ten_c2_2_1', 'listening', 'listening', 'Our neighbours deplore the dumping of rubbish beside the river.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.","Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc.","Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.","Câu hỏi ngây thơ hồn nhiên của cô ấy làm mọi người bật cười bên bàn ăn."]'::jsonb, 0, 'Our neighbours deplore the dumping of rubbish beside the river. → Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_2_1_3', 'en-c2-2', 'ten_c2_2_1', 'listening', 'listening', 'I am still learning the niceties of formal dining.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một trong những thói quen kỳ quặc của anh ấy là phân loại tất cả tất theo màu sắc.","Tôi vẫn đang học các quy tắc ứng xử trong những bữa tiệc trang trọng.","Người chủ nhà không chịu linh động ấy đã từ chối cung cấp thêm một chiếc ghế.","Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc."]'::jsonb, 1, 'I am still learning the niceties of formal dining. → Tôi vẫn đang học các quy tắc ứng xử trong những bữa tiệc trang trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_2_2', 'en-c2-2', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_2_1', 'ten_c2_2_2', 'bestow', 'Universities often bestow honorary degrees on individuals who have made outstanding contributions to society.', 'Universities often bestow honorary degrees on individuals who have made outstanding contributions to society.', '/bɪˈstoʊ/', 'Các trường đại học thường trao học vị danh dự cho những cá nhân đã có đóng góp xuất sắc cho xã hội.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_2_2', 'ten_c2_2_2', 'deplore', 'Many educators deplore funding cuts that limit access to music and art lessons in public schools.', 'Many educators deplore funding cuts that limit access to music and art lessons in public schools.', '/dɪˈplɔːr/', 'Nhiều nhà giáo dục kịch liệt phản đối việc cắt giảm ngân sách vốn làm hạn chế cơ hội tiếp cận các bài học âm nhạc và mỹ thuật tại các trường công lập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_2_3', 'ten_c2_2_2', 'nicety', 'Understanding the niceties of legal language is essential when translating international agreements that affect trade and environmental protection.', 'Understanding the niceties of legal language is essential when translating international agreements that affect trade and environmental protection.', '/ˈnaɪsəti/', 'Việc hiểu rõ những sắc thái tinh tế của ngôn ngữ pháp lý là điều cốt yếu khi dịch các hiệp định quốc tế ảnh hưởng đến thương mại và bảo vệ môi trường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_2_4', 'ten_c2_2_2', 'pervert', 'Political pressure can pervert scientific research when funding depends on producing results that support existing policies.', 'Political pressure can pervert scientific research when funding depends on producing results that support existing policies.', '/pɚˈvɝːt/', 'Áp lực chính trị có thể bóp méo nghiên cứu khoa học khi nguồn kinh phí phụ thuộc vào việc tạo ra kết quả ủng hộ các chính sách hiện hành.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_2_5', 'ten_c2_2_2', 'virile', 'Advertisements often present a virile male ideal, which may reinforce narrow expectations about men''s appearance and behaviour.', 'Advertisements often present a virile male ideal, which may reinforce narrow expectations about men''s appearance and behaviour.', '/ˈvɪrəl/', 'Các quảng cáo thường thể hiện hình mẫu nam giới lý tưởng đầy nam tính, điều này có thể củng cố những định kiến hẹp hòi về diện mạo và hành vi của đàn ông.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_2_2_6', 'ten_c2_2_2', 'ostentation', 'The ostentation associated with luxury consumption can intensify social pressure to display wealth rather than save responsibly.', 'The ostentation associated with luxury consumption can intensify social pressure to display wealth rather than save responsibly.', '/ˌɑːstenˈteɪʃən/', 'Thói phô trương gắn liền với tiêu dùng xa xỉ có thể làm gia tăng áp lực xã hội, khiến người ta phải trưng diện tài sản thay vì tiết kiệm một cách khôn ngoan.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_2_2_1', 'en-c2-2', 'ten_c2_2_2', 'listening', 'listening', 'Universities often bestow honorary degrees on individuals who have made outstanding contributions to society.', NULL, 'Trong câu vừa nghe, từ “bestow” mang nghĩa nào sau đây?', '["tỉ mỉ; cẩn trọng; chu đáo","người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm","của văn bản này; liên quan đến tài liệu này","ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)"]'::jsonb, 3, '“bestow” (/bɪˈstoʊ/): ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng). Câu đầy đủ: Universities often bestow honorary degrees on individuals who have made outstanding contributions to society.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_2_2_2', 'en-c2-2', 'ten_c2_2_2', 'listening', 'listening', 'Many educators deplore funding cuts that limit access to music and art lessons in public schools.', NULL, 'Trong câu vừa nghe, từ “deplore” mang nghĩa nào sau đây?', '["la ó, chế nhạo hoặc cười nhạo ai đó theo cách ác ý","kịch liệt phản đối; vô cùng đau xót","không thích; miễn cưỡng","chi trả; thanh toán (chi phí)"]'::jsonb, 1, '“deplore” (/dɪˈplɔːr/): kịch liệt phản đối; vô cùng đau xót. Câu đầy đủ: Many educators deplore funding cuts that limit access to music and art lessons in public schools.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
