INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_2_1', 'en-c2-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “bestow” (/bɪˈstoʊ/) có nghĩa là gì?', '["ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)","có khí phách đàn ông; cường tráng; mạnh mẽ","không khoan nhượng; không chịu linh động; không hợp tác","hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền"]'::jsonb, 0, '“bestow” (v.): ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng).', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
