INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_1', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'bestow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không thích hợp; không thỏa đáng; không khéo","mang tính ảo ảnh; hão huyền","cuộc hành trình dài và nhiều gian nan trắc trở","ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)"]'::jsonb, 3, 'bestow (/bɪˈstoʊ/) → ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_2', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'Our neighbours deplore the dumping of rubbish beside the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc sân chơi đột ngột đóng cửa đã gây ra làn sóng phẫn nộ mạnh mẽ.","Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.","Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.","Bức tượng khắc họa một vận động viên vạm vỡ đang vung đĩa tạ."]'::jsonb, 1, 'Our neighbours deplore the dumping of rubbish beside the river. → Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_3', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'nicety', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chi tiết tinh vi; điểm tế nhị","vòng xoáy nước, luồng không khí xoáy","đặc tính; thói quen kỳ quặc riêng biệt","được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh"]'::jsonb, 0, 'nicety (/ˈnaɪsəti/) → chi tiết tinh vi; điểm tế nhị; phép tắc xã giao; quy tắc lịch sự', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_4', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'The coach perverted fair competition by secretly changing the rules.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cặp đôi đã kết hôn vào mùa xuân năm ngoái.","Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc.","Bức tượng khắc họa một vận động viên vạm vỡ đang vung đĩa tạ.","Gu thẩm mỹ phong phú của cô ấy bao gồm nhạc jazz, nghệ thuật gốm sứ, đi bộ đường dài và opera."]'::jsonb, 1, 'The coach perverted fair competition by secretly changing the rules. → Huấn luyện viên đã làm vẩn đục sự cạnh tranh công bằng bằng cách ngầm thay đổi các quy tắc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_5', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'virile', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có khí phách đàn ông; cường tráng; mạnh mẽ","phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau","trái nghĩa; có nghĩa đối lập","nhiều và phong phú; đa dạng; nhiều mặt"]'::jsonb, 0, 'virile (/ˈvɪrəl/) → có khí phách đàn ông; cường tráng; mạnh mẽ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_6', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'Their wedding was warm and cheerful, without any ostentation.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các mặt hàng phong phú của khu chợ bao gồm gia vị, đồ gốm và đồ chơi thủ công.","Hàng xóm của chúng tôi kịch liệt lên án hành vi xả rác bên bờ sông.","Đám cưới của họ ấm cúng và vui vẻ, hoàn toàn không có sự phô trương nào.","Cặp đôi đã kết hôn vào mùa xuân năm ngoái."]'::jsonb, 2, 'Their wedding was warm and cheerful, without any ostentation. → Đám cưới của họ ấm cúng và vui vẻ, hoàn toàn không có sự phô trương nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_7', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'insolent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xỉ lò; xỉ quặng","vòng xoáy nước, luồng không khí xoáy","hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền","mãnh liệt; quyết liệt"]'::jsonb, 2, 'insolent (/ˈɪnsələnt/) → hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_8', 'en-c2-2', NULL, 'comprehensive_test', 'listening', 'A few spectators jeered when the player missed again.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xưởng mộc đã thuê một thợ làm đàn vĩ cầm có tiếng tăm lừng lẫy.","Câu hỏi ngây thơ hồn nhiên của cô ấy làm mọi người bật cười bên bàn ăn.","Huấn luyện viên đã xin lỗi vì những lời lẽ thô tục của mình sau trận đấu.","Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa."]'::jsonb, 3, 'A few spectators jeered when the player missed again. → Một vài khán giả đã la ó khi cầu thủ đó lại sút hỏng một lần nữa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
