INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_18', 'en-c2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Universities often bestow honorary degrees on individuals who have made outstanding contributions to society.', 'Dựa vào câu trên, từ “bestow” có nghĩa phù hợp nhất là gì?', '["đặc quyền; quyền riêng","ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng)","sự minh oan, việc chính thức tuyên bố ai đó vô tội hoặc không phải chịu trách nhiệm","toàn thể; họp toàn thể"]'::jsonb, 1, 'bestow: ban tặng; trao tặng (vinh dự, danh hiệu, quà tặng). Dịch cả câu: Các trường đại học thường trao học vị danh dự cho những cá nhân đã có đóng góp xuất sắc cho xã hội.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_19', 'en-c2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Many educators deplore funding cuts that limit access to music and art lessons in public schools.', 'Dựa vào câu trên, từ “deplore” có nghĩa phù hợp nhất là gì?', '["kịch liệt phản đối; vô cùng đau xót","chỉ quan tâm đến tiền bạc hơn là các yếu tố khác (hám lợi)","nằm sấp; phủ phục","sự dao động; sự đu đưa"]'::jsonb, 0, 'deplore: kịch liệt phản đối; vô cùng đau xót. Dịch cả câu: Nhiều nhà giáo dục kịch liệt phản đối việc cắt giảm ngân sách vốn làm hạn chế cơ hội tiếp cận các bài học âm nhạc và mỹ thuật tại các trường công lập.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_20', 'en-c2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Understanding the niceties of legal language is essential when translating international agreements that affect trade and environmental protection.', 'Dựa vào câu trên, từ “nicety” có nghĩa phù hợp nhất là gì?', '["bãi bỏ; hủy bỏ (luật, thỏa thuận)","chi tiết tinh vi; điểm tế nhị","vòng xoáy nước, luồng không khí xoáy","vươn; vắt; ép (nhất là để loại bỏ nước)"]'::jsonb, 1, 'nicety: chi tiết tinh vi; điểm tế nhị; phép tắc xã giao; quy tắc lịch sự. Dịch cả câu: Việc hiểu rõ những sắc thái tinh tế của ngôn ngữ pháp lý là điều cốt yếu khi dịch các hiệp định quốc tế ảnh hưởng đến thương mại và bảo vệ môi trường.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_21', 'en-c2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Political pressure can pervert scientific research when funding depends on producing results that support existing policies.', 'Dựa vào câu trên, từ “pervert” có nghĩa phù hợp nhất là gì?', '["bóp méo; xuyên tạc; làm bại hoại","nằm hoặc ngồi ngả ngớn, lười biếng; thõng xuống","của văn bản này; liên quan đến tài liệu này","ngành báo chí tường thuật; phóng sự"]'::jsonb, 0, 'pervert: bóp méo; xuyên tạc; làm bại hoại. Dịch cả câu: Áp lực chính trị có thể bóp méo nghiên cứu khoa học khi nguồn kinh phí phụ thuộc vào việc tạo ra kết quả ủng hộ các chính sách hiện hành.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_22', 'en-c2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có sở thích rộng rãi; bao quát; phong phú”', '["inveterate","catholic","avenge","promissory"]'::jsonb, 1, 'có sở thích rộng rãi; bao quát; phong phú → catholic (/ˈkæθəlɪk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_23', 'en-c2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đặc tính; thói quen kỳ quặc riêng biệt”', '["coinage","harangue","inexorable","idiosyncrasy"]'::jsonb, 3, 'đặc tính; thói quen kỳ quặc riêng biệt → idiosyncrasy (/ˌɪdiəˈsɪŋkrəsi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_2_24', 'en-c2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bác bỏ; từ chối”', '["coefficient","pneumatic","ruinous","repudiate"]'::jsonb, 3, 'bác bỏ; từ chối → repudiate (/rɪˈpjuːdieɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-3', 'en', 'Bài 3: Xã hội & Cộng đồng (2) - CEFR C2', 'CEFR C2', 'C2 · Xã hội', '19 từ vựng Tiếng Anh CEFR C2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6003, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strife', 'en-c2-3', 'strife', '/straɪf/', 'C2', 'sự xung đột; sự tranh chấp', 'n.', NULL, 'Đồng nghĩa: conflict, discord · Trái nghĩa: harmony', 'Là danh từ không đếm được, mang sắc thái trang trọng, trầm trọng hơn những cuộc tranh cãi thông thường.', 'Arguments over money caused constant strife in the family.', NULL, 'Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình.', '{"wordId":"strife","ukIpa":"/straɪf/","usIpa":"/straɪf/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"serious disagreement or conflict between people or groups","vi":"sự xung đột; sự tranh chấp"}],"examples":[{"en":"Arguments over money caused constant strife in the family.","vi":"Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình.","audioKind":"ex"},{"en":"Economic inequality can fuel social strife when communities feel excluded from opportunities for a better life.","vi":"Bất bình đẳng kinh tế có thể châm ngòi cho xung đột xã hội khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các cơ hội vươn lên cuộc sống tốt đẹp hơn.","audioKind":"ex2"}],"collocations":[{"en":"social strife","vi":"xung đột xã hội"},{"en":"civil strife","vi":"nội chiến"},{"en":"industrial strife","vi":"tranh chấp lao động"}],"wordFamily":[],"synonyms":["conflict","discord"],"antonyms":["harmony"],"tipVi":"Là danh từ không đếm được, mang sắc thái trang trọng, trầm trọng hơn những cuộc tranh cãi thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skirmish', 'en-c2-3', 'skirmish', '/ˈskɝːmɪʃ/', 'C2', 'cuộc đụng độ nhỏ; xung đột ngắn; cuộc cãi vã nhỏ; tranh cãi chớp nhoáng; xảy ra xung đột nhỏ; cãi vã chớp nhoáng', 'n.', 'skirmisher (n.)', 'Đồng nghĩa: clash, clash of arms', 'Nhấn mạnh quy mô nhỏ, thời gian ngắn; cũng có thể dùng theo nghĩa bóng để chỉ tranh cãi bằng lời nói.', 'Their skirmish over the remote ended with a compromise.', NULL, 'Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.', '{"wordId":"skirmish","ukIpa":"/ˈskɜːmɪʃ/","usIpa":"/ˈskɝːmɪʃ/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"A brief fight between small groups of opposing forces.","vi":"cuộc đụng độ nhỏ; xung đột ngắn"},{"pos":"n.","en":"A brief argument, often within a larger disagreement.","vi":"cuộc cãi vã nhỏ; tranh cãi chớp nhoáng"},{"pos":"v.","en":"Fight or argue briefly without a major confrontation.","vi":"xảy ra xung đột nhỏ; cãi vã chớp nhoáng"}],"examples":[{"en":"Their skirmish over the remote ended with a compromise.","vi":"Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.","audioKind":"ex"},{"en":"A brief border skirmish can undermine diplomatic progress and discourage investment in nearby communities.","vi":"Một cuộc xung đột biên giới chớp nhoáng có thể làm suy yếu tiến trình ngoại giao và làm nản lòng các nhà đầu tư vào các cộng đồng lân cận.","audioKind":"ex2"}],"collocations":[{"en":"border skirmish","vi":"xung đột biên giới nhỏ"},{"en":"minor skirmish","vi":"xung đột nhỏ"},{"en":"skirmish over something","vi":"cuộc cãi vã về vấn đề gì đó"}],"wordFamily":["skirmisher (n.)"],"synonyms":["clash","clash of arms"],"antonyms":[],"tipVi":"Nhấn mạnh quy mô nhỏ, thời gian ngắn; cũng có thể dùng theo nghĩa bóng để chỉ tranh cãi bằng lời nói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_redound', 'en-c2-3', 'redound', '/rɪˈdaʊnd/', 'C2', 'mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)', 'v.', NULL, NULL, 'Từ này mang tính trang trọng và ít khi dùng; thường đi với giới từ to, không trực tiếp đi theo sau tân ngữ để biểu thị sự gia tăng.', 'Your generosity will redound to the whole team''s credit.', NULL, 'Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ.', '{"wordId":"redound","ukIpa":"/rɪˈdaʊnd/","usIpa":"/rɪˈdaʊnd/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To produce a particular result, especially credit or benefit.","vi":"mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)"}],"examples":[{"en":"Your generosity will redound to the whole team''s credit.","vi":"Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ.","audioKind":"ex"},{"en":"Sustained investment in public libraries can redound to the benefit of communities by expanding access to knowledge.","vi":"Việc đầu tư liên tục vào các thư viện công cộng có thể đem lại lợi ích thiết thực cho cộng đồng thông qua việc mở rộng khả năng tiếp cận tri thức.","audioKind":"ex2"}],"collocations":[{"en":"redound to someone''s credit","vi":"góp phần đem lại uy tín cho ai"},{"en":"redound to the benefit of","vi":"có lợi cho"},{"en":"redound to someone''s honour","vi":"góp phần làm rạng danh ai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này mang tính trang trọng và ít khi dùng; thường đi với giới từ to, không trực tiếp đi theo sau tân ngữ để biểu thị sự gia tăng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fetter', 'en-c2-3', 'fetter', '/ˈfetər/', 'C2', 'cản trở; hạn chế; sự trói buộc; xiềng xích', 'v.', 'fettered (adj.), unfettered (adj.)', 'Đồng nghĩa: restrain, restrict · Trái nghĩa: free, liberate', 'Từ mang tính trang trọng; danh từ thường ở dạng số nhiều "fetters".', 'Don''t let fear fetter your plans to travel alone.', NULL, 'Đừng để nỗi sợ hãi cản trở kế hoạch đi du lịch một mình của bạn.', '{"wordId":"fetter","ukIpa":"/ˈfetə/","usIpa":"/ˈfetər/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To restrict someone''s freedom or ability to act.","vi":"cản trở; hạn chế"},{"pos":"n.","en":"Something limiting freedom, or a chain securing someone''s ankles.","vi":"sự trói buộc; xiềng xích"}],"examples":[{"en":"Don''t let fear fetter your plans to travel alone.","vi":"Đừng để nỗi sợ hãi cản trở kế hoạch đi du lịch một mình của bạn.","audioKind":"ex"},{"en":"Excessive administrative requirements can fetter small businesses, preventing them from investing in innovation and creating jobs.","vi":"Những yêu cầu hành chính quá mức có thể kìm hãm các doanh nghiệp nhỏ, khiến họ không thể đầu tư vào đổi mới sáng tạo và tạo ra việc làm.","audioKind":"ex2"}],"collocations":[{"en":"be fettered by","vi":"bị ràng buộc bởi"},{"en":"fetter creativity","vi":"kìm hãm sự sáng tạo"},{"en":"break free from fetters","vi":"thoát khỏi xiềng xích"}],"wordFamily":["fettered (adj.)","unfettered (adj.)"],"synonyms":["restrain","restrict"],"antonyms":["free","liberate"],"tipVi":"Từ mang tính trang trọng; danh từ thường ở dạng số nhiều \"fetters\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_urbane', 'en-c2-3', 'urbane', '/ɝːˈbeɪn/', 'C2', 'lịch lãm; tao nhã; khéo ứng xử', 'adj.', 'urbanely (adv.), urbanity (n.)', 'Đồng nghĩa: suave, sophisticated, polished · Trái nghĩa: uncouth', 'urbane chỉ sự lịch thiệp, tao nhã và giỏi giao tiếp xã hội; trong khi urban có nghĩa là thuộc về thành phố.', 'Our urbane host welcomed everyone with a warm smile.', NULL, 'Người chủ nhà lịch lãm của chúng tôi chào đón mọi người bằng nụ cười ấm áp.', '{"wordId":"urbane","ukIpa":"/ɜːˈbeɪn/","usIpa":"/ɝːˈbeɪn/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Polite, confident, and comfortable in social situations.","vi":"lịch lãm; tao nhã; khéo ứng xử"}],"examples":[{"en":"Our urbane host welcomed everyone with a warm smile.","vi":"Người chủ nhà lịch lãm của chúng tôi chào đón mọi người bằng nụ cười ấm áp.","audioKind":"ex"},{"en":"An urbane manner can help diplomats build trust, although successful negotiations also require substantial expertise.","vi":"Phong thái lịch lãm có thể giúp các nhà ngoại giao xây dựng lòng tin, mặc dù các cuộc đàm phán thành công cũng đòi hỏi chuyên môn vững chắc.","audioKind":"ex2"}],"collocations":[{"en":"urbane manner","vi":"phong thái lịch lãm"},{"en":"urbane charm","vi":"sức hút tao nhã"},{"en":"urbane host","vi":"chủ nhà khéo ứng xử"}],"wordFamily":["urbanely (adv.)","urbanity (n.)"],"synonyms":["suave","sophisticated","polished"],"antonyms":["uncouth"],"tipVi":"urbane chỉ sự lịch thiệp, tao nhã và giỏi giao tiếp xã hội; trong khi urban có nghĩa là thuộc về thành phố.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quagmire', 'en-c2-3', 'quagmire', '/ˈkwæɡmaɪr/', 'C2', 'vũng lầy; tình trạng khó khăn phức tạp; hoàn cảnh tiến thối lưỡng nan; vũng bùn lầy', 'n.', NULL, 'Đồng nghĩa: predicament', 'Thường dùng để ví von với hoàn cảnh phức tạp và khó thoát ra, không chỉ đơn thuần là khó khăn thông thường.', 'Our simple kitchen renovation became a quagmire of unexpected expenses.', NULL, 'Việc cải tạo nhà bếp tưởng chừng đơn giản của chúng tôi đã biến thành một vũng lầy tốn kém ngoài dự kiến.', '{"wordId":"quagmire","ukIpa":"/ˈkwɒɡmaɪə/","usIpa":"/ˈkwæɡmaɪr/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"A complicated, unpleasant situation that is difficult to escape.","vi":"vũng lầy; tình trạng khó khăn phức tạp; hoàn cảnh tiến thối lưỡng nan"},{"pos":"n.","en":"An area of soft wet ground that can trap you.","vi":"vũng bùn lầy"}],"examples":[{"en":"Our simple kitchen renovation became a quagmire of unexpected expenses.","vi":"Việc cải tạo nhà bếp tưởng chừng đơn giản của chúng tôi đã biến thành một vũng lầy tốn kém ngoài dự kiến.","audioKind":"ex"},{"en":"Without clear regulations, major infrastructure projects can become trapped in a quagmire of legal disputes and financial uncertainty.","vi":"Nếu thiếu các quy định rõ ràng, các dự án cơ sở hạ tầng lớn có thể rơi vào tình trạng vướng mắc bởi tranh chấp pháp lý và sự bất ổn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"a legal quagmire","vi":"vũng lầy pháp lý"},{"en":"a political quagmire","vi":"vũng lầy chính trị"},{"en":"be mired in a quagmire","vi":"sa lầy vào tình thế khó khăn"}],"wordFamily":[],"synonyms":["predicament"],"antonyms":[],"tipVi":"Thường dùng để ví von với hoàn cảnh phức tạp và khó thoát ra, không chỉ đơn thuần là khó khăn thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baroness', 'en-c2-3', 'baroness', '/ˈbærənəs/', 'C2', 'nữ nam tước; phu nhân nam tước', 'n.', 'baron (n.), barony (n.)', NULL, 'Có thể chỉ người phụ nữ tự mình giữ tước hiệu nam tước, hoặc là vợ của một nam tước.', 'The baroness welcomed visitors into her family''s old castle.', NULL, 'Nữ nam tước chào đón các du khách vào tòa lâu đài cổ của gia đình bà.', '{"wordId":"baroness","ukIpa":"/ˈbærənəs/","usIpa":"/ˈbærənəs/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"A woman holding a baron''s rank, or a baron''s wife.","vi":"nữ nam tước; phu nhân nam tước"}],"examples":[{"en":"The baroness welcomed visitors into her family''s old castle.","vi":"Nữ nam tước chào đón các du khách vào tòa lâu đài cổ của gia đình bà.","audioKind":"ex"},{"en":"The portrait of the baroness illustrates how clothing once communicated social rank and wealth.","vi":"Bức chân dung của nữ nam tước minh họa cách trang phục thời xưa thể hiện địa vị xã hội và sự giàu có.","audioKind":"ex2"}],"collocations":[{"en":"a life baroness","vi":"nữ nam tước suốt đời"},{"en":"the title of baroness","vi":"tước hiệu nữ nam tước"}],"wordFamily":["baron (n.)","barony (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ người phụ nữ tự mình giữ tước hiệu nam tước, hoặc là vợ của một nam tước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_venerate', 'en-c2-3', 'venerate', '/ˈvenəreɪt/', 'C2', 'tôn kính; kính trọng', 'v.', 'veneration (n.), venerable (adj.)', 'Đồng nghĩa: revere, honour · Trái nghĩa: despise', 'Từ trang trọng, mức độ mạnh hơn respect; đi thẳng với tân ngữ phía sau.', 'People here venerate the elder who founded this school.', NULL, 'Mọi người ở đây rất kính trọng vị trưởng bối đã sáng lập ra ngôi trường này.', '{"wordId":"venerate","ukIpa":"/ˈvenəreɪt/","usIpa":"/ˈvenəreɪt/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To regard someone or something with deep respect.","vi":"tôn kính; kính trọng"}],"examples":[{"en":"People here venerate the elder who founded this school.","vi":"Mọi người ở đây rất kính trọng vị trưởng bối đã sáng lập ra ngôi trường này.","audioKind":"ex"},{"en":"Many societies venerate historic buildings because they represent shared cultural achievements and a connection with the past.","vi":"Nhiều xã hội tôn kính các công trình lịch sử vì chúng đại diện cho các thành tựu văn hóa chung và sự gắn kết với quá khứ.","audioKind":"ex2"}],"collocations":[{"en":"venerate ancestors","vi":"kính cẩn tổ tiên"},{"en":"venerate as a hero","vi":"tôn kính như một anh hùng"},{"en":"widely venerated","vi":"được tôn kính rộng rãi"}],"wordFamily":["veneration (n.)","venerable (adj.)"],"synonyms":["revere","honour"],"antonyms":["despise"],"tipVi":"Từ trang trọng, mức độ mạnh hơn respect; đi thẳng với tân ngữ phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mercenary', 'en-c2-3', 'mercenary', '/ˈmɝːsəneri/', 'C2', 'chỉ quan tâm đến tiền bạc hơn là các yếu tố khác (hám lợi); lính đánh thuê được trả tiền để chiến đấu cho quân đội hoặc tổ chức nước ngoài', 'adj.', NULL, 'Đồng nghĩa: money-minded · Trái nghĩa: altruistic', 'Tính từ mang sắc thái tiêu cực, nhấn mạnh việc chỉ coi trọng tiền bạc; danh từ chỉ lính đánh thuê.', 'His mercenary attitude spoiled our plans for the charity.', NULL, 'Thái độ hám lợi của anh ta đã làm hỏng các kế hoạch làm từ thiện của chúng tôi.', '{"wordId":"mercenary","ukIpa":"/ˈmɜːsənəri/","usIpa":"/ˈmɝːsəneri/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Caring mainly about money rather than other considerations","vi":"chỉ quan tâm đến tiền bạc hơn là các yếu tố khác (hám lợi)"},{"pos":"n.","en":"A soldier paid to fight for a foreign army or group","vi":"lính đánh thuê được trả tiền để chiến đấu cho quân đội hoặc tổ chức nước ngoài"}],"examples":[{"en":"His mercenary attitude spoiled our plans for the charity.","vi":"Thái độ hám lợi của anh ta đã làm hỏng các kế hoạch làm từ thiện của chúng tôi.","audioKind":"ex"},{"en":"A purely mercenary approach to healthcare risks placing financial returns above the needs of patients.","vi":"Cách tiếp cận chăm sóc sức khỏe mang tính chất hoàn toàn vụ lợi có nguy cơ đặt lợi ích tài chính lên trên nhu cầu của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"mercenary motives","vi":"động cơ vụ lợi"},{"en":"mercenary attitude","vi":"thái độ hám lợi"},{"en":"mercenary soldiers","vi":"lính đánh thuê"}],"wordFamily":[],"synonyms":["money-minded"],"antonyms":["altruistic"],"tipVi":"Tính từ mang sắc thái tiêu cực, nhấn mạnh việc chỉ coi trọng tiền bạc; danh từ chỉ lính đánh thuê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhort', 'en-c2-3', 'exhort', '/ɪɡˈzɔːrt/', 'C2', 'thúc giục; hô hào; khuyên răn mạnh mẽ', 'v.', 'exhortation (n.), exhortative (adj.)', 'Đồng nghĩa: urge, encourage · Trái nghĩa: discourage, dissuade', 'Là từ trang trọng: exhort sb to do, mang ý nghĩa mạnh mẽ hơn việc đưa ra lời khuyên thông thường.', 'Our coach exhorted us to keep trying until the end.', NULL, 'Huấn luyện viên đã thúc giục chúng tôi tiếp tục cố gắng cho đến phút cuối cùng.', '{"wordId":"exhort","ukIpa":"/ɪɡˈzɔːt/","usIpa":"/ɪɡˈzɔːrt/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To strongly urge someone to do something.","vi":"thúc giục; hô hào; khuyên răn mạnh mẽ"}],"examples":[{"en":"Our coach exhorted us to keep trying until the end.","vi":"Huấn luyện viên đã thúc giục chúng tôi tiếp tục cố gắng cho đến phút cuối cùng.","audioKind":"ex"},{"en":"Public health campaigns exhort citizens to exercise regularly, but affordable facilities are also needed to support lasting change.","vi":"Các chiến dịch y tế cộng đồng kêu gọi người dân thường xuyên tập thể dục, nhưng cũng cần có các cơ sở vật chất với chi phí hợp lý để hỗ trợ sự thay đổi lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"exhort someone to act","vi":"thúc giục ai đó hành động"},{"en":"exhort citizens to vote","vi":"kêu gọi công dân đi bầu cử"}],"wordFamily":["exhortation (n.)","exhortative (adj.)"],"synonyms":["urge","encourage"],"antonyms":["discourage","dissuade"],"tipVi":"Là từ trang trọng: exhort sb to do, mang ý nghĩa mạnh mẽ hơn việc đưa ra lời khuyên thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vindicate', 'en-c2-3', 'vindicate', '/ˈvɪndɪkeɪt/', 'C2', 'minh oan; chứng minh là đúng; bảo vệ chính đáng', 'v.', 'vindication (n.)', 'Đồng nghĩa: justify, exonerate', 'Nhấn mạnh việc dùng bằng chứng hoặc kết quả thực tế để chứng minh sự đúng đắn, không chỉ là lời biện hộ bằng miệng.', 'The security footage vindicated the cleaner accused of stealing.', NULL, 'Đoạn camera an ninh đã minh oan cho nhân viên vệ sinh bị cáo buộc ăn trộm.', '{"wordId":"vindicate","ukIpa":"/ˈvɪndɪkeɪt/","usIpa":"/ˈvɪndɪkeɪt/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To prove someone innocent or show that something was justified.","vi":"minh oan; chứng minh là đúng; bảo vệ chính đáng"}],"examples":[{"en":"The security footage vindicated the cleaner accused of stealing.","vi":"Đoạn camera an ninh đã minh oan cho nhân viên vệ sinh bị cáo buộc ăn trộm.","audioKind":"ex"},{"en":"The significant decline in road accidents appears to vindicate the council''s decision to introduce lower speed limits.","vi":"Sự sụt giảm đáng kể về số vụ tai nạn giao thông dường như đã chứng minh quyết định ban hành giới hạn tốc độ thấp hơn của hội đồng thành phố là hoàn toàn đúng đắn.","audioKind":"ex2"}],"collocations":[{"en":"vindicate a decision","vi":"chứng minh một quyết định là đúng"},{"en":"vindicate an approach","vi":"chứng minh một phương pháp là hợp lý"},{"en":"feel vindicated","vi":"cảm thấy được minh oan"}],"wordFamily":["vindication (n.)"],"synonyms":["justify","exonerate"],"antonyms":[],"tipVi":"Nhấn mạnh việc dùng bằng chứng hoặc kết quả thực tế để chứng minh sự đúng đắn, không chỉ là lời biện hộ bằng miệng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exalt', 'en-c2-3', 'exalt', '/ɪɡˈzɔːlt/', 'C2', 'ca ngợi hết lời; tôn vinh; tôn lên; nâng cao địa vị', 'v.', 'exalted (adj.), exaltation (n.)', 'Đồng nghĩa: glorify, extol · Trái nghĩa: debase', 'Là từ mang phong cách trang trọng; dùng để chỉ sự tôn vinh cao độ, không phải là lời khen ngợi thông thường.', 'Her songs exalt the beauty of ordinary life.', NULL, 'Những bài hát của cô ấy ca ngợi vẻ đẹp của cuộc sống bình dị.', '{"wordId":"exalt","ukIpa":"/ɪɡˈzɔːlt/","usIpa":"/ɪɡˈzɔːlt/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"To praise someone or something very highly.","vi":"ca ngợi hết lời; tôn vinh"},{"pos":"v.","en":"To raise someone to a higher rank or position.","vi":"tôn lên; nâng cao địa vị"}],"examples":[{"en":"Her songs exalt the beauty of ordinary life.","vi":"Những bài hát của cô ấy ca ngợi vẻ đẹp của cuộc sống bình dị.","audioKind":"ex"},{"en":"Public monuments often exalt national heroes while overlooking the contributions of ordinary citizens.","vi":"Các đài tưởng niệm công cộng thường tôn vinh các anh hùng dân tộc trong khi lại bỏ quên những đóng góp của những người dân bình thường.","audioKind":"ex2"}],"collocations":[{"en":"exalt the virtues of","vi":"ca ngợi phẩm hạnh của"},{"en":"exalt someone to a position","vi":"đưa ai đó lên một vị trí cao"}],"wordFamily":["exalted (adj.)","exaltation (n.)"],"synonyms":["glorify","extol"],"antonyms":["debase"],"tipVi":"Là từ mang phong cách trang trọng; dùng để chỉ sự tôn vinh cao độ, không phải là lời khen ngợi thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_constitutive', 'en-c2-3', 'constitutive', '/ˈkɑːnstətuːtɪv/', 'C2', 'có tính cấu thành; tạo nên bản chất', 'adj.', 'constitute (v.), constitution (n.), constitutional (adj.)', NULL, 'Chỉ những yếu tố cấu thành bản chất của sự vật; từ "constitutional" mang nghĩa thuộc về hiến pháp.', 'For our club, cooperation is constitutive of its identity.', NULL, 'Đối với câu lạc bộ của chúng tôi, tinh thần hợp tác là yếu tố cấu thành bản sắc của nó.', '{"wordId":"constitutive","ukIpa":"/ˈkɒnstɪtjuːtɪv/","usIpa":"/ˈkɑːnstətuːtɪv/","cefr":"C2","topic":"society","senses":[{"pos":"adj.","en":"Helping to form something or define its essential nature.","vi":"có tính cấu thành; tạo nên bản chất"}],"examples":[{"en":"For our club, cooperation is constitutive of its identity.","vi":"Đối với câu lạc bộ của chúng tôi, tinh thần hợp tác là yếu tố cấu thành bản sắc của nó.","audioKind":"ex"},{"en":"Shared customs are constitutive of cultural identity, rather than merely optional features of community life.","vi":"Các phong tục chung là thành phần cấu thành bản sắc văn hóa, chứ không đơn thuần là những đặc điểm tùy chọn trong đời sống cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"constitutive of","vi":"cấu thành của"},{"en":"constitutive elements","vi":"các yếu tố cấu thành"},{"en":"constitutive role","vi":"vai trò cấu thành"}],"wordFamily":["constitute (v.)","constitution (n.)","constitutional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ những yếu tố cấu thành bản chất của sự vật; từ \"constitutional\" mang nghĩa thuộc về hiến pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harangue', 'en-c2-3', 'harangue', '/həˈræŋ/', 'C2', 'bài thuyết giáo dài và gay gắt; lời mắng mỏ sa sả; mắng mỏ dài dòng; diễn thuyết gay gắt', 'n.', NULL, 'Đồng nghĩa: tirade, diatribe', 'Mang sắc thái tiêu cực, nhấn mạnh vào sự dài dòng và gay gắt, không phải là một bài phát biểu thông thường.', 'His harangue about dirty dishes spoiled our quiet breakfast.', NULL, 'Lời mắng mỏ sa sả của anh ấy về đống bát đĩa bẩn đã phá hỏng bữa sáng yên bình của chúng tôi.', '{"wordId":"harangue","ukIpa":"/həˈræŋ/","usIpa":"/həˈræŋ/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"A long, forceful speech expressing anger or strong criticism.","vi":"bài thuyết giáo dài và gay gắt; lời mắng mỏ sa sả"},{"pos":"v.","en":"To speak angrily and at length to someone.","vi":"mắng mỏ dài dòng; diễn thuyết gay gắt"}],"examples":[{"en":"His harangue about dirty dishes spoiled our quiet breakfast.","vi":"Lời mắng mỏ sa sả của anh ấy về đống bát đĩa bẩn đã phá hỏng bữa sáng yên bình của chúng tôi.","audioKind":"ex"},{"en":"A lengthy harangue is unlikely to persuade citizens who expect constructive debate about public spending.","vi":"Một bài tràng giang đại hải gay gắt khó có thể thuyết phục được những công dân đang mong đợi một cuộc tranh luận mang tính xây dựng về chi tiêu công.","audioKind":"ex2"}],"collocations":[{"en":"a lengthy harangue","vi":"một bài tràng giang đại hải kéo dài"},{"en":"launch into a harangue","vi":"bắt đầu một bài tràng giang đại hải chỉ trích"},{"en":"harangue someone about something","vi":"la mắng ai đó một cách gay gắt về vấn đề gì"}],"wordFamily":[],"synonyms":["tirade","diatribe"],"antonyms":[],"tipVi":"Mang sắc thái tiêu cực, nhấn mạnh vào sự dài dòng và gay gắt, không phải là một bài phát biểu thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_partake', 'en-c2-3', 'partake', '/pɑːrˈteɪk/', 'C2', 'tham gia; góp mặt; thưởng thức; dùng (đồ ăn, thức uống)', 'v.', NULL, 'Đồng nghĩa: participate, join in', 'Từ mang tính trang trọng; dùng giới từ in khi mang nghĩa tham gia, và of khi mang nghĩa thưởng thức; dạng quá khứ là partook.', 'Everyone was invited to partake in the evening games.', NULL, 'Mọi người đều được mời tham gia các trò chơi buổi tối.', '{"wordId":"partake","ukIpa":"/pɑːˈteɪk/","usIpa":"/pɑːrˈteɪk/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"to take part in an activity","vi":"tham gia; góp mặt"},{"pos":"v.","en":"to eat or drink something, especially when offered","vi":"thưởng thức; dùng (đồ ăn, thức uống)"}],"examples":[{"en":"Everyone was invited to partake in the evening games.","vi":"Mọi người đều được mời tham gia các trò chơi buổi tối.","audioKind":"ex"},{"en":"Community centres enable residents of different ages to partake in activities that strengthen social connections.","vi":"Các trung tâm cộng đồng tạo điều kiện cho cư dân ở mọi lứa tuổi tham gia các hoạt động nhằm củng cố mối liên kết xã hội.","audioKind":"ex2"}],"collocations":[{"en":"partake in activities","vi":"tham gia các hoạt động"},{"en":"partake in celebrations","vi":"tham gia các lễ hội"},{"en":"partake of refreshments","vi":"thưởng thức trà bánh"}],"wordFamily":[],"synonyms":["participate","join in"],"antonyms":[],"tipVi":"Từ mang tính trang trọng; dùng giới từ in khi mang nghĩa tham gia, và of khi mang nghĩa thưởng thức; dạng quá khứ là partook.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_continuance', 'en-c2-3', 'continuance', '/kənˈtɪnjuəns/', 'C2', 'sự tiếp tục; sự duy trì; sự hoãn phiên tòa', 'n.', 'continue (v.), continuation (n.), continuous (adj.), continuity (n.)', 'Đồng nghĩa: continuation · Trái nghĩa: discontinuance, cessation', 'Từ dùng trong văn phong trang trọng; nghĩa pháp lý về "hoãn phiên tòa" chủ yếu dùng trong tiếng Anh - Mỹ.', 'The club''s continuance depends on help from local volunteers.', NULL, 'Sự tiếp tục hoạt động của câu lạc bộ phụ thuộc vào sự hỗ trợ từ các tình nguyện viên địa phương.', '{"wordId":"continuance","ukIpa":"/kənˈtɪnjuəns/","usIpa":"/kənˈtɪnjuəns/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"The state of continuing or being kept in existence.","vi":"sự tiếp tục; sự duy trì"},{"pos":"n.","en":"An official postponement of a court hearing or trial.","vi":"sự hoãn phiên tòa"}],"examples":[{"en":"The club''s continuance depends on help from local volunteers.","vi":"Sự tiếp tục hoạt động của câu lạc bộ phụ thuộc vào sự hỗ trợ từ các tình nguyện viên địa phương.","audioKind":"ex"},{"en":"The continuance of public funding is essential if rural libraries are to remain open.","vi":"Việc duy trì nguồn vốn công là điều cốt yếu để các thư viện vùng nông thôn tiếp tục mở cửa.","audioKind":"ex2"}],"collocations":[{"en":"continuance of support","vi":"sự duy trì hỗ trợ"},{"en":"continued existence and continuance","vi":"sự tiếp tục tồn tại và kéo dài"},{"en":"grant a continuance","vi":"chuẩn y hoãn phiên tòa"}],"wordFamily":["continue (v.)","continuation (n.)","continuous (adj.)","continuity (n.)"],"synonyms":["continuation"],"antonyms":["discontinuance","cessation"],"tipVi":"Từ dùng trong văn phong trang trọng; nghĩa pháp lý về \"hoãn phiên tòa\" chủ yếu dùng trong tiếng Anh - Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deliverance', 'en-c2-3', 'deliverance', '/dɪˈlɪvərəns/', 'C2', 'sự giải thoát; sự cứu rỗi', 'n.', 'deliver (v.), deliverer (n.)', 'Đồng nghĩa: rescue, liberation · Trái nghĩa: captivity', 'Từ mang văn phong trang trọng, thường xuất hiện trong ngữ cảnh văn học hoặc tôn giáo; hay đi với giới từ from.', 'The rescue boat brought deliverance from the rising flood.', NULL, 'Con thuyền cứu hộ đã mang lại sự giải thoát khỏi vùng nước lũ đang dâng cao.', '{"wordId":"deliverance","ukIpa":"/dɪˈlɪvərəns/","usIpa":"/dɪˈlɪvərəns/","cefr":"C2","topic":"society","senses":[{"pos":"n.","en":"The act of being freed from danger, suffering, or oppression","vi":"sự giải thoát; sự cứu rỗi"}],"examples":[{"en":"The rescue boat brought deliverance from the rising flood.","vi":"Con thuyền cứu hộ đã mang lại sự giải thoát khỏi vùng nước lũ đang dâng cao.","audioKind":"ex"},{"en":"For isolated communities, the arrival of emergency supplies can represent deliverance from prolonged hunger and hardship.","vi":"Đối với các cộng đồng bị cô lập, sự xuất hiện của hàng cứu trợ khẩn cấp có thể mang ý nghĩa thoát khỏi nạn đói và gian khổ kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"deliverance from danger","vi":"thoát khỏi nguy hiểm"},{"en":"pray for deliverance","vi":"cầu xin sự giải cứu"},{"en":"bring deliverance","vi":"mang lại sự cứu rỗi"}],"wordFamily":["deliver (v.)","deliverer (n.)"],"synonyms":["rescue","liberation"],"antonyms":["captivity"],"tipVi":"Từ mang văn phong trang trọng, thường xuất hiện trong ngữ cảnh văn học hoặc tôn giáo; hay đi với giới từ from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sneer', 'en-c2-3', 'sneer', '/snɪr/', 'C2', 'chế giễu; mỉa mai; nụ cười mỉa mai; lời chế giễu', 'v.', 'sneering (adj.), sneeringly (adv.)', 'Đồng nghĩa: mock, scoff', 'Thường dùng cấu trúc sneer at; biểu thị thái độ khinh miệt, không phải là nụ cười thân thiện.', 'Don''t sneer at someone for asking a simple question.', NULL, 'Đừng chế giễu ai đó chỉ vì họ đặt một câu hỏi đơn giản.', '{"wordId":"sneer","ukIpa":"/snɪə/","usIpa":"/snɪr/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"show disrespect through an unkind smile or remark","vi":"chế giễu; mỉa mai"},{"pos":"n.","en":"an unkind expression or remark showing disrespect","vi":"nụ cười mỉa mai; lời chế giễu"}],"examples":[{"en":"Don''t sneer at someone for asking a simple question.","vi":"Đừng chế giễu ai đó chỉ vì họ đặt một câu hỏi đơn giản.","audioKind":"ex"},{"en":"When colleagues sneer at unfamiliar ideas, employees may become less willing to suggest innovative solutions.","vi":"Khi các đồng nghiệp mỉa mai những ý tưởng lạ lẫm, nhân viên có thể cảm thấy ngại ngùng hơn trong việc đề xuất các giải pháp đổi mới.","audioKind":"ex2"}],"collocations":[{"en":"sneer at someone","vi":"chế giễu ai đó"},{"en":"a contemptuous sneer","vi":"nụ cười khinh miệt"},{"en":"with a sneer","vi":"với vẻ mặt mỉa mai"}],"wordFamily":["sneering (adj.)","sneeringly (adv.)"],"synonyms":["mock","scoff"],"antonyms":[],"tipVi":"Thường dùng cấu trúc sneer at; biểu thị thái độ khinh miệt, không phải là nụ cười thân thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profess', 'en-c2-3', 'profess', '/prəˈfes/', 'C2', 'tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành; theo đuổi một tôn giáo nhất định', 'v.', 'professed (adj.)', 'Đồng nghĩa: claim, declare', 'Từ trang trọng; profess to do thường ngụ ý rằng lời tuyên bố chưa chắc đã đúng sự thật.', 'My cousins profess to love cooking but always order takeaway.', NULL, 'Họ hàng của tôi lớn tiếng tuyên bố rất thích nấu ăn nhưng lúc nào cũng gọi đồ ăn mang về.', '{"wordId":"profess","ukIpa":"/prəˈfes/","usIpa":"/prəˈfes/","cefr":"C2","topic":"society","senses":[{"pos":"v.","en":"to openly claim a feeling or belief, sometimes without sincerity","vi":"tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành"},{"pos":"v.","en":"to declare that you follow a particular religion","vi":"tuyên bố; theo đuổi một tôn giáo nhất định"}],"examples":[{"en":"My cousins profess to love cooking but always order takeaway.","vi":"Họ hàng của tôi lớn tiếng tuyên bố rất thích nấu ăn nhưng lúc nào cũng gọi đồ ăn mang về.","audioKind":"ex"},{"en":"Many companies profess a commitment to sustainability, yet their production methods continue to generate substantial waste.","vi":"Nhiều công ty cam kết theo đuổi sự phát triển bền vững, song phương thức sản xuất của họ vẫn tiếp tục tạo ra lượng rác thải khổng lồ.","audioKind":"ex2"}],"collocations":[{"en":"profess to know","vi":"nhận là biết"},{"en":"profess ignorance","vi":"giả vờ không biết; tuyên bố không hay biết"},{"en":"profess a belief","vi":"công khai bày tỏ niềm tin"},{"en":"profess a religion","vi":"tuyên bố theo đạo"}],"wordFamily":["professed (adj.)"],"synonyms":["claim","declare"],"antonyms":[],"tipVi":"Từ trang trọng; profess to do thường ngụ ý rằng lời tuyên bố chưa chắc đã đúng sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_3_1', 'en-c2-3', 'Cách dùng “redound” (v.) — mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)', 'redound to someone''s credit  ·  redound to the benefit of  ·  redound to someone''s honour', 'Từ này mang tính trang trọng và ít khi dùng; thường đi với giới từ to, không trực tiếp đi theo sau tân ngữ để biểu thị sự gia tăng.', NULL, '[{"hanzi":"Your generosity will redound to the whole team''s credit.","pinyin":"","meaning":"Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ."},{"hanzi":"Sustained investment in public libraries can redound to the benefit of communities by expanding access to knowledge.","pinyin":"","meaning":"Việc đầu tư liên tục vào các thư viện công cộng có thể đem lại lợi ích thiết thực cho cộng đồng thông qua việc mở rộng khả năng tiếp cận tri thức."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_3_2', 'en-c2-3', 'Cách dùng “partake” (v.) — tham gia; góp mặt', 'partake in activities  ·  partake in celebrations  ·  partake of refreshments', 'Từ mang tính trang trọng; dùng giới từ in khi mang nghĩa tham gia, và of khi mang nghĩa thưởng thức; dạng quá khứ là partook.', 'Đồng nghĩa: participate, join in', '[{"hanzi":"Everyone was invited to partake in the evening games.","pinyin":"","meaning":"Mọi người đều được mời tham gia các trò chơi buổi tối."},{"hanzi":"Community centres enable residents of different ages to partake in activities that strengthen social connections.","pinyin":"","meaning":"Các trung tâm cộng đồng tạo điều kiện cho cư dân ở mọi lứa tuổi tham gia các hoạt động nhằm củng cố mối liên kết xã hội."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_3_3', 'en-c2-3', 'Cách dùng “vindicate” (v.) — minh oan; chứng minh là đúng; bảo vệ chính đáng', 'vindicate a decision  ·  vindicate an approach  ·  feel vindicated', 'Nhấn mạnh việc dùng bằng chứng hoặc kết quả thực tế để chứng minh sự đúng đắn, không chỉ là lời biện hộ bằng miệng.', 'Họ từ (Word Family): vindication (n.) | Đồng nghĩa: justify, exonerate', '[{"hanzi":"The security footage vindicated the cleaner accused of stealing.","pinyin":"","meaning":"Đoạn camera an ninh đã minh oan cho nhân viên vệ sinh bị cáo buộc ăn trộm."},{"hanzi":"The significant decline in road accidents appears to vindicate the council''s decision to introduce lower speed limits.","pinyin":"","meaning":"Sự sụt giảm đáng kể về số vụ tai nạn giao thông dường như đã chứng minh quyết định ban hành giới hạn tốc độ thấp hơn của hội đồng thành phố là hoàn toàn đúng đắn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_3_4', 'en-c2-3', 'Cách dùng “deliverance” (n.) — sự giải thoát; sự cứu rỗi', 'deliverance from danger  ·  pray for deliverance  ·  bring deliverance', 'Từ mang văn phong trang trọng, thường xuất hiện trong ngữ cảnh văn học hoặc tôn giáo; hay đi với giới từ from.', 'Họ từ (Word Family): deliver (v.), deliverer (n.) | Đồng nghĩa: rescue, liberation · Trái nghĩa: captivity', '[{"hanzi":"The rescue boat brought deliverance from the rising flood.","pinyin":"","meaning":"Con thuyền cứu hộ đã mang lại sự giải thoát khỏi vùng nước lũ đang dâng cao."},{"hanzi":"For isolated communities, the arrival of emergency supplies can represent deliverance from prolonged hunger and hardship.","pinyin":"","meaning":"Đối với các cộng đồng bị cô lập, sự xuất hiện của hàng cứu trợ khẩn cấp có thể mang ý nghĩa thoát khỏi nạn đói và gian khổ kéo dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_3_1', 'en-c2-3', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_1', 'ten_c2_3_1', 'strife', 'Arguments over money caused constant strife in the family.', 'Arguments over money caused constant strife in the family.', '/straɪf/', 'Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_2', 'ten_c2_3_1', 'skirmish', 'Their skirmish over the remote ended with a compromise.', 'Their skirmish over the remote ended with a compromise.', '/ˈskɝːmɪʃ/', 'Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_3', 'ten_c2_3_1', 'redound', 'Your generosity will redound to the whole team''s credit.', 'Your generosity will redound to the whole team''s credit.', '/rɪˈdaʊnd/', 'Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_4', 'ten_c2_3_1', 'fetter', 'Don''t let fear fetter your plans to travel alone.', 'Don''t let fear fetter your plans to travel alone.', '/ˈfetər/', 'Đừng để nỗi sợ hãi cản trở kế hoạch đi du lịch một mình của bạn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_5', 'ten_c2_3_1', 'urbane', 'Our urbane host welcomed everyone with a warm smile.', 'Our urbane host welcomed everyone with a warm smile.', '/ɝːˈbeɪn/', 'Người chủ nhà lịch lãm của chúng tôi chào đón mọi người bằng nụ cười ấm áp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_6', 'ten_c2_3_1', 'quagmire', 'Our simple kitchen renovation became a quagmire of unexpected expenses.', 'Our simple kitchen renovation became a quagmire of unexpected expenses.', '/ˈkwæɡmaɪr/', 'Việc cải tạo nhà bếp tưởng chừng đơn giản của chúng tôi đã biến thành một vũng lầy tốn kém ngoài dự kiến.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_7', 'ten_c2_3_1', 'baroness', 'The baroness welcomed visitors into her family''s old castle.', 'The baroness welcomed visitors into her family''s old castle.', '/ˈbærənəs/', 'Nữ nam tước chào đón các du khách vào tòa lâu đài cổ của gia đình bà.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_1_8', 'ten_c2_3_1', 'venerate', 'People here venerate the elder who founded this school.', 'People here venerate the elder who founded this school.', '/ˈvenəreɪt/', 'Mọi người ở đây rất kính trọng vị trưởng bối đã sáng lập ra ngôi trường này.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_3_1_1', 'en-c2-3', 'ten_c2_3_1', 'listening', 'listening', 'Arguments over money caused constant strife in the family.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nữ nam tước chào đón các du khách vào tòa lâu đài cổ của gia đình bà.","Đoạn camera an ninh đã minh oan cho nhân viên vệ sinh bị cáo buộc ăn trộm.","Đừng chế giễu ai đó chỉ vì họ đặt một câu hỏi đơn giản.","Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình."]'::jsonb, 3, 'Arguments over money caused constant strife in the family. → Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_3_1_2', 'en-c2-3', 'ten_c2_3_1', 'listening', 'listening', 'Their skirmish over the remote ended with a compromise.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thái độ hám lợi của anh ta đã làm hỏng các kế hoạch làm từ thiện của chúng tôi.","Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.","Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình.","Đoạn camera an ninh đã minh oan cho nhân viên vệ sinh bị cáo buộc ăn trộm."]'::jsonb, 1, 'Their skirmish over the remote ended with a compromise. → Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_3_1_3', 'en-c2-3', 'ten_c2_3_1', 'listening', 'listening', 'Your generosity will redound to the whole team''s credit.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ.","Người chủ nhà lịch lãm của chúng tôi chào đón mọi người bằng nụ cười ấm áp.","Con thuyền cứu hộ đã mang lại sự giải thoát khỏi vùng nước lũ đang dâng cao.","Thái độ hám lợi của anh ta đã làm hỏng các kế hoạch làm từ thiện của chúng tôi."]'::jsonb, 0, 'Your generosity will redound to the whole team''s credit. → Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_3_2', 'en-c2-3', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_2_1', 'ten_c2_3_2', 'strife', 'Economic inequality can fuel social strife when communities feel excluded from opportunities for a better life.', 'Economic inequality can fuel social strife when communities feel excluded from opportunities for a better life.', '/straɪf/', 'Bất bình đẳng kinh tế có thể châm ngòi cho xung đột xã hội khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các cơ hội vươn lên cuộc sống tốt đẹp hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_2_2', 'ten_c2_3_2', 'skirmish', 'A brief border skirmish can undermine diplomatic progress and discourage investment in nearby communities.', 'A brief border skirmish can undermine diplomatic progress and discourage investment in nearby communities.', '/ˈskɝːmɪʃ/', 'Một cuộc xung đột biên giới chớp nhoáng có thể làm suy yếu tiến trình ngoại giao và làm nản lòng các nhà đầu tư vào các cộng đồng lân cận.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_2_3', 'ten_c2_3_2', 'redound', 'Sustained investment in public libraries can redound to the benefit of communities by expanding access to knowledge.', 'Sustained investment in public libraries can redound to the benefit of communities by expanding access to knowledge.', '/rɪˈdaʊnd/', 'Việc đầu tư liên tục vào các thư viện công cộng có thể đem lại lợi ích thiết thực cho cộng đồng thông qua việc mở rộng khả năng tiếp cận tri thức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_2_4', 'ten_c2_3_2', 'fetter', 'Excessive administrative requirements can fetter small businesses, preventing them from investing in innovation and creating jobs.', 'Excessive administrative requirements can fetter small businesses, preventing them from investing in innovation and creating jobs.', '/ˈfetər/', 'Những yêu cầu hành chính quá mức có thể kìm hãm các doanh nghiệp nhỏ, khiến họ không thể đầu tư vào đổi mới sáng tạo và tạo ra việc làm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_2_5', 'ten_c2_3_2', 'urbane', 'An urbane manner can help diplomats build trust, although successful negotiations also require substantial expertise.', 'An urbane manner can help diplomats build trust, although successful negotiations also require substantial expertise.', '/ɝːˈbeɪn/', 'Phong thái lịch lãm có thể giúp các nhà ngoại giao xây dựng lòng tin, mặc dù các cuộc đàm phán thành công cũng đòi hỏi chuyên môn vững chắc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_3_2_6', 'ten_c2_3_2', 'quagmire', 'Without clear regulations, major infrastructure projects can become trapped in a quagmire of legal disputes and financial uncertainty.', 'Without clear regulations, major infrastructure projects can become trapped in a quagmire of legal disputes and financial uncertainty.', '/ˈkwæɡmaɪr/', 'Nếu thiếu các quy định rõ ràng, các dự án cơ sở hạ tầng lớn có thể rơi vào tình trạng vướng mắc bởi tranh chấp pháp lý và sự bất ổn tài chính.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_3_2_1', 'en-c2-3', 'ten_c2_3_2', 'listening', 'listening', 'Economic inequality can fuel social strife when communities feel excluded from opportunities for a better life.', NULL, 'Trong câu vừa nghe, từ “strife” mang nghĩa nào sau đây?', '["sự xung đột; sự tranh chấp","bán thiếu cân; gian lận trọng lượng","nhão; mềm nhão (cơ bắp)","phát triển nhanh chóng và ngoạn mục; vụt sáng"]'::jsonb, 0, '“strife” (/straɪf/): sự xung đột; sự tranh chấp. Câu đầy đủ: Economic inequality can fuel social strife when communities feel excluded from opportunities for a better life.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_3_2_2', 'en-c2-3', 'ten_c2_3_2', 'listening', 'listening', 'A brief border skirmish can undermine diplomatic progress and discourage investment in nearby communities.', NULL, 'Trong câu vừa nghe, từ “skirmish” mang nghĩa nào sau đây?', '["sự ngây ngất; niềm vui sướng tột độ; sự cuồng nhiệt","cuộc đụng độ nhỏ; xung đột ngắn","minh oan; chứng minh là đúng; bảo vệ chính đáng","dược sĩ; nhà bào chế thuốc"]'::jsonb, 1, '“skirmish” (/ˈskɝːmɪʃ/): cuộc đụng độ nhỏ; xung đột ngắn. Câu đầy đủ: A brief border skirmish can undermine diplomatic progress and discourage investment in nearby communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
