INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_1', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'strife', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mãnh liệt; quyết liệt","gây thiệt hại nặng nề; phá sản","sự tiếp tục; sự duy trì","sự xung đột; sự tranh chấp"]'::jsonb, 3, 'strife (/straɪf/) → sự xung đột; sự tranh chấp', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_2', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'Their skirmish over the remote ended with a compromise.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc cải tạo nhà bếp tưởng chừng đơn giản của chúng tôi đã biến thành một vũng lầy tốn kém ngoài dự kiến.","Đừng để nỗi sợ hãi cản trở kế hoạch đi du lịch một mình của bạn.","Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.","Thái độ hám lợi của anh ta đã làm hỏng các kế hoạch làm từ thiện của chúng tôi."]'::jsonb, 2, 'Their skirmish over the remote ended with a compromise. → Cuộc cãi vã nhỏ của họ về chiếc điều khiển từ xa đã kết thúc bằng một sự thỏa hiệp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_3', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'redound', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["báng bổ; xúc phạm thần linh; thô tục","bãi bỏ; hủy bỏ (luật, thỏa thuận)","mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)","ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý"]'::jsonb, 2, 'redound (/rɪˈdaʊnd/) → mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_4', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'Don''t let fear fetter your plans to travel alone.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đừng để nỗi sợ hãi cản trở kế hoạch đi du lịch một mình của bạn.","Lời mắng mỏ sa sả của anh ấy về đống bát đĩa bẩn đã phá hỏng bữa sáng yên bình của chúng tôi.","Sự hào phóng của bạn sẽ mang lại uy tín cho toàn bộ đội ngũ.","Đối với câu lạc bộ của chúng tôi, tinh thần hợp tác là yếu tố cấu thành bản sắc của nó."]'::jsonb, 0, 'Don''t let fear fetter your plans to travel alone. → Đừng để nỗi sợ hãi cản trở kế hoạch đi du lịch một mình của bạn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_5', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'urbane', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lịch lãm; tao nhã; khéo ứng xử","bóp méo; xuyên tạc; làm bại hoại","dồi dào; vô kể; tuôn trào","thấu hiểu; thăm dò sâu; khảo sát kỹ"]'::jsonb, 0, 'urbane (/ɝːˈbeɪn/) → lịch lãm; tao nhã; khéo ứng xử', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_6', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'Our simple kitchen renovation became a quagmire of unexpected expenses.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nữ nam tước chào đón các du khách vào tòa lâu đài cổ của gia đình bà.","Việc cải tạo nhà bếp tưởng chừng đơn giản của chúng tôi đã biến thành một vũng lầy tốn kém ngoài dự kiến.","Họ hàng của tôi lớn tiếng tuyên bố rất thích nấu ăn nhưng lúc nào cũng gọi đồ ăn mang về.","Đừng chế giễu ai đó chỉ vì họ đặt một câu hỏi đơn giản."]'::jsonb, 1, 'Our simple kitchen renovation became a quagmire of unexpected expenses. → Việc cải tạo nhà bếp tưởng chừng đơn giản của chúng tôi đã biến thành một vũng lầy tốn kém ngoài dự kiến.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_7', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'baroness', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nữ nam tước; phu nhân nam tước","thỏi kim loại được đúc khối để lưu trữ hoặc gia công","benzen","ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý"]'::jsonb, 0, 'baroness (/ˈbærənəs/) → nữ nam tước; phu nhân nam tước', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_8', 'en-c2-3', NULL, 'comprehensive_test', 'listening', 'People here venerate the elder who founded this school.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mọi người ở đây rất kính trọng vị trưởng bối đã sáng lập ra ngôi trường này.","Những cuộc cãi vã vì tiền bạc đã gây ra sự bất hòa liên tục trong gia đình.","Nữ nam tước chào đón các du khách vào tòa lâu đài cổ của gia đình bà.","Đối với câu lạc bộ của chúng tôi, tinh thần hợp tác là yếu tố cấu thành bản sắc của nó."]'::jsonb, 0, 'People here venerate the elder who founded this school. → Mọi người ở đây rất kính trọng vị trưởng bối đã sáng lập ra ngôi trường này.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
