INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_18', 'en-c2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Economic inequality can fuel social strife when communities feel excluded from opportunities for a better life.', 'Dựa vào câu trên, từ “strife” có nghĩa phù hợp nhất là gì?', '["sự xung đột; sự tranh chấp","lớp bọt bẩn; váng bẩn","xóa sạch; phá hủy hoàn toàn; làm biến mất không dấu vết","tỉ mỉ; cẩn trọng; chu đáo"]'::jsonb, 0, 'strife: sự xung đột; sự tranh chấp. Dịch cả câu: Bất bình đẳng kinh tế có thể châm ngòi cho xung đột xã hội khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các cơ hội vươn lên cuộc sống tốt đẹp hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_19', 'en-c2-3', NULL, 'comprehensive_test', 'reading', NULL, 'A brief border skirmish can undermine diplomatic progress and discourage investment in nearby communities.', 'Dựa vào câu trên, từ “skirmish” có nghĩa phù hợp nhất là gì?', '["cuộc đụng độ nhỏ; xung đột ngắn","sự giải thoát; sự cứu rỗi","sức gợi cảm; nỗi niềm xót xa; tính bi cảm","cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết"]'::jsonb, 0, 'skirmish: cuộc đụng độ nhỏ; xung đột ngắn; cuộc cãi vã nhỏ; tranh cãi chớp nhoáng; xảy ra xung đột nhỏ; cãi vã chớp nhoáng. Dịch cả câu: Một cuộc xung đột biên giới chớp nhoáng có thể làm suy yếu tiến trình ngoại giao và làm nản lòng các nhà đầu tư vào các cộng đồng lân cận.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_20', 'en-c2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Sustained investment in public libraries can redound to the benefit of communities by expanding access to knowledge.', 'Dựa vào câu trên, từ “redound” có nghĩa phù hợp nhất là gì?', '["ở mức độ trung bình; bình thường","định giá bằng một loại tiền tệ cụ thể","lan tỏa; bao trùm; thấm đượm khắp nơi","mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)"]'::jsonb, 3, 'redound: mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích). Dịch cả câu: Việc đầu tư liên tục vào các thư viện công cộng có thể đem lại lợi ích thiết thực cho cộng đồng thông qua việc mở rộng khả năng tiếp cận tri thức.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_21', 'en-c2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Excessive administrative requirements can fetter small businesses, preventing them from investing in innovation and creating jobs.', 'Dựa vào câu trên, từ “fetter” có nghĩa phù hợp nhất là gì?', '["cản trở; hạn chế","dẻo quánh; dính","kiên định, kiên cường, không bỏ cuộc dù gặp khó khăn","vó nước; xoáy nước; dòng xoáy"]'::jsonb, 0, 'fetter: cản trở; hạn chế; sự trói buộc; xiềng xích. Dịch cả câu: Những yêu cầu hành chính quá mức có thể kìm hãm các doanh nghiệp nhỏ, khiến họ không thể đầu tư vào đổi mới sáng tạo và tạo ra việc làm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_22', 'en-c2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự giải thoát; sự cứu rỗi”', '["deliverance","shamble","alga","zealous"]'::jsonb, 0, 'sự giải thoát; sự cứu rỗi → deliverance (/dɪˈlɪvərəns/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_23', 'en-c2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chế giễu; mỉa mai”', '["delusive","modish","sneer","loll"]'::jsonb, 2, 'chế giễu; mỉa mai → sneer (/snɪr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_3_24', 'en-c2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành”', '["reportage","furor","paraphernalia","profess"]'::jsonb, 3, 'tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành → profess (/prəˈfes/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-4', 'en', 'Bài 4: Thiên nhiên & Thời tiết - CEFR C2', 'CEFR C2', 'C2 · Thiên nhiên', '18 từ vựng Tiếng Anh CEFR C2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6004, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wreathe', 'en-c2-4', 'wreathe', '/riːð/', 'C2', 'bao quanh; lượn lờ; bao phủ', 'v.', 'wreath (n.)', 'Đồng nghĩa: envelop, surround', 'Từ mang tính văn chương; wreathe có phát âm đuôi /ð/, còn wreath phát âm đuôi /θ/.', 'Thin wisps of steam wreathed her face above the bowl.', NULL, 'Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.', '{"wordId":"wreathe","ukIpa":"/riːð/","usIpa":"/riːð/","cefr":"C2","topic":"nature","senses":[{"pos":"v.","en":"to surround or cover something, especially with smoke or mist","vi":"bao quanh; lượn lờ; bao phủ"}],"examples":[{"en":"Thin wisps of steam wreathed her face above the bowl.","vi":"Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.","audioKind":"ex"},{"en":"Smoke from nearby factories can wreathe residential buildings, highlighting the need for stricter industrial emission controls.","vi":"Khói từ các nhà máy lân cận có thể bao trùm các khu dân cư, làm nổi bật sự cần thiết của việc thắt chặt kiểm soát khí thải công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"be wreathed in smoke","vi":"bị khói bao phủ"},{"en":"mist wreathes the hills","vi":"sương mù bao quanh đồi"},{"en":"a face wreathed in smiles","vi":"khuôn mặt rạng rỡ nụ cười"}],"wordFamily":["wreath (n.)"],"synonyms":["envelop","surround"],"antonyms":[],"tipVi":"Từ mang tính văn chương; wreathe có phát âm đuôi /ð/, còn wreath phát âm đuôi /θ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vortex', 'en-c2-4', 'vortex', '/ˈvɔːrteks/', 'C2', 'vó nước; xoáy nước; dòng xoáy; vũng lầy; cơn lốc (tình huống lôi cuốn vào sự hỗn loạn hoặc khó khăn)', 'n.', NULL, 'Đồng nghĩa: whirlpool', 'Dạng số nhiều có thể là vortices hoặc vortexes; ngoài ra còn dùng theo nghĩa bóng chỉ tình trạng khó khăn.', 'Leaves spun in a vortex beside the riverbank.', NULL, 'Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.', '{"wordId":"vortex","ukIpa":"/ˈvɔːteks/","usIpa":"/ˈvɔːrteks/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"A spinning mass of fluid drawing things towards its centre","vi":"vó nước; xoáy nước; dòng xoáy"},{"pos":"n.","en":"A situation that pulls people into increasing confusion or difficulty","vi":"vũng lầy; cơn lốc (tình huống lôi cuốn vào sự hỗn loạn hoặc khó khăn)"}],"examples":[{"en":"Leaves spun in a vortex beside the riverbank.","vi":"Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.","audioKind":"ex"},{"en":"Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.","vi":"Khi không thể tiếp cận các khoản tín dụng có mức lãi suất hợp lý, một số hộ gia đình sẽ rơi vào vòng xoáy nợ nần và bất ổn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"a swirling vortex","vi":"một dòng nước xoáy cuồn cuộn"},{"en":"a vortex of debt","vi":"vòng xoáy nợ nần"},{"en":"be sucked into a vortex","vi":"bị cuốn vào vòng xoáy"}],"wordFamily":[],"synonyms":["whirlpool"],"antonyms":[],"tipVi":"Dạng số nhiều có thể là vortices hoặc vortexes; ngoài ra còn dùng theo nghĩa bóng chỉ tình trạng khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ramify', 'en-c2-4', 'ramify', '/ˈræmɪfaɪ/', 'C2', 'phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau', 'v.', 'ramification (n.)', 'Đồng nghĩa: branch, subdivide', 'Từ trang trọng và ít dùng, thường chỉ hệ thống rễ, mạch máu hoặc mạng lưới chia nhánh vươn rộng.', 'The tree''s roots ramify beneath the old garden wall.', NULL, 'Rễ cây đâm tủa phân nhánh bên dưới bức tường cũ của khu vườn.', '{"wordId":"ramify","ukIpa":"/ˈræmɪfaɪ/","usIpa":"/ˈræmɪfaɪ/","cefr":"C2","topic":"nature","senses":[{"pos":"v.","en":"To divide or spread into branches or connected parts.","vi":"phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau"}],"examples":[{"en":"The tree''s roots ramify beneath the old garden wall.","vi":"Rễ cây đâm tủa phân nhánh bên dưới bức tường cũ của khu vườn.","audioKind":"ex"},{"en":"As transport networks ramify across rural regions, previously isolated communities gain better access to essential services.","vi":"Khi mạng lưới giao thông mở rộng và phân nhánh khắp các vùng nông thôn, các cộng đồng vốn bị cô lập trước đây sẽ có điều kiện tiếp cận tốt hơn với các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"roots ramify","vi":"rễ cây phân nhánh"},{"en":"ramify into branches","vi":"phân chia thành các nhánh nhỏ"}],"wordFamily":["ramification (n.)"],"synonyms":["branch","subdivide"],"antonyms":[],"tipVi":"Từ trang trọng và ít dùng, thường chỉ hệ thống rễ, mạch máu hoặc mạng lưới chia nhánh vươn rộng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opal', 'en-c2-4', 'opal', '/ˈoʊpəl/', 'C2', 'đá mắt mèo; ngọc ô-pan', 'n.', NULL, NULL, 'Trong ngữ cảnh trang sức thường gọi là "ngọc ô-pan"; không phải tất cả các loại khoáng vật này đều có hiện tượng đổi màu.', 'The opal in her ring flashed green and blue.', NULL, 'Viên ngọc ô-pan trên nhẫn của cô ấy ánh lên sắc xanh lá và xanh dương.', '{"wordId":"opal","ukIpa":"/ˈəʊpəl/","usIpa":"/ˈoʊpəl/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"A gemstone often showing changing colours when light strikes it","vi":"đá mắt mèo; ngọc ô-pan"}],"examples":[{"en":"The opal in her ring flashed green and blue.","vi":"Viên ngọc ô-pan trên nhẫn của cô ấy ánh lên sắc xanh lá và xanh dương.","audioKind":"ex"},{"en":"Opal mining can provide employment in remote regions, although it may also disturb fragile desert environments.","vi":"Khai thác ngọc ô-pan có thể tạo việc làm ở các vùng hẻo lánh, dù nó cũng có thể phá hủy môi trường sa mạc mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"opal ring","vi":"nhẫn gắn đá ô-pan"},{"en":"opal mining","vi":"khai thác ngọc ô-pan"},{"en":"precious opal","vi":"đá ô-pan quý"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh trang sức thường gọi là \"ngọc ô-pan\"; không phải tất cả các loại khoáng vật này đều có hiện tượng đổi màu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eucalyptus', 'en-c2-4', 'eucalyptus', '/ˌjuːkəˈlɪptəs/', 'C2', 'cây khuynh diệp; cây bạch đàn', 'n.', NULL, NULL, 'Chỉ loài cây; eucalyptus oil chỉ tinh dầu chiết xuất từ lá bạch đàn.', 'A koala rested high in the eucalyptus tree.', NULL, 'Một chú koala đang nghỉ ngơi trên tán cao của cây bạch đàn.', '{"wordId":"eucalyptus","ukIpa":"/ˌjuːkəˈlɪptəs/","usIpa":"/ˌjuːkəˈlɪptəs/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"a tree mainly native to Australia, with strongly scented leaves","vi":"cây khuynh diệp; cây bạch đàn"}],"examples":[{"en":"A koala rested high in the eucalyptus tree.","vi":"Một chú koala đang nghỉ ngơi trên tán cao của cây bạch đàn.","audioKind":"ex"},{"en":"Planting eucalyptus outside its native range may affect local water supplies and reduce biodiversity.","vi":"Việc trồng cây bạch đàn bên ngoài vùng phân bố bản địa có thể ảnh hưởng đến nguồn nước địa phương và làm giảm đa dạng sinh học.","audioKind":"ex2"}],"collocations":[{"en":"eucalyptus tree","vi":"cây bạch đàn"},{"en":"eucalyptus oil","vi":"tinh dầu khuynh diệp"},{"en":"eucalyptus leaves","vi":"lá bạch đàn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ loài cây; eucalyptus oil chỉ tinh dầu chiết xuất từ lá bạch đàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arboreal', 'en-c2-4', 'arboreal', '/ɑːrˈbɔːriəl/', 'C2', 'sống trên cây; tính cây cối; thuộc về cây cối', 'adj.', NULL, NULL, 'Thường dùng trong sinh học và động vật học để mô tả các loài sinh sống chủ yếu trên cây.', 'The zoo''s arboreal snakes curled around branches above our heads.', NULL, 'Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi.', '{"wordId":"arboreal","ukIpa":"/ɑːˈbɔːriəl/","usIpa":"/ɑːrˈbɔːriəl/","cefr":"C2","topic":"nature","senses":[{"pos":"adj.","en":"living mainly in trees","vi":"sống trên cây; tính cây cối"},{"pos":"adj.","en":"relating to trees","vi":"thuộc về cây cối"}],"examples":[{"en":"The zoo''s arboreal snakes curled around branches above our heads.","vi":"Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi.","audioKind":"ex"},{"en":"Deforestation threatens arboreal species by removing the branches and canopy they depend on for survival.","vi":"Việc phá rừng đe dọa các loài sống trên cây bằng cách phá hủy các cành và tán lá mà chúng phụ thuộc để sinh tồn.","audioKind":"ex2"}],"collocations":[{"en":"arboreal species","vi":"loài sống trên cây"},{"en":"arboreal habitat","vi":"môi trường sống trên cây"},{"en":"arboreal mammals","vi":"động vật có vú sống trên cây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng trong sinh học và động vật học để mô tả các loài sinh sống chủ yếu trên cây.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bough', 'en-c2-4', 'bough', '/baʊ/', 'C2', 'cành lớn; nhánh cây chính', 'n.', NULL, 'Đồng nghĩa: branch, limb', 'Cách phát âm vần với từ cow; thường dùng cho cành to của cây, trong khi cành nhỏ dùng twig.', 'A heavy bough shaded the bench beside the pond.', NULL, 'Một nhánh cây lớn râm mát đã che bóng cho chiếc ghế băng bên bờ ao.', '{"wordId":"bough","ukIpa":"/baʊ/","usIpa":"/baʊ/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"a large branch of a tree","vi":"cành lớn; nhánh cây chính"}],"examples":[{"en":"A heavy bough shaded the bench beside the pond.","vi":"Một nhánh cây lớn râm mát đã che bóng cho chiếc ghế băng bên bờ ao.","audioKind":"ex"},{"en":"The broad boughs of mature trees provide shelter for wildlife and shade for people in urban parks.","vi":"Những cành cây xum xuê của các thân cổ thụ trong công viên thành phố cung cấp chỗ trú ẩn cho động vật hoang dã và bóng râm cho người dân.","audioKind":"ex2"}],"collocations":[{"en":"a low bough","vi":"cành cây lớn trĩu xuống"},{"en":"a spreading bough","vi":"cành cây lớn vươn rộng"}],"wordFamily":[],"synonyms":["branch","limb"],"antonyms":[],"tipVi":"Cách phát âm vần với từ cow; thường dùng cho cành to của cây, trong khi cành nhỏ dùng twig.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undulate', 'en-c2-4', 'undulate', '/ˈʌndʒəleɪt/', 'C2', 'uốn lượn; nhấp nhô; dập dờn', 'v.', 'undulation (n.), undulating (adj.)', 'Đồng nghĩa: ripple', 'Khi mô tả địa hình nhấp nhô, thường dùng tính từ undulating.', 'Long strands of seaweed undulate gently beneath the water.', NULL, 'Những dải rong biển dài uốn lượn nhẹ nhàng bên dưới mặt nước.', '{"wordId":"undulate","ukIpa":"/ˈʌndjʊleɪt/","usIpa":"/ˈʌndʒəleɪt/","cefr":"C2","topic":"nature","senses":[{"pos":"v.","en":"Move or rise and fall in a smooth, wave-like pattern.","vi":"uốn lượn; nhấp nhô; dập dờn"}],"examples":[{"en":"Long strands of seaweed undulate gently beneath the water.","vi":"Những dải rong biển dài uốn lượn nhẹ nhàng bên dưới mặt nước.","audioKind":"ex"},{"en":"The grasslands undulate towards the distant mountains, providing varied habitats for a wide range of species.","vi":"Những đồng cỏ nhấp nhô trải dài về phía những dãy núi ở đằng xa, tạo nên môi trường sống đa dạng cho vô số loài sinh vật.","audioKind":"ex2"}],"collocations":[{"en":"undulate gently","vi":"nhấp nhô nhẹ nhàng"},{"en":"undulating hills","vi":"những ngọn đồi nhấp nhô"},{"en":"undulating terrain","vi":"địa hình nhấp nhô"}],"wordFamily":["undulation (n.)","undulating (adj.)"],"synonyms":["ripple"],"antonyms":[],"tipVi":"Khi mô tả địa hình nhấp nhô, thường dùng tính từ undulating.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slithery', 'en-c2-4', 'slithery', '/ˈslɪðəri/', 'C2', 'trơn trượt; trườn uốn lượn', 'adj.', 'slither (v.)', 'Đồng nghĩa: slippery', 'Thường dùng để miêu tả rắn, lươn và các loài động vật có độ trơn hoặc chuyển động trườn uốn lượn.', 'A slithery eel wriggled out of the fishing net.', NULL, 'Một con lươn trơn trượt quẫy mình trườn ra khỏi lưới đánh cá.', '{"wordId":"slithery","ukIpa":"/ˈslɪðəri/","usIpa":"/ˈslɪðəri/","cefr":"C2","topic":"nature","senses":[{"pos":"adj.","en":"slippery or moving smoothly with a twisting motion","vi":"trơn trượt; trườn uốn lượn"}],"examples":[{"en":"A slithery eel wriggled out of the fishing net.","vi":"Một con lươn trơn trượt quẫy mình trườn ra khỏi lưới đánh cá.","audioKind":"ex"},{"en":"Children can overcome their fear of slithery animals through supervised observation and lessons about local wildlife.","vi":"Trẻ em có thể vượt qua nỗi sợ đối với các loài động vật trơn trượt thông qua việc quan sát có hướng dẫn và các bài học về động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a slithery snake","vi":"con rắn trườn uốn lượn"},{"en":"a slithery eel","vi":"con lươn trơn trượt"}],"wordFamily":["slither (v.)"],"synonyms":["slippery"],"antonyms":[],"tipVi":"Thường dùng để miêu tả rắn, lươn và các loài động vật có độ trơn hoặc chuyển động trườn uốn lượn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eddy', 'en-c2-4', 'eddy', '/ˈedi/', 'C2', 'vòng xoáy nước, luồng không khí xoáy; chuyển động xoáy tròn, tạo thành vũng xoáy', 'n.', NULL, NULL, 'Có thể chỉ dòng nước hoặc khí lưu chuyển động xoáy; dạng số nhiều là eddies.', 'A fallen leaf spun in an eddy beside the bridge.', NULL, 'Một chiếc lá rụng đang xoay tít trong dòng nước xoáy bên cạnh cây cầu.', '{"wordId":"eddy","ukIpa":"/ˈedi/","usIpa":"/ˈedi/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"A circular current in water or air.","vi":"vòng xoáy nước, luồng không khí xoáy"},{"pos":"v.","en":"To move in a circular current.","vi":"chuyển động xoáy tròn, tạo thành vũng xoáy"}],"examples":[{"en":"A fallen leaf spun in an eddy beside the bridge.","vi":"Một chiếc lá rụng đang xoay tít trong dòng nước xoáy bên cạnh cây cầu.","audioKind":"ex"},{"en":"Small eddies behind river barriers can trap floating waste and affect the movement of aquatic organisms.","vi":"Những dòng xoáy nhỏ phía sau các vật cản trên sông có thể giữ lại rác nổi và ảnh hưởng đến sự di chuyển của các loài sinh vật thủy sinh.","audioKind":"ex2"}],"collocations":[{"en":"a swirling eddy","vi":"dòng xoáy đang cuồn cuộn"},{"en":"river eddies","vi":"các dòng xoáy trên sông"},{"en":"eddy currents","vi":"dòng điện xoáy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ dòng nước hoặc khí lưu chuyển động xoáy; dạng số nhiều là eddies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_halibut', 'en-c2-4', 'halibut', '/ˈhælɪbət/', 'C2', 'cá bลม biển lớn; thịt cá bơn', 'n.', NULL, NULL, 'Khi chỉ con cá, dạng số nhiều thường vẫn giữ nguyên là "halibut"; khi chỉ thịt cá thì không đếm được.', 'We ordered grilled halibut with potatoes and fresh lemon.', NULL, 'Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi.', '{"wordId":"halibut","ukIpa":"/ˈhælɪbət/","usIpa":"/ˈhælɪbət/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"A large flat sea fish, also eaten as food","vi":"cá bลม biển lớn; thịt cá bơn"}],"examples":[{"en":"We ordered grilled halibut with potatoes and fresh lemon.","vi":"Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi.","audioKind":"ex"},{"en":"Strict fishing limits can help protect halibut populations while supporting the long-term livelihoods of coastal communities.","vi":"Các quy định hạn chế đánh bắt nghiêm ngặt có thể giúp bảo vệ quần thể cá bơn đồng thời duy trì sinh kế lâu dài cho các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"grilled halibut","vi":"cá bơn nướng"},{"en":"halibut fillet","vi":"phi lê cá bơn"},{"en":"halibut fishing","vi":"đánh bắt cá bơn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ con cá, dạng số nhiều thường vẫn giữ nguyên là \"halibut\"; khi chỉ thịt cá thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idyll', 'en-c2-4', 'idyll', '/ˈaɪdəl/', 'C2', 'khoảng thời gian yên bình, hạnh phúc (đặc biệt là ở vùng nông thôn); thơ điền viên, truyện ngắn viết về cảnh điền viên', 'n.', 'idyllic (adj.), idyllically (adv.)', NULL, 'Có thể chỉ thơ ca điền viên hoặc thường chỉ cuộc sống yên ả, thanh bình nơi thôn quê.', 'Our summer idyll ended when the noisy builders arrived.', NULL, 'Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện.', '{"wordId":"idyll","ukIpa":"/ˈɪdɪl/","usIpa":"/ˈaɪdəl/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"A peaceful, happy experience, especially in the countryside.","vi":"khoảng thời gian yên bình, hạnh phúc (đặc biệt là ở vùng nông thôn)"},{"pos":"n.","en":"A poem or short story describing peaceful country life.","vi":"thơ điền viên, truyện ngắn viết về cảnh điền viên"}],"examples":[{"en":"Our summer idyll ended when the noisy builders arrived.","vi":"Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện.","audioKind":"ex"},{"en":"The rural idyll portrayed in tourism campaigns often overlooks the economic difficulties faced by farming communities.","vi":"Cảnh sắc thôn quê thanh bình được khắc họa trong các chiến dịch quảng bá du lịch thường phớt lờ những khó khăn kinh tế mà các cộng đồng làm nông đang phải đối mặt.","audioKind":"ex2"}],"collocations":[{"en":"rural idyll","vi":"cảnh sắc thôn quê thanh bình"},{"en":"summer idyll","vi":"khoảng thời gian mùa hè yên ả"},{"en":"pastoral idyll","vi":"cuộc sống điền viên thơ mộng"}],"wordFamily":["idyllic (adj.)","idyllically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ thơ ca điền viên hoặc thường chỉ cuộc sống yên ả, thanh bình nơi thôn quê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turbot', 'en-c2-4', 'turbot', '/ˈtɝːbət/', 'C2', 'cá bơn lớn; thịt cá bơn lớn', 'n.', NULL, NULL, 'Khi chỉ thịt cá thì không đếm được; khi chỉ con cá thì dạng số nhiều thường vẫn là turbot.', 'We shared grilled turbot with potatoes by the harbour.', NULL, 'Chúng tôi cùng nhau thưởng thức món cá bơn nướng ăn kèm khoai tây ngay bên cảng.', '{"wordId":"turbot","ukIpa":"/ˈtɜːbət/","usIpa":"/ˈtɝːbət/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"a broad, flat sea fish, or its edible flesh","vi":"cá bơn lớn; thịt cá bơn lớn"}],"examples":[{"en":"We shared grilled turbot with potatoes by the harbour.","vi":"Chúng tôi cùng nhau thưởng thức món cá bơn nướng ăn kèm khoai tây ngay bên cảng.","audioKind":"ex"},{"en":"Farming turbot can supply seafood markets, but producers must carefully manage water quality and waste.","vi":"Việc nuôi cá bơn lớn có thể cung cấp nguồn hàng cho các chợ hải sản, nhưng người nuôi phải quản lý cẩn thận chất lượng nước và chất thải.","audioKind":"ex2"}],"collocations":[{"en":"grilled turbot","vi":"cá bơn nướng"},{"en":"farmed turbot","vi":"cá bơn nuôi"},{"en":"turbot fillets","vi":"phi-lê cá bơn lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thịt cá thì không đếm được; khi chỉ con cá thì dạng số nhiều thường vẫn là turbot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_woodside', 'en-c2-4', 'woodside', '/ˈwʊdsaɪd/', 'C2', 'vùng rìa rừng; bìa rừng', 'n.', NULL, 'Đồng nghĩa: woodland edge', 'Từ ít gặp; trong giao tiếp hàng ngày thường dùng the edge of the woods.', 'We rested at the woodside, just beyond the meadow.', NULL, 'Chúng tôi đã nghỉ chân ở bìa rừng, ngay phía bên kia đồng cỏ.', '{"wordId":"woodside","ukIpa":"/ˈwʊdsaɪd/","usIpa":"/ˈwʊdsaɪd/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"The edge of a wood or the land beside it.","vi":"vùng rìa rừng; bìa rừng"}],"examples":[{"en":"We rested at the woodside, just beyond the meadow.","vi":"Chúng tôi đã nghỉ chân ở bìa rừng, ngay phía bên kia đồng cỏ.","audioKind":"ex"},{"en":"Preserving vegetation along the woodside can provide shelter for wildlife moving between forests and open farmland.","vi":"Việc bảo vệ thảm thực vật dọc theo bìa rừng có thể cung cấp nơi trú ẩn cho động vật hoang dã di chuyển giữa các khu rừng và vùng đất nông nghiệp mở.","audioKind":"ex2"}],"collocations":[{"en":"at the woodside","vi":"ở bìa rừng"},{"en":"along the woodside","vi":"dọc theo mép rừng"}],"wordFamily":[],"synonyms":["woodland edge"],"antonyms":[],"tipVi":"Từ ít gặp; trong giao tiếp hàng ngày thường dùng the edge of the woods.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furrow', 'en-c2-4', 'furrow', '/ˈfɝːoʊ/', 'C2', 'luống cày; rãnh cày; nếp nhăn sâu; vết hằn; nhíu (mày); làm hằn nếp nhăn', 'n.', 'furrowed (adj.)', 'Đồng nghĩa: groove', 'Cụm "furrow your brow" là một cách diễn đạt phổ biến mang nghĩa là nhíu mày.', 'The farmer dropped seeds into a freshly ploughed furrow.', NULL, 'Người nông dân thả những hạt giống xuống luống đất vừa được cày xới.', '{"wordId":"furrow","ukIpa":"/ˈfʌrəʊ/","usIpa":"/ˈfɝːoʊ/","cefr":"C2","topic":"nature","senses":[{"pos":"n.","en":"A long narrow channel cut into soil by a plough","vi":"luống cày; rãnh cày"},{"pos":"n.","en":"A deep line in skin or another surface","vi":"nếp nhăn sâu; vết hằn"},{"pos":"v.","en":"Make deep lines in something, especially the forehead","vi":"nhíu (mày); làm hằn nếp nhăn"}],"examples":[{"en":"The farmer dropped seeds into a freshly ploughed furrow.","vi":"Người nông dân thả những hạt giống xuống luống đất vừa được cày xới.","audioKind":"ex"},{"en":"Planting along furrows that follow the contours of hills can help farmers reduce soil erosion.","vi":"Việc canh tác dọc theo các đường rãnh tuân theo đường đồng mức của đồi núi có thể giúp nông dân giảm thiểu tình trạng xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"plough a furrow","vi":"cày một đường luống"},{"en":"a deep furrow","vi":"một rãnh sâu; nếp nhăn sâu"},{"en":"furrow your brow","vi":"nhíu mày"}],"wordFamily":["furrowed (adj.)"],"synonyms":["groove"],"antonyms":[],"tipVi":"Cụm \"furrow your brow\" là một cách diễn đạt phổ biến mang nghĩa là nhíu mày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alluvial', 'en-c2-4', 'alluvial', '/əˈluːviəl/', 'C2', 'phù sa; do phù sa bồi đắp', 'adj.', 'alluvium (n.)', NULL, 'Thường đi kèm với "soil", "plain", "deposits", nhấn mạnh sự hình thành do dòng nước lắng đọng.', 'Our vegetables grow well in the rich alluvial soil.', NULL, 'Rau củ của chúng tôi phát triển rất tốt trong lớp đất phù sa màu mỡ.', '{"wordId":"alluvial","ukIpa":"/əˈluːviəl/","usIpa":"/əˈluːviəl/","cefr":"C2","topic":"nature","senses":[{"pos":"adj.","en":"formed from soil or sand deposited by flowing water","vi":"phù sa; do phù sa bồi đắp"}],"examples":[{"en":"Our vegetables grow well in the rich alluvial soil.","vi":"Rau củ của chúng tôi phát triển rất tốt trong lớp đất phù sa màu mỡ.","audioKind":"ex"},{"en":"Alluvial plains often support intensive agriculture because rivers deposit fertile sediment across these lowland areas.","vi":"Các đồng bằng phù sa thường rất thuận lợi cho nền nông nghiệp thâm canh bởi vì các con sông bồi đắp lượng trầm tích màu mỡ khắp các vùng đất thấp này.","audioKind":"ex2"}],"collocations":[{"en":"alluvial soil","vi":"đất phù sa"},{"en":"alluvial deposits","vi":"trầm tích phù sa"},{"en":"alluvial plain","vi":"đồng bằng phù sa"}],"wordFamily":["alluvium (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi kèm với \"soil\", \"plain\", \"deposits\", nhấn mạnh sự hình thành do dòng nước lắng đọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hoe', 'en-c2-4', 'hoe', '/hoʊ/', 'C2', 'dùng cuốc xới đất hoặc làm cỏ; cái cuốc', 'v.', NULL, NULL, 'Vừa là danh từ cái cuốc vừa là động từ cuốc đất; dạng phân từ hiện tại là hoeing.', 'We hoed the vegetable patch before planting the beans.', NULL, 'Chúng tôi đã cuốc đất luống rau trước khi gieo hạt đậu.', '{"wordId":"hoe","ukIpa":"/həʊ/","usIpa":"/hoʊ/","cefr":"C2","topic":"nature","senses":[{"pos":"v.","en":"to loosen soil or remove weeds using a hoe","vi":"dùng cuốc xới đất hoặc làm cỏ"},{"pos":"n.","en":"a long-handled garden tool with a flat blade for working soil","vi":"cái cuốc"}],"examples":[{"en":"We hoed the vegetable patch before planting the beans.","vi":"Chúng tôi đã cuốc đất luống rau trước khi gieo hạt đậu.","audioKind":"ex"},{"en":"Farmers who hoe between crop rows can control weeds while reducing their dependence on chemical herbicides.","vi":"Những người nông dân xới đất giữa các hàng cây trồng có thể diệt trừ cỏ dại đồng thời giảm sự phụ thuộc vào thuốc diệt cỏ hóa học.","audioKind":"ex2"}],"collocations":[{"en":"hoe the soil","vi":"xới đất"},{"en":"hoe weeds","vi":"làm cỏ bằng cuốc"},{"en":"garden hoe","vi":"cuốc làm vườn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Vừa là danh từ cái cuốc vừa là động từ cuốc đất; dạng phân từ hiện tại là hoeing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teem', 'en-c2-4', 'teem', '/tiːm/', 'C2', 'tràn ngập; lúc nhúc (sinh vật, người); mưa xối xả; mưa tầm tã', 'v.', 'teeming (adj.)', 'Đồng nghĩa: abound', 'Thường đi với cụm teem with, dùng để diễn tả sự đông đúc của sinh vật, con người hoặc hoạt động.', 'The pond was teeming with tiny fish this morning.', NULL, 'Sáng nay cái ao lúc nhúc những chú cá nhỏ.', '{"wordId":"teem","ukIpa":"/tiːm/","usIpa":"/tiːm/","cefr":"C2","topic":"nature","senses":[{"pos":"v.","en":"to contain large quantities of living things or moving people","vi":"tràn ngập; lúc nhúc (sinh vật, người)"},{"pos":"v.","en":"to rain very heavily","vi":"mưa xối xả; mưa tầm tã"}],"examples":[{"en":"The pond was teeming with tiny fish this morning.","vi":"Sáng nay cái ao lúc nhúc những chú cá nhỏ.","audioKind":"ex"},{"en":"Healthy coral reefs teem with marine life, making their protection essential for maintaining ocean biodiversity.","vi":"Các rạn san hô khỏe mạnh tràn ngập sinh vật biển, khiến việc bảo vệ chúng trở nên cốt yếu để duy trì đa dạng sinh học đại dương.","audioKind":"ex2"}],"collocations":[{"en":"teem with life","vi":"tràn trề sự sống"},{"en":"teem with visitors","vi":"nườm nượp khách tham quan"},{"en":"teem down","vi":"mưa như trút nước"}],"wordFamily":["teeming (adj.)"],"synonyms":["abound"],"antonyms":[],"tipVi":"Thường đi với cụm teem with, dùng để diễn tả sự đông đúc của sinh vật, con người hoặc hoạt động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_4_1', 'en-c2-4', 'Cách dùng “opal” (n.) — đá mắt mèo; ngọc ô-pan', 'opal ring  ·  opal mining  ·  precious opal', 'Trong ngữ cảnh trang sức thường gọi là "ngọc ô-pan"; không phải tất cả các loại khoáng vật này đều có hiện tượng đổi màu.', NULL, '[{"hanzi":"The opal in her ring flashed green and blue.","pinyin":"","meaning":"Viên ngọc ô-pan trên nhẫn của cô ấy ánh lên sắc xanh lá và xanh dương."},{"hanzi":"Opal mining can provide employment in remote regions, although it may also disturb fragile desert environments.","pinyin":"","meaning":"Khai thác ngọc ô-pan có thể tạo việc làm ở các vùng hẻo lánh, dù nó cũng có thể phá hủy môi trường sa mạc mỏng manh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_4_2', 'en-c2-4', 'Cách dùng “vortex” (n.) — vó nước; xoáy nước; dòng xoáy', 'a swirling vortex  ·  a vortex of debt  ·  be sucked into a vortex', 'Dạng số nhiều có thể là vortices hoặc vortexes; ngoài ra còn dùng theo nghĩa bóng chỉ tình trạng khó khăn.', 'Đồng nghĩa: whirlpool', '[{"hanzi":"Leaves spun in a vortex beside the riverbank.","pinyin":"","meaning":"Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông."},{"hanzi":"Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.","pinyin":"","meaning":"Khi không thể tiếp cận các khoản tín dụng có mức lãi suất hợp lý, một số hộ gia đình sẽ rơi vào vòng xoáy nợ nần và bất ổn tài chính."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_4_3', 'en-c2-4', 'Cách dùng “halibut” (n.) — cá bลม biển lớn; thịt cá bơn', 'grilled halibut  ·  halibut fillet  ·  halibut fishing', 'Khi chỉ con cá, dạng số nhiều thường vẫn giữ nguyên là "halibut"; khi chỉ thịt cá thì không đếm được.', NULL, '[{"hanzi":"We ordered grilled halibut with potatoes and fresh lemon.","pinyin":"","meaning":"Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi."},{"hanzi":"Strict fishing limits can help protect halibut populations while supporting the long-term livelihoods of coastal communities.","pinyin":"","meaning":"Các quy định hạn chế đánh bắt nghiêm ngặt có thể giúp bảo vệ quần thể cá bơn đồng thời duy trì sinh kế lâu dài cho các cộng đồng ven biển."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_4_4', 'en-c2-4', 'Cách dùng “slithery” (adj.) — trơn trượt; trườn uốn lượn', 'a slithery snake  ·  a slithery eel', 'Thường dùng để miêu tả rắn, lươn và các loài động vật có độ trơn hoặc chuyển động trườn uốn lượn.', 'Họ từ (Word Family): slither (v.) | Đồng nghĩa: slippery', '[{"hanzi":"A slithery eel wriggled out of the fishing net.","pinyin":"","meaning":"Một con lươn trơn trượt quẫy mình trườn ra khỏi lưới đánh cá."},{"hanzi":"Children can overcome their fear of slithery animals through supervised observation and lessons about local wildlife.","pinyin":"","meaning":"Trẻ em có thể vượt qua nỗi sợ đối với các loài động vật trơn trượt thông qua việc quan sát có hướng dẫn và các bài học về động vật hoang dã địa phương."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_4_1', 'en-c2-4', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_1', 'ten_c2_4_1', 'wreathe', 'Thin wisps of steam wreathed her face above the bowl.', 'Thin wisps of steam wreathed her face above the bowl.', '/riːð/', 'Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_2', 'ten_c2_4_1', 'vortex', 'Leaves spun in a vortex beside the riverbank.', 'Leaves spun in a vortex beside the riverbank.', '/ˈvɔːrteks/', 'Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_3', 'ten_c2_4_1', 'ramify', 'The tree''s roots ramify beneath the old garden wall.', 'The tree''s roots ramify beneath the old garden wall.', '/ˈræmɪfaɪ/', 'Rễ cây đâm tủa phân nhánh bên dưới bức tường cũ của khu vườn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_4', 'ten_c2_4_1', 'opal', 'The opal in her ring flashed green and blue.', 'The opal in her ring flashed green and blue.', '/ˈoʊpəl/', 'Viên ngọc ô-pan trên nhẫn của cô ấy ánh lên sắc xanh lá và xanh dương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_5', 'ten_c2_4_1', 'eucalyptus', 'A koala rested high in the eucalyptus tree.', 'A koala rested high in the eucalyptus tree.', '/ˌjuːkəˈlɪptəs/', 'Một chú koala đang nghỉ ngơi trên tán cao của cây bạch đàn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_6', 'ten_c2_4_1', 'arboreal', 'The zoo''s arboreal snakes curled around branches above our heads.', 'The zoo''s arboreal snakes curled around branches above our heads.', '/ɑːrˈbɔːriəl/', 'Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_7', 'ten_c2_4_1', 'bough', 'A heavy bough shaded the bench beside the pond.', 'A heavy bough shaded the bench beside the pond.', '/baʊ/', 'Một nhánh cây lớn râm mát đã che bóng cho chiếc ghế băng bên bờ ao.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_1_8', 'ten_c2_4_1', 'undulate', 'Long strands of seaweed undulate gently beneath the water.', 'Long strands of seaweed undulate gently beneath the water.', '/ˈʌndʒəleɪt/', 'Những dải rong biển dài uốn lượn nhẹ nhàng bên dưới mặt nước.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_4_1_1', 'en-c2-4', 'ten_c2_4_1', 'listening', 'listening', 'Thin wisps of steam wreathed her face above the bowl.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.","Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi.","Rau củ của chúng tôi phát triển rất tốt trong lớp đất phù sa màu mỡ.","Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi."]'::jsonb, 0, 'Thin wisps of steam wreathed her face above the bowl. → Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_4_1_2', 'en-c2-4', 'ten_c2_4_1', 'listening', 'listening', 'Leaves spun in a vortex beside the riverbank.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một chú koala đang nghỉ ngơi trên tán cao của cây bạch đàn.","Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi.","Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.","Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi."]'::jsonb, 2, 'Leaves spun in a vortex beside the riverbank. → Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_4_1_3', 'en-c2-4', 'ten_c2_4_1', 'listening', 'listening', 'The tree''s roots ramify beneath the old garden wall.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi.","Rễ cây đâm tủa phân nhánh bên dưới bức tường cũ của khu vườn.","Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện.","Chúng tôi đã nghỉ chân ở bìa rừng, ngay phía bên kia đồng cỏ."]'::jsonb, 1, 'The tree''s roots ramify beneath the old garden wall. → Rễ cây đâm tủa phân nhánh bên dưới bức tường cũ của khu vườn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_4_2', 'en-c2-4', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_2_1', 'ten_c2_4_2', 'wreathe', 'Smoke from nearby factories can wreathe residential buildings, highlighting the need for stricter industrial emission controls.', 'Smoke from nearby factories can wreathe residential buildings, highlighting the need for stricter industrial emission controls.', '/riːð/', 'Khói từ các nhà máy lân cận có thể bao trùm các khu dân cư, làm nổi bật sự cần thiết của việc thắt chặt kiểm soát khí thải công nghiệp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_2_2', 'ten_c2_4_2', 'vortex', 'Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.', 'Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.', '/ˈvɔːrteks/', 'Khi không thể tiếp cận các khoản tín dụng có mức lãi suất hợp lý, một số hộ gia đình sẽ rơi vào vòng xoáy nợ nần và bất ổn tài chính.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_2_3', 'ten_c2_4_2', 'ramify', 'As transport networks ramify across rural regions, previously isolated communities gain better access to essential services.', 'As transport networks ramify across rural regions, previously isolated communities gain better access to essential services.', '/ˈræmɪfaɪ/', 'Khi mạng lưới giao thông mở rộng và phân nhánh khắp các vùng nông thôn, các cộng đồng vốn bị cô lập trước đây sẽ có điều kiện tiếp cận tốt hơn với các dịch vụ thiết yếu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_2_4', 'ten_c2_4_2', 'opal', 'Opal mining can provide employment in remote regions, although it may also disturb fragile desert environments.', 'Opal mining can provide employment in remote regions, although it may also disturb fragile desert environments.', '/ˈoʊpəl/', 'Khai thác ngọc ô-pan có thể tạo việc làm ở các vùng hẻo lánh, dù nó cũng có thể phá hủy môi trường sa mạc mỏng manh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_2_5', 'ten_c2_4_2', 'eucalyptus', 'Planting eucalyptus outside its native range may affect local water supplies and reduce biodiversity.', 'Planting eucalyptus outside its native range may affect local water supplies and reduce biodiversity.', '/ˌjuːkəˈlɪptəs/', 'Việc trồng cây bạch đàn bên ngoài vùng phân bố bản địa có thể ảnh hưởng đến nguồn nước địa phương và làm giảm đa dạng sinh học.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_4_2_6', 'ten_c2_4_2', 'arboreal', 'Deforestation threatens arboreal species by removing the branches and canopy they depend on for survival.', 'Deforestation threatens arboreal species by removing the branches and canopy they depend on for survival.', '/ɑːrˈbɔːriəl/', 'Việc phá rừng đe dọa các loài sống trên cây bằng cách phá hủy các cành và tán lá mà chúng phụ thuộc để sinh tồn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_4_2_1', 'en-c2-4', 'ten_c2_4_2', 'listening', 'listening', 'Smoke from nearby factories can wreathe residential buildings, highlighting the need for stricter industrial emission controls.', NULL, 'Trong câu vừa nghe, từ “wreathe” mang nghĩa nào sau đây?', '["kẻ ám sát; kẻ thủ ác","bao quanh; lượn lờ; bao phủ","báng bổ; xúc phạm thần linh; thô tục","làm trọng thương gây tàn tật; đánh trọng thương"]'::jsonb, 1, '“wreathe” (/riːð/): bao quanh; lượn lờ; bao phủ. Câu đầy đủ: Smoke from nearby factories can wreathe residential buildings, highlighting the need for stricter industrial emission controls.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_4_2_2', 'en-c2-4', 'ten_c2_4_2', 'listening', 'listening', 'Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.', NULL, 'Trong câu vừa nghe, từ “vortex” mang nghĩa nào sau đây?', '["tụ cầu khuẩn","vó nước; xoáy nước; dòng xoáy","nắm chặt, ôm chặt","dây cương ngựa; đầu cương"]'::jsonb, 1, '“vortex” (/ˈvɔːrteks/): vó nước; xoáy nước; dòng xoáy. Câu đầy đủ: Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_4_1', 'en-c2-4', 'Thin wisps of steam wreathed her face above the bowl', 'Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.', 'wreathe /riːð/', '["above","her","wisps","bowl","Thin","of","wreathed","the","steam","face"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
