INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_1', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'wreathe', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sẩy thai","nhiễm trùng; mưng mủ","bao quanh; lượn lờ; bao phủ","suy đoán; phỏng đoán"]'::jsonb, 2, 'wreathe (/riːð/) → bao quanh; lượn lờ; bao phủ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_2', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'Leaves spun in a vortex beside the riverbank.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện.","Một chú koala đang nghỉ ngơi trên tán cao của cây bạch đàn.","Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.","Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước."]'::jsonb, 2, 'Leaves spun in a vortex beside the riverbank. → Những chiếc lá xoay tít trong dòng nước xoáy bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_3', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'ramify', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nẹp cố định","nằm hoặc ngồi ngả ngớn, lười biếng; thõng xuống","chuyển tải; trung chuyển hàng hóa","phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau"]'::jsonb, 3, 'ramify (/ˈræmɪfaɪ/) → phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_4', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'The opal in her ring flashed green and blue.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Viên ngọc ô-pan trên nhẫn của cô ấy ánh lên sắc xanh lá và xanh dương.","Rễ cây đâm tủa phân nhánh bên dưới bức tường cũ của khu vườn.","Những làn hơi nước mỏng bay lượn quanh khuôn mặt cô ấy phía trên bát nước.","Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện."]'::jsonb, 0, 'The opal in her ring flashed green and blue. → Viên ngọc ô-pan trên nhẫn của cô ấy ánh lên sắc xanh lá và xanh dương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_5', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'eucalyptus', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cản trở; hạn chế","cây khuynh diệp; cây bạch đàn","làm trọng thương gây tàn tật; đánh trọng thương","tràn ngập; lúc nhúc (sinh vật, người)"]'::jsonb, 1, 'eucalyptus (/ˌjuːkəˈlɪptəs/) → cây khuynh diệp; cây bạch đàn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_6', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'The zoo''s arboreal snakes curled around branches above our heads.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện.","Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi.","Một chiếc lá rụng đang xoay tít trong dòng nước xoáy bên cạnh cây cầu.","Những dải rong biển dài uốn lượn nhẹ nhàng bên dưới mặt nước."]'::jsonb, 1, 'The zoo''s arboreal snakes curled around branches above our heads. → Những loài rắn sống trên cây trong vườn thú cuộn tròn quanh các cành cây ngay trên đầu chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_7', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'bough', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kẻ ám sát; kẻ thủ ác","cành lớn; nhánh cây chính","ca ngợi hết lời; tôn vinh","hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền"]'::jsonb, 1, 'bough (/baʊ/) → cành lớn; nhánh cây chính', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_8', 'en-c2-4', NULL, 'comprehensive_test', 'listening', 'Long strands of seaweed undulate gently beneath the water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuộc sống điền viên êm đềm mùa hè của chúng tôi chấm dứt khi những công nhân xây dựng ồn ào xuất hiện.","Người nông dân thả những hạt giống xuống luống đất vừa được cày xới.","Chúng tôi gọi món cá bơn nướng kèm khoai tây và chanh tươi.","Những dải rong biển dài uốn lượn nhẹ nhàng bên dưới mặt nước."]'::jsonb, 3, 'Long strands of seaweed undulate gently beneath the water. → Những dải rong biển dài uốn lượn nhẹ nhàng bên dưới mặt nước.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_9', 'en-c2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a tree mainly native to Australia, with strongly scented leaves”?', '["vortex","eucalyptus","ramify","bough"]'::jsonb, 1, 'eucalyptus (/ˌjuːkəˈlɪptəs/) → cây khuynh diệp; cây bạch đàn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_10', 'en-c2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “living mainly in trees”?', '["undulate","ramify","arboreal","woodside"]'::jsonb, 2, 'arboreal (/ɑːrˈbɔːriəl/) → sống trên cây; tính cây cối', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_11', 'en-c2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a large branch of a tree”?', '["furrow","turbot","bough","woodside"]'::jsonb, 2, 'bough (/baʊ/) → cành lớn; nhánh cây chính', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_12', 'en-c2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Move or rise and fall in a smooth, wave-like pattern.”?', '["vortex","undulate","halibut","idyll"]'::jsonb, 1, 'undulate (/ˈʌndʒəleɪt/) → uốn lượn; nhấp nhô; dập dờn', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_13', 'en-c2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “slippery or moving smoothly with a twisting motion”?', '["wreathe","slithery","eucalyptus","teem"]'::jsonb, 1, 'slithery (/ˈslɪðəri/) → trơn trượt; trườn uốn lượn', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
