INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_18', 'en-c2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Smoke from nearby factories can wreathe residential buildings, highlighting the need for stricter industrial emission controls.', 'Dựa vào câu trên, từ “wreathe” có nghĩa phù hợp nhất là gì?', '["hào phóng và bao dung, đặc biệt là đối với đối thủ hoặc người yếu thế hơn","bao quanh; lượn lờ; bao phủ","hợp mốt; sành điệu; hợp thời trang","hỗn láo, xấc láo và thiếu tôn trọng, đặc biệt là đối với người có thẩm quyền"]'::jsonb, 1, 'wreathe: bao quanh; lượn lờ; bao phủ. Dịch cả câu: Khói từ các nhà máy lân cận có thể bao trùm các khu dân cư, làm nổi bật sự cần thiết của việc thắt chặt kiểm soát khí thải công nghiệp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_19', 'en-c2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Without access to affordable credit, some households become trapped in a vortex of debt and financial insecurity.', 'Dựa vào câu trên, từ “vortex” có nghĩa phù hợp nhất là gì?', '["được đề cập hoặc trình bày trước đó trong một văn bản","vết loét","sự dao động; sự đu đưa","vó nước; xoáy nước; dòng xoáy"]'::jsonb, 3, 'vortex: vó nước; xoáy nước; dòng xoáy; vũng lầy; cơn lốc (tình huống lôi cuốn vào sự hỗn loạn hoặc khó khăn). Dịch cả câu: Khi không thể tiếp cận các khoản tín dụng có mức lãi suất hợp lý, một số hộ gia đình sẽ rơi vào vòng xoáy nợ nần và bất ổn tài chính.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_20', 'en-c2-4', NULL, 'comprehensive_test', 'reading', NULL, 'As transport networks ramify across rural regions, previously isolated communities gain better access to essential services.', 'Dựa vào câu trên, từ “ramify” có nghĩa phù hợp nhất là gì?', '["luyện kim học","tiền đề; tiền thân; tiền lệ","phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau","phát triển nhanh chóng và ngoạn mục; vụt sáng"]'::jsonb, 2, 'ramify: phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau. Dịch cả câu: Khi mạng lưới giao thông mở rộng và phân nhánh khắp các vùng nông thôn, các cộng đồng vốn bị cô lập trước đây sẽ có điều kiện tiếp cận tốt hơn với các dịch vụ thiết yếu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_21', 'en-c2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Opal mining can provide employment in remote regions, although it may also disturb fragile desert environments.', 'Dựa vào câu trên, từ “opal” có nghĩa phù hợp nhất là gì?', '["ngực; bầu ngực; vòng tay ôm ấp","cảm giác khó chịu, mệt mỏi chung không rõ nguyên nhân","về dáng vẻ: vụng về; lóng ngóng; không uyển chuyển","đá mắt mèo; ngọc ô-pan"]'::jsonb, 3, 'opal: đá mắt mèo; ngọc ô-pan. Dịch cả câu: Khai thác ngọc ô-pan có thể tạo việc làm ở các vùng hẻo lánh, dù nó cũng có thể phá hủy môi trường sa mạc mỏng manh.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_22', 'en-c2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phù sa; do phù sa bồi đắp”', '["infantry","alluvial","shamble","peroxide"]'::jsonb, 1, 'phù sa; do phù sa bồi đắp → alluvial (/əˈluːviəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_23', 'en-c2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dùng cuốc xới đất hoặc làm cỏ”', '["hoe","poliomyelitis","haughty","eucalyptus"]'::jsonb, 0, 'dùng cuốc xới đất hoặc làm cỏ → hoe (/hoʊ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_4_24', 'en-c2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tràn ngập; lúc nhúc (sinh vật, người)”', '["Leninism","teem","idyll","trite"]'::jsonb, 1, 'tràn ngập; lúc nhúc (sinh vật, người) → teem (/tiːm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-5', 'en', 'Bài 5: Sức khỏe & Cơ thể - CEFR C2', 'CEFR C2', 'C2 · Sức khỏe', '20 từ vựng Tiếng Anh CEFR C2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6005, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_splint', 'en-c2-5', 'splint', '/splɪnt/', 'C2', 'nẹp cố định; nẹp cố định (bằng nẹp)', 'n.', NULL, NULL, 'Chỉ dụng cụ nẹp cố định vết thương; khác với cast dùng để bó bột cố định.', 'The nurse fitted a splint to my injured finger.', NULL, 'Y tá đã nẹp ngón tay bị thương của tôi lại.', '{"wordId":"splint","ukIpa":"/splɪnt/","usIpa":"/splɪnt/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A rigid support that keeps an injured body part still.","vi":"nẹp cố định"},{"pos":"v.","en":"To support an injured body part with a splint.","vi":"nẹp cố định (bằng nẹp)"}],"examples":[{"en":"The nurse fitted a splint to my injured finger.","vi":"Y tá đã nẹp ngón tay bị thương của tôi lại.","audioKind":"ex"},{"en":"Using a splint to stabilise an injured limb can prevent further damage while patients await medical treatment.","vi":"Việc dùng nẹp để cố định một chi bị thương có thể ngăn ngừa tổn thương thêm trong lúc bệnh nhân chờ điều trị y tế.","audioKind":"ex2"}],"collocations":[{"en":"wear a splint","vi":"đeo nẹp"},{"en":"apply a splint","vi":"đặt nẹp"},{"en":"a wrist splint","vi":"nẹp cổ tay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ dụng cụ nẹp cố định vết thương; khác với cast dùng để bó bột cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_staphylococcus', 'en-c2-5', 'staphylococcus', '/ˌstæfɪləˈkɑːkəs/', 'C2', 'tụ cầu khuẩn', 'n.', 'staphylococcal (adj.), staphylococci (n.)', 'Đồng nghĩa: staph', 'Số nhiều là staphylococci; thường được gọi tắt là staph.', 'The laboratory found staphylococcus in the skin sample.', NULL, 'Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.', '{"wordId":"staphylococcus","ukIpa":"/ˌstæfɪləˈkɒkəs/","usIpa":"/ˌstæfɪləˈkɑːkəs/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A round bacterium forming clusters, sometimes causing infections.","vi":"tụ cầu khuẩn"}],"examples":[{"en":"The laboratory found staphylococcus in the skin sample.","vi":"Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.","audioKind":"ex"},{"en":"Some strains of staphylococcus resist common antibiotics, making hospital infections more difficult to treat.","vi":"Một số chủng tụ cầu khuẩn có khả năng kháng lại các loại kháng sinh thông thường, khiến cho các bệnh nhiễm trùng trong bệnh viện trở nên khó điều trị hơn.","audioKind":"ex2"}],"collocations":[{"en":"staphylococcus infection","vi":"nhiễm trùng tụ cầu khuẩn"},{"en":"strains of staphylococcus","vi":"chủng tụ cầu khuẩn"},{"en":"antibiotic-resistant staphylococcus","vi":"tụ cầu khuẩn kháng kháng sinh"}],"wordFamily":["staphylococcal (adj.)","staphylococci (n.)"],"synonyms":["staph"],"antonyms":[],"tipVi":"Số nhiều là staphylococci; thường được gọi tắt là staph.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cervix', 'en-c2-5', 'cervix', '/ˈsɝːvɪks/', 'C2', 'cổ tử cung', 'n.', 'cervical (adj.)', NULL, 'Thường chỉ cổ tử cung; từ cervical cũng có thể mang nghĩa liên quan đến cổ.', 'The nurse explained where the cervix is on the model.', NULL, 'Nữ hộ sinh đã giải thích vị trí của cổ tử cung trên mô hình.', '{"wordId":"cervix","ukIpa":"/ˈsɜːvɪks/","usIpa":"/ˈsɝːvɪks/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"The narrow lower part of the uterus opening into the vagina.","vi":"cổ tử cung"}],"examples":[{"en":"The nurse explained where the cervix is on the model.","vi":"Nữ hộ sinh đã giải thích vị trí của cổ tử cung trên mô hình.","audioKind":"ex"},{"en":"Regular screening can detect abnormal cells in the cervix before they develop into a serious health problem.","vi":"Việc tầm soát định kỳ có thể phát hiện các tế bào bất thường ở cổ tử cung trước khi chúng tiến triển thành vấn đề sức khỏe nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"the cervix of the uterus","vi":"cổ tử cung"},{"en":"cells of the cervix","vi":"tế bào cổ tử cung"},{"en":"cancer of the cervix","vi":"ung thư cổ tử cung"}],"wordFamily":["cervical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ cổ tử cung; từ cervical cũng có thể mang nghĩa liên quan đến cổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prostrate', 'en-c2-5', 'prostrate', '/ˈprɑːstreɪt/', 'C2', 'nằm sấp; phủ phục; kiệt sức; suy nhược; suy sụp; làm cho nằm sấp; làm cho kiệt sức', 'adj.', 'prostration (n.)', 'Đồng nghĩa: prone · Trái nghĩa: upright', 'Cần phân biệt với prostate (tiền liệt tuyến); lưu ý từ này có nhiều hơn một chữ r.', 'After crawling under the fence, he lay prostrate on the grass.', NULL, 'Sau khi bò qua hàng rào, anh ấy nằm sấp trên bãi cỏ.', '{"wordId":"prostrate","ukIpa":"/ˈprɒstreɪt/","usIpa":"/ˈprɑːstreɪt/","cefr":"C2","topic":"health","senses":[{"pos":"adj.","en":"lying flat with your face towards the ground","vi":"nằm sấp; phủ phục"},{"pos":"adj.","en":"overwhelmed by exhaustion, illness, or strong emotion","vi":"kiệt sức; suy nhược; suy sụp"},{"pos":"v.","en":"to make someone lie face down or become extremely weak","vi":"làm cho nằm sấp; làm cho kiệt sức"}],"examples":[{"en":"After crawling under the fence, he lay prostrate on the grass.","vi":"Sau khi bò qua hàng rào, anh ấy nằm sấp trên bãi cỏ.","audioKind":"ex"},{"en":"Extreme heat can leave outdoor workers prostrate with exhaustion, highlighting the importance of regular breaks.","vi":"Nắng nóng cực độ có thể khiến lao động ngoài trời kiệt sức, làm nổi bật tầm quan trọng của việc nghỉ ngơi đều đặn.","audioKind":"ex2"}],"collocations":[{"en":"lie prostrate","vi":"nằm sấp"},{"en":"prostrate with exhaustion","vi":"kiệt sức không còn sức lực"},{"en":"prostrate oneself","vi":"phủ phục sát đất"}],"wordFamily":["prostration (n.)"],"synonyms":["prone"],"antonyms":["upright"],"tipVi":"Cần phân biệt với prostate (tiền liệt tuyến); lưu ý từ này có nhiều hơn một chữ r.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tibia', 'en-c2-5', 'tibia', '/ˈtɪbiə/', 'C2', 'xương chày', 'n.', 'tibial (adj.)', 'Đồng nghĩa: shinbone', 'Còn gọi là xương ống chân (shinbone); dạng số nhiều có thể là tibias hoặc tibiae.', 'The doctor showed me my tibia on the scan.', NULL, 'Bác sĩ đã chỉ cho tôi thấy xương chày của mình trên phim chụp.', '{"wordId":"tibia","ukIpa":"/ˈtɪbiə/","usIpa":"/ˈtɪbiə/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"The larger front bone between the knee and ankle","vi":"xương chày"}],"examples":[{"en":"The doctor showed me my tibia on the scan.","vi":"Bác sĩ đã chỉ cho tôi thấy xương chày của mình trên phim chụp.","audioKind":"ex"},{"en":"A fracture of the tibia may require several months of rehabilitation before an athlete can safely resume training.","vi":"Một vết gãy xương chày có thể đòi hỏi vài tháng phục hồi chức năng trước khi một vận động viên có thể an toàn trở lại tập luyện.","audioKind":"ex2"}],"collocations":[{"en":"a fractured tibia","vi":"xương chày bị gãy"},{"en":"the tibia and fibula","vi":"xương chày và xương mác"},{"en":"tibial fracture","vi":"gãy xương chày"}],"wordFamily":["tibial (adj.)"],"synonyms":["shinbone"],"antonyms":[],"tipVi":"Còn gọi là xương ống chân (shinbone); dạng số nhiều có thể là tibias hoặc tibiae.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_miscarry', 'en-c2-5', 'miscarry', '/ˌmɪsˈkæri/', 'C2', 'sẩy thai; thất bại; hỏng việc', 'v.', 'miscarriage (n.)', NULL, 'Thường chỉ việc sẩy thai tự nhiên; nghĩa chỉ kế hoạch thất bại mang tính trang trọng và ít dùng hơn.', 'After she miscarried, her family offered comfort and support.', NULL, 'Sau khi cô ấy sẩy thai, gia đình đã an ủi và hỗ trợ cô ấy.', '{"wordId":"miscarry","ukIpa":"/ˌmɪsˈkæri/","usIpa":"/ˌmɪsˈkæri/","cefr":"C2","topic":"health","senses":[{"pos":"v.","en":"Lose a pregnancy before the baby can survive outside the womb.","vi":"sẩy thai"},{"pos":"v.","en":"Fail to achieve the intended result.","vi":"thất bại; hỏng việc"}],"examples":[{"en":"After she miscarried, her family offered comfort and support.","vi":"Sau khi cô ấy sẩy thai, gia đình đã an ủi và hỗ trợ cô ấy.","audioKind":"ex"},{"en":"People who miscarry should have access to compassionate medical care and appropriate psychological support.","vi":"Những phụ nữ bị sẩy thai nên được tiếp cận dịch vụ y tế nhân đạo và hỗ trợ tâm lý phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"miscarry early in pregnancy","vi":"sẩy thai ở giai đoạn đầu của thai kỳ"},{"en":"a plan miscarries","vi":"kế hoạch thất bại"}],"wordFamily":["miscarriage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ việc sẩy thai tự nhiên; nghĩa chỉ kế hoạch thất bại mang tính trang trọng và ít dùng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distend', 'en-c2-5', 'distend', '/dɪˈstend/', 'C2', 'làm phồng lên; làm căng ra; trương lên', 'v.', 'distension (n.), distention (n.)', 'Đồng nghĩa: swell, expand · Trái nghĩa: contract', 'Thường dùng trong y học, nhấn mạnh áp lực từ bên trong khiến bộ phận cơ thể phồng to.', 'Too much gas can distend your stomach after meals.', NULL, 'Quá nhiều khí có thể làm dạ dày bạn phồng lên sau bữa ăn.', '{"wordId":"distend","ukIpa":"/dɪˈstend/","usIpa":"/dɪˈstend/","cefr":"C2","topic":"health","senses":[{"pos":"v.","en":"To swell or become larger because of pressure from inside.","vi":"làm phồng lên; làm căng ra; trương lên"}],"examples":[{"en":"Too much gas can distend your stomach after meals.","vi":"Quá nhiều khí có thể làm dạ dày bạn phồng lên sau bữa ăn.","audioKind":"ex"},{"en":"During digestion, excess gas may distend the abdomen, causing discomfort that can affect daily activities.","vi":"Trong quá trình tiêu hóa, lượng khí dư thừa có thể làm căng phồng vùng bụng, gây ra cảm giác khó chịu ảnh hưởng đến các hoạt động hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a distended abdomen","vi":"vùng bụng bị căng phồng"},{"en":"a distended stomach","vi":"dạ dày bị trương lên"},{"en":"distended with gas","vi":"trương lên vì đầy khí"}],"wordFamily":["distension (n.)","distention (n.)"],"synonyms":["swell","expand"],"antonyms":["contract"],"tipVi":"Thường dùng trong y học, nhấn mạnh áp lực từ bên trong khiến bộ phận cơ thể phồng to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_septic', 'en-c2-5', 'septic', '/ˈseptɪk/', 'C2', 'nhiễm trùng; mưng mủ', 'adj.', 'sepsis (n.)', 'Đồng nghĩa: infected', '"Septic tank" nghĩa là bể phốt; "septic" không dùng làm danh từ chỉ chất mục rữa.', 'The nurse cleaned the septic wound and changed its dressing.', NULL, 'Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó.', '{"wordId":"septic","ukIpa":"/ˈseptɪk/","usIpa":"/ˈseptɪk/","cefr":"C2","topic":"health","senses":[{"pos":"adj.","en":"infected with harmful bacteria, or relating to such infection","vi":"nhiễm trùng; mưng mủ"}],"examples":[{"en":"The nurse cleaned the septic wound and changed its dressing.","vi":"Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó.","audioKind":"ex"},{"en":"Prompt treatment of bacterial infections can reduce the risk of septic shock and improve patient outcomes.","vi":"Việc điều trị kịp thời các bệnh nhiễm khuẩn có thể làm giảm nguy cơ sốc nhiễm khuẩn và cải thiện kết quả điều trị cho bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"a septic wound","vi":"vết thương bị nhiễm trùng"},{"en":"septic shock","vi":"sốc nhiễm trùng"},{"en":"a septic tank","vi":"bể phốt"}],"wordFamily":["sepsis (n.)"],"synonyms":["infected"],"antonyms":[],"tipVi":"\"Septic tank\" nghĩa là bể phốt; \"septic\" không dùng làm danh từ chỉ chất mục rữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ulcer', 'en-c2-5', 'ulcer', '/ˈʌlsɚ/', 'C2', 'vết loét', 'n.', 'ulceration (n.), ulcerative (adj.)', NULL, 'Là danh từ đếm được, thường kết hợp với các từ chỉ bộ phận cơ thể như mouth ulcer.', 'This mouth ulcer makes eating fresh oranges uncomfortable.', NULL, 'Vết lở miệng này khiến việc ăn cam tươi trở nên khó chịu.', '{"wordId":"ulcer","ukIpa":"/ˈʌlsə/","usIpa":"/ˈʌlsɚ/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"an open sore on the skin or inside the body","vi":"vết loét"}],"examples":[{"en":"This mouth ulcer makes eating fresh oranges uncomfortable.","vi":"Vết lở miệng này khiến việc ăn cam tươi trở nên khó chịu.","audioKind":"ex"},{"en":"Early diagnosis of a stomach ulcer can help patients receive appropriate treatment and avoid complications.","vi":"Việc chẩn đoán sớm bệnh loét dạ dày có thể giúp bệnh nhân nhận được phương pháp điều trị thích hợp và tránh được các biến chứng.","audioKind":"ex2"}],"collocations":[{"en":"a stomach ulcer","vi":"loét dạ dày"},{"en":"a mouth ulcer","vi":"lở miệng"},{"en":"a peptic ulcer","vi":"loét tiêu hóa"}],"wordFamily":["ulceration (n.)","ulcerative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, thường kết hợp với các từ chỉ bộ phận cơ thể như mouth ulcer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remission', 'en-c2-5', 'remission', '/rɪˈmɪʃən/', 'C2', 'thời kỳ thuyên giảm, giai đoạn bệnh tình thuyên giảm hoặc ngừng phát triển; sự miễn giảm hoặc bãi bỏ chính thức một khoản nợ hay hình phạt', 'n.', 'remit (v.)', NULL, 'in remission chỉ tình trạng bệnh thuyên giảm, không nhất thiết có nghĩa là đã khỏi hẳn.', 'Her illness is in remission, and she feels stronger.', NULL, 'Bệnh tình của cô ấy đang trong giai đoạn thuyên giảm và cô ấy cảm thấy khỏe khoắn hơn.', '{"wordId":"remission","ukIpa":"/rɪˈmɪʃən/","usIpa":"/rɪˈmɪʃən/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A period when a serious illness improves or becomes inactive.","vi":"thời kỳ thuyên giảm, giai đoạn bệnh tình thuyên giảm hoặc ngừng phát triển"},{"pos":"n.","en":"An official reduction or cancellation of a debt or punishment.","vi":"sự miễn giảm hoặc bãi bỏ chính thức một khoản nợ hay hình phạt"}],"examples":[{"en":"Her illness is in remission, and she feels stronger.","vi":"Bệnh tình của cô ấy đang trong giai đoạn thuyên giảm và cô ấy cảm thấy khỏe khoắn hơn.","audioKind":"ex"},{"en":"Advances in medical treatment have enabled more patients to achieve remission and enjoy a better quality of life.","vi":"Những tiến bộ trong y học đã giúp cho nhiều bệnh nhân đạt được tình trạng thuyên giảm bệnh và tận hưởng chất lượng cuộc sống tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"in remission","vi":"đang trong thời kỳ thuyên giảm bệnh"},{"en":"complete remission","vi":"thuyên giảm hoàn toàn"},{"en":"remission of debt","vi":"sự miễn giảm nợ"}],"wordFamily":["remit (v.)"],"synonyms":[],"antonyms":[],"tipVi":"in remission chỉ tình trạng bệnh thuyên giảm, không nhất thiết có nghĩa là đã khỏi hẳn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_malaise', 'en-c2-5', 'malaise', '/mæˈleɪz/', 'C2', 'cảm giác khó chịu, mệt mỏi chung không rõ nguyên nhân; tình trạng thiếu hụt niềm tin, năng lượng hoặc sự tiến bộ trên diện rộng trong xã hội', 'n.', NULL, NULL, 'Mang tính trang trọng, vừa dùng để chỉ tình trạng mệt mỏi thể chất mơ hồ, vừa ám chỉ sự trì trệ kinh tế-xã hội.', 'A lingering malaise kept me on the sofa all afternoon.', NULL, 'Cảm giác mệt mỏi kéo dài khiến tôi nằm lì trên ghế sofa cả buổi chiều.', '{"wordId":"malaise","ukIpa":"/mæˈleɪz/","usIpa":"/mæˈleɪz/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"a general feeling of illness or unease without a clear cause","vi":"cảm giác khó chịu, mệt mỏi chung không rõ nguyên nhân"},{"pos":"n.","en":"a widespread lack of confidence, energy, or progress in society","vi":"tình trạng thiếu hụt niềm tin, năng lượng hoặc sự tiến bộ trên diện rộng trong xã hội"}],"examples":[{"en":"A lingering malaise kept me on the sofa all afternoon.","vi":"Cảm giác mệt mỏi kéo dài khiến tôi nằm lì trên ghế sofa cả buổi chiều.","audioKind":"ex"},{"en":"Prolonged economic malaise can weaken public confidence and discourage businesses from investing in new projects.","vi":"Tình trạng trì trệ kinh tế kéo dài có thể làm xói mòn niềm tin của công chúng và khiến các doanh nghiệp ngần ngại đầu tư vào các dự án mới.","audioKind":"ex2"}],"collocations":[{"en":"general malaise","vi":"cảm giác khó chịu toàn thân"},{"en":"economic malaise","vi":"suy thoái kinh tế"},{"en":"a sense of malaise","vi":"một cảm giác bất an"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mang tính trang trọng, vừa dùng để chỉ tình trạng mệt mỏi thể chất mơ hồ, vừa ám chỉ sự trì trệ kinh tế-xã hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sclerosis', 'en-c2-5', 'sclerosis', '/skləˈroʊsɪs/', 'C2', 'xơ hóa; chứng xơ cứng', 'n.', 'sclerotic (adj.)', NULL, 'Từ thuộc lĩnh vực y học; "multiple sclerosis" là bệnh đa xơ cứng.', 'The specialist explained that sclerosis involves hardening of body tissue.', NULL, 'Chuyên gia giải thích rằng xơ hóa liên quan đến hiện tượng các mô trong cơ thể trở nên cứng lại.', '{"wordId":"sclerosis","ukIpa":"/skləˈrəʊsɪs/","usIpa":"/skləˈroʊsɪs/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"Abnormal hardening of tissue within the body.","vi":"xơ hóa; chứng xơ cứng"}],"examples":[{"en":"The specialist explained that sclerosis involves hardening of body tissue.","vi":"Chuyên gia giải thích rằng xơ hóa liên quan đến hiện tượng các mô trong cơ thể trở nên cứng lại.","audioKind":"ex"},{"en":"Multiple sclerosis affects the central nervous system, and its symptoms can vary considerably between individuals.","vi":"Bệnh đa xơ cứng ảnh hưởng đến hệ thần kinh trung ương và các triệu chứng của nó có thể thay đổi đáng kể tùy theo từng cá.","audioKind":"ex2"}],"collocations":[{"en":"multiple sclerosis","vi":"đa xơ cứng"},{"en":"tissue sclerosis","vi":"xơ hóa mô"}],"wordFamily":["sclerotic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ thuộc lĩnh vực y học; \"multiple sclerosis\" là bệnh đa xơ cứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delirium', 'en-c2-5', 'delirium', '/dɪˈlɪriəm/', 'C2', 'chứng sảng; tình trạng mê sảng; trạng thái cực kỳ hưng phấn; niềm vui tột độ', 'n.', 'delirious (adj.), deliriously (adv.)', NULL, 'Trong y học nghĩa là tình trạng rối loạn ý thức cấp tính, không đồng nhất với chứng mất trí nhớ mãn tính.', 'During his fever, he slipped into delirium and spoke incoherently.', NULL, 'Trong cơn sốt, anh ấy rơi vào trạng thái mê sảng và nói năng lú lẫn.', '{"wordId":"delirium","ukIpa":"/dɪˈlɪriəm/","usIpa":"/dɪˈlɪriəm/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A sudden confused mental state, often caused by illness.","vi":"chứng sảng; tình trạng mê sảng"},{"pos":"n.","en":"A state of extreme excitement or happiness.","vi":"trạng thái cực kỳ hưng phấn; niềm vui tột độ"}],"examples":[{"en":"During his fever, he slipped into delirium and spoke incoherently.","vi":"Trong cơn sốt, anh ấy rơi vào trạng thái mê sảng và nói năng lú lẫn.","audioKind":"ex"},{"en":"Hospital staff need appropriate training to recognise delirium promptly, particularly among older patients recovering from surgery.","vi":"Nhân viên bệnh viện cần được đào tạo phù hợp để nhận biết kịp thời chứng mê sảng, đặc biệt là ở những bệnh nhân lớn tuổi đang hồi phục sau phẫu thuật.","audioKind":"ex2"}],"collocations":[{"en":"acute delirium","vi":"chứng mê sảng cấp tính"},{"en":"postoperative delirium","vi":"mê sảng hậu phẫu"},{"en":"a state of delirium","vi":"trạng thái mê sảng"}],"wordFamily":["delirious (adj.)","deliriously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong y học nghĩa là tình trạng rối loạn ý thức cấp tính, không đồng nhất với chứng mất trí nhớ mãn tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mumps', 'en-c2-5', 'mumps', '/mʌmps/', 'C2', 'bệnh quai bị', 'n.', NULL, NULL, 'Dù tận cùng bằng s, từ này được dùng ở số ít khi chỉ tên bệnh: mumps is.', 'The doctor checked her swollen cheeks for signs of mumps.', NULL, 'Bác sĩ đã kiểm tra má bị sưng của cô ấy để tìm dấu hiệu của bệnh quai bị.', '{"wordId":"mumps","ukIpa":"/mʌmps/","usIpa":"/mʌmps/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A viral illness causing painful swelling near the jaw","vi":"bệnh quai bị"}],"examples":[{"en":"The doctor checked her swollen cheeks for signs of mumps.","vi":"Bác sĩ đã kiểm tra má bị sưng của cô ấy để tìm dấu hiệu của bệnh quai bị.","audioKind":"ex"},{"en":"Routine vaccination helps prevent mumps and reduces the likelihood of outbreaks in schools and other crowded settings.","vi":"Tiêm chủng định kỳ giúp ngăn ngừa bệnh quai bị và giảm nguy cơ bùng phát dịch ở trường học cũng như các khu vực đông đúc khác.","audioKind":"ex2"}],"collocations":[{"en":"catch mumps","vi":"mắc bệnh quai bị"},{"en":"mumps vaccine","vi":"vắc-xin quai bị"},{"en":"mumps outbreak","vi":"bùng phát dịch quai bị"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dù tận cùng bằng s, từ này được dùng ở số ít khi chỉ tên bệnh: mumps is.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maim', 'en-c2-5', 'maim', '/meɪm/', 'C2', 'làm trọng thương gây tàn tật; đánh trọng thương', 'v.', 'maimed (adj.)', NULL, 'Nghiêm trọng hơn injure, nhấn mạnh việc gây tổn thương cơ thể vĩnh viễn.', 'This machine could maim someone without its safety guard.', NULL, 'Chiếc máy này có thể khiến ai đó bị thương nặng và tàn phế nếu không có bộ phận bảo vệ an toàn.', '{"wordId":"maim","ukIpa":"/meɪm/","usIpa":"/meɪm/","cefr":"C2","topic":"health","senses":[{"pos":"v.","en":"To injure someone severely, causing lasting damage to their body.","vi":"làm trọng thương gây tàn tật; đánh trọng thương"}],"examples":[{"en":"This machine could maim someone without its safety guard.","vi":"Chiếc máy này có thể khiến ai đó bị thương nặng và tàn phế nếu không có bộ phận bảo vệ an toàn.","audioKind":"ex"},{"en":"Strict workplace inspections are essential because unguarded machinery can maim workers and leave them with lifelong disabilities.","vi":"Việc thanh kiểm tra nơi làm việc nghiêm ngặt là vô cùng cần thiết vì máy móc không có thiết bị bảo vệ có thể làm công nhân tàn tật suốt đời.","audioKind":"ex2"}],"collocations":[{"en":"maim workers","vi":"làm công nhân tàn phế"},{"en":"maimed in an accident","vi":"bị tàn tật trong một vụ tai nạn"}],"wordFamily":["maimed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghiêm trọng hơn injure, nhấn mạnh việc gây tổn thương cơ thể vĩnh viễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poliomyelitis', 'en-c2-5', 'poliomyelitis', '/ˌpoʊlioʊˌmaɪəˈlaɪtɪs/', 'C2', 'bệnh bại liệt; bệnh viêm tủy xám', 'n.', NULL, 'Đồng nghĩa: polio', 'Hằng ngày dùng nhiều polio; dù gọi là bại liệt trẻ em, người lớn vẫn có thể mắc.', 'The nurse explained how vaccination protects children against poliomyelitis.', NULL, 'Nữ hộ sinh giải thích việc tiêm chủng bảo vệ trẻ em khỏi bệnh bại liệt như thế nào.', '{"wordId":"poliomyelitis","ukIpa":"/ˌpəʊliəʊˌmaɪəˈlaɪtɪs/","usIpa":"/ˌpoʊlioʊˌmaɪəˈlaɪtɪs/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A viral disease that can damage nerves and cause paralysis.","vi":"bệnh bại liệt; bệnh viêm tủy xám"}],"examples":[{"en":"The nurse explained how vaccination protects children against poliomyelitis.","vi":"Nữ hộ sinh giải thích việc tiêm chủng bảo vệ trẻ em khỏi bệnh bại liệt như thế nào.","audioKind":"ex"},{"en":"International vaccination programmes have greatly reduced poliomyelitis, although continued monitoring remains essential to prevent further outbreaks.","vi":"Các chương trình tiêm chủng quốc tế đã làm giảm đáng kể bệnh bại liệt, mặc dù việc giám sát liên tục vẫn rất cần thiết để ngăn chặn các đợt bùng phát tiếp theo.","audioKind":"ex2"}],"collocations":[{"en":"vaccination against poliomyelitis","vi":"tiêm phòng bệnh bại liệt"},{"en":"eradicate poliomyelitis","vi":"tiêu diệt bệnh bại liệt"},{"en":"poliomyelitis outbreak","vi":"đợt bùng phát bệnh bại liệt"}],"wordFamily":[],"synonyms":["polio"],"antonyms":[],"tipVi":"Hằng ngày dùng nhiều polio; dù gọi là bại liệt trẻ em, người lớn vẫn có thể mắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neurosis', 'en-c2-5', 'neurosis', '/nʊˈroʊsɪs/', 'C2', 'chứng thần kinh (thuật ngữ cũ chỉ các vấn đề tâm lý liên quan đến lo âu hoặc căng thẳng)', 'n.', 'neurotic (adj.), neurotically (adv.)', NULL, 'Thuật ngữ tâm lý học cũ, không đồng nghĩa với suy nhược thần kinh; dạng số nhiều là neuroses.', 'The old psychology book devoted a chapter to neurosis.', NULL, 'Cuốn sách tâm lý học cũ đã dành hẳn một chương nói về chứng thần kinh.', '{"wordId":"neurosis","ukIpa":"/njʊəˈrəʊsɪs/","usIpa":"/nʊˈroʊsɪs/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"An older term for psychological difficulties involving anxiety or distress.","vi":"chứng thần kinh (thuật ngữ cũ chỉ các vấn đề tâm lý liên quan đến lo âu hoặc căng thẳng)"}],"examples":[{"en":"The old psychology book devoted a chapter to neurosis.","vi":"Cuốn sách tâm lý học cũ đã dành hẳn một chương nói về chứng thần kinh.","audioKind":"ex"},{"en":"Although neurosis appears frequently in older research, modern clinicians generally use more specific diagnostic terms.","vi":"Mặc dù chứng thần kinh xuất hiện thường xuyên trong các nghiên cứu trước đây, các bác sĩ lâm sàng hiện đại thường sử dụng các thuật ngữ chẩn đoán cụ thể hơn.","audioKind":"ex2"}],"collocations":[{"en":"anxiety neurosis","vi":"chứng lo âu thần kinh"},{"en":"obsessional neurosis","vi":"chứng nhiễu tâm ám ảnh"}],"wordFamily":["neurotic (adj.)","neurotically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ tâm lý học cũ, không đồng nghĩa với suy nhược thần kinh; dạng số nhiều là neuroses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flabby', 'en-c2-5', 'flabby', '/ˈflæbi/', 'C2', 'nhão; mềm nhão (cơ bắp); yếu ớt; thiếu sức sống; lỏng lẻo, thiếu chặt chẽ', 'adj.', 'flab (n.), flabbiness (n.)', 'Trái nghĩa: firm, toned', 'Thường chỉ cơ bắp mềm nhão; khi miêu tả bài viết nghĩa là lỏng lẻo, thiếu sức thuyết phục, mang ý chê bai.', 'He felt his muscles had grown flabby during recovery.', NULL, 'Anh ấy cảm thấy cơ bắp của mình trở nên mềm nhão trong thời gian hồi phục.', '{"wordId":"flabby","ukIpa":"/ˈflæbi/","usIpa":"/ˈflæbi/","cefr":"C2","topic":"health","senses":[{"pos":"adj.","en":"having soft, loose flesh rather than firm muscles","vi":"nhão; mềm nhão (cơ bắp)"},{"pos":"adj.","en":"lacking strength, effectiveness, or clear structure","vi":"yếu ớt; thiếu sức sống; lỏng lẻo, thiếu chặt chẽ"}],"examples":[{"en":"He felt his muscles had grown flabby during recovery.","vi":"Anh ấy cảm thấy cơ bắp của mình trở nên mềm nhão trong thời gian hồi phục.","audioKind":"ex"},{"en":"An essay with flabby arguments may fail to persuade readers, even when its topic is important.","vi":"Một bài văn với các luận điểm lỏng lẻo, thiếu chặt chẽ có thể không thuyết phục được người đọc, ngay cả khi chủ đề của nó rất quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"flabby muscles","vi":"cơ bắp nhão"},{"en":"flabby arms","vi":"bắp tay nhão"},{"en":"flabby prose","vi":"văn phong lỏng lẻo"}],"wordFamily":["flab (n.)","flabbiness (n.)"],"synonyms":[],"antonyms":["firm","toned"],"tipVi":"Thường chỉ cơ bắp mềm nhão; khi miêu tả bài viết nghĩa là lỏng lẻo, thiếu sức thuyết phục, mang ý chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excrement', 'en-c2-5', 'excrement', '/ˈekskrɪmənt/', 'C2', 'phân; chất thải', 'n.', NULL, 'Đồng nghĩa: faeces', 'Là danh từ không đếm được, mang sắc thái trang trọng; trong đời sống thường dùng poo.', 'We found bird excrement on the garden bench.', NULL, 'Chúng tôi phát hiện thấy phân chim trên chiếc ghế dài ở vườn.', '{"wordId":"excrement","ukIpa":"/ˈekskrɪmənt/","usIpa":"/ˈekskrɪmənt/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"Solid waste passed out of a person''s or animal''s body.","vi":"phân; chất thải"}],"examples":[{"en":"We found bird excrement on the garden bench.","vi":"Chúng tôi phát hiện thấy phân chim trên chiếc ghế dài ở vườn.","audioKind":"ex"},{"en":"Untreated animal excrement can contaminate local water supplies and pose serious risks to public health.","vi":"Phân động vật chưa qua xử lý có thể làm ô nhiễm nguồn nước địa phương và gây ra rủi ro nghiêm trọng cho sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"animal excrement","vi":"phân động vật"},{"en":"human excrement","vi":"phân người"},{"en":"bird excrement","vi":"phân chim"}],"wordFamily":[],"synonyms":["faeces"],"antonyms":[],"tipVi":"Là danh từ không đếm được, mang sắc thái trang trọng; trong đời sống thường dùng poo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pharmaceutist', 'en-c2-5', 'pharmaceutist', '/ˌfɑːrməˈsuːtɪst/', 'C2', 'dược sĩ; nhà bào chế thuốc', 'n.', 'pharmacy (n.), pharmacist (n.), pharmaceutical (adj.)', 'Đồng nghĩa: pharmacist', 'Đây là từ cổ và ít dùng; trong tiếng Anh hiện đại, người ta thường dùng từ pharmacist.', 'The pharmaceutist carefully prepared the medicine for her patient.', NULL, 'Người dược sĩ cẩn thận chuẩn bị thuốc cho bệnh nhân của mình.', '{"wordId":"pharmaceutist","ukIpa":"/ˌfɑːməˈsjuːtɪst/","usIpa":"/ˌfɑːrməˈsuːtɪst/","cefr":"C2","topic":"health","senses":[{"pos":"n.","en":"A professional qualified to prepare and supply medicines","vi":"dược sĩ; nhà bào chế thuốc"}],"examples":[{"en":"The pharmaceutist carefully prepared the medicine for her patient.","vi":"Người dược sĩ cẩn thận chuẩn bị thuốc cho bệnh nhân của mình.","audioKind":"ex"},{"en":"In historical accounts of healthcare, the pharmaceutist often appears as an important provider of medicines and practical advice.","vi":"Trong các tài liệu lịch sử về y tế, dược sĩ thường xuất hiện như một nhà cung cấp thuốc men và đưa ra những lời khuyên thực tế quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"a qualified pharmaceutist","vi":"một dược sĩ đủ điều kiện hành nghề"},{"en":"a practising pharmaceutist","vi":"một dược sĩ đang hành nghề"}],"wordFamily":["pharmacy (n.)","pharmacist (n.)","pharmaceutical (adj.)"],"synonyms":["pharmacist"],"antonyms":[],"tipVi":"Đây là từ cổ và ít dùng; trong tiếng Anh hiện đại, người ta thường dùng từ pharmacist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_5_1', 'en-c2-5', 'Cách dùng “malaise” (n.) — cảm giác khó chịu, mệt mỏi chung không rõ nguyên nhân', 'general malaise  ·  economic malaise  ·  a sense of malaise', 'Mang tính trang trọng, vừa dùng để chỉ tình trạng mệt mỏi thể chất mơ hồ, vừa ám chỉ sự trì trệ kinh tế-xã hội.', NULL, '[{"hanzi":"A lingering malaise kept me on the sofa all afternoon.","pinyin":"","meaning":"Cảm giác mệt mỏi kéo dài khiến tôi nằm lì trên ghế sofa cả buổi chiều."},{"hanzi":"Prolonged economic malaise can weaken public confidence and discourage businesses from investing in new projects.","pinyin":"","meaning":"Tình trạng trì trệ kinh tế kéo dài có thể làm xói mòn niềm tin của công chúng và khiến các doanh nghiệp ngần ngại đầu tư vào các dự án mới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_5_2', 'en-c2-5', 'Cách dùng “flabby” (adj.) — nhão; mềm nhão (cơ bắp)', 'flabby muscles  ·  flabby arms  ·  flabby prose', 'Thường chỉ cơ bắp mềm nhão; khi miêu tả bài viết nghĩa là lỏng lẻo, thiếu sức thuyết phục, mang ý chê bai.', 'Họ từ (Word Family): flab (n.), flabbiness (n.) | Trái nghĩa: firm, toned', '[{"hanzi":"He felt his muscles had grown flabby during recovery.","pinyin":"","meaning":"Anh ấy cảm thấy cơ bắp của mình trở nên mềm nhão trong thời gian hồi phục."},{"hanzi":"An essay with flabby arguments may fail to persuade readers, even when its topic is important.","pinyin":"","meaning":"Một bài văn với các luận điểm lỏng lẻo, thiếu chặt chẽ có thể không thuyết phục được người đọc, ngay cả khi chủ đề của nó rất quan trọng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_5_3', 'en-c2-5', 'Cách dùng “delirium” (n.) — chứng sảng; tình trạng mê sảng', 'acute delirium  ·  postoperative delirium  ·  a state of delirium', 'Trong y học nghĩa là tình trạng rối loạn ý thức cấp tính, không đồng nhất với chứng mất trí nhớ mãn tính.', 'Họ từ (Word Family): delirious (adj.), deliriously (adv.)', '[{"hanzi":"During his fever, he slipped into delirium and spoke incoherently.","pinyin":"","meaning":"Trong cơn sốt, anh ấy rơi vào trạng thái mê sảng và nói năng lú lẫn."},{"hanzi":"Hospital staff need appropriate training to recognise delirium promptly, particularly among older patients recovering from surgery.","pinyin":"","meaning":"Nhân viên bệnh viện cần được đào tạo phù hợp để nhận biết kịp thời chứng mê sảng, đặc biệt là ở những bệnh nhân lớn tuổi đang hồi phục sau phẫu thuật."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_5_4', 'en-c2-5', 'Cách dùng “miscarry” (v.) — sẩy thai', 'miscarry early in pregnancy  ·  a plan miscarries', 'Thường chỉ việc sẩy thai tự nhiên; nghĩa chỉ kế hoạch thất bại mang tính trang trọng và ít dùng hơn.', 'Họ từ (Word Family): miscarriage (n.)', '[{"hanzi":"After she miscarried, her family offered comfort and support.","pinyin":"","meaning":"Sau khi cô ấy sẩy thai, gia đình đã an ủi và hỗ trợ cô ấy."},{"hanzi":"People who miscarry should have access to compassionate medical care and appropriate psychological support.","pinyin":"","meaning":"Những phụ nữ bị sẩy thai nên được tiếp cận dịch vụ y tế nhân đạo và hỗ trợ tâm lý phù hợp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_5_1', 'en-c2-5', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_1', 'ten_c2_5_1', 'splint', 'The nurse fitted a splint to my injured finger.', 'The nurse fitted a splint to my injured finger.', '/splɪnt/', 'Y tá đã nẹp ngón tay bị thương của tôi lại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_2', 'ten_c2_5_1', 'staphylococcus', 'The laboratory found staphylococcus in the skin sample.', 'The laboratory found staphylococcus in the skin sample.', '/ˌstæfɪləˈkɑːkəs/', 'Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_3', 'ten_c2_5_1', 'cervix', 'The nurse explained where the cervix is on the model.', 'The nurse explained where the cervix is on the model.', '/ˈsɝːvɪks/', 'Nữ hộ sinh đã giải thích vị trí của cổ tử cung trên mô hình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_4', 'ten_c2_5_1', 'prostrate', 'After crawling under the fence, he lay prostrate on the grass.', 'After crawling under the fence, he lay prostrate on the grass.', '/ˈprɑːstreɪt/', 'Sau khi bò qua hàng rào, anh ấy nằm sấp trên bãi cỏ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_5', 'ten_c2_5_1', 'tibia', 'The doctor showed me my tibia on the scan.', 'The doctor showed me my tibia on the scan.', '/ˈtɪbiə/', 'Bác sĩ đã chỉ cho tôi thấy xương chày của mình trên phim chụp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_6', 'ten_c2_5_1', 'miscarry', 'After she miscarried, her family offered comfort and support.', 'After she miscarried, her family offered comfort and support.', '/ˌmɪsˈkæri/', 'Sau khi cô ấy sẩy thai, gia đình đã an ủi và hỗ trợ cô ấy.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_7', 'ten_c2_5_1', 'distend', 'Too much gas can distend your stomach after meals.', 'Too much gas can distend your stomach after meals.', '/dɪˈstend/', 'Quá nhiều khí có thể làm dạ dày bạn phồng lên sau bữa ăn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_1_8', 'ten_c2_5_1', 'septic', 'The nurse cleaned the septic wound and changed its dressing.', 'The nurse cleaned the septic wound and changed its dressing.', '/ˈseptɪk/', 'Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_5_1_1', 'en-c2-5', 'ten_c2_5_1', 'listening', 'listening', 'The nurse fitted a splint to my injured finger.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Y tá đã nẹp ngón tay bị thương của tôi lại.","Anh ấy cảm thấy cơ bắp của mình trở nên mềm nhão trong thời gian hồi phục.","Cuốn sách tâm lý học cũ đã dành hẳn một chương nói về chứng thần kinh.","Cảm giác mệt mỏi kéo dài khiến tôi nằm lì trên ghế sofa cả buổi chiều."]'::jsonb, 0, 'The nurse fitted a splint to my injured finger. → Y tá đã nẹp ngón tay bị thương của tôi lại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_5_1_2', 'en-c2-5', 'ten_c2_5_1', 'listening', 'listening', 'The laboratory found staphylococcus in the skin sample.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc máy này có thể khiến ai đó bị thương nặng và tàn phế nếu không có bộ phận bảo vệ an toàn.","Bác sĩ đã chỉ cho tôi thấy xương chày của mình trên phim chụp.","Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.","Nữ hộ sinh đã giải thích vị trí của cổ tử cung trên mô hình."]'::jsonb, 2, 'The laboratory found staphylococcus in the skin sample. → Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_5_1_3', 'en-c2-5', 'ten_c2_5_1', 'listening', 'listening', 'The nurse explained where the cervix is on the model.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nữ hộ sinh đã giải thích vị trí của cổ tử cung trên mô hình.","Người dược sĩ cẩn thận chuẩn bị thuốc cho bệnh nhân của mình.","Chuyên gia giải thích rằng xơ hóa liên quan đến hiện tượng các mô trong cơ thể trở nên cứng lại.","Nữ hộ sinh giải thích việc tiêm chủng bảo vệ trẻ em khỏi bệnh bại liệt như thế nào."]'::jsonb, 0, 'The nurse explained where the cervix is on the model. → Nữ hộ sinh đã giải thích vị trí của cổ tử cung trên mô hình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_5_2', 'en-c2-5', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_2_1', 'ten_c2_5_2', 'splint', 'Using a splint to stabilise an injured limb can prevent further damage while patients await medical treatment.', 'Using a splint to stabilise an injured limb can prevent further damage while patients await medical treatment.', '/splɪnt/', 'Việc dùng nẹp để cố định một chi bị thương có thể ngăn ngừa tổn thương thêm trong lúc bệnh nhân chờ điều trị y tế.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_2_2', 'ten_c2_5_2', 'staphylococcus', 'Some strains of staphylococcus resist common antibiotics, making hospital infections more difficult to treat.', 'Some strains of staphylococcus resist common antibiotics, making hospital infections more difficult to treat.', '/ˌstæfɪləˈkɑːkəs/', 'Một số chủng tụ cầu khuẩn có khả năng kháng lại các loại kháng sinh thông thường, khiến cho các bệnh nhiễm trùng trong bệnh viện trở nên khó điều trị hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_2_3', 'ten_c2_5_2', 'cervix', 'Regular screening can detect abnormal cells in the cervix before they develop into a serious health problem.', 'Regular screening can detect abnormal cells in the cervix before they develop into a serious health problem.', '/ˈsɝːvɪks/', 'Việc tầm soát định kỳ có thể phát hiện các tế bào bất thường ở cổ tử cung trước khi chúng tiến triển thành vấn đề sức khỏe nghiêm trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_2_4', 'ten_c2_5_2', 'prostrate', 'Extreme heat can leave outdoor workers prostrate with exhaustion, highlighting the importance of regular breaks.', 'Extreme heat can leave outdoor workers prostrate with exhaustion, highlighting the importance of regular breaks.', '/ˈprɑːstreɪt/', 'Nắng nóng cực độ có thể khiến lao động ngoài trời kiệt sức, làm nổi bật tầm quan trọng của việc nghỉ ngơi đều đặn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_2_5', 'ten_c2_5_2', 'tibia', 'A fracture of the tibia may require several months of rehabilitation before an athlete can safely resume training.', 'A fracture of the tibia may require several months of rehabilitation before an athlete can safely resume training.', '/ˈtɪbiə/', 'Một vết gãy xương chày có thể đòi hỏi vài tháng phục hồi chức năng trước khi một vận động viên có thể an toàn trở lại tập luyện.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_5_2_6', 'ten_c2_5_2', 'miscarry', 'People who miscarry should have access to compassionate medical care and appropriate psychological support.', 'People who miscarry should have access to compassionate medical care and appropriate psychological support.', '/ˌmɪsˈkæri/', 'Những phụ nữ bị sẩy thai nên được tiếp cận dịch vụ y tế nhân đạo và hỗ trợ tâm lý phù hợp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_5_2_1', 'en-c2-5', 'ten_c2_5_2', 'listening', 'listening', 'Using a splint to stabilise an injured limb can prevent further damage while patients await medical treatment.', NULL, 'Trong câu vừa nghe, từ “splint” mang nghĩa nào sau đây?', '["nẹp cố định","lan tỏa; bao trùm; thấm đượm khắp nơi","cành lớn; nhánh cây chính","tính thích hợp; sự liên quan trực tiếp"]'::jsonb, 0, '“splint” (/splɪnt/): nẹp cố định. Câu đầy đủ: Using a splint to stabilise an injured limb can prevent further damage while patients await medical treatment.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_5_2_2', 'en-c2-5', 'ten_c2_5_2', 'listening', 'listening', 'Some strains of staphylococcus resist common antibiotics, making hospital infections more difficult to treat.', NULL, 'Trong câu vừa nghe, từ “staphylococcus” mang nghĩa nào sau đây?', '["tụ cầu khuẩn","bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)","phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức","thuật luyện kim; phép luyện đan"]'::jsonb, 0, '“staphylococcus” (/ˌstæfɪləˈkɑːkəs/): tụ cầu khuẩn. Câu đầy đủ: Some strains of staphylococcus resist common antibiotics, making hospital infections more difficult to treat.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
