INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_5_4', 'en-c2-5', 'After crawling under the fence, he lay prostrate on the grass', 'Sau khi bò qua hàng rào, anh ấy nằm sấp trên bãi cỏ.', 'prostrate /ˈprɑːstreɪt/', '["he","on","crawling","the","grass","fence","lay","the","prostrate","under","After"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
