INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_5_2', 'en-c2-5', 'en_to_vi', 'The nurse cleaned the septic wound and changed its dressing.', 'The nurse cleaned the septic wound and changed its dressing.', '/ˈseptɪk/', NULL, 'Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó.', NULL, '["nữ","y","tá","đã","sát","trùng","vết","thương"]'::jsonb, 'Từ trọng tâm: septic (nhiễm trùng; mưng mủ)', 'The nurse cleaned the septic wound and changed its dressing. → Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
