INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_2', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'The laboratory found staphylococcus in the skin sample.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chuyên gia giải thích rằng xơ hóa liên quan đến hiện tượng các mô trong cơ thể trở nên cứng lại.","Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.","Chúng tôi phát hiện thấy phân chim trên chiếc ghế dài ở vườn.","Bệnh tình của cô ấy đang trong giai đoạn thuyên giảm và cô ấy cảm thấy khỏe khoắn hơn."]'::jsonb, 1, 'The laboratory found staphylococcus in the skin sample. → Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_3', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'cervix', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vết loét","đánh bại hoàn toàn một đối thủ","cổ tử cung","dồi dào; vô kể; tuôn trào"]'::jsonb, 2, 'cervix (/ˈsɝːvɪks/) → cổ tử cung', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_4', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'After crawling under the fence, he lay prostrate on the grass.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuốn sách tâm lý học cũ đã dành hẳn một chương nói về chứng thần kinh.","Chiếc máy này có thể khiến ai đó bị thương nặng và tàn phế nếu không có bộ phận bảo vệ an toàn.","Sau khi bò qua hàng rào, anh ấy nằm sấp trên bãi cỏ.","Chuyên gia giải thích rằng xơ hóa liên quan đến hiện tượng các mô trong cơ thể trở nên cứng lại."]'::jsonb, 2, 'After crawling under the fence, he lay prostrate on the grass. → Sau khi bò qua hàng rào, anh ấy nằm sấp trên bãi cỏ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_5', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'tibia', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vết loét","xương chày","trọng lượng của bao bì hoặc vật chứa (bì)","đặc trưng; tiêu biểu"]'::jsonb, 1, 'tibia (/ˈtɪbiə/) → xương chày', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_6', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'After she miscarried, her family offered comfort and support.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau khi cô ấy sẩy thai, gia đình đã an ủi và hỗ trợ cô ấy.","Phòng thí nghiệm đã tìm thấy tụ cầu khuẩn trong mẫu da.","Chuyên gia giải thích rằng xơ hóa liên quan đến hiện tượng các mô trong cơ thể trở nên cứng lại.","Người dược sĩ cẩn thận chuẩn bị thuốc cho bệnh nhân của mình."]'::jsonb, 0, 'After she miscarried, her family offered comfort and support. → Sau khi cô ấy sẩy thai, gia đình đã an ủi và hỗ trợ cô ấy.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_7', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'distend', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mang tính bước ngoặt; mở ra thời đại mới; vĩ đại","trọng lượng của bao bì hoặc vật chứa (bì)","làm phồng lên; làm căng ra; trương lên","du dương; êm tai; ngọt ngào"]'::jsonb, 2, 'distend (/dɪˈstend/) → làm phồng lên; làm căng ra; trương lên', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_8', 'en-c2-5', NULL, 'comprehensive_test', 'listening', 'The nurse cleaned the septic wound and changed its dressing.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc máy này có thể khiến ai đó bị thương nặng và tàn phế nếu không có bộ phận bảo vệ an toàn.","Nữ hộ sinh giải thích việc tiêm chủng bảo vệ trẻ em khỏi bệnh bại liệt như thế nào.","Bác sĩ đã kiểm tra má bị sưng của cô ấy để tìm dấu hiệu của bệnh quai bị.","Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó."]'::jsonb, 3, 'The nurse cleaned the septic wound and changed its dressing. → Nữ y tá đã sát trùng vết thương bị nhiễm trùng và thay băng cho nó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_9', 'en-c2-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The larger front bone between the knee and ankle”?', '["splint","neurosis","pharmaceutist","tibia"]'::jsonb, 3, 'tibia (/ˈtɪbiə/) → xương chày', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_10', 'en-c2-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Lose a pregnancy before the baby can survive outside the womb.”?', '["miscarry","staphylococcus","delirium","neurosis"]'::jsonb, 0, 'miscarry (/ˌmɪsˈkæri/) → sẩy thai', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_11', 'en-c2-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To swell or become larger because of pressure from inside.”?', '["maim","distend","miscarry","neurosis"]'::jsonb, 1, 'distend (/dɪˈstend/) → làm phồng lên; làm căng ra; trương lên', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_12', 'en-c2-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “infected with harmful bacteria, or relating to such infection”?', '["staphylococcus","septic","ulcer","sclerosis"]'::jsonb, 1, 'septic (/ˈseptɪk/) → nhiễm trùng; mưng mủ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_13', 'en-c2-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “an open sore on the skin or inside the body”?', '["staphylococcus","sclerosis","ulcer","miscarry"]'::jsonb, 2, 'ulcer (/ˈʌlsɚ/) → vết loét', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
