INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_18', 'en-c2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Using a splint to stabilise an injured limb can prevent further damage while patients await medical treatment.', 'Dựa vào câu trên, từ “splint” có nghĩa phù hợp nhất là gì?', '["trái nghĩa; có nghĩa đối lập","kích động; khiêu khích; xúi giục","kịch liệt phản đối; vô cùng đau xót","nẹp cố định"]'::jsonb, 3, 'splint: nẹp cố định; nẹp cố định (bằng nẹp). Dịch cả câu: Việc dùng nẹp để cố định một chi bị thương có thể ngăn ngừa tổn thương thêm trong lúc bệnh nhân chờ điều trị y tế.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_19', 'en-c2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Some strains of staphylococcus resist common antibiotics, making hospital infections more difficult to treat.', 'Dựa vào câu trên, từ “staphylococcus” có nghĩa phù hợp nhất là gì?', '["ôn hòa; hòa bình; chuộng hòa bình","tụ cầu khuẩn","sự phô trương; sự khoe khoang; tính chưng diện","cuộc đụng độ nhỏ; xung đột ngắn"]'::jsonb, 1, 'staphylococcus: tụ cầu khuẩn. Dịch cả câu: Một số chủng tụ cầu khuẩn có khả năng kháng lại các loại kháng sinh thông thường, khiến cho các bệnh nhiễm trùng trong bệnh viện trở nên khó điều trị hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_20', 'en-c2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Regular screening can detect abnormal cells in the cervix before they develop into a serious health problem.', 'Dựa vào câu trên, từ “cervix” có nghĩa phù hợp nhất là gì?', '["hệ thống hoặc máy truyền bản tài liệu qua đường dây điện thoại; máy fax","cổ tử cung","ghê tởm; đáng ghét","mang tính cam kết, đặc biệt là cam kết trả tiền bằng văn bản"]'::jsonb, 1, 'cervix: cổ tử cung. Dịch cả câu: Việc tầm soát định kỳ có thể phát hiện các tế bào bất thường ở cổ tử cung trước khi chúng tiến triển thành vấn đề sức khỏe nghiêm trọng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_21', 'en-c2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Extreme heat can leave outdoor workers prostrate with exhaustion, highlighting the importance of regular breaks.', 'Dựa vào câu trên, từ “prostrate” có nghĩa phù hợp nhất là gì?', '["nằm sấp; phủ phục","vết loét","chuyển tải; trung chuyển hàng hóa","trong tài liệu này; ở đây; trong này"]'::jsonb, 0, 'prostrate: nằm sấp; phủ phục; kiệt sức; suy nhược; suy sụp; làm cho nằm sấp; làm cho kiệt sức. Dịch cả câu: Nắng nóng cực độ có thể khiến lao động ngoài trời kiệt sức, làm nổi bật tầm quan trọng của việc nghỉ ngơi đều đặn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_22', 'en-c2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhão; mềm nhão (cơ bắp)”', '["undulate","flabby","pervade","tantalize"]'::jsonb, 1, 'nhão; mềm nhão (cơ bắp) → flabby (/ˈflæbi/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_23', 'en-c2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phân; chất thải”', '["harangue","alchemy","excrement","peroxide"]'::jsonb, 2, 'phân; chất thải → excrement (/ˈekskrɪmənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_5_24', 'en-c2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dược sĩ; nhà bào chế thuốc”', '["alluvial","plaintive","inexorable","pharmaceutist"]'::jsonb, 3, 'dược sĩ; nhà bào chế thuốc → pharmaceutist (/ˌfɑːrməˈsuːtɪst/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-6', 'en', 'Bài 6: Nghệ thuật & Sáng tạo - CEFR C2', 'CEFR C2', 'C2 · Nghệ thuật', '11 từ vựng Tiếng Anh CEFR C2 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6006, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trite', 'en-c2-6', 'trite', '/traɪt/', 'C2', 'sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm', 'adj.', 'tritely (adv.), triteness (n.)', 'Đồng nghĩa: hackneyed, banal, unoriginal · Trái nghĩa: original, fresh', 'Nhấn mạnh tính chất mất đi sự tươi mới do lặp đi lặp lại nhiều lần, không chỉ đơn thuần là có từ lâu đời.', 'The film ends with a trite speech about friendship.', NULL, 'Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn.', '{"wordId":"trite","ukIpa":"/traɪt/","usIpa":"/traɪt/","cefr":"C2","topic":"arts","senses":[{"pos":"adj.","en":"Overused and therefore no longer interesting or original","vi":"sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm"}],"examples":[{"en":"The film ends with a trite speech about friendship.","vi":"Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn.","audioKind":"ex"},{"en":"Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.","vi":"Các chiến dịch nâng cao nhận thức cộng đồng có thể thất bại nếu chúng chỉ dựa vào các khẩu hiệu sáo rỗng thay vì đưa ra lời khuyên thực tế cùng những bằng chứng thuyết phục.","audioKind":"ex2"}],"collocations":[{"en":"trite remark","vi":"lời nói sáo rỗng"},{"en":"trite phrase","vi":"cách diễn đạt cũ rích"},{"en":"sound trite","vi":"nghe có vẻ nhàm chán"}],"wordFamily":["tritely (adv.)","triteness (n.)"],"synonyms":["hackneyed","banal","unoriginal"],"antonyms":["original","fresh"],"tipVi":"Nhấn mạnh tính chất mất đi sự tươi mới do lặp đi lặp lại nhiều lần, không chỉ đơn thuần là có từ lâu đời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modish', 'en-c2-6', 'modish', '/ˈmoʊdɪʃ/', 'C2', 'hợp mốt; sành điệu; hợp thời trang', 'adj.', 'modishly (adv.), modishness (n.)', 'Đồng nghĩa: fashionable, stylish, trendy · Trái nghĩa: unfashionable, outdated', 'Mang tính văn phong cao, đôi khi ngụ ý sự "chạy theo mốt".', 'He arrived wearing a modish jacket and polished boots.', NULL, 'Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.', '{"wordId":"modish","ukIpa":"/ˈməʊdɪʃ/","usIpa":"/ˈmoʊdɪʃ/","cefr":"C2","topic":"arts","senses":[{"pos":"adj.","en":"Following the styles that are currently fashionable.","vi":"hợp mốt; sành điệu; hợp thời trang"}],"examples":[{"en":"He arrived wearing a modish jacket and polished boots.","vi":"Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.","audioKind":"ex"},{"en":"Modish interiors may attract customers initially, but lasting success depends on reliable service and quality.","vi":"Nội thất hợp mốt có thể thu hút khách hàng lúc ban đầu, nhưng thành công lâu dài phụ thuộc vào dịch vụ đáng tin cậy và chất lượng.","audioKind":"ex2"}],"collocations":[{"en":"modish clothes","vi":"trang phục hợp mốt"},{"en":"modish design","vi":"thiết kế thời trang"},{"en":"modish interiors","vi":"nội thất hợp thời trang"}],"wordFamily":["modishly (adv.)","modishness (n.)"],"synonyms":["fashionable","stylish","trendy"],"antonyms":["unfashionable","outdated"],"tipVi":"Mang tính văn phong cao, đôi khi ngụ ý sự \"chạy theo mốt\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slay', 'en-c2-6', 'slay', '/sleɪ/', 'C2', 'giết; tiêu diệt', 'v.', 'slayer (n.)', 'Đồng nghĩa: kill', 'Có dạng quá khứ là "slew" và phân từ hai là "slain"; thường gặp trong văn học hoặc bản tin.', 'In the old tale, a knight slays a dragon.', NULL, 'Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.', '{"wordId":"slay","ukIpa":"/sleɪ/","usIpa":"/sleɪ/","cefr":"C2","topic":"arts","senses":[{"pos":"v.","en":"To kill someone or something, especially violently.","vi":"giết; tiêu diệt"}],"examples":[{"en":"In the old tale, a knight slays a dragon.","vi":"Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.","audioKind":"ex"},{"en":"Traditional legends often celebrate heroes who slay monsters to protect their communities from danger.","vi":"Các truyền thuyết truyền thống thường ca ngợi những người anh hùng tiêu diệt quái vật để bảo vệ cộng đồng khỏi hiểm nguy.","audioKind":"ex2"}],"collocations":[{"en":"slay a dragon","vi":"tiêu diệt rồng"},{"en":"slay a monster","vi":"giết quái vật"}],"wordFamily":["slayer (n.)"],"synonyms":["kill"],"antonyms":[],"tipVi":"Có dạng quá khứ là \"slew\" và phân từ hai là \"slain\"; thường gặp trong văn học hoặc bản tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dainty', 'en-c2-6', 'dainty', '/ˈdeɪnti/', 'C2', 'nhỏ nhắn và tinh xảo; xinh xắn; nhã nhặn; thanh lịch; nhẹ nhàng', 'adj.', 'daintily (adv.), daintiness (n.)', 'Đồng nghĩa: delicate, exquisite · Trái nghĩa: clumsy', 'Thường miêu tả các vật dụng như tách trà, trang sức nhỏ gọn và tinh tế, không dùng để chỉ đồ cao cấp nói chung.', 'She served the tea in dainty porcelain cups.', NULL, 'Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.', '{"wordId":"dainty","ukIpa":"/ˈdeɪnti/","usIpa":"/ˈdeɪnti/","cefr":"C2","topic":"arts","senses":[{"pos":"adj.","en":"small, delicate, and attractive","vi":"nhỏ nhắn và tinh xảo; xinh xắn"},{"pos":"adj.","en":"showing delicate or careful movements and manners","vi":"nhã nhặn; thanh lịch; nhẹ nhàng"}],"examples":[{"en":"She served the tea in dainty porcelain cups.","vi":"Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.","audioKind":"ex"},{"en":"The exhibition features dainty ornaments that demonstrate the remarkable precision achieved by traditional craft workers.","vi":"Triển lãm trưng bày những món đồ trang sức tinh xảo thể hiện độ chính xác đáng kinh ngạc của các thợ thủ công truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"dainty jewellery","vi":"trang sức tinh xảo"},{"en":"dainty cups","vi":"tách trà xinh xắn"},{"en":"dainty bites","vi":"ăn miếng nhỏ"}],"wordFamily":["daintily (adv.)","daintiness (n.)"],"synonyms":["delicate","exquisite"],"antonyms":["clumsy"],"tipVi":"Thường miêu tả các vật dụng như tách trà, trang sức nhỏ gọn và tinh tế, không dùng để chỉ đồ cao cấp nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_melodious', 'en-c2-6', 'melodious', '/məˈloʊdiəs/', 'C2', 'du dương; êm tai; ngọt ngào', 'adj.', 'melody (n.), melodiously (adv.), melodic (adj.)', 'Đồng nghĩa: tuneful, musical · Trái nghĩa: discordant', 'Nhấn mạnh âm thanh nghe du dương, êm tai; trong khi melodic thiên về cấu trúc giai điệu.', 'A melodious whistle drifted through the open kitchen window.', NULL, 'Một tiếng huýt sáo du dương văng vẳng qua ô cửa sổ bếp đang mở.', '{"wordId":"melodious","ukIpa":"/məˈləʊdiəs/","usIpa":"/məˈloʊdiəs/","cefr":"C2","topic":"arts","senses":[{"pos":"adj.","en":"Having a pleasant musical sound","vi":"du dương; êm tai; ngọt ngào"}],"examples":[{"en":"A melodious whistle drifted through the open kitchen window.","vi":"Một tiếng huýt sáo du dương văng vẳng qua ô cửa sổ bếp đang mở.","audioKind":"ex"},{"en":"Traditional instruments produce melodious sounds that can introduce younger audiences to their cultural heritage.","vi":"Các nhạc cụ truyền thống tạo ra những âm thanh du dương có thể giúp khán giả trẻ tiếp cận di sản văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"melodious voice","vi":"giọng ca du dương"},{"en":"melodious song","vi":"bài hát trữ tình"},{"en":"melodious sound","vi":"âm thanh du dương"}],"wordFamily":["melody (n.)","melodiously (adv.)","melodic (adj.)"],"synonyms":["tuneful","musical"],"antonyms":["discordant"],"tipVi":"Nhấn mạnh âm thanh nghe du dương, êm tai; trong khi melodic thiên về cấu trúc giai điệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abridge', 'en-c2-6', 'abridge', '/əˈbrɪdʒ/', 'C2', 'rút gọn; cô đọng (văn bản nhưng vẫn giữ nguyên nội dung chính)', 'v.', 'abridged (adj.), abridgement (n.), unabridged (adj.)', 'Đồng nghĩa: shorten, condense · Trái nghĩa: expand', 'Cắt bớt nội dung nhưng giữ nguyên phần cốt lõi, không đồng nghĩa với việc viết tóm tắt.', 'The publisher abridged the novel for younger readers.', NULL, 'Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi.', '{"wordId":"abridge","ukIpa":"/əˈbrɪdʒ/","usIpa":"/əˈbrɪdʒ/","cefr":"C2","topic":"arts","senses":[{"pos":"v.","en":"To shorten a written work while keeping its main content.","vi":"rút gọn; cô đọng (văn bản nhưng vẫn giữ nguyên nội dung chính)"}],"examples":[{"en":"The publisher abridged the novel for younger readers.","vi":"Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi.","audioKind":"ex"},{"en":"Publishers often abridge classic novels to make them more accessible to students with limited reading experience.","vi":"Các nhà xuất bản thường rút gọn các tiểu thuyết kinh điển để học sinh có ít kinh nghiệm đọc sách có thể dễ dàng tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"abridge a novel","vi":"rút gọn một cuốn tiểu thuyết"},{"en":"an abridged edition","vi":"bản rút gọn"},{"en":"an abridged version","vi":"phiên bản rút gọn"}],"wordFamily":["abridged (adj.)","abridgement (n.)","unabridged (adj.)"],"synonyms":["shorten","condense"],"antonyms":["expand"],"tipVi":"Cắt bớt nội dung nhưng giữ nguyên phần cốt lõi, không đồng nghĩa với việc viết tóm tắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_macabre', 'en-c2-6', 'macabre', '/məˈkɑːbrə/', 'C2', 'rùng rợn; kinh dị (do có liên quan đến cái chết)', 'adj.', NULL, 'Đồng nghĩa: gruesome, ghoulish', 'Không dùng chung chung cho mọi thứ đáng sợ, mà thường gắn liền với cái chết hoặc những chi tiết gây ám ảnh.', 'The old theatre displayed a macabre painting of dancing skeletons.', NULL, 'Nhà hát cổ trưng bày một bức tranh rùng rợn vẽ những bộ xương đang nhảy múa.', '{"wordId":"macabre","ukIpa":"/məˈkɑːbrə/","usIpa":"/məˈkɑːbrə/","cefr":"C2","topic":"arts","senses":[{"pos":"adj.","en":"Disturbing or frightening because of a connection with death.","vi":"rùng rợn; kinh dị (do có liên quan đến cái chết)"}],"examples":[{"en":"The old theatre displayed a macabre painting of dancing skeletons.","vi":"Nhà hát cổ trưng bày một bức tranh rùng rợn vẽ những bộ xương đang nhảy múa.","audioKind":"ex"},{"en":"Macabre imagery in literature can encourage readers to reflect on mortality rather than merely provoke fear.","vi":"Hình ảnh mang tính kinh dị về cái chết trong văn học có thể khuyến khích độc giả suy ngẫm về sự tử vong thay vì chỉ đơn thuần gây ra sợ hãi.","audioKind":"ex2"}],"collocations":[{"en":"macabre humour","vi":"sự hài hước đen tối về cái chết"},{"en":"macabre imagery","vi":"hình ảnh rùng rợn về cái chết"},{"en":"macabre tale","vi":"câu chuyện rùng rợn"}],"wordFamily":[],"synonyms":["gruesome","ghoulish"],"antonyms":[],"tipVi":"Không dùng chung chung cho mọi thứ đáng sợ, mà thường gắn liền với cái chết hoặc những chi tiết gây ám ảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diction', 'en-c2-6', 'diction', '/ˈdɪkʃən/', 'C2', 'cách dùng từ; phong cách lựa chọn từ ngữ; cách phát âm; sự rõ ràng trong lời nói', 'n.', NULL, NULL, 'Có thể chỉ phong cách từ vựng hoặc cách phát âm rõ ràng.', 'Her formal diction sounded strange at our relaxed picnic.', NULL, 'Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi.', '{"wordId":"diction","ukIpa":"/ˈdɪkʃən/","usIpa":"/ˈdɪkʃən/","cefr":"C2","topic":"arts","senses":[{"pos":"n.","en":"The choice and style of words in speech or writing.","vi":"cách dùng từ; phong cách lựa chọn từ ngữ"},{"pos":"n.","en":"The way someone pronounces words, especially how clearly.","vi":"cách phát âm; sự rõ ràng trong lời nói"}],"examples":[{"en":"Her formal diction sounded strange at our relaxed picnic.","vi":"Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi.","audioKind":"ex"},{"en":"Writers often adapt their diction to make complex scientific ideas accessible to a wider audience.","vi":"Các nhà văn thường điều chỉnh cách dùng từ để giúp đông đảo độc giả hơn có thể tiếp cận các ý tưởng khoa học phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"formal diction","vi":"lối dùng từ trang trọng"},{"en":"poetic diction","vi":"ngôn ngữ thơ ca"},{"en":"clear diction","vi":"phát âm rõ ràng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ phong cách từ vựng hoặc cách phát âm rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bosom', 'en-c2-6', 'bosom', '/ˈbʊzəm/', 'C2', 'ngực; bầu ngực; vòng tay ôm ấp; thân thiết; tri kỷ (thường dùng trước danh từ chỉ bạn bè)', 'n.', NULL, 'Đồng nghĩa: chest', 'Từ mang tính văn học hoặc hơi cổ; bosom friend chỉ bạn tri kỷ.', 'The grandmother held the sleepy child to her bosom.', NULL, 'Người bà ôm đứa cháu đang ngái ngủ vào lòng.', '{"wordId":"bosom","ukIpa":"/ˈbʊzəm/","usIpa":"/ˈbʊzəm/","cefr":"C2","topic":"arts","senses":[{"pos":"n.","en":"The chest, especially a woman''s, or the embrace it provides.","vi":"ngực; bầu ngực; vòng tay ôm ấp"},{"pos":"adj.","en":"Very close and trusted, used mainly before friend.","vi":"thân thiết; tri kỷ (thường dùng trước danh từ chỉ bạn bè)"}],"examples":[{"en":"The grandmother held the sleepy child to her bosom.","vi":"Người bà ôm đứa cháu đang ngái ngủ vào lòng.","audioKind":"ex"},{"en":"Traditional paintings often depict a parent holding a child to their bosom, symbolising protection and affection.","vi":"Các bức tranh truyền thống thường khắc họa cảnh cha mẹ ôm con vào lòng, tượng trưng cho sự bảo bọc và tình yêu thương.","audioKind":"ex2"}],"collocations":[{"en":"hold someone to one''s bosom","vi":"ôm ai đó vào lòng"},{"en":"bosom friend","vi":"bạn tri kỷ"},{"en":"in the bosom of the family","vi":"trong vòng tay ấm áp của gia đình"}],"wordFamily":[],"synonyms":["chest"],"antonyms":[],"tipVi":"Từ mang tính văn học hoặc hơi cổ; bosom friend chỉ bạn tri kỷ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pathos', 'en-c2-6', 'pathos', '/ˈpeɪθɑːs/', 'C2', 'sức gợi cảm; nỗi niềm xót xa; tính bi cảm', 'n.', NULL, 'Đồng nghĩa: poignancy', 'Thường là danh từ không đếm được, nhấn mạnh chất lượng khơi gợi lòng trắc ẩn hoặc sự buồn thương sâu sắc.', 'The abandoned toy gave the photograph a quiet pathos.', NULL, 'Món đồ chơi bị bỏ rơi đã mang lại cho bức ảnh một nỗi buồn man mác và tĩnh lặng.', '{"wordId":"pathos","ukIpa":"/ˈpeɪθɒs/","usIpa":"/ˈpeɪθɑːs/","cefr":"C2","topic":"arts","senses":[{"pos":"n.","en":"A quality that makes people feel pity or sadness.","vi":"sức gợi cảm; nỗi niềm xót xa; tính bi cảm"}],"examples":[{"en":"The abandoned toy gave the photograph a quiet pathos.","vi":"Món đồ chơi bị bỏ rơi đã mang lại cho bức ảnh một nỗi buồn man mác và tĩnh lặng.","audioKind":"ex"},{"en":"The pathos of personal stories can make documentaries about social inequality more emotionally engaging.","vi":"Sức mạnh bi cảm trong những câu chuyện cá nhân có thể làm cho các bộ phim tài liệu về sự bất công xã hội trở nên chạm đến cảm xúc người xem hơn.","audioKind":"ex2"}],"collocations":[{"en":"full of pathos","vi":"đầy nỗi xót xa bi cảm"},{"en":"a sense of pathos","vi":"một cảm giác xót xa"},{"en":"humour and pathos","vi":"sự hài hước và bi cảm"}],"wordFamily":[],"synonyms":["poignancy"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, nhấn mạnh chất lượng khơi gợi lòng trắc ẩn hoặc sự buồn thương sâu sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mien', 'en-c2-6', 'mien', '/miːn/', 'C2', 'thần thái; phong thái; dáng vẻ', 'n.', NULL, 'Đồng nghĩa: demeanour, bearing', 'Là từ mang phong cách trang trọng hoặc văn chương; phát âm giống từ mean, chỉ biểu cảm hoặc dáng vẻ bên ngoài.', 'Her cheerful mien brightened the room as she entered.', NULL, 'Vẻ ngoài vui tươi của cô ấy làm bừng sáng cả căn phòng ngay khi cô bước vào.', '{"wordId":"mien","ukIpa":"/miːn/","usIpa":"/miːn/","cefr":"C2","topic":"arts","senses":[{"pos":"n.","en":"A person''s appearance or manner, especially showing mood or character.","vi":"thần thái; phong thái; dáng vẻ"}],"examples":[{"en":"Her cheerful mien brightened the room as she entered.","vi":"Vẻ ngoài vui tươi của cô ấy làm bừng sáng cả căn phòng ngay khi cô bước vào.","audioKind":"ex"},{"en":"Despite his stern mien, the headteacher encouraged students to discuss their concerns openly and without fear.","vi":"Mặc dù có vẻ ngoài nghiêm nghị, hiệu trưởng vẫn khuyến khích học sinh cởi mở thảo luận về những băn khoăn của mình mà không phải sợ hãi.","audioKind":"ex2"}],"collocations":[{"en":"a serious mien","vi":"thần thái nghiêm nghị"},{"en":"a cheerful mien","vi":"dáng vẻ vui tươi"},{"en":"a dignified mien","vi":"phong thái uy nghiêm"}],"wordFamily":[],"synonyms":["demeanour","bearing"],"antonyms":[],"tipVi":"Là từ mang phong cách trang trọng hoặc văn chương; phát âm giống từ mean, chỉ biểu cảm hoặc dáng vẻ bên ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_6_1', 'en-c2-6', 'Cách dùng “dainty” (adj.) — nhỏ nhắn và tinh xảo; xinh xắn', 'dainty jewellery  ·  dainty cups  ·  dainty bites', 'Thường miêu tả các vật dụng như tách trà, trang sức nhỏ gọn và tinh tế, không dùng để chỉ đồ cao cấp nói chung.', 'Họ từ (Word Family): daintily (adv.), daintiness (n.) | Đồng nghĩa: delicate, exquisite · Trái nghĩa: clumsy', '[{"hanzi":"She served the tea in dainty porcelain cups.","pinyin":"","meaning":"Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn."},{"hanzi":"The exhibition features dainty ornaments that demonstrate the remarkable precision achieved by traditional craft workers.","pinyin":"","meaning":"Triển lãm trưng bày những món đồ trang sức tinh xảo thể hiện độ chính xác đáng kinh ngạc của các thợ thủ công truyền thống."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_6_2', 'en-c2-6', 'Cách dùng “mien” (n.) — thần thái; phong thái; dáng vẻ', 'a serious mien  ·  a cheerful mien  ·  a dignified mien', 'Là từ mang phong cách trang trọng hoặc văn chương; phát âm giống từ mean, chỉ biểu cảm hoặc dáng vẻ bên ngoài.', 'Đồng nghĩa: demeanour, bearing', '[{"hanzi":"Her cheerful mien brightened the room as she entered.","pinyin":"","meaning":"Vẻ ngoài vui tươi của cô ấy làm bừng sáng cả căn phòng ngay khi cô bước vào."},{"hanzi":"Despite his stern mien, the headteacher encouraged students to discuss their concerns openly and without fear.","pinyin":"","meaning":"Mặc dù có vẻ ngoài nghiêm nghị, hiệu trưởng vẫn khuyến khích học sinh cởi mở thảo luận về những băn khoăn của mình mà không phải sợ hãi."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_6_3', 'en-c2-6', 'Cách dùng “macabre” (adj.) — rùng rợn; kinh dị (do có liên quan đến cái chết)', 'macabre humour  ·  macabre imagery  ·  macabre tale', 'Không dùng chung chung cho mọi thứ đáng sợ, mà thường gắn liền với cái chết hoặc những chi tiết gây ám ảnh.', 'Đồng nghĩa: gruesome, ghoulish', '[{"hanzi":"The old theatre displayed a macabre painting of dancing skeletons.","pinyin":"","meaning":"Nhà hát cổ trưng bày một bức tranh rùng rợn vẽ những bộ xương đang nhảy múa."},{"hanzi":"Macabre imagery in literature can encourage readers to reflect on mortality rather than merely provoke fear.","pinyin":"","meaning":"Hình ảnh mang tính kinh dị về cái chết trong văn học có thể khuyến khích độc giả suy ngẫm về sự tử vong thay vì chỉ đơn thuần gây ra sợ hãi."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_6_4', 'en-c2-6', 'Cách dùng “trite” (adj.) — sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm', 'trite remark  ·  trite phrase  ·  sound trite', 'Nhấn mạnh tính chất mất đi sự tươi mới do lặp đi lặp lại nhiều lần, không chỉ đơn thuần là có từ lâu đời.', 'Họ từ (Word Family): tritely (adv.), triteness (n.) | Đồng nghĩa: hackneyed, banal, unoriginal · Trái nghĩa: original, fresh', '[{"hanzi":"The film ends with a trite speech about friendship.","pinyin":"","meaning":"Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn."},{"hanzi":"Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.","pinyin":"","meaning":"Các chiến dịch nâng cao nhận thức cộng đồng có thể thất bại nếu chúng chỉ dựa vào các khẩu hiệu sáo rỗng thay vì đưa ra lời khuyên thực tế cùng những bằng chứng thuyết phục."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_6_1', 'en-c2-6', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_1_1', 'ten_c2_6_1', 'trite', 'The film ends with a trite speech about friendship.', 'The film ends with a trite speech about friendship.', '/traɪt/', 'Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_1_2', 'ten_c2_6_1', 'modish', 'He arrived wearing a modish jacket and polished boots.', 'He arrived wearing a modish jacket and polished boots.', '/ˈmoʊdɪʃ/', 'Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_1_3', 'ten_c2_6_1', 'slay', 'In the old tale, a knight slays a dragon.', 'In the old tale, a knight slays a dragon.', '/sleɪ/', 'Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
