INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_1_6', 'ten_c2_6_1', 'abridge', 'The publisher abridged the novel for younger readers.', 'The publisher abridged the novel for younger readers.', '/əˈbrɪdʒ/', 'Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_1_7', 'ten_c2_6_1', 'macabre', 'The old theatre displayed a macabre painting of dancing skeletons.', 'The old theatre displayed a macabre painting of dancing skeletons.', '/məˈkɑːbrə/', 'Nhà hát cổ trưng bày một bức tranh rùng rợn vẽ những bộ xương đang nhảy múa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_1_8', 'ten_c2_6_1', 'diction', 'Her formal diction sounded strange at our relaxed picnic.', 'Her formal diction sounded strange at our relaxed picnic.', '/ˈdɪkʃən/', 'Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_6_1_1', 'en-c2-6', 'ten_c2_6_1', 'listening', 'listening', 'The film ends with a trite speech about friendship.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi.","Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.","Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.","Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn."]'::jsonb, 3, 'The film ends with a trite speech about friendship. → Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_6_1_2', 'en-c2-6', 'ten_c2_6_1', 'listening', 'listening', 'He arrived wearing a modish jacket and polished boots.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà hát cổ trưng bày một bức tranh rùng rợn vẽ những bộ xương đang nhảy múa.","Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi.","Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.","Người bà ôm đứa cháu đang ngái ngủ vào lòng."]'::jsonb, 2, 'He arrived wearing a modish jacket and polished boots. → Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_6_1_3', 'en-c2-6', 'ten_c2_6_1', 'listening', 'listening', 'In the old tale, a knight slays a dragon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.","Vẻ ngoài vui tươi của cô ấy làm bừng sáng cả căn phòng ngay khi cô bước vào.","Người bà ôm đứa cháu đang ngái ngủ vào lòng.","Bộ phim kết thúc bằng một bài phát biểu sáo rỗng về tình bạn."]'::jsonb, 0, 'In the old tale, a knight slays a dragon. → Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_6_2', 'en-c2-6', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_2_1', 'ten_c2_6_2', 'trite', 'Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.', 'Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.', '/traɪt/', 'Các chiến dịch nâng cao nhận thức cộng đồng có thể thất bại nếu chúng chỉ dựa vào các khẩu hiệu sáo rỗng thay vì đưa ra lời khuyên thực tế cùng những bằng chứng thuyết phục.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_2_2', 'ten_c2_6_2', 'modish', 'Modish interiors may attract customers initially, but lasting success depends on reliable service and quality.', 'Modish interiors may attract customers initially, but lasting success depends on reliable service and quality.', '/ˈmoʊdɪʃ/', 'Nội thất hợp mốt có thể thu hút khách hàng lúc ban đầu, nhưng thành công lâu dài phụ thuộc vào dịch vụ đáng tin cậy và chất lượng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_2_3', 'ten_c2_6_2', 'slay', 'Traditional legends often celebrate heroes who slay monsters to protect their communities from danger.', 'Traditional legends often celebrate heroes who slay monsters to protect their communities from danger.', '/sleɪ/', 'Các truyền thuyết truyền thống thường ca ngợi những người anh hùng tiêu diệt quái vật để bảo vệ cộng đồng khỏi hiểm nguy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_2_4', 'ten_c2_6_2', 'dainty', 'The exhibition features dainty ornaments that demonstrate the remarkable precision achieved by traditional craft workers.', 'The exhibition features dainty ornaments that demonstrate the remarkable precision achieved by traditional craft workers.', '/ˈdeɪnti/', 'Triển lãm trưng bày những món đồ trang sức tinh xảo thể hiện độ chính xác đáng kinh ngạc của các thợ thủ công truyền thống.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_2_5', 'ten_c2_6_2', 'melodious', 'Traditional instruments produce melodious sounds that can introduce younger audiences to their cultural heritage.', 'Traditional instruments produce melodious sounds that can introduce younger audiences to their cultural heritage.', '/məˈloʊdiəs/', 'Các nhạc cụ truyền thống tạo ra những âm thanh du dương có thể giúp khán giả trẻ tiếp cận di sản văn hóa của họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_6_2_6', 'ten_c2_6_2', 'abridge', 'Publishers often abridge classic novels to make them more accessible to students with limited reading experience.', 'Publishers often abridge classic novels to make them more accessible to students with limited reading experience.', '/əˈbrɪdʒ/', 'Các nhà xuất bản thường rút gọn các tiểu thuyết kinh điển để học sinh có ít kinh nghiệm đọc sách có thể dễ dàng tiếp cận hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_6_2_1', 'en-c2-6', 'ten_c2_6_2', 'listening', 'listening', 'Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.', NULL, 'Trong câu vừa nghe, từ “trite” mang nghĩa nào sau đây?', '["được đề cập hoặc trình bày trước đó trong một văn bản","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm","đã nói ở trên; kể trên; trước đó","cái ách (gỗ để trói buộc hai con vật kéo cày)"]'::jsonb, 1, '“trite” (/traɪt/): sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm. Câu đầy đủ: Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_6_2_2', 'en-c2-6', 'ten_c2_6_2', 'listening', 'listening', 'Modish interiors may attract customers initially, but lasting success depends on reliable service and quality.', NULL, 'Trong câu vừa nghe, từ “modish” mang nghĩa nào sau đây?', '["ngành báo chí tường thuật; phóng sự","hợp mốt; sành điệu; hợp thời trang","định giá bằng một loại tiền tệ cụ thể","xơ hóa; chứng xơ cứng"]'::jsonb, 1, '“modish” (/ˈmoʊdɪʃ/): hợp mốt; sành điệu; hợp thời trang. Câu đầy đủ: Modish interiors may attract customers initially, but lasting success depends on reliable service and quality.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
