INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_1', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'trite', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoáng vật vàng giả, quặng pyrit (một loại khoáng sản màu vàng sáng chứa sắt và lưu huỳnh)","hệ thống hoặc máy truyền bản tài liệu qua đường dây điện thoại; máy fax","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm","trả thù; rửa hận; phục thù"]'::jsonb, 2, 'trite (/traɪt/) → sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_2', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'He arrived wearing a modish jacket and polished boots.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người bà ôm đứa cháu đang ngái ngủ vào lòng.","Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.","Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.","Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi."]'::jsonb, 2, 'He arrived wearing a modish jacket and polished boots. → Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_3', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'slay', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giết; tiêu diệt","vững chắc; có thể đứng vững được","người theo chủ nghĩa tự do cá nhân","chi trả; thanh toán (chi phí)"]'::jsonb, 0, 'slay (/sleɪ/) → giết; tiêu diệt', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_4', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'She served the tea in dainty porcelain cups.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vẻ ngoài vui tươi của cô ấy làm bừng sáng cả căn phòng ngay khi cô bước vào.","Nhà hát cổ trưng bày một bức tranh rùng rợn vẽ những bộ xương đang nhảy múa.","Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.","Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng."]'::jsonb, 2, 'She served the tea in dainty porcelain cups. → Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_5', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'melodious', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không thích, không muốn hoặc miễn cưỡng làm điều gì đó","giám sát; quản lý","vững chắc; có thể đứng vững được","du dương; êm tai; ngọt ngào"]'::jsonb, 3, 'melodious (/məˈloʊdiəs/) → du dương; êm tai; ngọt ngào', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_6', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'The publisher abridged the novel for younger readers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn.","Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi.","Anh ấy đến với chiếc áo khoác hợp mốt và đôi bốt được đánh bóng sáng loáng.","Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi."]'::jsonb, 3, 'The publisher abridged the novel for younger readers. → Nhà xuất bản đã rút gọn cuốn tiểu thuyết cho độc giả trẻ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
