INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_8', 'en-c2-6', NULL, 'comprehensive_test', 'listening', 'Her formal diction sounded strange at our relaxed picnic.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vẻ ngoài vui tươi của cô ấy làm bừng sáng cả căn phòng ngay khi cô bước vào.","Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi.","Trong câu chuyện cổ tích, một hiệp sĩ đã tiêu diệt con rồng.","Cô ấy rót trà vào những chiếc tách bằng sứ nhỏ nhắn xinh xắn."]'::jsonb, 1, 'Her formal diction sounded strange at our relaxed picnic. → Cách dùng từ trang trọng của cô ấy nghe có vẻ lạ lẫm trong buổi dã ngoại thoải mái của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
