INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_18', 'en-c2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Public awareness campaigns may fail when they rely on trite slogans rather than practical advice and convincing evidence.', 'Dựa vào câu trên, từ “trite” có nghĩa phù hợp nhất là gì?', '["sự tiếp tục; sự duy trì","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm","cản trở; hạn chế","kích động; khiêu khích; xúi giục"]'::jsonb, 1, 'trite: sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm. Dịch cả câu: Các chiến dịch nâng cao nhận thức cộng đồng có thể thất bại nếu chúng chỉ dựa vào các khẩu hiệu sáo rỗng thay vì đưa ra lời khuyên thực tế cùng những bằng chứng thuyết phục.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_19', 'en-c2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Modish interiors may attract customers initially, but lasting success depends on reliable service and quality.', 'Dựa vào câu trên, từ “modish” có nghĩa phù hợp nhất là gì?', '["sự đền bù; thù lao","ủy quyền; ủy nhiệm; cử","hợp mốt; sành điệu; hợp thời trang","bán thiếu cân; gian lận trọng lượng"]'::jsonb, 2, 'modish: hợp mốt; sành điệu; hợp thời trang. Dịch cả câu: Nội thất hợp mốt có thể thu hút khách hàng lúc ban đầu, nhưng thành công lâu dài phụ thuộc vào dịch vụ đáng tin cậy và chất lượng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_20', 'en-c2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Traditional legends often celebrate heroes who slay monsters to protect their communities from danger.', 'Dựa vào câu trên, từ “slay” có nghĩa phù hợp nhất là gì?', '["tham gia; góp mặt","nguyên tố ra-đi; chất ra-đi","giết; tiêu diệt","nắm chặt, ôm chặt"]'::jsonb, 2, 'slay: giết; tiêu diệt. Dịch cả câu: Các truyền thuyết truyền thống thường ca ngợi những người anh hùng tiêu diệt quái vật để bảo vệ cộng đồng khỏi hiểm nguy.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_21', 'en-c2-6', NULL, 'comprehensive_test', 'reading', NULL, 'The exhibition features dainty ornaments that demonstrate the remarkable precision achieved by traditional craft workers.', 'Dựa vào câu trên, từ “dainty” có nghĩa phù hợp nhất là gì?', '["xương chày","sẩy thai","nhỏ nhắn và tinh xảo; xinh xắn","trong tài liệu này; ở đây; trong này"]'::jsonb, 2, 'dainty: nhỏ nhắn và tinh xảo; xinh xắn; nhã nhặn; thanh lịch; nhẹ nhàng. Dịch cả câu: Triển lãm trưng bày những món đồ trang sức tinh xảo thể hiện độ chính xác đáng kinh ngạc của các thợ thủ công truyền thống.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_22', 'en-c2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngực; bầu ngực; vòng tay ôm ấp”', '["bridle","dainty","bosom","misconceive"]'::jsonb, 2, 'ngực; bầu ngực; vòng tay ôm ấp → bosom (/ˈbʊzəm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_23', 'en-c2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sức gợi cảm; nỗi niềm xót xa; tính bi cảm”', '["pathos","libertarian","repent","lexicographer"]'::jsonb, 0, 'sức gợi cảm; nỗi niềm xót xa; tính bi cảm → pathos (/ˈpeɪθɑːs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_6_24', 'en-c2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thần thái; phong thái; dáng vẻ”', '["miscarry","slithery","ingenuous","mien"]'::jsonb, 3, 'thần thái; phong thái; dáng vẻ → mien (/miːn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-7', 'en', 'Bài 7: Tư duy & Nhận thức - CEFR C2', 'CEFR C2', 'C2 · Tư duy', '24 từ vựng Tiếng Anh CEFR C2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6007, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preclude', 'en-c2-7', 'preclude', '/prɪˈkluːd/', 'C2', 'ngăn chặn; làm cho không thể xảy ra; loại trừ', 'v.', 'preclusion (n.)', 'Đồng nghĩa: prevent, rule out · Trái nghĩa: permit, allow', 'Từ ngữ mang tính trang trọng; có cấu trúc preclude sb from doing sth.', 'The heavy rain precluded our planned picnic by the lake.', NULL, 'Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.', '{"wordId":"preclude","ukIpa":"/prɪˈkluːd/","usIpa":"/prɪˈkluːd/","cefr":"C2","topic":"thinking","senses":[{"pos":"v.","en":"to prevent something or make it impossible","vi":"ngăn chặn; làm cho không thể xảy ra; loại trừ"}],"examples":[{"en":"The heavy rain precluded our planned picnic by the lake.","vi":"Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.","audioKind":"ex"},{"en":"High tuition fees may preclude students from disadvantaged backgrounds from accessing higher education without financial support.","vi":"Học phí cao có thể khiến học sinh đến từ các hoàn cảnh khó khăn không thể tiếp cận giáo dục đại học nếu không có sự hỗ trợ tài chính.","audioKind":"ex2"}],"collocations":[{"en":"preclude the possibility","vi":"loại trừ khả năng"},{"en":"preclude someone from doing something","vi":"khiến ai đó không thể làm gì"},{"en":"preclude further discussion","vi":"làm cho không thể bàn bạc thêm"}],"wordFamily":["preclusion (n.)"],"synonyms":["prevent","rule out"],"antonyms":["permit","allow"],"tipVi":"Từ ngữ mang tính trang trọng; có cấu trúc preclude sb from doing sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surmise', 'en-c2-7', 'surmise', '/sərˈmaɪz/', 'C2', 'suy đoán; phỏng đoán; sự phỏng đoán; điều phỏng đoán', 'v.', NULL, 'Đồng nghĩa: conjecture, guess', 'Từ mang tính trang trọng, nhấn mạnh việc thiếu bằng chứng; động từ thường đi với mệnh đề that.', 'Seeing wet umbrellas, I surmised that it was raining.', NULL, 'Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa.', '{"wordId":"surmise","ukIpa":"/səˈmaɪz/","usIpa":"/sərˈmaɪz/","cefr":"C2","topic":"thinking","senses":[{"pos":"v.","en":"Form an opinion using limited evidence","vi":"suy đoán; phỏng đoán"},{"pos":"n.","en":"An opinion formed without enough evidence to be certain","vi":"sự phỏng đoán; điều phỏng đoán"}],"examples":[{"en":"Seeing wet umbrellas, I surmised that it was raining.","vi":"Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa.","audioKind":"ex"},{"en":"Researchers surmise that flexible schedules improve employee wellbeing, although stronger evidence is needed to confirm this.","vi":"Các nhà nghiên cứu suy đoán rằng lịch trình linh hoạt giúp cải thiện sức khỏe tinh thần của nhân viên, mặc dù vẫn cần nhiều bằng chứng thuyết phục hơn để xác nhận điều này.","audioKind":"ex2"}],"collocations":[{"en":"surmise that","vi":"phỏng đoán rằng"},{"en":"surmise from","vi":"suy đoán từ"},{"en":"pure surmise","vi":"thuần túy là phỏng đoán"}],"wordFamily":[],"synonyms":["conjecture","guess"],"antonyms":[],"tipVi":"Từ mang tính trang trọng, nhấn mạnh việc thiếu bằng chứng; động từ thường đi với mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intimation', 'en-c2-7', 'intimation', '/ˌɪntəˈmeɪʃən/', 'C2', 'sự gợi ý; lời ám chỉ; dấu hiệu', 'n.', 'intimate (v.)', 'Đồng nghĩa: hint, indication, suggestion', 'Tránh nhầm lẫn với intimacy (sự thân mật); thường đi với giới từ of hoặc mệnh đề that.', 'His sudden silence gave us an intimation of trouble.', NULL, 'Sự im lặng đột ngột của anh ấy mang lại cho chúng tôi linh cảm rằng có rắc rối.', '{"wordId":"intimation","ukIpa":"/ˌɪntɪˈmeɪʃən/","usIpa":"/ˌɪntəˈmeɪʃən/","cefr":"C2","topic":"thinking","senses":[{"pos":"n.","en":"An indirect suggestion or indication of something.","vi":"sự gợi ý; lời ám chỉ; dấu hiệu"}],"examples":[{"en":"His sudden silence gave us an intimation of trouble.","vi":"Sự im lặng đột ngột của anh ấy mang lại cho chúng tôi linh cảm rằng có rắc rối.","audioKind":"ex"},{"en":"The minister''s remarks offered the first intimation that funding for public transport might increase.","vi":"Phát biểu của vị bộ trưởng đã hé lộ dấu hiệu đầu tiên cho thấy ngân sách dành cho giao thông công cộng có thể tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"an intimation of trouble","vi":"dấu hiệu của rắc rối"},{"en":"the first intimation","vi":"dấu hiệu đầu tiên"},{"en":"give an intimation","vi":"đưa ra ám chỉ"}],"wordFamily":["intimate (v.)"],"synonyms":["hint","indication","suggestion"],"antonyms":[],"tipVi":"Tránh nhầm lẫn với intimacy (sự thân mật); thường đi với giới từ of hoặc mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_characteristical', 'en-c2-7', 'characteristical', '/ˌkærəktəˈrɪstɪkəl/', 'C2', 'đặc trưng; tiêu biểu', 'adj.', 'characteristic (adj.), characteristically (adv.), character (n.)', 'Đồng nghĩa: characteristic, distinctive, typical · Trái nghĩa: uncharacteristic', 'Đây là hình thức cũ và ít gặp; văn viết hiện đại nên ưu tiên dùng characteristic.', 'The old guide describes the village''s characteristical stone cottages.', NULL, 'Cuốn hướng dẫn cũ miêu tả những ngôi nhà đá đặc trưng của ngôi làng.', '{"wordId":"characteristical","ukIpa":"/ˌkærəktəˈrɪstɪkəl/","usIpa":"/ˌkærəktəˈrɪstɪkəl/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Showing the distinctive qualities of a person or thing.","vi":"đặc trưng; tiêu biểu"}],"examples":[{"en":"The old guide describes the village''s characteristical stone cottages.","vi":"Cuốn hướng dẫn cũ miêu tả những ngôi nhà đá đặc trưng của ngôi làng.","audioKind":"ex"},{"en":"The historical account highlights the characteristical features of rural architecture, including local stone and steep roofs.","vi":"Bản ghi chép lịch sử làm nổi bật các đặc trưng của kiến trúc nông thôn, bao gồm đá địa phương và mái nhà dốc.","audioKind":"ex2"}],"collocations":[{"en":"characteristical features","vi":"các đặc điểm tiêu biểu"},{"en":"characteristical qualities","vi":"những phẩm chất đặc trưng"}],"wordFamily":["characteristic (adj.)","characteristically (adv.)","character (n.)"],"synonyms":["characteristic","distinctive","typical"],"antonyms":["uncharacteristic"],"tipVi":"Đây là hình thức cũ và ít gặp; văn viết hiện đại nên ưu tiên dùng characteristic.","noteVi":"Đây là tính từ dạng cổ hiếm gặp, trong tiếng Anh hiện đại thường dùng characteristic.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_panacea', 'en-c2-7', 'panacea', '/ˌpænəˈsiːə/', 'C2', 'thuốc tiên; giải pháp vạn năng', 'n.', NULL, 'Đồng nghĩa: cure-all', 'Thường đi với a panacea for; hay dùng ở dạng phủ định để chỉ giải pháp không toàn diện.', 'A new phone is no panacea for your troubles.', NULL, 'Một chiếc điện thoại mới không phải là liều thuốc tiên giải quyết mọi rắc rối của bạn.', '{"wordId":"panacea","ukIpa":"/ˌpænəˈsiːə/","usIpa":"/ˌpænəˈsiːə/","cefr":"C2","topic":"thinking","senses":[{"pos":"n.","en":"Something believed to solve every problem or cure every illness.","vi":"thuốc tiên; giải pháp vạn năng"}],"examples":[{"en":"A new phone is no panacea for your troubles.","vi":"Một chiếc điện thoại mới không phải là liều thuốc tiên giải quyết mọi rắc rối của bạn.","audioKind":"ex"},{"en":"Although technology can improve classroom learning, it should not be regarded as a panacea for educational inequality.","vi":"Mặc dù công nghệ có thể cải thiện việc học tập trên lớp, nó không nên được xem là giải pháp vạn năng cho sự bất bình đẳng trong giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"a panacea for","vi":"giải pháp vạn năng cho"},{"en":"no panacea","vi":"không phải là giải pháp vạn năng"},{"en":"a universal panacea","vi":"liều thuốc chữa bách bệnh"}],"wordFamily":[],"synonyms":["cure-all"],"antonyms":[],"tipVi":"Thường đi với a panacea for; hay dùng ở dạng phủ định để chỉ giải pháp không toàn diện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plumb', 'en-c2-7', 'plumb', '/plʌm/', 'C2', 'thấu hiểu; thăm dò sâu; khảo sát kỹ; đo độ sâu của nước; quả rọi; quả chì', 'v.', 'plumbing (n.), plumber (n.)', 'Đồng nghĩa: probe, investigate', 'Chữ b cuối từ là âm câm; cụm từ plumb the depths thường mang nghĩa bóng là dò xét tận cùng hoặc rơi xuống mức thấp nhất.', 'The documentary plumbs the mysteries of the deep ocean.', NULL, 'Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm.', '{"wordId":"plumb","ukIpa":"/plʌm/","usIpa":"/plʌm/","cefr":"C2","topic":"thinking","senses":[{"pos":"v.","en":"examine something closely to understand it fully","vi":"thấu hiểu; thăm dò sâu; khảo sát kỹ"},{"pos":"v.","en":"measure how deep water is","vi":"đo độ sâu của nước"},{"pos":"n.","en":"a weight on a string used to check vertical alignment","vi":"quả rọi; quả chì"}],"examples":[{"en":"The documentary plumbs the mysteries of the deep ocean.","vi":"Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm.","audioKind":"ex"},{"en":"Through detailed interviews, researchers sought to plumb the causes of declining public trust in local institutions.","vi":"Thông qua các cuộc phỏng vấn chi tiết, các nhà nghiên cứu đã cố gắng tìm hiểu sâu xa nguyên nhân dẫn đến việc công chúng ngày càng giảm niềm tin vào các cơ quan địa phương.","audioKind":"ex2"}],"collocations":[{"en":"plumb the depths of","vi":"thâm nhập tận đáy; tìm hiểu sâu sắc"},{"en":"plumb line","vi":"đường dọi"},{"en":"plumb bob","vi":"quả rọi"}],"wordFamily":["plumbing (n.)","plumber (n.)"],"synonyms":["probe","investigate"],"antonyms":[],"tipVi":"Chữ b cuối từ là âm câm; cụm từ plumb the depths thường mang nghĩa bóng là dò xét tận cùng hoặc rơi xuống mức thấp nhất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manifold', 'en-c2-7', 'manifold', '/ˈmænɪfoʊld/', 'C2', 'nhiều và phong phú; đa dạng; nhiều mặt; ống góp; hệ thống ống chia', 'adj.', NULL, 'Đồng nghĩa: various, numerous', 'Dạng tính từ mang tính trang trọng, thường bổ nghĩa cho các danh từ số nhiều như benefits hoặc problems.', 'The benefits of growing your own vegetables are manifold.', NULL, 'Lợi ích của việc tự trồng rau củ tại nhà là vô cùng đa dạng.', '{"wordId":"manifold","ukIpa":"/ˈmænɪfəʊld/","usIpa":"/ˈmænɪfoʊld/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Numerous and varied","vi":"nhiều và phong phú; đa dạng; nhiều mặt"},{"pos":"n.","en":"A pipe system distributing or collecting gas or liquid","vi":"ống góp; hệ thống ống chia"}],"examples":[{"en":"The benefits of growing your own vegetables are manifold.","vi":"Lợi ích của việc tự trồng rau củ tại nhà là vô cùng đa dạng.","audioKind":"ex"},{"en":"The manifold challenges of urban growth require cooperation between local authorities, businesses, and residents.","vi":"Những thách thức đa dạng của sự phát triển đô thị đòi hỏi sự hợp tác giữa chính quyền địa phương, doanh nghiệp và cư dân.","audioKind":"ex2"}],"collocations":[{"en":"manifold benefits","vi":"nhiều lợi ích thiết thực"},{"en":"manifold challenges","vi":"nhiều thách thức đa dạng"},{"en":"exhaust manifold","vi":"ống góp khí thải"}],"wordFamily":[],"synonyms":["various","numerous"],"antonyms":[],"tipVi":"Dạng tính từ mang tính trang trọng, thường bổ nghĩa cho các danh từ số nhiều như benefits hoặc problems.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misconceive', 'en-c2-7', 'misconceive', '/ˌmɪskənˈsiːv/', 'C2', 'hiểu lầm; nhận thức sai', 'v.', 'misconception (n.), misconceived (adj.)', 'Đồng nghĩa: misunderstand, misinterpret · Trái nghĩa: understand', 'Từ mang tính trang trọng hơn; trong giao tiếp hàng ngày, từ "misunderstand" được dùng phổ biến hơn.', 'I misconceived her silence as a sign of agreement.', NULL, 'Tôi đã hiểu lầm sự im lặng của cô ấy là dấu hiệu đồng ý.', '{"wordId":"misconceive","ukIpa":"/ˌmɪskənˈsiːv/","usIpa":"/ˌmɪskənˈsiːv/","cefr":"C2","topic":"thinking","senses":[{"pos":"v.","en":"to understand something in the wrong way","vi":"hiểu lầm; nhận thức sai"}],"examples":[{"en":"I misconceived her silence as a sign of agreement.","vi":"Tôi đã hiểu lầm sự im lặng của cô ấy là dấu hiệu đồng ý.","audioKind":"ex"},{"en":"Policymakers may misconceive local needs if they fail to consult residents before introducing changes.","vi":"Các nhà hoạch định chính sách có thể hiểu lầm nhu cầu địa phương nếu họ không tham khảo ý kiến người dân trước khi đưa ra các thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"misconceive someone''s intentions","vi":"hiểu lầm ý định của ai đó"},{"en":"misconceive the purpose","vi":"hiểu sai mục đích"}],"wordFamily":["misconception (n.)","misconceived (adj.)"],"synonyms":["misunderstand","misinterpret"],"antonyms":["understand"],"tipVi":"Từ mang tính trang trọng hơn; trong giao tiếp hàng ngày, từ \"misunderstand\" được dùng phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortuity', 'en-c2-7', 'fortuity', '/fɔːrˈtuːəti/', 'C2', 'sự tình cờ; cơ may', 'n.', 'fortuitous (adj.), fortuitously (adv.)', 'Đồng nghĩa: chance, coincidence', 'Là từ trang trọng ít gặp; trong văn nói thường dùng chance hoặc coincidence.', 'By sheer fortuity, we booked seats beside each other.', NULL, 'Thật là một sự tình cờ hoàn toàn khi chúng tôi đặt chỗ ngồi cạnh nhau.', '{"wordId":"fortuity","ukIpa":"/fɔːˈtjuːəti/","usIpa":"/fɔːrˈtuːəti/","cefr":"C2","topic":"thinking","senses":[{"pos":"n.","en":"An event happening by chance, or chance itself.","vi":"sự tình cờ; cơ may"}],"examples":[{"en":"By sheer fortuity, we booked seats beside each other.","vi":"Thật là một sự tình cờ hoàn toàn khi chúng tôi đặt chỗ ngồi cạnh nhau.","audioKind":"ex"},{"en":"Scientific breakthroughs sometimes involve fortuity, although careful observation remains essential for recognising the value of unexpected results.","vi":"Các bước đột phá khoa học đôi khi có sự góp mặt của yếu tố tình cờ, mặc dù việc quan sát kỹ lưỡng vẫn đóng vai trò cốt lõi để nhận ra giá trị của những kết quả bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"by sheer fortuity","vi":"hoàn toàn tình cờ"},{"en":"an element of fortuity","vi":"yếu tố may rủi"}],"wordFamily":["fortuitous (adj.)","fortuitously (adv.)"],"synonyms":["chance","coincidence"],"antonyms":[],"tipVi":"Là từ trang trọng ít gặp; trong văn nói thường dùng chance hoặc coincidence.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tenacious', 'en-c2-7', 'tenacious', '/təˈneɪʃəs/', 'C2', 'kiên định, kiên cường, không bỏ cuộc dù gặp khó khăn; bám chặt, dai dẳng, khó gỡ bỏ hoặc khó thay đổi', 'adj.', 'tenacity (n.), tenaciously (adv.)', 'Đồng nghĩa: persistent, determined', 'Cốt lõi là kiên trì không bỏ cuộc; cũng có thể diễn tả việc bám rất chắc hoặc khó loại bỏ.', 'The tenacious runner kept going despite the steep hill.', NULL, 'Vận động viên chạy bền kiên cường ấy vẫn tiếp tục tiến bước mặc cho con dốc cao.', '{"wordId":"tenacious","ukIpa":"/təˈneɪʃəs/","usIpa":"/təˈneɪʃəs/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"determined to continue despite difficulties","vi":"kiên định, kiên cường, không bỏ cuộc dù gặp khó khăn"},{"pos":"adj.","en":"holding firmly or remaining difficult to remove or change","vi":"bám chặt, dai dẳng, khó gỡ bỏ hoặc khó thay đổi"}],"examples":[{"en":"The tenacious runner kept going despite the steep hill.","vi":"Vận động viên chạy bền kiên cường ấy vẫn tiếp tục tiến bước mặc cho con dốc cao.","audioKind":"ex"},{"en":"Tenacious researchers often overcome repeated setbacks before producing discoveries that significantly improve public health.","vi":"Những nhà nghiên cứu kiên định thường phải vượt qua nhiều thất bại lặp đi lặp lại trước khi đạt được những phát hiện cải thiện đáng kể sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a tenacious campaigner","vi":"một nhà vận động kiên trì"},{"en":"a tenacious grip","vi":"cái nắm tay chặt"},{"en":"tenacious resistance","vi":"sự kháng cự bền bỉ"}],"wordFamily":["tenacity (n.)","tenaciously (adv.)"],"synonyms":["persistent","determined"],"antonyms":[],"tipVi":"Cốt lõi là kiên trì không bỏ cuộc; cũng có thể diễn tả việc bám rất chắc hoặc khó loại bỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tenable', 'en-c2-7', 'tenable', '/ˈtenəbl/', 'C2', 'vững chắc; có thể đứng vững được', 'adj.', 'untenable (adj.), tenability (n.)', 'Đồng nghĩa: defensible, sustainable · Trái nghĩa: untenable, indefensible', 'Thường dùng để mô tả lập luận hoặc quan điểm có cơ sở vững chắc, không dùng để chỉ sự thoải mái.', 'His excuse was no longer tenable after we checked.', NULL, 'Lời bào chữa của anh ấy không còn đứng vững được sau khi chúng tôi kiểm tra lại.', '{"wordId":"tenable","ukIpa":"/ˈtenəbl/","usIpa":"/ˈtenəbl/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Able to be defended or maintained against criticism.","vi":"vững chắc; có thể đứng vững được"}],"examples":[{"en":"His excuse was no longer tenable after we checked.","vi":"Lời bào chữa của anh ấy không còn đứng vững được sau khi chúng tôi kiểm tra lại.","audioKind":"ex"},{"en":"The assumption that economic growth always improves public wellbeing is no longer tenable in every context.","vi":"Giả định cho rằng tăng trưởng kinh tế luôn cải thiện phúc lợi công cộng không còn phù hợp trong mọi hoàn cảnh.","audioKind":"ex2"}],"collocations":[{"en":"a tenable position","vi":"lập trường vững chắc"},{"en":"a tenable argument","vi":"lập luận xác đáng"},{"en":"no longer tenable","vi":"không còn đứng vững được"}],"wordFamily":["untenable (adj.)","tenability (n.)"],"synonyms":["defensible","sustainable"],"antonyms":["untenable","indefensible"],"tipVi":"Thường dùng để mô tả lập luận hoặc quan điểm có cơ sở vững chắc, không dùng để chỉ sự thoải mái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conceptive', 'en-c2-7', 'conceptive', '/kənˈseptɪv/', 'C2', 'có khả năng nhận thức, có năng lực tư duy, có khả năng hình thành ý tưởng', 'adj.', 'conceive (v.), conception (n.), concept (n.), conceptual (adj.)', NULL, 'Từ ít dùng; tránh nhầm lẫn với từ conceptual có nghĩa là "mang tính khái niệm".', 'The philosopher described imagination as a conceptive faculty.', NULL, 'Triết gia miêu tả trí tưởng tượng như một năng lực tư duy hình thành khái niệm.', '{"wordId":"conceptive","ukIpa":"/kənˈseptɪv/","usIpa":"/kənˈseptɪv/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Capable of forming ideas or mental images.","vi":"có khả năng nhận thức, có năng lực tư duy, có khả năng hình thành ý tưởng"}],"examples":[{"en":"The philosopher described imagination as a conceptive faculty.","vi":"Triết gia miêu tả trí tưởng tượng như một năng lực tư duy hình thành khái niệm.","audioKind":"ex"},{"en":"In older philosophical writing, the conceptive faculty enables people to form ideas beyond their immediate sensory experience.","vi":"Trong các trước tác triết học cổ xưa, năng lực nhận thức giúp con người hình thành các ý niệm vượt ra khỏi trải nghiệm cảm giác trực tiếp của họ.","audioKind":"ex2"}],"collocations":[{"en":"conceptive faculty","vi":"năng lực tư duy khái niệm"},{"en":"conceptive power","vi":"sức mạnh tư duy"}],"wordFamily":["conceive (v.)","conception (n.)","concept (n.)","conceptual (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ ít dùng; tránh nhầm lẫn với từ conceptual có nghĩa là \"mang tính khái niệm\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eminently', 'en-c2-7', 'eminently', '/ˈemɪnəntli/', 'C2', 'hết sức; vô cùng; cực kỳ', 'adv.', 'eminent (adj.), eminence (n.)', 'Đồng nghĩa: highly, extremely', 'Thường bổ nghĩa cho các tính từ mang nghĩa tích cực; tránh nhầm lẫn với imminently (sắp xảy ra).', 'Your spare room looks eminently suitable for a study.', NULL, 'Phòng trống nhà bạn trông vô cùng thích hợp để làm phòng làm việc.', '{"wordId":"eminently","ukIpa":"/ˈemɪnəntli/","usIpa":"/ˈemɪnəntli/","cefr":"C2","topic":"thinking","senses":[{"pos":"adv.","en":"To a very great degree, especially in a positive way.","vi":"hết sức; vô cùng; cực kỳ"}],"examples":[{"en":"Your spare room looks eminently suitable for a study.","vi":"Phòng trống nhà bạn trông vô cùng thích hợp để làm phòng làm việc.","audioKind":"ex"},{"en":"Improving insulation is an eminently sensible way to reduce household energy consumption and heating costs.","vi":"Cải thiện khả năng cách nhiệt là một cách hết sức khôn ngoan để giảm mức tiêu thụ năng lượng và chi phí sưởi ấm trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"eminently suitable","vi":"hết sức thích hợp"},{"en":"eminently sensible","vi":"vô cùng hợp lý"},{"en":"eminently reasonable","vi":"hết sức phải chăng"},{"en":"eminently qualified","vi":"hoàn toàn đủ năng lực"}],"wordFamily":["eminent (adj.)","eminence (n.)"],"synonyms":["highly","extremely"],"antonyms":[],"tipVi":"Thường bổ nghĩa cho các tính từ mang nghĩa tích cực; tránh nhầm lẫn với imminently (sắp xảy ra).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ostensible', 'en-c2-7', 'ostensible', '/ɑːˈstensəbl/', 'C2', 'trên danh nghĩa; bề ngoài; tự xưng', 'adj.', 'ostensibly (adv.)', 'Đồng nghĩa: apparent, professed', 'Hàm ý rằng vẻ bề ngoài có thể không phải là sự thật, nhưng không đồng nghĩa là đã được chứng minh là sai sự thật.', 'His ostensible reason for visiting was to return my umbrella.', NULL, 'Lý do bề ngoài của anh ấy khi đến thăm là để trả chiếc ô của tôi.', '{"wordId":"ostensible","ukIpa":"/ɒˈstensəbl/","usIpa":"/ɑːˈstensəbl/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Stated or appearing to be true, but possibly not genuine","vi":"trên danh nghĩa; bề ngoài; tự xưng"}],"examples":[{"en":"His ostensible reason for visiting was to return my umbrella.","vi":"Lý do bề ngoài của anh ấy khi đến thăm là để trả chiếc ô của tôi.","audioKind":"ex"},{"en":"The ostensible purpose of the policy was environmental protection, although it also benefited domestic manufacturers.","vi":"Mục đích trên danh nghĩa của chính sách này là bảo vệ môi trường, mặc dù nó cũng mang lại lợi ích cho các nhà sản xuất trong nước.","audioKind":"ex2"}],"collocations":[{"en":"ostensible reason","vi":"lý do bề ngoài"},{"en":"ostensible purpose","vi":"mục đích trên danh nghĩa"},{"en":"ostensible aim","vi":"mục tiêu bề ngoài"}],"wordFamily":["ostensibly (adv.)"],"synonyms":["apparent","professed"],"antonyms":[],"tipVi":"Hàm ý rằng vẻ bề ngoài có thể không phải là sự thật, nhưng không đồng nghĩa là đã được chứng minh là sai sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reflexion', 'en-c2-7', 'reflexion', '/rɪˈflekʃən/', 'C2', 'hình ảnh phản chiếu; sự phản chiếu; sự ngẫm nghĩ; sự suy ngẫm', 'n.', 'reflect (v.), reflective (adj.)', 'Đồng nghĩa: reflection', 'reflexion là ít dùng biến thể; thi cử viết lách nên dùng reflection.', 'She caught her reflexion in the still pond.', NULL, 'Cô ấy nhìn thấy hình ảnh phản chiếu của mình trong ao nước phẳng lặng.', '{"wordId":"reflexion","ukIpa":"/rɪˈflekʃən/","usIpa":"/rɪˈflekʃən/","cefr":"C2","topic":"thinking","senses":[{"pos":"n.","en":"an image in a shiny surface, or light bouncing back","vi":"hình ảnh phản chiếu; sự phản chiếu"},{"pos":"n.","en":"careful thought about an experience or idea","vi":"sự ngẫm nghĩ; sự suy ngẫm"}],"examples":[{"en":"She caught her reflexion in the still pond.","vi":"Cô ấy nhìn thấy hình ảnh phản chiếu của mình trong ao nước phẳng lặng.","audioKind":"ex"},{"en":"Regular reflexion on classroom experiences can help teachers identify more effective ways to support individual learners.","vi":"Việc thường xuyên suy ngẫm về các trải nghiệm trên lớp có thể giúp giáo viên tìm ra những phương pháp hiệu quả hơn để hỗ trợ từng học viên.","audioKind":"ex2"}],"collocations":[{"en":"reflexion of light","vi":"sự phản chiếu ánh sáng"},{"en":"on reflexion","vi":"sau khi suy nghĩ kỹ"},{"en":"careful reflexion","vi":"sự suy ngẫm cẩn thận"}],"wordFamily":["reflect (v.)","reflective (adj.)"],"synonyms":["reflection"],"antonyms":[],"tipVi":"reflexion là ít dùng biến thể; thi cử viết lách nên dùng reflection.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delusive', 'en-c2-7', 'delusive', '/dɪˈluːsɪv/', 'C2', 'ảo tưởng; đánh lừa; làm sai lệch thực tế', 'adj.', 'delude (v.), delusion (n.), delusory (adj.)', 'Đồng nghĩa: misleading, deceptive, illusory', 'Khá trang trọng và ít dùng; trong đời thường thường dùng misleading hoặc deceptive.', 'The mirror created a delusive impression of extra space.', NULL, 'Tấm gương tạo ra ấn tượng sai lệch về một không gian rộng rãi hơn.', '{"wordId":"delusive","ukIpa":"/dɪˈluːsɪv/","usIpa":"/dɪˈluːsɪv/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Making something false seem true or something unreal seem real.","vi":"ảo tưởng; đánh lừa; làm sai lệch thực tế"}],"examples":[{"en":"The mirror created a delusive impression of extra space.","vi":"Tấm gương tạo ra ấn tượng sai lệch về một không gian rộng rãi hơn.","audioKind":"ex"},{"en":"Early economic gains may create a delusive sense of security if governments ignore underlying weaknesses in public finances.","vi":"Những thành tựu kinh tế ban đầu có thể tạo ra cảm giác an toàn ảo nếu chính phủ bỏ qua những yếu điểm tiềm ẩn trong tài chính công.","audioKind":"ex2"}],"collocations":[{"en":"delusive hopes","vi":"hy vọng viển vông"},{"en":"delusive appearance","vi":"vẻ bề ngoài đánh lừa"},{"en":"delusive sense of security","vi":"cảm giác an toàn ảo"}],"wordFamily":["delude (v.)","delusion (n.)","delusory (adj.)"],"synonyms":["misleading","deceptive","illusory"],"antonyms":[],"tipVi":"Khá trang trọng và ít dùng; trong đời thường thường dùng misleading hoặc deceptive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illusive', 'en-c2-7', 'illusive', '/ɪˈluːsɪv/', 'C2', 'mang tính ảo ảnh; hão huyền', 'adj.', 'illusion (n.), illusory (adj.)', 'Đồng nghĩa: illusory, deceptive · Trái nghĩa: real', 'Ít dùng, thường dùng illusory; elusive có nghĩa là khó nắm bắt.', 'The desert shimmered with illusive pools of water.', NULL, 'Sa mạc lấp lánh với những vũng nước ảo ảnh.', '{"wordId":"illusive","ukIpa":"/ɪˈluːsɪv/","usIpa":"/ɪˈluːsɪv/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"appearing real but based on illusion","vi":"mang tính ảo ảnh; hão huyền"}],"examples":[{"en":"The desert shimmered with illusive pools of water.","vi":"Sa mạc lấp lánh với những vũng nước ảo ảnh.","audioKind":"ex"},{"en":"Advertising may create an illusive sense of happiness by linking personal fulfilment exclusively to material possessions.","vi":"Quảng cáo có thể tạo ra cảm giác hạnh phúc hão huyền bằng cách gắn kết sự thỏa mãn cá nhân hoàn toàn với tài sản vật chất.","audioKind":"ex2"}],"collocations":[{"en":"illusive appearance","vi":"vẻ ngoài hão huyền"},{"en":"illusive happiness","vi":"hạnh phúc hão huyền"}],"wordFamily":["illusion (n.)","illusory (adj.)"],"synonyms":["illusory","deceptive"],"antonyms":["real"],"tipVi":"Ít dùng, thường dùng illusory; elusive có nghĩa là khó nắm bắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lest', 'en-c2-7', 'lest', '/lest/', 'C2', 'để phòng khi; e rằng; vì sợ rằng', 'conj.', NULL, NULL, 'Mang tính trang trọng; mệnh đề theo sau thường dùng động từ nguyên mẫu hoặc should đi với động từ nguyên mẫu.', 'She whispered lest she wake the sleeping baby.', NULL, 'Cô ấy nói thì thầm để tránh làm thức giấc đứa trẻ đang ngủ.', '{"wordId":"lest","ukIpa":"/lest/","usIpa":"/lest/","cefr":"C2","topic":"thinking","senses":[{"pos":"conj.","en":"To prevent something unwanted, or because of fearing it","vi":"để phòng khi; e rằng; vì sợ rằng"}],"examples":[{"en":"She whispered lest she wake the sleeping baby.","vi":"Cô ấy nói thì thầm để tránh làm thức giấc đứa trẻ đang ngủ.","audioKind":"ex"},{"en":"Policymakers should assess new technologies carefully lest short-term economic gains create lasting environmental problems.","vi":"Các nhà hoạch định chính sách nên đánh giá cẩn thận các công nghệ mới e rằng những lợi ích kinh tế ngắn hạn sẽ gây ra các vấn đề môi trường lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"lest we forget","vi":"kẻo chúng ta quên"},{"en":"lest someone should","vi":"vì sợ rằng ai đó sẽ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mang tính trang trọng; mệnh đề theo sau thường dùng động từ nguyên mẫu hoặc should đi với động từ nguyên mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inexorable', 'en-c2-7', 'inexorable', '/ɪnˈeksərəbl/', 'C2', 'không thể ngăn cản; không thể kìm hãm', 'adj.', 'inexorably (adv.), inexorability (n.)', 'Đồng nghĩa: unstoppable, relentless', 'Nhấn mạnh xu hướng hoặc tiến trình không thể ngăn cản, không chỉ mang nghĩa là "vô tình".', 'We watched the inexorable tide creep towards our sandcastle.', NULL, 'Chúng tôi đứng nhìn con thủy triều không thể ngăn cản đang tiến dần về phía lâu đài cát của mình.', '{"wordId":"inexorable","ukIpa":"/ɪnˈeksərəbl/","usIpa":"/ɪnˈeksərəbl/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"impossible to stop or prevent","vi":"không thể ngăn cản; không thể kìm hãm"}],"examples":[{"en":"We watched the inexorable tide creep towards our sandcastle.","vi":"Chúng tôi đứng nhìn con thủy triều không thể ngăn cản đang tiến dần về phía lâu đài cát của mình.","audioKind":"ex"},{"en":"The inexorable rise in demand for electricity highlights the need for investment in renewable energy.","vi":"Sự gia tăng không thể đảo ngược của nhu cầu điện năng nhấn mạnh sự cần thiết phải đầu tư vào năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"inexorable rise","vi":"sự gia tăng không ngừng"},{"en":"inexorable decline","vi":"sự suy thoái không thể tránh khỏi"},{"en":"inexorable march of time","vi":"dòng thời gian trôi đi không ngừng nghỉ"}],"wordFamily":["inexorably (adv.)","inexorability (n.)"],"synonyms":["unstoppable","relentless"],"antonyms":[],"tipVi":"Nhấn mạnh xu hướng hoặc tiến trình không thể ngăn cản, không chỉ mang nghĩa là \"vô tình\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perverse', 'en-c2-7', 'perverse', '/pɚˈvɝːs/', 'C2', 'ngoan cố chống đối; cố chấp; bất thường; trái khoáy; phản tác dụng; mang lại kết quả ngược lại', 'adj.', 'perversely (adv.), perversity (n.)', 'Đồng nghĩa: contrary, unreasonable · Trái nghĩa: reasonable', 'Không dùng chung chung cho việc trái pháp luật; thường chỉ thái độ cố tình chống đối hoặc mang lại kết quả phản tác dụng.', 'He took perverse pleasure in disagreeing with every suggestion.', NULL, 'Anh ta lấy làm vui thích một cách lệch lạc khi phản đối mọi đề xuất được đưa ra.', '{"wordId":"perverse","ukIpa":"/pəˈvɜːs/","usIpa":"/pɚˈvɝːs/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Deliberately contrary to what is reasonable, expected, or wanted.","vi":"ngoan cố chống đối; cố chấp; bất thường"},{"pos":"adj.","en":"Producing effects opposite to those intended or considered desirable.","vi":"trái khoáy; phản tác dụng; mang lại kết quả ngược lại"}],"examples":[{"en":"He took perverse pleasure in disagreeing with every suggestion.","vi":"Anh ta lấy làm vui thích một cách lệch lạc khi phản đối mọi đề xuất được đưa ra.","audioKind":"ex"},{"en":"Poorly designed subsidies can create perverse incentives, encouraging companies to increase pollution rather than invest in cleaner production.","vi":"Các khoản trợ cấp được thiết kế kém có thể tạo ra các động cơ sai lệch, khuyến khích các công ty gia tăng ô nhiễm thay vì đầu tư vào sản xuất sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"perverse pleasure","vi":"niềm vui quái đản"},{"en":"perverse incentives","vi":"động cơ trái khoáy; động cơ ngược đời"},{"en":"perverse effect","vi":"hiệu ứng ngược; tác dụng phản tác dụng"}],"wordFamily":["perversely (adv.)","perversity (n.)"],"synonyms":["contrary","unreasonable"],"antonyms":["reasonable"],"tipVi":"Không dùng chung chung cho việc trái pháp luật; thường chỉ thái độ cố tình chống đối hoặc mang lại kết quả phản tác dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pertinence', 'en-c2-7', 'pertinence', '/ˈpɜːrtnəns/', 'C2', 'tính thích hợp; sự liên quan trực tiếp', 'n.', 'pertinent (adj.), pertinently (adv.)', 'Đồng nghĩa: relevance · Trái nghĩa: irrelevance', 'Từ này mang tính trang trọng và ít phổ biến hơn; thông thường dùng relevance sẽ tự nhiên hơn.', 'The teacher questioned the pertinence of my final paragraph.', NULL, 'Giáo viên đã đặt vấn đề về sự liên quan của đoạn văn cuối trong bài của tôi.', '{"wordId":"pertinence","ukIpa":"/ˈpɜːtɪnəns/","usIpa":"/ˈpɜːrtnəns/","cefr":"C2","topic":"thinking","senses":[{"pos":"n.","en":"the quality of being directly relevant to a particular matter","vi":"tính thích hợp; sự liên quan trực tiếp"}],"examples":[{"en":"The teacher questioned the pertinence of my final paragraph.","vi":"Giáo viên đã đặt vấn đề về sự liên quan của đoạn văn cuối trong bài của tôi.","audioKind":"ex"},{"en":"The pertinence of historical evidence to current policy debates depends partly on how closely the social conditions resemble ours.","vi":"Sự gắn kết của các bằng chứng lịch sử đối với các cuộc tranh luận chính sách hiện tại phần nào phụ thuộc vào mức độ tương đồng của điều kiện xã hội thời đó với hiện tại.","audioKind":"ex2"}],"collocations":[{"en":"pertinence to the topic","vi":"sự liên quan đến chủ đề"},{"en":"question the pertinence of","vi":"đặt câu hỏi về tính liên quan của"}],"wordFamily":["pertinent (adj.)","pertinently (adv.)"],"synonyms":["relevance"],"antonyms":["irrelevance"],"tipVi":"Từ này mang tính trang trọng và ít phổ biến hơn; thông thường dùng relevance sẽ tự nhiên hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inapt', 'en-c2-7', 'inapt', '/ɪnˈæpt/', 'C2', 'không thích hợp; không thỏa đáng; không khéo', 'adj.', 'inaptly (adv.), inaptness (n.), apt (adj.)', 'Đồng nghĩa: inappropriate, unsuitable, inapposite · Trái nghĩa: apt, appropriate', 'Từ này mang sắc thái trang trọng và ít gặp; tránh nhầm lẫn với inept vốn chỉ sự kém cỏi, vụng về.', 'His inapt joke made everyone at dinner feel uncomfortable.', NULL, 'Câu đùa kém duyên của anh ấy khiến mọi người trong bữa tối cảm thấy khó chịu.', '{"wordId":"inapt","ukIpa":"/ɪnˈæpt/","usIpa":"/ɪnˈæpt/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Not suitable or appropriate for a particular situation.","vi":"không thích hợp; không thỏa đáng; không khéo"}],"examples":[{"en":"His inapt joke made everyone at dinner feel uncomfortable.","vi":"Câu đùa kém duyên của anh ấy khiến mọi người trong bữa tối cảm thấy khó chịu.","audioKind":"ex"},{"en":"Comparing schools solely by examination results is inapt when their students have very different social backgrounds.","vi":"Việc so sánh các trường học chỉ dựa trên kết quả thi là không thỏa đáng khi học sinh của các trường có nền tảng xã hội rất khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"an inapt comparison","vi":"một sự so sánh khập khiễng"},{"en":"an inapt remark","vi":"một nhận xét không phù hợp"},{"en":"an inapt description","vi":"một sự miêu tả không chuẩn xác"}],"wordFamily":["inaptly (adv.)","inaptness (n.)","apt (adj.)"],"synonyms":["inappropriate","unsuitable","inapposite"],"antonyms":["apt","appropriate"],"tipVi":"Từ này mang sắc thái trang trọng và ít gặp; tránh nhầm lẫn với inept vốn chỉ sự kém cỏi, vụng về.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_actuality', 'en-c2-7', 'actuality', '/ˌæktʃuˈæləti/', 'C2', 'thực tế; thực trạng', 'n.', 'actual (adj.), actually (adv.), actualise (v.), actualisation (n.)', 'Đồng nghĩa: reality · Trái nghĩa: fantasy', 'Cụm từ in actuality mang tính trang trọng hơn; trong giao tiếp hàng ngày thường dùng actually.', 'The flat looked spacious, but in actuality it was tiny.', NULL, 'Căn hộ trông có vẻ rộng rãi, nhưng trên thực tế nó lại rất nhỏ.', '{"wordId":"actuality","ukIpa":"/ˌæktʃuˈæləti/","usIpa":"/ˌæktʃuˈæləti/","cefr":"C2","topic":"thinking","senses":[{"pos":"n.","en":"What really exists or happens, rather than what is imagined.","vi":"thực tế; thực trạng"}],"examples":[{"en":"The flat looked spacious, but in actuality it was tiny.","vi":"Căn hộ trông có vẻ rộng rãi, nhưng trên thực tế nó lại rất nhỏ.","audioKind":"ex"},{"en":"Although online services appear universally accessible, in actuality many rural communities still lack reliable internet connections.","vi":"Mặc dù các dịch vụ trực tuyến có vẻ ai cũng tiếp cận được, nhưng trên thực tế, nhiều cộng đồng nông thôn vẫn thiếu kết nối internet ổn định.","audioKind":"ex2"}],"collocations":[{"en":"in actuality","vi":"trên thực tế"},{"en":"turn into actuality","vi":"biến thành hiện thực"}],"wordFamily":["actual (adj.)","actually (adv.)","actualise (v.)","actualisation (n.)"],"synonyms":["reality"],"antonyms":["fantasy"],"tipVi":"Cụm từ in actuality mang tính trang trọng hơn; trong giao tiếp hàng ngày thường dùng actually.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fatuous', 'en-c2-7', 'fatuous', '/ˈfætʃ.u.əs/', 'C2', 'ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý', 'adj.', 'fatuously (adv.), fatuousness (n.)', 'Đồng nghĩa: foolish, inane, silly · Trái nghĩa: sensible', 'Là từ mang tính trang trọng và có sắc thái chê bai, thường dùng để phê phán những lời nói hoặc ý tưởng ngớ ngẩn nhưng tỏ ra đắc ý.', 'His fatuous suggestion was to water plants with lemonade.', NULL, 'Lời đề nghị ngớ ngẩn của anh ấy là tưới cây bằng nước chanh ngọt.', '{"wordId":"fatuous","ukIpa":"/ˈfætʃ.u.əs/","usIpa":"/ˈfætʃ.u.əs/","cefr":"C2","topic":"thinking","senses":[{"pos":"adj.","en":"Foolish and unreasonable, often with misplaced confidence","vi":"ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý"}],"examples":[{"en":"His fatuous suggestion was to water plants with lemonade.","vi":"Lời đề nghị ngớ ngẩn của anh ấy là tưới cây bằng nước chanh ngọt.","audioKind":"ex"},{"en":"The fatuous assumption that technology alone can solve poverty ignores the importance of education and effective governance.","vi":"Giả định ngớ ngẩn cho rằng chỉ riêng công nghệ có thể giải quyết được tình trạng nghèo đói đã bỏ qua tầm quan trọng của giáo dục và quản trị hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"a fatuous remark","vi":"một phát ngôn ngớ ngẩn"},{"en":"a fatuous argument","vi":"một lập luận ngốc nghếch"},{"en":"a fatuous assumption","vi":"một giả định vô lý"}],"wordFamily":["fatuously (adv.)","fatuousness (n.)"],"synonyms":["foolish","inane","silly"],"antonyms":["sensible"],"tipVi":"Là từ mang tính trang trọng và có sắc thái chê bai, thường dùng để phê phán những lời nói hoặc ý tưởng ngớ ngẩn nhưng tỏ ra đắc ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_7_1', 'en-c2-7', 'Cách dùng “fatuous” (adj.) — ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý', 'a fatuous remark  ·  a fatuous argument  ·  a fatuous assumption', 'Là từ mang tính trang trọng và có sắc thái chê bai, thường dùng để phê phán những lời nói hoặc ý tưởng ngớ ngẩn nhưng tỏ ra đắc ý.', 'Họ từ (Word Family): fatuously (adv.), fatuousness (n.) | Đồng nghĩa: foolish, inane, silly · Trái nghĩa: sensible', '[{"hanzi":"His fatuous suggestion was to water plants with lemonade.","pinyin":"","meaning":"Lời đề nghị ngớ ngẩn của anh ấy là tưới cây bằng nước chanh ngọt."},{"hanzi":"The fatuous assumption that technology alone can solve poverty ignores the importance of education and effective governance.","pinyin":"","meaning":"Giả định ngớ ngẩn cho rằng chỉ riêng công nghệ có thể giải quyết được tình trạng nghèo đói đã bỏ qua tầm quan trọng của giáo dục và quản trị hiệu quả."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_7_2', 'en-c2-7', 'Cách dùng “perverse” (adj.) — ngoan cố chống đối; cố chấp; bất thường', 'perverse pleasure  ·  perverse incentives  ·  perverse effect', 'Không dùng chung chung cho việc trái pháp luật; thường chỉ thái độ cố tình chống đối hoặc mang lại kết quả phản tác dụng.', 'Họ từ (Word Family): perversely (adv.), perversity (n.) | Đồng nghĩa: contrary, unreasonable · Trái nghĩa: reasonable', '[{"hanzi":"He took perverse pleasure in disagreeing with every suggestion.","pinyin":"","meaning":"Anh ta lấy làm vui thích một cách lệch lạc khi phản đối mọi đề xuất được đưa ra."},{"hanzi":"Poorly designed subsidies can create perverse incentives, encouraging companies to increase pollution rather than invest in cleaner production.","pinyin":"","meaning":"Các khoản trợ cấp được thiết kế kém có thể tạo ra các động cơ sai lệch, khuyến khích các công ty gia tăng ô nhiễm thay vì đầu tư vào sản xuất sạch hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_7_3', 'en-c2-7', 'Cách dùng “plumb” (v.) — thấu hiểu; thăm dò sâu; khảo sát kỹ', 'plumb the depths of  ·  plumb line  ·  plumb bob', 'Chữ b cuối từ là âm câm; cụm từ plumb the depths thường mang nghĩa bóng là dò xét tận cùng hoặc rơi xuống mức thấp nhất.', 'Họ từ (Word Family): plumbing (n.), plumber (n.) | Đồng nghĩa: probe, investigate', '[{"hanzi":"The documentary plumbs the mysteries of the deep ocean.","pinyin":"","meaning":"Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm."},{"hanzi":"Through detailed interviews, researchers sought to plumb the causes of declining public trust in local institutions.","pinyin":"","meaning":"Thông qua các cuộc phỏng vấn chi tiết, các nhà nghiên cứu đã cố gắng tìm hiểu sâu xa nguyên nhân dẫn đến việc công chúng ngày càng giảm niềm tin vào các cơ quan địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_7_4', 'en-c2-7', 'Cách dùng “ostensible” (adj.) — trên danh nghĩa; bề ngoài; tự xưng', 'ostensible reason  ·  ostensible purpose  ·  ostensible aim', 'Hàm ý rằng vẻ bề ngoài có thể không phải là sự thật, nhưng không đồng nghĩa là đã được chứng minh là sai sự thật.', 'Họ từ (Word Family): ostensibly (adv.) | Đồng nghĩa: apparent, professed', '[{"hanzi":"His ostensible reason for visiting was to return my umbrella.","pinyin":"","meaning":"Lý do bề ngoài của anh ấy khi đến thăm là để trả chiếc ô của tôi."},{"hanzi":"The ostensible purpose of the policy was environmental protection, although it also benefited domestic manufacturers.","pinyin":"","meaning":"Mục đích trên danh nghĩa của chính sách này là bảo vệ môi trường, mặc dù nó cũng mang lại lợi ích cho các nhà sản xuất trong nước."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_7_1', 'en-c2-7', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_1', 'ten_c2_7_1', 'preclude', 'The heavy rain precluded our planned picnic by the lake.', 'The heavy rain precluded our planned picnic by the lake.', '/prɪˈkluːd/', 'Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_2', 'ten_c2_7_1', 'surmise', 'Seeing wet umbrellas, I surmised that it was raining.', 'Seeing wet umbrellas, I surmised that it was raining.', '/sərˈmaɪz/', 'Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_3', 'ten_c2_7_1', 'intimation', 'His sudden silence gave us an intimation of trouble.', 'His sudden silence gave us an intimation of trouble.', '/ˌɪntəˈmeɪʃən/', 'Sự im lặng đột ngột của anh ấy mang lại cho chúng tôi linh cảm rằng có rắc rối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_4', 'ten_c2_7_1', 'characteristical', 'The old guide describes the village''s characteristical stone cottages.', 'The old guide describes the village''s characteristical stone cottages.', '/ˌkærəktəˈrɪstɪkəl/', 'Cuốn hướng dẫn cũ miêu tả những ngôi nhà đá đặc trưng của ngôi làng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_5', 'ten_c2_7_1', 'panacea', 'A new phone is no panacea for your troubles.', 'A new phone is no panacea for your troubles.', '/ˌpænəˈsiːə/', 'Một chiếc điện thoại mới không phải là liều thuốc tiên giải quyết mọi rắc rối của bạn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_6', 'ten_c2_7_1', 'plumb', 'The documentary plumbs the mysteries of the deep ocean.', 'The documentary plumbs the mysteries of the deep ocean.', '/plʌm/', 'Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_7', 'ten_c2_7_1', 'manifold', 'The benefits of growing your own vegetables are manifold.', 'The benefits of growing your own vegetables are manifold.', '/ˈmænɪfoʊld/', 'Lợi ích của việc tự trồng rau củ tại nhà là vô cùng đa dạng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_1_8', 'ten_c2_7_1', 'misconceive', 'I misconceived her silence as a sign of agreement.', 'I misconceived her silence as a sign of agreement.', '/ˌmɪskənˈsiːv/', 'Tôi đã hiểu lầm sự im lặng của cô ấy là dấu hiệu đồng ý.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_7_1_1', 'en-c2-7', 'ten_c2_7_1', 'listening', 'listening', 'The heavy rain precluded our planned picnic by the lake.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Căn hộ trông có vẻ rộng rãi, nhưng trên thực tế nó lại rất nhỏ.","Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.","Lời đề nghị ngớ ngẩn của anh ấy là tưới cây bằng nước chanh ngọt.","Tấm gương tạo ra ấn tượng sai lệch về một không gian rộng rãi hơn."]'::jsonb, 1, 'The heavy rain precluded our planned picnic by the lake. → Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_7_1_2', 'en-c2-7', 'ten_c2_7_1', 'listening', 'listening', 'Seeing wet umbrellas, I surmised that it was raining.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Căn hộ trông có vẻ rộng rãi, nhưng trên thực tế nó lại rất nhỏ.","Chúng tôi đứng nhìn con thủy triều không thể ngăn cản đang tiến dần về phía lâu đài cát của mình.","Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa.","Giáo viên đã đặt vấn đề về sự liên quan của đoạn văn cuối trong bài của tôi."]'::jsonb, 2, 'Seeing wet umbrellas, I surmised that it was raining. → Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_7_1_3', 'en-c2-7', 'ten_c2_7_1', 'listening', 'listening', 'His sudden silence gave us an intimation of trouble.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.","Sự im lặng đột ngột của anh ấy mang lại cho chúng tôi linh cảm rằng có rắc rối.","Lời đề nghị ngớ ngẩn của anh ấy là tưới cây bằng nước chanh ngọt.","Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm."]'::jsonb, 1, 'His sudden silence gave us an intimation of trouble. → Sự im lặng đột ngột của anh ấy mang lại cho chúng tôi linh cảm rằng có rắc rối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_7_2', 'en-c2-7', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_2_1', 'ten_c2_7_2', 'preclude', 'High tuition fees may preclude students from disadvantaged backgrounds from accessing higher education without financial support.', 'High tuition fees may preclude students from disadvantaged backgrounds from accessing higher education without financial support.', '/prɪˈkluːd/', 'Học phí cao có thể khiến học sinh đến từ các hoàn cảnh khó khăn không thể tiếp cận giáo dục đại học nếu không có sự hỗ trợ tài chính.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_2_2', 'ten_c2_7_2', 'surmise', 'Researchers surmise that flexible schedules improve employee wellbeing, although stronger evidence is needed to confirm this.', 'Researchers surmise that flexible schedules improve employee wellbeing, although stronger evidence is needed to confirm this.', '/sərˈmaɪz/', 'Các nhà nghiên cứu suy đoán rằng lịch trình linh hoạt giúp cải thiện sức khỏe tinh thần của nhân viên, mặc dù vẫn cần nhiều bằng chứng thuyết phục hơn để xác nhận điều này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_2_3', 'ten_c2_7_2', 'intimation', 'The minister''s remarks offered the first intimation that funding for public transport might increase.', 'The minister''s remarks offered the first intimation that funding for public transport might increase.', '/ˌɪntəˈmeɪʃən/', 'Phát biểu của vị bộ trưởng đã hé lộ dấu hiệu đầu tiên cho thấy ngân sách dành cho giao thông công cộng có thể tăng lên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_2_4', 'ten_c2_7_2', 'characteristical', 'The historical account highlights the characteristical features of rural architecture, including local stone and steep roofs.', 'The historical account highlights the characteristical features of rural architecture, including local stone and steep roofs.', '/ˌkærəktəˈrɪstɪkəl/', 'Bản ghi chép lịch sử làm nổi bật các đặc trưng của kiến trúc nông thôn, bao gồm đá địa phương và mái nhà dốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_2_5', 'ten_c2_7_2', 'panacea', 'Although technology can improve classroom learning, it should not be regarded as a panacea for educational inequality.', 'Although technology can improve classroom learning, it should not be regarded as a panacea for educational inequality.', '/ˌpænəˈsiːə/', 'Mặc dù công nghệ có thể cải thiện việc học tập trên lớp, nó không nên được xem là giải pháp vạn năng cho sự bất bình đẳng trong giáo dục.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_7_2_6', 'ten_c2_7_2', 'plumb', 'Through detailed interviews, researchers sought to plumb the causes of declining public trust in local institutions.', 'Through detailed interviews, researchers sought to plumb the causes of declining public trust in local institutions.', '/plʌm/', 'Thông qua các cuộc phỏng vấn chi tiết, các nhà nghiên cứu đã cố gắng tìm hiểu sâu xa nguyên nhân dẫn đến việc công chúng ngày càng giảm niềm tin vào các cơ quan địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_7_2_1', 'en-c2-7', 'ten_c2_7_2', 'listening', 'listening', 'High tuition fees may preclude students from disadvantaged backgrounds from accessing higher education without financial support.', NULL, 'Trong câu vừa nghe, từ “preclude” mang nghĩa nào sau đây?', '["ngăn chặn; làm cho không thể xảy ra; loại trừ","phát triển nhanh chóng và ngoạn mục; vụt sáng","làm cho ai đó cực kỳ tức giận hoặc bực bội","phân nhánh, chia nhánh hoặc lan rộng thành các bộ phận kết nối với nhau"]'::jsonb, 0, '“preclude” (/prɪˈkluːd/): ngăn chặn; làm cho không thể xảy ra; loại trừ. Câu đầy đủ: High tuition fees may preclude students from disadvantaged backgrounds from accessing higher education without financial support.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_7_2_2', 'en-c2-7', 'ten_c2_7_2', 'listening', 'listening', 'Researchers surmise that flexible schedules improve employee wellbeing, although stronger evidence is needed to confirm this.', NULL, 'Trong câu vừa nghe, từ “surmise” mang nghĩa nào sau đây?', '["bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu","suy đoán; phỏng đoán","vui vẻ; hoạt bát","đầu hàng; khuất phục; nhượng bộ"]'::jsonb, 1, '“surmise” (/sərˈmaɪz/): suy đoán; phỏng đoán. Câu đầy đủ: Researchers surmise that flexible schedules improve employee wellbeing, although stronger evidence is needed to confirm this.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_7_1', 'en-c2-7', 'The heavy rain precluded our planned picnic by the lake', 'Cơn mưa lớn đã làm cho buổi dã ngoại bên hồ mà chúng tôi lên kế hoạch từ trước không thể diễn ra.', 'preclude /prɪˈkluːd/', '["lake","heavy","picnic","rain","planned","our","The","the","precluded","by"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
