INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_2', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'Seeing wet umbrellas, I surmised that it was raining.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu đùa kém duyên của anh ấy khiến mọi người trong bữa tối cảm thấy khó chịu.","Lợi ích của việc tự trồng rau củ tại nhà là vô cùng đa dạng.","Lời đề nghị ngớ ngẩn của anh ấy là tưới cây bằng nước chanh ngọt.","Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa."]'::jsonb, 3, 'Seeing wet umbrellas, I surmised that it was raining. → Nhìn thấy những chiếc ô ướt, tôi phỏng đoán rằng trời đang mưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_3', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'intimation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chế giễu; mỉa mai","sự gợi ý; lời ám chỉ; dấu hiệu","thuộc về tiềm thức; dưới ngưỡng ý thức","trả thù; rửa hận; phục thù"]'::jsonb, 1, 'intimation (/ˌɪntəˈmeɪʃən/) → sự gợi ý; lời ám chỉ; dấu hiệu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_4', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'The old guide describes the village''s characteristical stone cottages.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuốn hướng dẫn cũ miêu tả những ngôi nhà đá đặc trưng của ngôi làng.","Vận động viên chạy bền kiên cường ấy vẫn tiếp tục tiến bước mặc cho con dốc cao.","Tôi đã hiểu lầm sự im lặng của cô ấy là dấu hiệu đồng ý.","Lời bào chữa của anh ấy không còn đứng vững được sau khi chúng tôi kiểm tra lại."]'::jsonb, 0, 'The old guide describes the village''s characteristical stone cottages. → Cuốn hướng dẫn cũ miêu tả những ngôi nhà đá đặc trưng của ngôi làng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_5', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'panacea', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuốc tiên; giải pháp vạn năng","sự đền bù; thù lao","vó nước; xoáy nước; dòng xoáy","trên danh nghĩa; bề ngoài; tự xưng"]'::jsonb, 0, 'panacea (/ˌpænəˈsiːə/) → thuốc tiên; giải pháp vạn năng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_6', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'The documentary plumbs the mysteries of the deep ocean.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu đùa kém duyên của anh ấy khiến mọi người trong bữa tối cảm thấy khó chịu.","Sa mạc lấp lánh với những vũng nước ảo ảnh.","Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm.","Triết gia miêu tả trí tưởng tượng như một năng lực tư duy hình thành khái niệm."]'::jsonb, 2, 'The documentary plumbs the mysteries of the deep ocean. → Bộ phim tài liệu khám phá những bí ẩn của đại dương sâu thẳm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_7', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'manifold', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chi trả; thanh toán (chi phí)","được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh","nhiều và phong phú; đa dạng; nhiều mặt","làm phiền; làm bực mình; làm lo lắng"]'::jsonb, 2, 'manifold (/ˈmænɪfoʊld/) → nhiều và phong phú; đa dạng; nhiều mặt; ống góp; hệ thống ống chia', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_8', 'en-c2-7', NULL, 'comprehensive_test', 'listening', 'I misconceived her silence as a sign of agreement.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Triết gia miêu tả trí tưởng tượng như một năng lực tư duy hình thành khái niệm.","Thật là một sự tình cờ hoàn toàn khi chúng tôi đặt chỗ ngồi cạnh nhau.","Câu đùa kém duyên của anh ấy khiến mọi người trong bữa tối cảm thấy khó chịu.","Tôi đã hiểu lầm sự im lặng của cô ấy là dấu hiệu đồng ý."]'::jsonb, 3, 'I misconceived her silence as a sign of agreement. → Tôi đã hiểu lầm sự im lặng của cô ấy là dấu hiệu đồng ý.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_9', 'en-c2-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Something believed to solve every problem or cure every illness.”?', '["inapt","panacea","fortuity","tenacious"]'::jsonb, 1, 'panacea (/ˌpænəˈsiːə/) → thuốc tiên; giải pháp vạn năng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_10', 'en-c2-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “examine something closely to understand it fully”?', '["pertinence","perverse","ostensible","plumb"]'::jsonb, 3, 'plumb (/plʌm/) → thấu hiểu; thăm dò sâu; khảo sát kỹ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_11', 'en-c2-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Numerous and varied”?', '["characteristical","preclude","fortuity","manifold"]'::jsonb, 3, 'manifold (/ˈmænɪfoʊld/) → nhiều và phong phú; đa dạng; nhiều mặt', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_12', 'en-c2-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to understand something in the wrong way”?', '["preclude","panacea","fatuous","misconceive"]'::jsonb, 3, 'misconceive (/ˌmɪskənˈsiːv/) → hiểu lầm; nhận thức sai', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_13', 'en-c2-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An event happening by chance, or chance itself.”?', '["fatuous","characteristical","conceptive","fortuity"]'::jsonb, 3, 'fortuity (/fɔːrˈtuːəti/) → sự tình cờ; cơ may', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
