INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_18', 'en-c2-7', NULL, 'comprehensive_test', 'reading', NULL, 'High tuition fees may preclude students from disadvantaged backgrounds from accessing higher education without financial support.', 'Dựa vào câu trên, từ “preclude” có nghĩa phù hợp nhất là gì?', '["đeo kính","ngăn chặn; làm cho không thể xảy ra; loại trừ","tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành","thuốc tiên; giải pháp vạn năng"]'::jsonb, 1, 'preclude: ngăn chặn; làm cho không thể xảy ra; loại trừ. Dịch cả câu: Học phí cao có thể khiến học sinh đến từ các hoàn cảnh khó khăn không thể tiếp cận giáo dục đại học nếu không có sự hỗ trợ tài chính.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_19', 'en-c2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers surmise that flexible schedules improve employee wellbeing, although stronger evidence is needed to confirm this.', 'Dựa vào câu trên, từ “surmise” có nghĩa phù hợp nhất là gì?', '["hiểu lầm; nhận thức sai","cành lớn; nhánh cây chính","người theo chủ nghĩa tự do cá nhân","suy đoán; phỏng đoán"]'::jsonb, 3, 'surmise: suy đoán; phỏng đoán; sự phỏng đoán; điều phỏng đoán. Dịch cả câu: Các nhà nghiên cứu suy đoán rằng lịch trình linh hoạt giúp cải thiện sức khỏe tinh thần của nhân viên, mặc dù vẫn cần nhiều bằng chứng thuyết phục hơn để xác nhận điều này.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_20', 'en-c2-7', NULL, 'comprehensive_test', 'reading', NULL, 'The minister''s remarks offered the first intimation that funding for public transport might increase.', 'Dựa vào câu trên, từ “intimation” có nghĩa phù hợp nhất là gì?', '["một nhóm gồm bốn thứ","thuộc về thành tố; mang tính phân tích thành phần","sự gợi ý; lời ám chỉ; dấu hiệu","ghê tởm; đáng ghét"]'::jsonb, 2, 'intimation: sự gợi ý; lời ám chỉ; dấu hiệu. Dịch cả câu: Phát biểu của vị bộ trưởng đã hé lộ dấu hiệu đầu tiên cho thấy ngân sách dành cho giao thông công cộng có thể tăng lên.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_21', 'en-c2-7', NULL, 'comprehensive_test', 'reading', NULL, 'The historical account highlights the characteristical features of rural architecture, including local stone and steep roofs.', 'Dựa vào câu trên, từ “characteristical” có nghĩa phù hợp nhất là gì?', '["chứng thần kinh (thuật ngữ cũ chỉ các vấn đề tâm lý liên quan đến lo âu hoặc căng thẳng)","mang tính bước ngoặt; mở ra thời đại mới; vĩ đại","đặc trưng; tiêu biểu","dẻo dai; dễ uốn; dễ gập"]'::jsonb, 2, 'characteristical: đặc trưng; tiêu biểu. Dịch cả câu: Bản ghi chép lịch sử làm nổi bật các đặc trưng của kiến trúc nông thôn, bao gồm đá địa phương và mái nhà dốc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_22', 'en-c2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không thích hợp; không thỏa đáng; không khéo”', '["madden","surmise","furor","inapt"]'::jsonb, 3, 'không thích hợp; không thỏa đáng; không khéo → inapt (/ɪnˈæpt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_23', 'en-c2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thực tế; thực trạng”', '["staphylococcus","sneer","eddy","actuality"]'::jsonb, 3, 'thực tế; thực trạng → actuality (/ˌæktʃuˈæləti/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_7_24', 'en-c2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý”', '["fatuous","rapture","malleable","hitherto"]'::jsonb, 0, 'ngu ngốc; ngớ ngẩn; tự mãn một cách vô lý → fatuous (/ˈfætʃ.u.əs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-8', 'en', 'Bài 8: Cảm xúc & Tính cách - CEFR C2', 'CEFR C2', 'C2 · Cảm xúc', '22 từ vựng Tiếng Anh CEFR C2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6008, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vex', 'en-c2-8', 'vex', '/veks/', 'C2', 'làm phiền; làm bực mình; làm lo lắng', 'v.', 'vexed (adj.), vexing (adj.), vexation (n.)', 'Đồng nghĩa: annoy, irritate, trouble · Trái nghĩa: soothe', 'Là ngoại động từ mang tính trang trọng hơn; trong giao tiếp hàng ngày thường dùng annoy.', 'The constant dripping from the tap began to vex him.', NULL, 'Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.', '{"wordId":"vex","ukIpa":"/veks/","usIpa":"/veks/","cefr":"C2","topic":"emotion","senses":[{"pos":"v.","en":"To make someone annoyed, worried, or frustrated.","vi":"làm phiền; làm bực mình; làm lo lắng"}],"examples":[{"en":"The constant dripping from the tap began to vex him.","vi":"Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.","audioKind":"ex"},{"en":"Disagreements over how to fund public transport continue to vex policymakers in many growing cities.","vi":"Những bất đồng về cách tài trợ cho giao thông công cộng tiếp tục làm đau đầu các nhà hoạch định chính sách ở nhiều đô thị đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"vex policymakers","vi":"làm đau đầu các nhà hoạch định chính sách"},{"en":"a vexed question","vi":"một vấn đề nan giải; câu hỏi hóc búa"},{"en":"be vexed by delays","vi":"bực bội vì sự chậm trễ"}],"wordFamily":["vexed (adj.)","vexing (adj.)","vexation (n.)"],"synonyms":["annoy","irritate","trouble"],"antonyms":["soothe"],"tipVi":"Là ngoại động từ mang tính trang trọng hơn; trong giao tiếp hàng ngày thường dùng annoy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_madden', 'en-c2-8', 'madden', '/ˈmædən/', 'C2', 'làm cho ai đó cực kỳ tức giận hoặc bực bội', 'v.', 'mad (adj.), maddening (adj.), maddeningly (adv.), madness (n.)', 'Đồng nghĩa: infuriate, enrage · Trái nghĩa: calm', 'Thường là động từ ngoại mệnh đề, diễn tả việc làm cho ai đó tức giận đến mức phát điên.', 'The constant buzzing of that broken fan maddens me.', NULL, 'Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên.', '{"wordId":"madden","ukIpa":"/ˈmædən/","usIpa":"/ˈmædən/","cefr":"C2","topic":"emotion","senses":[{"pos":"v.","en":"to make someone extremely angry or frustrated","vi":"làm cho ai đó cực kỳ tức giận hoặc bực bội"}],"examples":[{"en":"The constant buzzing of that broken fan maddens me.","vi":"Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên.","audioKind":"ex"},{"en":"Repeated delays and unclear explanations can madden commuters who depend on reliable public transport.","vi":"Việc lặp lại các sự cố chậm trễ và những lời giải thích mơ hồ có thể làm cho những người đi làm phụ thuộc vào phương tiện giao thông công cộng đáng tin cậy cảm thấy vô cùng bực bội.","audioKind":"ex2"}],"collocations":[{"en":"madden someone","vi":"làm cho ai đó cực kỳ tức giận"},{"en":"be maddened by delays","vi":"bị làm cho phát điên vì sự chậm trễ"}],"wordFamily":["mad (adj.)","maddening (adj.)","maddeningly (adv.)","madness (n.)"],"synonyms":["infuriate","enrage"],"antonyms":["calm"],"tipVi":"Thường là động từ ngoại mệnh đề, diễn tả việc làm cho ai đó tức giận đến mức phát điên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loth', 'en-c2-8', 'loth', '/loʊθ/', 'C2', 'không thích, không muốn hoặc miễn cưỡng làm điều gì đó', 'adj.', NULL, 'Đồng nghĩa: reluctant, unwilling · Trái nghĩa: willing, eager', 'Là biến thể ít phổ biến hơn của từ ''loath''; thường dùng cấu trúc ''be loth to do''.', 'I was loth to leave the warm kitchen.', NULL, 'Tôi không hề muốn rời khỏi căn bếp ấm áp chút nào.', '{"wordId":"loth","ukIpa":"/ləʊθ/","usIpa":"/loʊθ/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Unwilling or reluctant to do something.","vi":"không thích, không muốn hoặc miễn cưỡng làm điều gì đó"}],"examples":[{"en":"I was loth to leave the warm kitchen.","vi":"Tôi không hề muốn rời khỏi căn bếp ấm áp chút nào.","audioKind":"ex"},{"en":"Some residents are loth to support redevelopment because they fear losing their neighbourhood''s distinctive character.","vi":"Một số cư dân không muốn ủng hộ việc tái phát triển vì họ sợ mất đi nét đặc trưng riêng biệt của khu ố phố của mình.","audioKind":"ex2"}],"collocations":[{"en":"loth to admit","vi":"không muốn thừa nhận"},{"en":"loth to leave","vi":"lưu luyến không muốn rời đi"},{"en":"loth to accept","vi":"miễn cưỡng chấp nhận"}],"wordFamily":[],"synonyms":["reluctant","unwilling"],"antonyms":["willing","eager"],"tipVi":"Là biến thể ít phổ biến hơn của từ ''loath''; thường dùng cấu trúc ''be loth to do''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magnanimous', 'en-c2-8', 'magnanimous', '/mæɡˈnænɪməs/', 'C2', 'hào phóng và bao dung, đặc biệt là đối với đối thủ hoặc người yếu thế hơn', 'adj.', 'magnanimity (n.), magnanimously (adv.)', 'Đồng nghĩa: generous, forgiving · Trái nghĩa: petty, vindictive', 'Từ trang trọng, thường dùng để mô tả thái độ rộng lượng đối với đối thủ hoặc người đã xúc phạm mình.', 'She was magnanimous and congratulated her rival warmly.', NULL, 'Cô ấy rất hào hiệp và nhiệt tình chúc mừng đối thủ của mình.', '{"wordId":"magnanimous","ukIpa":"/mæɡˈnænɪməs/","usIpa":"/mæɡˈnænɪməs/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"generous and forgiving, especially towards a rival or weaker person","vi":"hào phóng và bao dung, đặc biệt là đối với đối thủ hoặc người yếu thế hơn"}],"examples":[{"en":"She was magnanimous and congratulated her rival warmly.","vi":"Cô ấy rất hào hiệp và nhiệt tình chúc mừng đối thủ của mình.","audioKind":"ex"},{"en":"A magnanimous response to criticism can help leaders build trust and encourage constructive public debate.","vi":"Một phản ứng cao thượng trước những lời chỉ trích có thể giúp các nhà lãnh đạo xây dựng lòng tin và khuyến khích các cuộc tranh luận công khai mang tính xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"magnanimous in victory","vi":"cao thượng khi chiến thắng"},{"en":"a magnanimous gesture","vi":"một nghĩa cử cao đẹp"},{"en":"a magnanimous response","vi":"một phản ứng bao dung"}],"wordFamily":["magnanimity (n.)","magnanimously (adv.)"],"synonyms":["generous","forgiving"],"antonyms":["petty","vindictive"],"tipVi":"Từ trang trọng, thường dùng để mô tả thái độ rộng lượng đối với đối thủ hoặc người đã xúc phạm mình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tantalize', 'en-c2-8', 'tantalize', '/ˈtæntəlaɪz/', 'C2', 'trêu ngươi; khơi gợi khao khát nhưng khó với tới', 'v.', 'tantalizing (adj.), tantalizingly (adv.), tantalization (n.)', 'Đồng nghĩa: tempt, tease', 'Tiếng Anh Anh cũng viết là tantalise; nhấn mạnh việc khơi gợi ham muốn nhưng tạm thời chưa thể đạt được.', 'The smell of fresh bread tantalized us outside the bakery.', NULL, 'Mùi thơm của bánh mì mới nướng ở ngoài tiệm bánh cứ trêu ngươi chúng tôi.', '{"wordId":"tantalize","ukIpa":"/ˈtæntəlaɪz/","usIpa":"/ˈtæntəlaɪz/","cefr":"C2","topic":"emotion","senses":[{"pos":"v.","en":"To excite desire for something that remains out of reach.","vi":"trêu ngươi; khơi gợi khao khát nhưng khó với tới"}],"examples":[{"en":"The smell of fresh bread tantalized us outside the bakery.","vi":"Mùi thơm của bánh mì mới nướng ở ngoài tiệm bánh cứ trêu ngươi chúng tôi.","audioKind":"ex"},{"en":"Early discoveries tantalize researchers with the possibility of finding affordable treatments for currently incurable diseases.","vi":"Những phát hiện ban đầu thắp lên hy vọng cho các nhà nghiên cứu về khả năng tìm ra phương pháp điều trị phải chăng cho các căn bệnh hiện chưa có thuốc chữa.","audioKind":"ex2"}],"collocations":[{"en":"tantalize someone with","vi":"dụ dỗ ai bằng cái gì"},{"en":"tantalizing glimpse","vi":"cái nhìn thoáng qua đầy cám dỗ"},{"en":"tantalizing prospect","vi":"triển vọng hấp dẫn nhưng khó nắm bắt"}],"wordFamily":["tantalizing (adj.)","tantalizingly (adv.)","tantalization (n.)"],"synonyms":["tempt","tease"],"antonyms":[],"tipVi":"Tiếng Anh Anh cũng viết là tantalise; nhấn mạnh việc khơi gợi ham muốn nhưng tạm thời chưa thể đạt được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhilarate', 'en-c2-8', 'exhilarate', '/ɪɡˈzɪləreɪt/', 'C2', 'làm phấn chấn; làm hưng phấn; làm vui sướng', 'v.', 'exhilaration (n.), exhilarating (adj.), exhilarated (adj.)', 'Đồng nghĩa: thrill, excite, elate · Trái nghĩa: depress', 'Động từ ngoại động từ; người cảm thấy hứng thú sử dụng tính từ exhilarated.', 'The fast boat ride exhilarated everyone on board.', NULL, 'Chuyến đi thuyền tốc độ cao khiến mọi người trên tàu đều phấn chấn.', '{"wordId":"exhilarate","ukIpa":"/ɪɡˈzɪləreɪt/","usIpa":"/ɪɡˈzɪləreɪt/","cefr":"C2","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel excited, energetic, and very happy","vi":"làm phấn chấn; làm hưng phấn; làm vui sướng"}],"examples":[{"en":"The fast boat ride exhilarated everyone on board.","vi":"Chuyến đi thuyền tốc độ cao khiến mọi người trên tàu đều phấn chấn.","audioKind":"ex"},{"en":"Outdoor adventures can exhilarate participants while helping them develop confidence and a stronger connection with nature.","vi":"Các hoạt động phiêu lưu ngoài trời có thể làm cho người tham gia tràn đầy hứng khởi đồng thời giúp họ phát triển sự tự tin và gắn kết sâu sắc hơn với thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"feel exhilarated","vi":"cảm thấy phấn khích"},{"en":"exhilarated by the experience","vi":"được truyền cảm hứng và phấn chấn bởi trải nghiệm này"},{"en":"an exhilarating experience","vi":"một trải nghiệm đầy hứng khởi"}],"wordFamily":["exhilaration (n.)","exhilarating (adj.)","exhilarated (adj.)"],"synonyms":["thrill","excite","elate"],"antonyms":["depress"],"tipVi":"Động từ ngoại động từ; người cảm thấy hứng thú sử dụng tính từ exhilarated.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vehement', 'en-c2-8', 'vehement', '/ˈviː.ə.mənt/', 'C2', 'mãnh liệt; quyết liệt', 'adj.', 'vehemently (adv.), vehemence (n.)', 'Đồng nghĩa: fierce, forceful, passionate · Trái nghĩa: mild', 'Thường dùng để mô tả mức độ mãnh liệt của sự phản đối, phủ nhận hoặc chỉ trích, mang sắc thái trang trọng.', 'Her vehement refusal surprised everyone at the table.', NULL, 'Sự từ chối quyết liệt của cô ấy khiến mọi người quanh bàn ngạc nhiên.', '{"wordId":"vehement","ukIpa":"/ˈviː.ə.mənt/","usIpa":"/ˈviː.ə.mənt/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Expressing very strong feelings, especially anger or opposition","vi":"mãnh liệt; quyết liệt"}],"examples":[{"en":"Her vehement refusal surprised everyone at the table.","vi":"Sự từ chối quyết liệt của cô ấy khiến mọi người quanh bàn ngạc nhiên.","audioKind":"ex"},{"en":"The proposed closure of the community library met with vehement opposition from residents and local educators.","vi":"Việc đề xuất đóng cửa thư viện cộng đồng đã vấp phải sự phản đối dữ dội từ cư dân và các nhà giáo dục địa phương.","audioKind":"ex2"}],"collocations":[{"en":"vehement opposition","vi":"sự phản đối mạnh mẽ"},{"en":"vehement denial","vi":"sự phủ nhận quyết liệt"},{"en":"vehement criticism","vi":"sự chỉ trích gay gắt"}],"wordFamily":["vehemently (adv.)","vehemence (n.)"],"synonyms":["fierce","forceful","passionate"],"antonyms":["mild"],"tipVi":"Thường dùng để mô tả mức độ mãnh liệt của sự phản đối, phủ nhận hoặc chỉ trích, mang sắc thái trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loath', 'en-c2-8', 'loath', '/loʊθ/', 'C2', 'không thích; miễn cưỡng', 'adj.', NULL, 'Đồng nghĩa: reluctant, unwilling · Trái nghĩa: willing, eager', 'Thường dùng cấu trúc be loath to do; tránh nhầm lẫn với động từ loathe (cực kỳ ghét).', 'I was loath to leave the warm kitchen.', NULL, 'Tôi không nỡ rời khỏi căn bếp ấm áp.', '{"wordId":"loath","ukIpa":"/ləʊθ/","usIpa":"/loʊθ/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Unwilling to do something.","vi":"không thích; miễn cưỡng"}],"examples":[{"en":"I was loath to leave the warm kitchen.","vi":"Tôi không nỡ rời khỏi căn bếp ấm áp.","audioKind":"ex"},{"en":"Many residents are loath to support redevelopment projects that could destroy the character of their neighbourhoods.","vi":"Nhiều cư dân không muốn ủng hộ các dự án tái phát triển có thể phá hủy bản sắc của khu phố họ.","audioKind":"ex2"}],"collocations":[{"en":"be loath to admit","vi":"không muốn thừa nhận"},{"en":"be loath to leave","vi":"không nỡ rời đi"},{"en":"be loath to accept","vi":"miễn cưỡng chấp nhận"}],"wordFamily":[],"synonyms":["reluctant","unwilling"],"antonyms":["willing","eager"],"tipVi":"Thường dùng cấu trúc be loath to do; tránh nhầm lẫn với động từ loathe (cực kỳ ghét).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disgustful', 'en-c2-8', 'disgustful', '/dɪsˈɡʌstfəl/', 'C2', 'ghê tởm; đáng ghét', 'adj.', 'disgust (n.), disgusting (adj.), disgusted (adj.)', 'Đồng nghĩa: disgusting, revolting, repulsive · Trái nghĩa: pleasant', 'Từ này ít dùng và mang tính cổ; trong tiếng Anh hiện đại thường dùng disgusting.', 'A disgustful smell rose from the forgotten food.', NULL, 'Một mùi hương ghê tởm bốc lên từ món ăn bị bỏ quên.', '{"wordId":"disgustful","ukIpa":"/dɪsˈɡʌstfəl/","usIpa":"/dɪsˈɡʌstfəl/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Causing strong dislike or a feeling of sickness.","vi":"ghê tởm; đáng ghét"}],"examples":[{"en":"A disgustful smell rose from the forgotten food.","vi":"Một mùi hương ghê tởm bốc lên từ món ăn bị bỏ quên.","audioKind":"ex"},{"en":"The disgustful condition of neglected public toilets can discourage residents from using otherwise attractive parks.","vi":"Tình trạng ghê tởm của những nhà vệ sinh công cộng bị bỏ bê có thể làm nản lòng người dân khi đến những công viên vốn dĩ rất hấp dẫn.","audioKind":"ex2"}],"collocations":[{"en":"disgustful smell","vi":"mùi hôi ghê tởm"},{"en":"disgustful sight","vi":"cảnh tượng ghê tởm"}],"wordFamily":["disgust (n.)","disgusting (adj.)","disgusted (adj.)"],"synonyms":["disgusting","revolting","repulsive"],"antonyms":["pleasant"],"tipVi":"Từ này ít dùng và mang tính cổ; trong tiếng Anh hiện đại thường dùng disgusting.","noteVi":"Từ thực tế nhưng hiếm gặp và hơi cũ; thông thường nên dùng disgusting.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goad', 'en-c2-8', 'goad', '/ɡoʊd/', 'C2', 'kích động; khiêu khích; xúi giục; gậy nhọn để lùa gia súc; động lực thúc đẩy', 'v.', NULL, 'Đồng nghĩa: provoke, prod · Trái nghĩa: deter', 'Thường dùng cấu trúc goad sb into doing, hay mang nghĩa kích động tiêu cực.', 'His teasing goaded me into joining the race.', NULL, 'Lời trêu chọc của anh ấy đã kích động tôi tham gia cuộc đua.', '{"wordId":"goad","ukIpa":"/ɡəʊd/","usIpa":"/ɡoʊd/","cefr":"C2","topic":"emotion","senses":[{"pos":"v.","en":"to provoke someone into acting through persistent pressure or annoyance","vi":"kích động; khiêu khích; xúi giục"},{"pos":"n.","en":"a pointed stick used to make animals move","vi":"gậy nhọn để lùa gia súc"},{"pos":"n.","en":"something that strongly pushes a person to act","vi":"động lực thúc đẩy"}],"examples":[{"en":"His teasing goaded me into joining the race.","vi":"Lời trêu chọc của anh ấy đã kích động tôi tham gia cuộc đua.","audioKind":"ex"},{"en":"Competitive school environments may goad students into pursuing high grades at the expense of genuine understanding.","vi":"Môi trường học đường mang tính cạnh tranh có thể thúc đẩy học sinh theo đuổi điểm số cao mà đánh đổi sự hiểu biết thực sự.","audioKind":"ex2"}],"collocations":[{"en":"goad someone into doing something","vi":"kích động ai làm gì"},{"en":"goad someone on","vi":"thúc giục ai đó tiếp tục hành động"},{"en":"a goad to action","vi":"động lực hành động"}],"wordFamily":[],"synonyms":["provoke","prod"],"antonyms":["deter"],"tipVi":"Thường dùng cấu trúc goad sb into doing, hay mang nghĩa kích động tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zealous', 'en-c2-8', 'zealous', '/ˈzeləs/', 'C2', 'sốt sắng; nhiệt huyết; tận tụy', 'adj.', 'zeal (n.), zealously (adv.), overzealous (adj.)', 'Đồng nghĩa: enthusiastic, ardent, fervent · Trái nghĩa: apathetic, indifferent', 'Sắc thái mạnh hơn "enthusiastic", đôi khi ngụ ý sự nhiệt tình đến mức thái quá.', 'A zealous volunteer cleaned the entire beach before lunch.', NULL, 'Một tình nguyện viên nhiệt huyết đã dọn sạch toàn bộ bãi biển trước giờ ăn trưa.', '{"wordId":"zealous","ukIpa":"/ˈzeləs/","usIpa":"/ˈzeləs/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Showing great enthusiasm and commitment to a cause or activity.","vi":"sốt sắng; nhiệt huyết; tận tụy"}],"examples":[{"en":"A zealous volunteer cleaned the entire beach before lunch.","vi":"Một tình nguyện viên nhiệt huyết đã dọn sạch toàn bộ bãi biển trước giờ ăn trưa.","audioKind":"ex"},{"en":"Zealous campaigners can raise public awareness, but lasting environmental progress also requires effective government policies.","vi":"Những nhà vận động nhiệt huyết có thể nâng cao nhận thức cộng đồng, nhưng sự tiến bộ lâu dài về môi trường cũng đòi hỏi những chính sách hiệu quả từ chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"a zealous supporter","vi":"người ủng hộ nhiệt thành"},{"en":"zealous in their efforts","vi":"nỗ lực hết mình nhiệt huyết"},{"en":"overly zealous","vi":"nhiệt tình thái quá"}],"wordFamily":["zeal (n.)","zealously (adv.)","overzealous (adj.)"],"synonyms":["enthusiastic","ardent","fervent"],"antonyms":["apathetic","indifferent"],"tipVi":"Sắc thái mạnh hơn \"enthusiastic\", đôi khi ngụ ý sự nhiệt tình đến mức thái quá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contemptuous', 'en-c2-8', 'contemptuous', '/kənˈtemptʃuəs/', 'C2', 'khinh miệt; coi thường; tỏ thái độ khinh bỉ', 'adj.', 'contempt (n.), contemptuously (adv.), contemptible (adj.)', 'Đồng nghĩa: scornful, disdainful · Trái nghĩa: respectful', 'contemptuous dùng để chỉ thái độ khinh miệt người khác; trong khi contemptible có nghĩa là đáng khinh.', 'She gave my muddy shoes a contemptuous glance.', NULL, 'Cô ấy ném cho đôi giày dính bùn của tôi một ánh mắt khinh miệt.', '{"wordId":"contemptuous","ukIpa":"/kənˈtemptʃuəs/","usIpa":"/kənˈtemptʃuəs/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"showing that you consider someone or something unworthy of respect","vi":"khinh miệt; coi thường; tỏ thái độ khinh bỉ"}],"examples":[{"en":"She gave my muddy shoes a contemptuous glance.","vi":"Cô ấy ném cho đôi giày dính bùn của tôi một ánh mắt khinh miệt.","audioKind":"ex"},{"en":"Leaders who are contemptuous of public concerns risk damaging trust in the institutions they represent.","vi":"Các nhà lãnh đạo tỏ thái độ khinh miệt trước những mối bận tâm của công chúng có nguy cơ làm tổn hại niềm tin vào các thể chế mà họ đại diện.","audioKind":"ex2"}],"collocations":[{"en":"contemptuous of","vi":"khinh miệt cái gì đó"},{"en":"a contemptuous glance","vi":"ánh mắt khinh miệt"},{"en":"a contemptuous tone","vi":"giọng điệu khinh miệt"}],"wordFamily":["contempt (n.)","contemptuously (adv.)","contemptible (adj.)"],"synonyms":["scornful","disdainful"],"antonyms":["respectful"],"tipVi":"contemptuous dùng để chỉ thái độ khinh miệt người khác; trong khi contemptible có nghĩa là đáng khinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disposition', 'en-c2-8', 'disposition', '/ˌdɪspəˈzɪʃən/', 'C2', 'tính tình, bản tính, tâm trạng và cách cư xử thường ngày của một người; khuynh hướng tự nhiên, sự sẵn lòng làm việc gì đó; sự sắp xếp, bố trí con người hoặc sự vật ở những vị trí nhất định', 'n.', NULL, 'Đồng nghĩa: temperament, inclination', 'Nghĩa tính tình thường dùng ở số ít; a disposition to do thể hiện khuynh hướng làm gì.', 'Her cheerful disposition makes even rainy mornings feel brighter.', NULL, 'Tính cách vui vẻ của cô ấy khiến ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn.', '{"wordId":"disposition","ukIpa":"/ˌdɪspəˈzɪʃən/","usIpa":"/ˌdɪspəˈzɪʃən/","cefr":"C2","topic":"emotion","senses":[{"pos":"n.","en":"a person''s usual mood and way of behaving","vi":"tính tình, bản tính, tâm trạng và cách cư xử thường ngày của một người"},{"pos":"n.","en":"a natural tendency or willingness to do something","vi":"khuynh hướng tự nhiên, sự sẵn lòng làm việc gì đó"},{"pos":"n.","en":"the arrangement of people or things in particular positions","vi":"sự sắp xếp, bố trí con người hoặc sự vật ở những vị trí nhất định"}],"examples":[{"en":"Her cheerful disposition makes even rainy mornings feel brighter.","vi":"Tính cách vui vẻ của cô ấy khiến ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn.","audioKind":"ex"},{"en":"Children with a cautious disposition may benefit from gradual exposure to unfamiliar classroom activities.","vi":"Trẻ em có tính tình thận trọng có thể được hưởng lợi từ việc từ từ tiếp cận các hoạt động quen thuộc trong lớp học.","audioKind":"ex2"}],"collocations":[{"en":"cheerful disposition","vi":"tính cách vui tươi"},{"en":"a disposition to help","vi":"khuynh hướng muốn giúp đỡ"},{"en":"a disposition towards anxiety","vi":"khuynh hướng dễ bị lo âu"}],"wordFamily":[],"synonyms":["temperament","inclination"],"antonyms":[],"tipVi":"Nghĩa tính tình thường dùng ở số ít; a disposition to do thể hiện khuynh hướng làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sullen', 'en-c2-8', 'sullen', '/ˈsʌlən/', 'C2', 'hậm hực, u sầu, cau có và không chịu thân thiện', 'adj.', 'sullenly (adv.), sullenness (n.)', 'Đồng nghĩa: morose, sulky · Trái nghĩa: cheerful', 'Nhấn mạnh thái độ giận dữ hoặc bất mãn nhưng giữ vẻ im lặng, không thân thiện.', 'He gave a sullen shrug and stared at the floor.', NULL, 'Cậu ấy nhún vai một cách hậm hực và nhìn chằm chằm xuống sàn nhà.', '{"wordId":"sullen","ukIpa":"/ˈsʌlən/","usIpa":"/ˈsʌlən/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Silently showing anger or unhappiness and refusing to be friendly.","vi":"hậm hực, u sầu, cau có và không chịu thân thiện"}],"examples":[{"en":"He gave a sullen shrug and stared at the floor.","vi":"Cậu ấy nhún vai một cách hậm hực và nhìn chằm chằm xuống sàn nhà.","audioKind":"ex"},{"en":"Students who feel excluded may become sullen and less willing to participate in classroom discussions.","vi":"Những học sinh cảm thấy bị cô lập có thể trở nên lầm lì, cáu kỉnh và ít sẵn lòng tham gia vào các cuộc thảo luận trên lớp hơn.","audioKind":"ex2"}],"collocations":[{"en":"sullen silence","vi":"sự im lặng nặng nề, sự im lặng u uất"},{"en":"a sullen expression","vi":"vẻ mặt u ám, biểu cảm cau có"},{"en":"a sullen mood","vi":"tâm trạng hậm hực, tâm trạng u sầu"}],"wordFamily":["sullenly (adv.)","sullenness (n.)"],"synonyms":["morose","sulky"],"antonyms":["cheerful"],"tipVi":"Nhấn mạnh thái độ giận dữ hoặc bất mãn nhưng giữ vẻ im lặng, không thân thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plaintive', 'en-c2-8', 'plaintive', '/ˈpleɪntɪv/', 'C2', 'ai oán, thê thiết, buồn bã và mang tính than van', 'adj.', 'plaintively (adv.)', 'Đồng nghĩa: mournful, sorrowful · Trái nghĩa: cheerful', 'Thường dùng để miêu tả âm thanh, giọng nói hoặc giai điệu mang sắc thái đau buồn, xót xa.', 'A plaintive cry came from the kitten outside our door.', NULL, 'Một tiếng kêu thê thiết phát ra từ chú mèo con ở ngoài cửa nhà chúng tôi.', '{"wordId":"plaintive","ukIpa":"/ˈpleɪntɪv/","usIpa":"/ˈpleɪntɪv/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Sounding sad, especially in a gentle or complaining way.","vi":"ai oán, thê thiết, buồn bã và mang tính than van"}],"examples":[{"en":"A plaintive cry came from the kitten outside our door.","vi":"Một tiếng kêu thê thiết phát ra từ chú mèo con ở ngoài cửa nhà chúng tôi.","audioKind":"ex"},{"en":"The musician uses a plaintive melody to convey the loneliness experienced by people living far from home.","vi":"Nhạc sĩ sử dụng giai điệu ai oán để truyền tải nỗi cô đơn mà những người sống xa quê hương phải trải qua.","audioKind":"ex2"}],"collocations":[{"en":"plaintive cry","vi":"tiếng kêu ai oán"},{"en":"plaintive voice","vi":"giọng điệu thê thiết"},{"en":"plaintive melody","vi":"giai điệu buồn bã"}],"wordFamily":["plaintively (adv.)"],"synonyms":["mournful","sorrowful"],"antonyms":["cheerful"],"tipVi":"Thường dùng để miêu tả âm thanh, giọng nói hoặc giai điệu mang sắc thái đau buồn, xót xa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reverence', 'en-c2-8', 'reverence', '/ˈrevərəns/', 'C2', 'sự tôn kính; lòng kính trọng sâu sắc', 'n.', 'revere (v.), reverent (adj.), reverently (adv.)', 'Đồng nghĩa: respect, veneration · Trái nghĩa: disrespect', 'Thường là danh từ không đếm được; đi với giới từ for khi thể hiện sự kính trọng đối với ai hoặc cái gì (reverence for).', 'She handled her grandmother''s old violin with quiet reverence.', NULL, 'Cô ấy nâng niu cây đàn vĩ cầm cũ của bà mình với một niềm tôn kính lặng lẽ.', '{"wordId":"reverence","ukIpa":"/ˈrevərəns/","usIpa":"/ˈrevərəns/","cefr":"C2","topic":"emotion","senses":[{"pos":"n.","en":"Deep respect and admiration for someone or something.","vi":"sự tôn kính; lòng kính trọng sâu sắc"}],"examples":[{"en":"She handled her grandmother''s old violin with quiet reverence.","vi":"Cô ấy nâng niu cây đàn vĩ cầm cũ của bà mình với một niềm tôn kính lặng lẽ.","audioKind":"ex"},{"en":"Reverence for traditional craftsmanship can encourage communities to preserve skills that might otherwise disappear.","vi":"Lòng tôn kính đối với nghề thủ công truyền thống có thể khuyến khích các cộng đồng gìn giữ những kỹ năng có nguy cơ bị mai một.","audioKind":"ex2"}],"collocations":[{"en":"reverence for","vi":"lòng tôn kính đối với"},{"en":"deep reverence","vi":"sự kính trọng sâu sắc"},{"en":"treat with reverence","vi":"đối xử bằng sự tôn kính"}],"wordFamily":["revere (v.)","reverent (adj.)","reverently (adv.)"],"synonyms":["respect","veneration"],"antonyms":["disrespect"],"tipVi":"Thường là danh từ không đếm được; đi với giới từ for khi thể hiện sự kính trọng đối với ai hoặc cái gì (reverence for).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_countenance', 'en-c2-8', 'countenance', '/ˈkaʊntənəns/', 'C2', 'nét mặt; thần sắc; chấp thuận; dung túng', 'n.', NULL, NULL, 'Danh từ mang tính văn học; động từ thường dùng trong câu phủ định với nghĩa dung túng, cho phép.', 'Her calm countenance reassured the children during the storm.', NULL, 'Nét mặt bình tĩnh của cô ấy đã trấn an lũ trẻ trong suốt cơn bão.', '{"wordId":"countenance","ukIpa":"/ˈkaʊntənəns/","usIpa":"/ˈkaʊntənəns/","cefr":"C2","topic":"emotion","senses":[{"pos":"n.","en":"A person''s face or facial expression.","vi":"nét mặt; thần sắc"},{"pos":"v.","en":"To accept or approve of something.","vi":"chấp thuận; dung túng"}],"examples":[{"en":"Her calm countenance reassured the children during the storm.","vi":"Nét mặt bình tĩnh của cô ấy đã trấn an lũ trẻ trong suốt cơn bão.","audioKind":"ex"},{"en":"Governments should not countenance discriminatory practices that prevent qualified candidates from accessing employment opportunities.","vi":"Chính phủ không nên dung túng cho các hành vi phân biệt đối xử cản trở các ứng viên đủ điều kiện tiếp cận cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"a calm countenance","vi":"vẻ mặt bình thản"},{"en":"a stern countenance","vi":"nét mặt nghiêm nghị"},{"en":"refuse to countenance","vi":"từ chối chấp thuận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ mang tính văn học; động từ thường dùng trong câu phủ định với nghĩa dung túng, cho phép.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_haughty', 'en-c2-8', 'haughty', '/ˈhɔːti/', 'C2', 'kiêu ngạo; kiêu kỳ; trịch thượng', 'adj.', 'haughtily (adv.), haughtiness (n.)', 'Đồng nghĩa: arrogant, disdainful, supercilious · Trái nghĩa: humble, modest', 'Mang sắc thái chê bai, nhấn mạnh việc tự cho mình giỏi giang hơn người khác, không đồng nghĩa với tự tin.', 'The customer gave the waiter a haughty look.', NULL, 'Vị khách hàng liếc nhìn người phục vụ với vẻ kiêu ngạo.', '{"wordId":"haughty","ukIpa":"/ˈhɔːti/","usIpa":"/ˈhɔːti/","cefr":"C2","topic":"emotion","senses":[{"pos":"adj.","en":"Acting as though you are better than other people.","vi":"kiêu ngạo; kiêu kỳ; trịch thượng"}],"examples":[{"en":"The customer gave the waiter a haughty look.","vi":"Vị khách hàng liếc nhìn người phục vụ với vẻ kiêu ngạo.","audioKind":"ex"},{"en":"A haughty attitude among senior managers can discourage employees from sharing ideas and reporting problems openly.","vi":"Thái độ trịch thượng của các nhà quản lý cấp cao có thể khiến nhân viên nản lòng, không dám cởi mở chia sẻ ý tưởng và báo cáo vấn đề.","audioKind":"ex2"}],"collocations":[{"en":"haughty expression","vi":"vẻ mặt kiêu ngạo"},{"en":"haughty attitude","vi":"thái độ trịch thượng"},{"en":"haughty tone","vi":"giọng điệu kiêu kỳ"}],"wordFamily":["haughtily (adv.)","haughtiness (n.)"],"synonyms":["arrogant","disdainful","supercilious"],"antonyms":["humble","modest"],"tipVi":"Mang sắc thái chê bai, nhấn mạnh việc tự cho mình giỏi giang hơn người khác, không đồng nghĩa với tự tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rapture', 'en-c2-8', 'rapture', '/ˈræptʃɚ/', 'C2', 'sự ngây ngất; niềm vui sướng tột độ; sự cuồng nhiệt', 'n.', 'rapturous (adj.), rapturously (adv.)', 'Đồng nghĩa: ecstasy, elation, delight · Trái nghĩa: despair', 'Mang ý nghĩa mạnh hơn từ hạnh phúc (happiness), thường mang màu sắc văn học.', 'The children watched the dancing dolphins in rapture.', NULL, 'Bọn trẻ chăm chú ngắm nhìn những chú cá heo nhảy múa với sự thích thú tột độ.', '{"wordId":"rapture","ukIpa":"/ˈræptʃə/","usIpa":"/ˈræptʃɚ/","cefr":"C2","topic":"emotion","senses":[{"pos":"n.","en":"An extremely strong feeling of joy and delight.","vi":"sự ngây ngất; niềm vui sướng tột độ; sự cuồng nhiệt"}],"examples":[{"en":"The children watched the dancing dolphins in rapture.","vi":"Bọn trẻ chăm chú ngắm nhìn những chú cá heo nhảy múa với sự thích thú tột độ.","audioKind":"ex"},{"en":"The rapture experienced during live performances helps explain why audiences continue to value shared cultural events.","vi":"Niềm vui sướng tột cùng trải nghiệm trong các buổi biểu diễn trực tiếp giúp giải thích lý do vì sao khán giả vẫn trân trọng các sự kiện văn hóa mang tính cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"in rapture","vi":"trong niềm ngây ngất"},{"en":"go into raptures over","vi":"cảm thấy vô cùng phấn khích trước"},{"en":"sheer rapture","vi":"niềm vui sướng thuần túy"}],"wordFamily":["rapturous (adj.)","rapturously (adv.)"],"synonyms":["ecstasy","elation","delight"],"antonyms":["despair"],"tipVi":"Mang ý nghĩa mạnh hơn từ hạnh phúc (happiness), thường mang màu sắc văn học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repent', 'en-c2-8', 'repent', '/rɪˈpent/', 'C2', 'ân hận; hối lỗi; ăn năn', 'v.', 'repentance (n.), repentant (adj.), unrepentant (adj.)', 'Đồng nghĩa: feel remorse', 'Thường dùng repent of sth; mang nghĩa nặng hơn và nhấn mạnh việc hối lỗi so với regret.', 'He came to repent of lying to his closest friend.', NULL, 'Cuối cùng anh ấy đã hối hận vì đã nói dối người bạn thân nhất của mình.', '{"wordId":"repent","ukIpa":"/rɪˈpent/","usIpa":"/rɪˈpent/","cefr":"C2","topic":"emotion","senses":[{"pos":"v.","en":"To regret wrongdoing deeply and intend to behave better.","vi":"ân hận; hối lỗi; ăn năn"}],"examples":[{"en":"He came to repent of lying to his closest friend.","vi":"Cuối cùng anh ấy đã hối hận vì đã nói dối người bạn thân nhất của mình.","audioKind":"ex"},{"en":"Some argue that justice should allow offenders to repent and rebuild their lives through education and community service.","vi":"Một số người cho rằng công lý nên tạo cơ hội cho những kẻ phạm tội ăn năn và làm lại cuộc đời thông qua giáo dục và lao động công ích.","audioKind":"ex2"}],"collocations":[{"en":"repent of wrongdoing","vi":"ân hận vì lỗi lầm"},{"en":"sincerely repent","vi":"thành tâm hối lỗi"}],"wordFamily":["repentance (n.)","repentant (adj.)","unrepentant (adj.)"],"synonyms":["feel remorse"],"antonyms":[],"tipVi":"Thường dùng repent of sth; mang nghĩa nặng hơn và nhấn mạnh việc hối lỗi so với regret.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gaily', 'en-c2-8', 'gaily', '/ˈɡeɪli/', 'C2', 'vui vẻ; hoạt bát; sặc sỡ; tươi tắn (về màu sắc)', 'adv.', 'gaiety (n.)', 'Đồng nghĩa: cheerfully, merrily · Trái nghĩa: sadly', 'Mang hơi hướng văn học; cũng có thể dùng để mô tả màu sắc trang trí rực rỡ.', 'The children laughed gaily as they chased bubbles outside.', NULL, 'Bọn trẻ vừa cười vang vừa ruổi bắt những chùm bong bóng ở bên ngoài.', '{"wordId":"gaily","ukIpa":"/ˈɡeɪli/","usIpa":"/ˈɡeɪli/","cefr":"C2","topic":"emotion","senses":[{"pos":"adv.","en":"In a cheerful and lively way.","vi":"vui vẻ; hoạt bát"},{"pos":"adv.","en":"With bright, cheerful colours.","vi":"sặc sỡ; tươi tắn (về màu sắc)"}],"examples":[{"en":"The children laughed gaily as they chased bubbles outside.","vi":"Bọn trẻ vừa cười vang vừa ruổi bắt những chùm bong bóng ở bên ngoài.","audioKind":"ex"},{"en":"Gaily decorated streets can attract visitors during local festivals and encourage spending in nearby shops.","vi":"Những con đường được trang trí sặc sỡ có thể thu hút du khách trong các dịp lễ hội địa phương và thúc đẩy chi tiêu tại các cửa hàng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"laugh gaily","vi":"cười vui vẻ"},{"en":"gaily decorated","vi":"được trang trí sặc sỡ"},{"en":"gaily coloured","vi":"màu sắc tươi tắn"}],"wordFamily":["gaiety (n.)"],"synonyms":["cheerfully","merrily"],"antonyms":["sadly"],"tipVi":"Mang hơi hướng văn học; cũng có thể dùng để mô tả màu sắc trang trí rực rỡ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortitude', 'en-c2-8', 'fortitude', '/ˈfɔːrtətuːd/', 'C2', 'sự kiên cường; sự gan góc (trong nghịch cảnh)', 'n.', NULL, 'Đồng nghĩa: resilience, courage', 'Từ thuộc văn phong trang trọng, là danh từ không đếm được, nhấn mạnh sự chịu đựng trong nghịch cảnh hoặc nỗi đau.', 'She faced months of painful treatment with remarkable fortitude.', NULL, 'Cô ấy đã trải qua nhiều tháng điều trị đau đớn với sự kiên cường đáng nể.', '{"wordId":"fortitude","ukIpa":"/ˈfɔːtɪtjuːd/","usIpa":"/ˈfɔːrtətuːd/","cefr":"C2","topic":"emotion","senses":[{"pos":"n.","en":"Courage and mental strength during pain or difficulty.","vi":"sự kiên cường; sự gan góc (trong nghịch cảnh)"}],"examples":[{"en":"She faced months of painful treatment with remarkable fortitude.","vi":"Cô ấy đã trải qua nhiều tháng điều trị đau đớn với sự kiên cường đáng nể.","audioKind":"ex"},{"en":"Communities affected by natural disasters often show extraordinary fortitude while rebuilding their homes and livelihoods.","vi":"Các cộng đồng chịu ảnh hưởng bởi thảm họa thiên nhiên thường thể hiện sự kiên cường phi thường trong quá trình tái thiết nhà cửa và ổn định sinh kế.","audioKind":"ex2"}],"collocations":[{"en":"show fortitude","vi":"thể hiện sự kiên cường"},{"en":"mental fortitude","vi":"sự vững vàng trong tâm lý"},{"en":"with remarkable fortitude","vi":"với nghị lực phi thường"}],"wordFamily":[],"synonyms":["resilience","courage"],"antonyms":[],"tipVi":"Từ thuộc văn phong trang trọng, là danh từ không đếm được, nhấn mạnh sự chịu đựng trong nghịch cảnh hoặc nỗi đau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_8_1', 'en-c2-8', 'Cách dùng “reverence” (n.) — sự tôn kính; lòng kính trọng sâu sắc', 'reverence for  ·  deep reverence  ·  treat with reverence', 'Thường là danh từ không đếm được; đi với giới từ for khi thể hiện sự kính trọng đối với ai hoặc cái gì (reverence for).', 'Họ từ (Word Family): revere (v.), reverent (adj.), reverently (adv.) | Đồng nghĩa: respect, veneration · Trái nghĩa: disrespect', '[{"hanzi":"She handled her grandmother''s old violin with quiet reverence.","pinyin":"","meaning":"Cô ấy nâng niu cây đàn vĩ cầm cũ của bà mình với một niềm tôn kính lặng lẽ."},{"hanzi":"Reverence for traditional craftsmanship can encourage communities to preserve skills that might otherwise disappear.","pinyin":"","meaning":"Lòng tôn kính đối với nghề thủ công truyền thống có thể khuyến khích các cộng đồng gìn giữ những kỹ năng có nguy cơ bị mai một."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_8_2', 'en-c2-8', 'Cách dùng “fortitude” (n.) — sự kiên cường; sự gan góc (trong nghịch cảnh)', 'show fortitude  ·  mental fortitude  ·  with remarkable fortitude', 'Từ thuộc văn phong trang trọng, là danh từ không đếm được, nhấn mạnh sự chịu đựng trong nghịch cảnh hoặc nỗi đau.', 'Đồng nghĩa: resilience, courage', '[{"hanzi":"She faced months of painful treatment with remarkable fortitude.","pinyin":"","meaning":"Cô ấy đã trải qua nhiều tháng điều trị đau đớn với sự kiên cường đáng nể."},{"hanzi":"Communities affected by natural disasters often show extraordinary fortitude while rebuilding their homes and livelihoods.","pinyin":"","meaning":"Các cộng đồng chịu ảnh hưởng bởi thảm họa thiên nhiên thường thể hiện sự kiên cường phi thường trong quá trình tái thiết nhà cửa và ổn định sinh kế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_8_3', 'en-c2-8', 'Cách dùng “vehement” (adj.) — mãnh liệt; quyết liệt', 'vehement opposition  ·  vehement denial  ·  vehement criticism', 'Thường dùng để mô tả mức độ mãnh liệt của sự phản đối, phủ nhận hoặc chỉ trích, mang sắc thái trang trọng.', 'Họ từ (Word Family): vehemently (adv.), vehemence (n.) | Đồng nghĩa: fierce, forceful, passionate · Trái nghĩa: mild', '[{"hanzi":"Her vehement refusal surprised everyone at the table.","pinyin":"","meaning":"Sự từ chối quyết liệt của cô ấy khiến mọi người quanh bàn ngạc nhiên."},{"hanzi":"The proposed closure of the community library met with vehement opposition from residents and local educators.","pinyin":"","meaning":"Việc đề xuất đóng cửa thư viện cộng đồng đã vấp phải sự phản đối dữ dội từ cư dân và các nhà giáo dục địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_8_4', 'en-c2-8', 'Cách dùng “haughty” (adj.) — kiêu ngạo; kiêu kỳ; trịch thượng', 'haughty expression  ·  haughty attitude  ·  haughty tone', 'Mang sắc thái chê bai, nhấn mạnh việc tự cho mình giỏi giang hơn người khác, không đồng nghĩa với tự tin.', 'Họ từ (Word Family): haughtily (adv.), haughtiness (n.) | Đồng nghĩa: arrogant, disdainful, supercilious · Trái nghĩa: humble, modest', '[{"hanzi":"The customer gave the waiter a haughty look.","pinyin":"","meaning":"Vị khách hàng liếc nhìn người phục vụ với vẻ kiêu ngạo."},{"hanzi":"A haughty attitude among senior managers can discourage employees from sharing ideas and reporting problems openly.","pinyin":"","meaning":"Thái độ trịch thượng của các nhà quản lý cấp cao có thể khiến nhân viên nản lòng, không dám cởi mở chia sẻ ý tưởng và báo cáo vấn đề."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_8_1', 'en-c2-8', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_1', 'ten_c2_8_1', 'vex', 'The constant dripping from the tap began to vex him.', 'The constant dripping from the tap began to vex him.', '/veks/', 'Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_2', 'ten_c2_8_1', 'madden', 'The constant buzzing of that broken fan maddens me.', 'The constant buzzing of that broken fan maddens me.', '/ˈmædən/', 'Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_3', 'ten_c2_8_1', 'loth', 'I was loth to leave the warm kitchen.', 'I was loth to leave the warm kitchen.', '/loʊθ/', 'Tôi không hề muốn rời khỏi căn bếp ấm áp chút nào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_4', 'ten_c2_8_1', 'magnanimous', 'She was magnanimous and congratulated her rival warmly.', 'She was magnanimous and congratulated her rival warmly.', '/mæɡˈnænɪməs/', 'Cô ấy rất hào hiệp và nhiệt tình chúc mừng đối thủ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_5', 'ten_c2_8_1', 'tantalize', 'The smell of fresh bread tantalized us outside the bakery.', 'The smell of fresh bread tantalized us outside the bakery.', '/ˈtæntəlaɪz/', 'Mùi thơm của bánh mì mới nướng ở ngoài tiệm bánh cứ trêu ngươi chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_6', 'ten_c2_8_1', 'exhilarate', 'The fast boat ride exhilarated everyone on board.', 'The fast boat ride exhilarated everyone on board.', '/ɪɡˈzɪləreɪt/', 'Chuyến đi thuyền tốc độ cao khiến mọi người trên tàu đều phấn chấn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_7', 'ten_c2_8_1', 'vehement', 'Her vehement refusal surprised everyone at the table.', 'Her vehement refusal surprised everyone at the table.', '/ˈviː.ə.mənt/', 'Sự từ chối quyết liệt của cô ấy khiến mọi người quanh bàn ngạc nhiên.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_1_8', 'ten_c2_8_1', 'loath', 'I was loath to leave the warm kitchen.', 'I was loath to leave the warm kitchen.', '/loʊθ/', 'Tôi không nỡ rời khỏi căn bếp ấm áp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_8_1_1', 'en-c2-8', 'ten_c2_8_1', 'listening', 'listening', 'The constant dripping from the tap began to vex him.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bọn trẻ chăm chú ngắm nhìn những chú cá heo nhảy múa với sự thích thú tột độ.","Nét mặt bình tĩnh của cô ấy đã trấn an lũ trẻ trong suốt cơn bão.","Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.","Một mùi hương ghê tởm bốc lên từ món ăn bị bỏ quên."]'::jsonb, 2, 'The constant dripping from the tap began to vex him. → Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_8_1_2', 'en-c2-8', 'ten_c2_8_1', 'listening', 'listening', 'The constant buzzing of that broken fan maddens me.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đã trải qua nhiều tháng điều trị đau đớn với sự kiên cường đáng nể.","Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên.","Cậu ấy nhún vai một cách hậm hực và nhìn chằm chằm xuống sàn nhà.","Tôi không nỡ rời khỏi căn bếp ấm áp."]'::jsonb, 1, 'The constant buzzing of that broken fan maddens me. → Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_8_1_3', 'en-c2-8', 'ten_c2_8_1', 'listening', 'listening', 'I was loth to leave the warm kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mùi thơm của bánh mì mới nướng ở ngoài tiệm bánh cứ trêu ngươi chúng tôi.","Lời trêu chọc của anh ấy đã kích động tôi tham gia cuộc đua.","Cô ấy đã trải qua nhiều tháng điều trị đau đớn với sự kiên cường đáng nể.","Tôi không hề muốn rời khỏi căn bếp ấm áp chút nào."]'::jsonb, 3, 'I was loth to leave the warm kitchen. → Tôi không hề muốn rời khỏi căn bếp ấm áp chút nào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_8_2', 'en-c2-8', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_2_1', 'ten_c2_8_2', 'vex', 'Disagreements over how to fund public transport continue to vex policymakers in many growing cities.', 'Disagreements over how to fund public transport continue to vex policymakers in many growing cities.', '/veks/', 'Những bất đồng về cách tài trợ cho giao thông công cộng tiếp tục làm đau đầu các nhà hoạch định chính sách ở nhiều đô thị đang phát triển.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_2_2', 'ten_c2_8_2', 'madden', 'Repeated delays and unclear explanations can madden commuters who depend on reliable public transport.', 'Repeated delays and unclear explanations can madden commuters who depend on reliable public transport.', '/ˈmædən/', 'Việc lặp lại các sự cố chậm trễ và những lời giải thích mơ hồ có thể làm cho những người đi làm phụ thuộc vào phương tiện giao thông công cộng đáng tin cậy cảm thấy vô cùng bực bội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_2_3', 'ten_c2_8_2', 'loth', 'Some residents are loth to support redevelopment because they fear losing their neighbourhood''s distinctive character.', 'Some residents are loth to support redevelopment because they fear losing their neighbourhood''s distinctive character.', '/loʊθ/', 'Một số cư dân không muốn ủng hộ việc tái phát triển vì họ sợ mất đi nét đặc trưng riêng biệt của khu ố phố của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_2_4', 'ten_c2_8_2', 'magnanimous', 'A magnanimous response to criticism can help leaders build trust and encourage constructive public debate.', 'A magnanimous response to criticism can help leaders build trust and encourage constructive public debate.', '/mæɡˈnænɪməs/', 'Một phản ứng cao thượng trước những lời chỉ trích có thể giúp các nhà lãnh đạo xây dựng lòng tin và khuyến khích các cuộc tranh luận công khai mang tính xây dựng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_2_5', 'ten_c2_8_2', 'tantalize', 'Early discoveries tantalize researchers with the possibility of finding affordable treatments for currently incurable diseases.', 'Early discoveries tantalize researchers with the possibility of finding affordable treatments for currently incurable diseases.', '/ˈtæntəlaɪz/', 'Những phát hiện ban đầu thắp lên hy vọng cho các nhà nghiên cứu về khả năng tìm ra phương pháp điều trị phải chăng cho các căn bệnh hiện chưa có thuốc chữa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_8_2_6', 'ten_c2_8_2', 'exhilarate', 'Outdoor adventures can exhilarate participants while helping them develop confidence and a stronger connection with nature.', 'Outdoor adventures can exhilarate participants while helping them develop confidence and a stronger connection with nature.', '/ɪɡˈzɪləreɪt/', 'Các hoạt động phiêu lưu ngoài trời có thể làm cho người tham gia tràn đầy hứng khởi đồng thời giúp họ phát triển sự tự tin và gắn kết sâu sắc hơn với thiên nhiên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_8_2_1', 'en-c2-8', 'ten_c2_8_2', 'listening', 'listening', 'Disagreements over how to fund public transport continue to vex policymakers in many growing cities.', NULL, 'Trong câu vừa nghe, từ “vex” mang nghĩa nào sau đây?', '["thủy thủ; hải thủ","để phòng khi; e rằng; vì sợ rằng","làm phiền; làm bực mình; làm lo lắng","về dáng vẻ: vụng về; lóng ngóng; không uyển chuyển"]'::jsonb, 2, '“vex” (/veks/): làm phiền; làm bực mình; làm lo lắng. Câu đầy đủ: Disagreements over how to fund public transport continue to vex policymakers in many growing cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_8_2_2', 'en-c2-8', 'ten_c2_8_2', 'listening', 'listening', 'Repeated delays and unclear explanations can madden commuters who depend on reliable public transport.', NULL, 'Trong câu vừa nghe, từ “madden” mang nghĩa nào sau đây?', '["thực tế; thực trạng","làm cho ai đó cực kỳ tức giận hoặc bực bội","không khoan nhượng; không chịu linh động; không hợp tác","có thể chấm dứt; có thể hủy bỏ"]'::jsonb, 1, '“madden” (/ˈmædən/): làm cho ai đó cực kỳ tức giận hoặc bực bội. Câu đầy đủ: Repeated delays and unclear explanations can madden commuters who depend on reliable public transport.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
