INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_1', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'vex', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phương Tây; thế giới phương Tây","suy đoán; phỏng đoán","làm phiền; làm bực mình; làm lo lắng","không khoan nhượng; không chịu linh động; không hợp tác"]'::jsonb, 2, 'vex (/veks/) → làm phiền; làm bực mình; làm lo lắng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_2', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'The constant buzzing of that broken fan maddens me.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuối cùng anh ấy đã hối hận vì đã nói dối người bạn thân nhất của mình.","Tính cách vui vẻ của cô ấy khiến ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn.","Một mùi hương ghê tởm bốc lên từ món ăn bị bỏ quên.","Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên."]'::jsonb, 3, 'The constant buzzing of that broken fan maddens me. → Tiếng vo ve liên tục của chiếc quạt bị hỏng đó làm tôi phát điên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_3', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'loth', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khinh miệt; coi thường; tỏ thái độ khinh bỉ","glycerin; glixerin","không thích, không muốn hoặc miễn cưỡng làm điều gì đó","trái nghĩa; có nghĩa đối lập"]'::jsonb, 2, 'loth (/loʊθ/) → không thích, không muốn hoặc miễn cưỡng làm điều gì đó', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_4', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'She was magnanimous and congratulated her rival warmly.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một tình nguyện viên nhiệt huyết đã dọn sạch toàn bộ bãi biển trước giờ ăn trưa.","Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.","Chuyến đi thuyền tốc độ cao khiến mọi người trên tàu đều phấn chấn.","Cô ấy rất hào hiệp và nhiệt tình chúc mừng đối thủ của mình."]'::jsonb, 3, 'She was magnanimous and congratulated her rival warmly. → Cô ấy rất hào hiệp và nhiệt tình chúc mừng đối thủ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_5', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'tantalize', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bệnh bại liệt; bệnh viêm tủy xám","trêu ngươi; khơi gợi khao khát nhưng khó với tới","tính dễ bán; khả năng tiêu thụ trên thị trường","dẻo dai; dễ uốn; dễ gập"]'::jsonb, 1, 'tantalize (/ˈtæntəlaɪz/) → trêu ngươi; khơi gợi khao khát nhưng khó với tới', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_6', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'The fast boat ride exhilarated everyone on board.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tính cách vui vẻ của cô ấy khiến ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn.","Chuyến đi thuyền tốc độ cao khiến mọi người trên tàu đều phấn chấn.","Cô ấy nâng niu cây đàn vĩ cầm cũ của bà mình với một niềm tôn kính lặng lẽ.","Bọn trẻ vừa cười vang vừa ruổi bắt những chùm bong bóng ở bên ngoài."]'::jsonb, 1, 'The fast boat ride exhilarated everyone on board. → Chuyến đi thuyền tốc độ cao khiến mọi người trên tàu đều phấn chấn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_7', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'vehement', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mãnh liệt; quyết liệt","cây khuynh diệp; cây bạch đàn","chi (đơn vị phân loại sinh học bao gồm các loài có họ hàng gần)","chuỗi con; dãy con"]'::jsonb, 0, 'vehement (/ˈviː.ə.mənt/) → mãnh liệt; quyết liệt', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_8', 'en-c2-8', NULL, 'comprehensive_test', 'listening', 'I was loath to leave the warm kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi không hề muốn rời khỏi căn bếp ấm áp chút nào.","Tôi không nỡ rời khỏi căn bếp ấm áp.","Tiếng giọt nước rò rỉ từ vòi nước không ngừng đã bắt đầu làm anh ấy thấy bực mình.","Một tiếng kêu thê thiết phát ra từ chú mèo con ở ngoài cửa nhà chúng tôi."]'::jsonb, 1, 'I was loath to leave the warm kitchen. → Tôi không nỡ rời khỏi căn bếp ấm áp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_9', 'en-c2-8', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To excite desire for something that remains out of reach.”?', '["goad","plaintive","tantalize","rapture"]'::jsonb, 2, 'tantalize (/ˈtæntəlaɪz/) → trêu ngươi; khơi gợi khao khát nhưng khó với tới', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_10', 'en-c2-8', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make someone feel excited, energetic, and very happy”?', '["gaily","rapture","plaintive","exhilarate"]'::jsonb, 3, 'exhilarate (/ɪɡˈzɪləreɪt/) → làm phấn chấn; làm hưng phấn; làm vui sướng', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_11', 'en-c2-8', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Expressing very strong feelings, especially anger or opposition”?', '["plaintive","vehement","haughty","fortitude"]'::jsonb, 1, 'vehement (/ˈviː.ə.mənt/) → mãnh liệt; quyết liệt', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_12', 'en-c2-8', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Unwilling to do something.”?', '["madden","countenance","disposition","loath"]'::jsonb, 3, 'loath (/loʊθ/) → không thích; miễn cưỡng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_13', 'en-c2-8', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Causing strong dislike or a feeling of sickness.”?', '["repent","vex","disgustful","goad"]'::jsonb, 2, 'disgustful (/dɪsˈɡʌstfəl/) → ghê tởm; đáng ghét', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
