INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_18', 'en-c2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Disagreements over how to fund public transport continue to vex policymakers in many growing cities.', 'Dựa vào câu trên, từ “vex” có nghĩa phù hợp nhất là gì?', '["cá bลม biển lớn; thịt cá bơn","cảm giác khó chịu, mệt mỏi chung không rõ nguyên nhân","làm phiền; làm bực mình; làm lo lắng","glycerin; glixerin"]'::jsonb, 2, 'vex: làm phiền; làm bực mình; làm lo lắng. Dịch cả câu: Những bất đồng về cách tài trợ cho giao thông công cộng tiếp tục làm đau đầu các nhà hoạch định chính sách ở nhiều đô thị đang phát triển.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_19', 'en-c2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Repeated delays and unclear explanations can madden commuters who depend on reliable public transport.', 'Dựa vào câu trên, từ “madden” có nghĩa phù hợp nhất là gì?', '["ở mức độ trung bình; bình thường","làm cho ai đó cực kỳ tức giận hoặc bực bội","cảm giác khó chịu, mệt mỏi chung không rõ nguyên nhân","cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết"]'::jsonb, 1, 'madden: làm cho ai đó cực kỳ tức giận hoặc bực bội. Dịch cả câu: Việc lặp lại các sự cố chậm trễ và những lời giải thích mơ hồ có thể làm cho những người đi làm phụ thuộc vào phương tiện giao thông công cộng đáng tin cậy cảm thấy vô cùng bực bội.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_20', 'en-c2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Some residents are loth to support redevelopment because they fear losing their neighbourhood''s distinctive character.', 'Dựa vào câu trên, từ “loth” có nghĩa phù hợp nhất là gì?', '["sự phẫn nộ; sự náo động; sự xôn xao","nhỏ nhắn và tinh xảo; xinh xắn","benzen","không thích, không muốn hoặc miễn cưỡng làm điều gì đó"]'::jsonb, 3, 'loth: không thích, không muốn hoặc miễn cưỡng làm điều gì đó. Dịch cả câu: Một số cư dân không muốn ủng hộ việc tái phát triển vì họ sợ mất đi nét đặc trưng riêng biệt của khu ố phố của mình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_21', 'en-c2-8', NULL, 'comprehensive_test', 'reading', NULL, 'A magnanimous response to criticism can help leaders build trust and encourage constructive public debate.', 'Dựa vào câu trên, từ “magnanimous” có nghĩa phù hợp nhất là gì?', '["thuốc tiên; giải pháp vạn năng","hào phóng và bao dung, đặc biệt là đối với đối thủ hoặc người yếu thế hơn","ở mức độ trung bình; bình thường","phù sa; do phù sa bồi đắp"]'::jsonb, 1, 'magnanimous: hào phóng và bao dung, đặc biệt là đối với đối thủ hoặc người yếu thế hơn. Dịch cả câu: Một phản ứng cao thượng trước những lời chỉ trích có thể giúp các nhà lãnh đạo xây dựng lòng tin và khuyến khích các cuộc tranh luận công khai mang tính xây dựng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_22', 'en-c2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ân hận; hối lỗi; ăn năn”', '["repent","componential","ulcer","virile"]'::jsonb, 0, 'ân hận; hối lỗi; ăn năn → repent (/rɪˈpent/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_23', 'en-c2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vui vẻ; hoạt bát”', '["disburse","subliminal","gaily","mincer"]'::jsonb, 2, 'vui vẻ; hoạt bát → gaily (/ˈɡeɪli/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_8_24', 'en-c2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự kiên cường; sự gan góc (trong nghịch cảnh)”', '["sneer","mumps","lexicographer","fortitude"]'::jsonb, 3, 'sự kiên cường; sự gan góc (trong nghịch cảnh) → fortitude (/ˈfɔːrtətuːd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-9', 'en', 'Bài 9: Công việc & Nghề nghiệp - CEFR C2', 'CEFR C2', 'C2 · Công việc', '12 từ vựng Tiếng Anh CEFR C2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6009, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depute', 'en-c2-9', 'depute', '/dɪˈpjuːt/', 'C2', 'ủy quyền; ủy nhiệm; cử', 'v.', 'deputation (n.), deputy (n.)', 'Đồng nghĩa: delegate, appoint', 'Từ trang trọng, thường dùng cấu trúc depute sb to do sth.', 'The manager deputed her assistant to attend the meeting.', NULL, 'Giám đốc đã ủy quyền cho trợ lý của mình đi dự họp.', '{"wordId":"depute","ukIpa":"/dɪˈpjuːt/","usIpa":"/dɪˈpjuːt/","cefr":"C2","topic":"work","senses":[{"pos":"v.","en":"to appoint someone to act or perform a task for you","vi":"ủy quyền; ủy nhiệm; cử"}],"examples":[{"en":"The manager deputed her assistant to attend the meeting.","vi":"Giám đốc đã ủy quyền cho trợ lý của mình đi dự họp.","audioKind":"ex"},{"en":"Local authorities may depute trained officers to inspect buildings and ensure compliance with safety regulations.","vi":"Các cơ quan chức năng địa phương có thể cử các sĩ quan đã qua đào tạo đi kiểm tra các tòa nhà và đảm bảo tuân thủ các quy định an toàn.","audioKind":"ex2"}],"collocations":[{"en":"depute someone to do something","vi":"ủy quyền cho ai làm gì"},{"en":"depute a representative","vi":"cử người đại diện"}],"wordFamily":["deputation (n.)","deputy (n.)"],"synonyms":["delegate","appoint"],"antonyms":[],"tipVi":"Từ trang trọng, thường dùng cấu trúc depute sb to do sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pilferage', 'en-c2-9', 'pilferage', '/ˈpɪlfərɪdʒ/', 'C2', 'sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt', 'n.', 'pilfer (v.), pilferer (n.)', 'Đồng nghĩa: theft', 'Pilferage là danh từ không đếm được, không phải động từ; động từ tương ứng là pilfer.', 'The shop now locks its stockroom to prevent pilferage.', NULL, 'Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.', '{"wordId":"pilferage","ukIpa":"/ˈpɪlfərɪdʒ/","usIpa":"/ˈpɪlfərɪdʒ/","cefr":"C2","topic":"work","senses":[{"pos":"n.","en":"The theft of small amounts or items, especially from workplaces.","vi":"sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt"}],"examples":[{"en":"The shop now locks its stockroom to prevent pilferage.","vi":"Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.","audioKind":"ex"},{"en":"Retailers can reduce losses from pilferage by improving stock monitoring and providing secure storage for valuable goods.","vi":"Các nhà bán lẻ có thể giảm thiểu thiệt hại từ nạn trộm cắp vặt bằng cách cải thiện việc giám sát hàng tồn kho và cung cấp nơi lưu trữ an toàn cho hàng hóa có giá trị.","audioKind":"ex2"}],"collocations":[{"en":"prevent pilferage","vi":"ngăn chặn nạn trộm cắp vặt"},{"en":"losses from pilferage","vi":"tổn thất từ nạn trộm cắp vặt"},{"en":"employee pilferage","vi":"nhân viên ăn cắp vặt"}],"wordFamily":["pilfer (v.)","pilferer (n.)"],"synonyms":["theft"],"antonyms":[],"tipVi":"Pilferage là danh từ không đếm được, không phải động từ; động từ tương ứng là pilfer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terminable', 'en-c2-9', 'terminable', '/ˈtɝːmɪnəbəl/', 'C2', 'có thể chấm dứt; có thể hủy bỏ', 'adj.', 'terminate (v.), termination (n.)', 'Trái nghĩa: interminable', 'Thuật ngữ pháp lý trang trọng, thường dùng để mô tả hợp đồng; không đồng nghĩa với terminal.', 'My rental agreement is terminable with one month''s notice.', NULL, 'Hợp đồng thuê nhà của tôi có thể chấm dứt nếu báo trước một tháng.', '{"wordId":"terminable","ukIpa":"/ˈtɜːmɪnəbəl/","usIpa":"/ˈtɝːmɪnəbəl/","cefr":"C2","topic":"work","senses":[{"pos":"adj.","en":"Able to be ended, especially under agreed conditions","vi":"có thể chấm dứt; có thể hủy bỏ"}],"examples":[{"en":"My rental agreement is terminable with one month''s notice.","vi":"Hợp đồng thuê nhà của tôi có thể chấm dứt nếu báo trước một tháng.","audioKind":"ex"},{"en":"Employment contracts should be terminable by either party, provided that reasonable notice is given.","vi":"Hợp đồng lao động phải cho phép bất kỳ bên nào cũng có thể chấm dứt, miễn là đưa ra thông báo hợp lý trước.","audioKind":"ex2"}],"collocations":[{"en":"terminable contract","vi":"hợp đồng có thể chấm dứt"},{"en":"terminable on notice","vi":"có thể chấm dứt sau khi thông báo"},{"en":"terminable by either party","vi":"bên nào cũng có thể chấm dứt"}],"wordFamily":["terminate (v.)","termination (n.)"],"synonyms":[],"antonyms":["interminable"],"tipVi":"Thuật ngữ pháp lý trang trọng, thường dùng để mô tả hợp đồng; không đồng nghĩa với terminal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hotelling', 'en-c2-9', 'hotelling', '/hoʊˈtelɪŋ/', 'C2', 'hệ thống nhân viên đặt trước không gian làm việc chung thay vì dùng bàn làm việc cố định', 'n.', 'hotel (n.)', NULL, 'Thường chỉ việc đặt trước không gian làm việc chung; trong ngành khách sạn thường dùng hotel industry.', 'With hotelling, I book a desk before coming in.', NULL, 'Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng.', '{"wordId":"hotelling","ukIpa":"/həʊˈtelɪŋ/","usIpa":"/hoʊˈtelɪŋ/","cefr":"C2","topic":"work","senses":[{"pos":"n.","en":"a system where employees reserve shared workspaces instead of permanent desks","vi":"hệ thống nhân viên đặt trước không gian làm việc chung thay vì dùng bàn làm việc cố định"}],"examples":[{"en":"With hotelling, I book a desk before coming in.","vi":"Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng.","audioKind":"ex"},{"en":"Hotelling can reduce office costs, although employees may miss having a permanent space for their belongings.","vi":"Hệ thống đặt chỗ làm việc chung có thể giúp giảm chi phí văn phòng, mặc dù nhân viên có thể cảm thấy tiếc vì không có một không gian cố định để cất đồ đạc cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"office hotelling","vi":"chế độ đặt bàn làm việc văn phòng"},{"en":"hotelling system","vi":"hệ thống đặt chỗ làm việc chung"},{"en":"desk hotelling","vi":"đặt chỗ ngồi làm việc linh hoạt"}],"wordFamily":["hotel (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ việc đặt trước không gian làm việc chung; trong ngành khách sạn thường dùng hotel industry.","noteVi":"Từ thực tế, còn được viết là hotelling; nghĩa phổ biến hiện nay là hệ thống đặt chỗ làm việc linh hoạt chứ không phải ngành khách sạn.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scrupulous', 'en-c2-9', 'scrupulous', '/ˈskruːpjələs/', 'C2', 'tỉ mỉ; cẩn trọng; chu đáo; liêm khiết; chính trực; cẩn trọng về đạo đức', 'adj.', 'scrupulously (adv.), scrupulousness (n.), unscrupulous (adj.)', 'Đồng nghĩa: meticulous, conscientious · Trái nghĩa: careless, unscrupulous', 'Từ này vừa có thể dùng để chỉ sự cẩn thận, chính xác trong công việc, vừa chỉ sự ngay thẳng, giữ gìn đạo đức.', 'She gave every cup a scrupulous wash before serving tea.', NULL, 'Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên.', '{"wordId":"scrupulous","ukIpa":"/ˈskruːpjələs/","usIpa":"/ˈskruːpjələs/","cefr":"C2","topic":"work","senses":[{"pos":"adj.","en":"extremely careful to do things correctly and thoroughly","vi":"tỉ mỉ; cẩn trọng; chu đáo"},{"pos":"adj.","en":"careful to act honestly and avoid doing anything wrong","vi":"liêm khiết; chính trực; cẩn trọng về đạo đức"}],"examples":[{"en":"She gave every cup a scrupulous wash before serving tea.","vi":"Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên.","audioKind":"ex"},{"en":"Scrupulous attention to research methods is essential for producing reliable evidence in public health studies.","vi":"Việc tuân thủ một cách nghiêm ngặt các phương pháp nghiên cứu là điều cốt lõi để tạo ra các bằng chứng đáng tin cậy trong các nghiên cứu y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"scrupulous attention to detail","vi":"sự chú ý tỉ mỉ đến từng chi tiết"},{"en":"scrupulous care","vi":"sự chăm sóc vô cùng chu đáo"},{"en":"scrupulous honesty","vi":"sự trung thực tuyệt đối"}],"wordFamily":["scrupulously (adv.)","scrupulousness (n.)","unscrupulous (adj.)"],"synonyms":["meticulous","conscientious"],"antonyms":["careless","unscrupulous"],"tipVi":"Từ này vừa có thể dùng để chỉ sự cẩn thận, chính xác trong công việc, vừa chỉ sự ngay thẳng, giữ gìn đạo đức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recompense', 'en-c2-9', 'recompense', '/ˈrekəmpens/', 'C2', 'sự đền bù; thù lao; đền bù; trả công', 'n.', NULL, 'Đồng nghĩa: compensation, repayment', 'Từ mang tính trang trọng; động từ thường dùng cấu trúc "recompense sb for sth".', 'The shop offered a refund as recompense for the inconvenience.', NULL, 'Cửa hàng đã đề xuất hoàn tiền như một sự đền bù cho sự bất tiện gây ra.', '{"wordId":"recompense","ukIpa":"/ˈrekəmpens/","usIpa":"/ˈrekəmpens/","cefr":"C2","topic":"work","senses":[{"pos":"n.","en":"Payment or a reward for work, loss, or inconvenience.","vi":"sự đền bù; thù lao"},{"pos":"v.","en":"To pay or reward someone for work, loss, or inconvenience.","vi":"đền bù; trả công"}],"examples":[{"en":"The shop offered a refund as recompense for the inconvenience.","vi":"Cửa hàng đã đề xuất hoàn tiền như một sự đền bù cho sự bất tiện gây ra.","audioKind":"ex"},{"en":"Employees should receive fair recompense for additional duties rather than being expected to work extra hours without payment.","vi":"Nhân viên cần nhận được thù lao công bằng cho các nhiệm vụ bổ sung thay vì bị kỳ vọng phải làm thêm giờ mà không được trả lương.","audioKind":"ex2"}],"collocations":[{"en":"fair recompense","vi":"thù lao công bằng"},{"en":"recompense for","vi":"đền bù cho"},{"en":"recompense someone for something","vi":"bồi thường cho ai vì điều gì"}],"wordFamily":[],"synonyms":["compensation","repayment"],"antonyms":[],"tipVi":"Từ mang tính trang trọng; động từ thường dùng cấu trúc \"recompense sb for sth\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rectification', 'en-c2-9', 'rectification', '/ˌrektɪfɪˈkeɪʃn/', 'C2', 'sự sửa chữa; sự hiệu chỉnh; sự chỉnh lưu', 'n.', 'rectify (v.), rectifier (n.)', 'Đồng nghĩa: correction', 'Là danh từ trang trọng; trong văn nói thường dùng correction để chỉ việc sửa chữa.', 'The builder promised prompt rectification of the faulty wiring.', NULL, 'Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi.', '{"wordId":"rectification","ukIpa":"/ˌrektɪfɪˈkeɪʃn/","usIpa":"/ˌrektɪfɪˈkeɪʃn/","cefr":"C2","topic":"work","senses":[{"pos":"n.","en":"The process of correcting an error or putting something right","vi":"sự sửa chữa; sự hiệu chỉnh"},{"pos":"n.","en":"The process of converting alternating electric current into direct current","vi":"sự chỉnh lưu"}],"examples":[{"en":"The builder promised prompt rectification of the faulty wiring.","vi":"Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi.","audioKind":"ex"},{"en":"Independent inspections allow the early identification and rectification of structural defects before buildings are opened to the public.","vi":"Các cuộc kiểm tra độc lập giúp phát hiện sớm và sửa chữa các khiếm khuyết về cấu trúc trước khi các tòa nhà mở cửa đón công chúng.","audioKind":"ex2"}],"collocations":[{"en":"rectification of errors","vi":"sự sửa chữa lỗi lầm"},{"en":"rectification work","vi":"công tác chấn chỉnh"},{"en":"half-wave rectification","vi":"sự chỉnh lưu nửa sóng"}],"wordFamily":["rectify (v.)","rectifier (n.)"],"synonyms":["correction"],"antonyms":[],"tipVi":"Là danh từ trang trọng; trong văn nói thường dùng correction để chỉ việc sửa chữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superintend', 'en-c2-9', 'superintend', '/ˌsuːpərɪnˈtend/', 'C2', 'giám sát; quản lý', 'v.', 'superintendent (n.), superintendence (n.)', 'Đồng nghĩa: supervise, oversee, manage', 'Là ngoại động từ trang trọng, đi trực tiếp với công việc hoặc hoạt động; thông thường dùng supervise nhiều hơn trong đời sống.', 'An experienced gardener superintended the planting of our trees.', NULL, 'Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi.', '{"wordId":"superintend","ukIpa":"/ˌsuːpərɪnˈtend/","usIpa":"/ˌsuːpərɪnˈtend/","cefr":"C2","topic":"work","senses":[{"pos":"v.","en":"To oversee and take responsibility for work or an activity.","vi":"giám sát; quản lý"}],"examples":[{"en":"An experienced gardener superintended the planting of our trees.","vi":"Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi.","audioKind":"ex"},{"en":"Qualified engineers should superintend major construction projects to ensure that safety standards are consistently maintained.","vi":"Các kỹ sư có trình độ chuyên môn nên giám sát các dự án xây dựng lớn để đảm bảo các tiêu chuẩn an toàn luôn được duy trì.","audioKind":"ex2"}],"collocations":[{"en":"superintend construction","vi":"giám sát thi công"},{"en":"superintend the work","vi":"chỉ đạo công việc"},{"en":"superintend operations","vi":"quản lý vận hành"}],"wordFamily":["superintendent (n.)","superintendence (n.)"],"synonyms":["supervise","oversee","manage"],"antonyms":[],"tipVi":"Là ngoại động từ trang trọng, đi trực tiếp với công việc hoặc hoạt động; thông thường dùng supervise nhiều hơn trong đời sống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apprise', 'en-c2-9', 'apprise', '/əˈpraɪz/', 'C2', 'thông báo, báo cho biết chính thức', 'v.', NULL, 'Đồng nghĩa: inform, notify', 'Là từ trang trọng; dùng cấu trúc apprise sb of sth, tránh nhầm với từ appraise.', 'Please apprise me of any changes before Friday.', NULL, 'Xin vui lòng thông báo cho tôi về bất kỳ thay đổi nào trước thứ Sáu.', '{"wordId":"apprise","ukIpa":"/əˈpraɪz/","usIpa":"/əˈpraɪz/","cefr":"C2","topic":"work","senses":[{"pos":"v.","en":"to formally inform someone about something","vi":"thông báo, báo cho biết chính thức"}],"examples":[{"en":"Please apprise me of any changes before Friday.","vi":"Xin vui lòng thông báo cho tôi về bất kỳ thay đổi nào trước thứ Sáu.","audioKind":"ex"},{"en":"Schools should apprise parents of significant policy changes before introducing new rules that affect their children.","vi":"Nhà trường nên thông báo trước cho các bậc phụ huynh về những thay đổi chính sách quan trọng trước khi áp dụng các quy định mới ảnh hưởng đến con em họ.","audioKind":"ex2"}],"collocations":[{"en":"apprise someone of something","vi":"thông báo cho ai về điều gì"},{"en":"keep someone apprised","vi":"giữ liên lạc cập nhật thông tin cho ai"}],"wordFamily":[],"synonyms":["inform","notify"],"antonyms":[],"tipVi":"Là từ trang trọng; dùng cấu trúc apprise sb of sth, tránh nhầm với từ appraise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herculean', 'en-c2-9', 'herculean', '/ˌhɝːkjəˈliːən/', 'C2', 'cần sức mạnh lớn; gian khổ', 'adj.', NULL, 'Đồng nghĩa: arduous, formidable · Trái nghĩa: effortless', 'Bắt nguồn từ vị thần sức mạnh Hercules; cũng hay viết là Herculean.', 'Moving that enormous sofa upstairs was a herculean task.', NULL, 'Việc khuân chiếc ghế sofa khổng lồ đó lên lầu thực sự là một nhiệm vụ gian khổ.', '{"wordId":"herculean","ukIpa":"/ˌhɜːkjəˈliːən/","usIpa":"/ˌhɝːkjəˈliːən/","cefr":"C2","topic":"work","senses":[{"pos":"adj.","en":"Requiring an exceptionally large amount of strength or effort.","vi":"cần sức mạnh lớn; gian khổ"}],"examples":[{"en":"Moving that enormous sofa upstairs was a herculean task.","vi":"Việc khuân chiếc ghế sofa khổng lồ đó lên lầu thực sự là một nhiệm vụ gian khổ.","audioKind":"ex"},{"en":"Restoring transport networks after widespread flooding requires a herculean effort from engineers, local authorities and volunteers.","vi":"Việc khôi phục mạng lưới giao thông sau trận lụt diện rộng đòi hỏi nỗ lực vô cùng lớn từ các kỹ sư, chính quyền địa phương và tình nguyện viên.","audioKind":"ex2"}],"collocations":[{"en":"a herculean task","vi":"một nhiệm vụ gian khổ"},{"en":"a herculean effort","vi":"một nỗ lực to lớn"}],"wordFamily":[],"synonyms":["arduous","formidable"],"antonyms":["effortless"],"tipVi":"Bắt nguồn từ vị thần sức mạnh Hercules; cũng hay viết là Herculean.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hairdress', 'en-c2-9', 'hairdress', '/ˈherdres/', 'C2', 'cắt tỉa hoặc tạo kiểu tóc', 'v.', 'hairdresser (n.), hairdressing (n.)', NULL, 'Trong đời thường, dùng style hair để nói về việc làm tóc; ngành dịch vụ làm tóc dùng hairdressing.', 'She learned to hairdress by practising on a mannequin.', NULL, 'Cô ấy học tạo kiểu tóc bằng cách thực hành trên ma-nơ-canh.', '{"wordId":"hairdress","ukIpa":"/ˈheədres/","usIpa":"/ˈherdres/","cefr":"C2","topic":"work","senses":[{"pos":"v.","en":"Arrange or style hair.","vi":"cắt tỉa hoặc tạo kiểu tóc"}],"examples":[{"en":"She learned to hairdress by practising on a mannequin.","vi":"Cô ấy học tạo kiểu tóc bằng cách thực hành trên ma-nơ-canh.","audioKind":"ex"},{"en":"People who learn to hairdress professionally may develop practical skills that support employment in local service industries.","vi":"Những người học nghề làm tóc chuyên nghiệp có thể phát triển các kỹ năng thực tế giúp họ tìm việc làm trong ngành dịch vụ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"hairdress professionally","vi":"làm tóc chuyên nghiệp"},{"en":"learn to hairdress","vi":"học nghề làm tóc"}],"wordFamily":["hairdresser (n.)","hairdressing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong đời thường, dùng style hair để nói về việc làm tóc; ngành dịch vụ làm tóc dùng hairdressing.","noteVi":"Động từ ít dùng, không thích hợp làm danh từ thông dụng; \"nghề làm tóc\" thường dùng hairdressing.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meteoric', 'en-c2-9', 'meteoric', '/ˌmiːtiˈɔːrɪk/', 'C2', 'phát triển nhanh chóng và ngoạn mục; vụt sáng; thuộc về sao băng', 'adj.', 'meteor (n.), meteorically (adv.)', 'Đồng nghĩa: rapid, spectacular · Trái nghĩa: gradual', 'Thường bổ nghĩa cho từ rise (sự trỗi dậy), nhấn mạnh tốc độ nhanh chóng chứ không nhất thiết chỉ mang tính ngắn ngủi.', 'Her meteoric rise surprised everyone at the small theatre.', NULL, 'Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.', '{"wordId":"meteoric","ukIpa":"/ˌmiːtiˈɒrɪk/","usIpa":"/ˌmiːtiˈɔːrɪk/","cefr":"C2","topic":"work","senses":[{"pos":"adj.","en":"Developing or becoming successful with remarkable speed","vi":"phát triển nhanh chóng và ngoạn mục; vụt sáng"},{"pos":"adj.","en":"Relating to meteors","vi":"thuộc về sao băng"}],"examples":[{"en":"Her meteoric rise surprised everyone at the small theatre.","vi":"Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.","audioKind":"ex"},{"en":"The meteoric growth of online shopping has transformed consumer habits and increased demand for delivery services.","vi":"Sự bùng nổ vũ bão của mua sắm trực tuyến đã làm thay đổi thói quen tiêu dùng và làm gia tăng nhu cầu đối với các dịch vụ giao hàng.","audioKind":"ex2"}],"collocations":[{"en":"a meteoric rise","vi":"sự trỗi dậy thần tốc"},{"en":"meteoric growth","vi":"sự tăng trưởng vũ bão"},{"en":"meteoric success","vi":"thành công vụt sáng"}],"wordFamily":["meteor (n.)","meteorically (adv.)"],"synonyms":["rapid","spectacular"],"antonyms":["gradual"],"tipVi":"Thường bổ nghĩa cho từ rise (sự trỗi dậy), nhấn mạnh tốc độ nhanh chóng chứ không nhất thiết chỉ mang tính ngắn ngủi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_9_1', 'en-c2-9', 'Cách dùng “superintend” (v.) — giám sát; quản lý', 'superintend construction  ·  superintend the work  ·  superintend operations', 'Là ngoại động từ trang trọng, đi trực tiếp với công việc hoặc hoạt động; thông thường dùng supervise nhiều hơn trong đời sống.', 'Họ từ (Word Family): superintendent (n.), superintendence (n.) | Đồng nghĩa: supervise, oversee, manage', '[{"hanzi":"An experienced gardener superintended the planting of our trees.","pinyin":"","meaning":"Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi."},{"hanzi":"Qualified engineers should superintend major construction projects to ensure that safety standards are consistently maintained.","pinyin":"","meaning":"Các kỹ sư có trình độ chuyên môn nên giám sát các dự án xây dựng lớn để đảm bảo các tiêu chuẩn an toàn luôn được duy trì."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_9_2', 'en-c2-9', 'Cách dùng “meteoric” (adj.) — phát triển nhanh chóng và ngoạn mục; vụt sáng', 'a meteoric rise  ·  meteoric growth  ·  meteoric success', 'Thường bổ nghĩa cho từ rise (sự trỗi dậy), nhấn mạnh tốc độ nhanh chóng chứ không nhất thiết chỉ mang tính ngắn ngủi.', 'Họ từ (Word Family): meteor (n.), meteorically (adv.) | Đồng nghĩa: rapid, spectacular · Trái nghĩa: gradual', '[{"hanzi":"Her meteoric rise surprised everyone at the small theatre.","pinyin":"","meaning":"Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên."},{"hanzi":"The meteoric growth of online shopping has transformed consumer habits and increased demand for delivery services.","pinyin":"","meaning":"Sự bùng nổ vũ bão của mua sắm trực tuyến đã làm thay đổi thói quen tiêu dùng và làm gia tăng nhu cầu đối với các dịch vụ giao hàng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_9_3', 'en-c2-9', 'Cách dùng “scrupulous” (adj.) — tỉ mỉ; cẩn trọng; chu đáo', 'scrupulous attention to detail  ·  scrupulous care  ·  scrupulous honesty', 'Từ này vừa có thể dùng để chỉ sự cẩn thận, chính xác trong công việc, vừa chỉ sự ngay thẳng, giữ gìn đạo đức.', 'Họ từ (Word Family): scrupulously (adv.), scrupulousness (n.), unscrupulous (adj.) | Đồng nghĩa: meticulous, conscientious · Trái nghĩa: careless, unscrupulous', '[{"hanzi":"She gave every cup a scrupulous wash before serving tea.","pinyin":"","meaning":"Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên."},{"hanzi":"Scrupulous attention to research methods is essential for producing reliable evidence in public health studies.","pinyin":"","meaning":"Việc tuân thủ một cách nghiêm ngặt các phương pháp nghiên cứu là điều cốt lõi để tạo ra các bằng chứng đáng tin cậy trong các nghiên cứu y tế công cộng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_9_4', 'en-c2-9', 'Cách dùng “hotelling” (n.) — hệ thống nhân viên đặt trước không gian làm việc chung thay vì dùng bàn làm việc cố định', 'office hotelling  ·  hotelling system  ·  desk hotelling', 'Thường chỉ việc đặt trước không gian làm việc chung; trong ngành khách sạn thường dùng hotel industry.', 'Họ từ (Word Family): hotel (n.)', '[{"hanzi":"With hotelling, I book a desk before coming in.","pinyin":"","meaning":"Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng."},{"hanzi":"Hotelling can reduce office costs, although employees may miss having a permanent space for their belongings.","pinyin":"","meaning":"Hệ thống đặt chỗ làm việc chung có thể giúp giảm chi phí văn phòng, mặc dù nhân viên có thể cảm thấy tiếc vì không có một không gian cố định để cất đồ đạc cá nhân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_9_1', 'en-c2-9', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_1', 'ten_c2_9_1', 'depute', 'The manager deputed her assistant to attend the meeting.', 'The manager deputed her assistant to attend the meeting.', '/dɪˈpjuːt/', 'Giám đốc đã ủy quyền cho trợ lý của mình đi dự họp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_2', 'ten_c2_9_1', 'pilferage', 'The shop now locks its stockroom to prevent pilferage.', 'The shop now locks its stockroom to prevent pilferage.', '/ˈpɪlfərɪdʒ/', 'Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_3', 'ten_c2_9_1', 'terminable', 'My rental agreement is terminable with one month''s notice.', 'My rental agreement is terminable with one month''s notice.', '/ˈtɝːmɪnəbəl/', 'Hợp đồng thuê nhà của tôi có thể chấm dứt nếu báo trước một tháng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_4', 'ten_c2_9_1', 'hotelling', 'With hotelling, I book a desk before coming in.', 'With hotelling, I book a desk before coming in.', '/hoʊˈtelɪŋ/', 'Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_5', 'ten_c2_9_1', 'scrupulous', 'She gave every cup a scrupulous wash before serving tea.', 'She gave every cup a scrupulous wash before serving tea.', '/ˈskruːpjələs/', 'Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_6', 'ten_c2_9_1', 'recompense', 'The shop offered a refund as recompense for the inconvenience.', 'The shop offered a refund as recompense for the inconvenience.', '/ˈrekəmpens/', 'Cửa hàng đã đề xuất hoàn tiền như một sự đền bù cho sự bất tiện gây ra.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_7', 'ten_c2_9_1', 'rectification', 'The builder promised prompt rectification of the faulty wiring.', 'The builder promised prompt rectification of the faulty wiring.', '/ˌrektɪfɪˈkeɪʃn/', 'Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_1_8', 'ten_c2_9_1', 'superintend', 'An experienced gardener superintended the planting of our trees.', 'An experienced gardener superintended the planting of our trees.', '/ˌsuːpərɪnˈtend/', 'Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_9_1_1', 'en-c2-9', 'ten_c2_9_1', 'listening', 'listening', 'The manager deputed her assistant to attend the meeting.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên.","Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng.","Giám đốc đã ủy quyền cho trợ lý của mình đi dự họp.","Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi."]'::jsonb, 2, 'The manager deputed her assistant to attend the meeting. → Giám đốc đã ủy quyền cho trợ lý của mình đi dự họp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_9_1_2', 'en-c2-9', 'ten_c2_9_1', 'listening', 'listening', 'The shop now locks its stockroom to prevent pilferage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.","Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên.","Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.","Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi."]'::jsonb, 2, 'The shop now locks its stockroom to prevent pilferage. → Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_9_1_3', 'en-c2-9', 'ten_c2_9_1', 'listening', 'listening', 'My rental agreement is terminable with one month''s notice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi.","Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.","Hợp đồng thuê nhà của tôi có thể chấm dứt nếu báo trước một tháng.","Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt."]'::jsonb, 2, 'My rental agreement is terminable with one month''s notice. → Hợp đồng thuê nhà của tôi có thể chấm dứt nếu báo trước một tháng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_9_2', 'en-c2-9', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_2_1', 'ten_c2_9_2', 'depute', 'Local authorities may depute trained officers to inspect buildings and ensure compliance with safety regulations.', 'Local authorities may depute trained officers to inspect buildings and ensure compliance with safety regulations.', '/dɪˈpjuːt/', 'Các cơ quan chức năng địa phương có thể cử các sĩ quan đã qua đào tạo đi kiểm tra các tòa nhà và đảm bảo tuân thủ các quy định an toàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_2_2', 'ten_c2_9_2', 'pilferage', 'Retailers can reduce losses from pilferage by improving stock monitoring and providing secure storage for valuable goods.', 'Retailers can reduce losses from pilferage by improving stock monitoring and providing secure storage for valuable goods.', '/ˈpɪlfərɪdʒ/', 'Các nhà bán lẻ có thể giảm thiểu thiệt hại từ nạn trộm cắp vặt bằng cách cải thiện việc giám sát hàng tồn kho và cung cấp nơi lưu trữ an toàn cho hàng hóa có giá trị.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_2_3', 'ten_c2_9_2', 'terminable', 'Employment contracts should be terminable by either party, provided that reasonable notice is given.', 'Employment contracts should be terminable by either party, provided that reasonable notice is given.', '/ˈtɝːmɪnəbəl/', 'Hợp đồng lao động phải cho phép bất kỳ bên nào cũng có thể chấm dứt, miễn là đưa ra thông báo hợp lý trước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_2_4', 'ten_c2_9_2', 'hotelling', 'Hotelling can reduce office costs, although employees may miss having a permanent space for their belongings.', 'Hotelling can reduce office costs, although employees may miss having a permanent space for their belongings.', '/hoʊˈtelɪŋ/', 'Hệ thống đặt chỗ làm việc chung có thể giúp giảm chi phí văn phòng, mặc dù nhân viên có thể cảm thấy tiếc vì không có một không gian cố định để cất đồ đạc cá nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_2_5', 'ten_c2_9_2', 'scrupulous', 'Scrupulous attention to research methods is essential for producing reliable evidence in public health studies.', 'Scrupulous attention to research methods is essential for producing reliable evidence in public health studies.', '/ˈskruːpjələs/', 'Việc tuân thủ một cách nghiêm ngặt các phương pháp nghiên cứu là điều cốt lõi để tạo ra các bằng chứng đáng tin cậy trong các nghiên cứu y tế công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_9_2_6', 'ten_c2_9_2', 'recompense', 'Employees should receive fair recompense for additional duties rather than being expected to work extra hours without payment.', 'Employees should receive fair recompense for additional duties rather than being expected to work extra hours without payment.', '/ˈrekəmpens/', 'Nhân viên cần nhận được thù lao công bằng cho các nhiệm vụ bổ sung thay vì bị kỳ vọng phải làm thêm giờ mà không được trả lương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_9_2_1', 'en-c2-9', 'ten_c2_9_2', 'listening', 'listening', 'Local authorities may depute trained officers to inspect buildings and ensure compliance with safety regulations.', NULL, 'Trong câu vừa nghe, từ “depute” mang nghĩa nào sau đây?', '["máy xay thịt; máy băm thịt","trọng lượng của bao bì hoặc vật chứa (bì)","ủy quyền; ủy nhiệm; cử","có thể chấm dứt; có thể hủy bỏ"]'::jsonb, 2, '“depute” (/dɪˈpjuːt/): ủy quyền; ủy nhiệm; cử. Câu đầy đủ: Local authorities may depute trained officers to inspect buildings and ensure compliance with safety regulations.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_9_2_2', 'en-c2-9', 'ten_c2_9_2', 'listening', 'listening', 'Retailers can reduce losses from pilferage by improving stock monitoring and providing secure storage for valuable goods.', NULL, 'Trong câu vừa nghe, từ “pilferage” mang nghĩa nào sau đây?', '["cắt tỉa hoặc tạo kiểu tóc","sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt","sự ngây ngất; niềm vui sướng tột độ; sự cuồng nhiệt","bạo ngược; chuyên quyền; độc đoán"]'::jsonb, 1, '“pilferage” (/ˈpɪlfərɪdʒ/): sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt. Câu đầy đủ: Retailers can reduce losses from pilferage by improving stock monitoring and providing secure storage for valuable goods.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
