INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_9_7', 'en-c2-9', 'The builder promised prompt rectification of the faulty wiring', 'Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi.', 'rectification /ˌrektɪfɪˈkeɪʃn/', '["prompt","builder","rectification","the","faulty","promised","wiring","The","of"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
