INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_1', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'depute', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ủy quyền; ủy nhiệm; cử","hiểu lầm; nhận thức sai","đá mắt mèo; ngọc ô-pan","chập chững tập đi; bước đi lững thững"]'::jsonb, 0, 'depute (/dɪˈpjuːt/) → ủy quyền; ủy nhiệm; cử', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_2', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'The shop now locks its stockroom to prevent pilferage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc khuân chiếc ghế sofa khổng lồ đó lên lầu thực sự là một nhiệm vụ gian khổ.","Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi.","Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.","Xin vui lòng thông báo cho tôi về bất kỳ thay đổi nào trước thứ Sáu."]'::jsonb, 2, 'The shop now locks its stockroom to prevent pilferage. → Cửa hàng hiện đã khóa phòng kho lại để ngăn chặn tình trạng mất cắp vặt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_3', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'terminable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có thể chấm dứt; có thể hủy bỏ","không thích, không muốn hoặc miễn cưỡng làm điều gì đó","tính thích hợp; sự liên quan trực tiếp","sự gợi ý; lời ám chỉ; dấu hiệu"]'::jsonb, 0, 'terminable (/ˈtɝːmɪnəbəl/) → có thể chấm dứt; có thể hủy bỏ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_4', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'With hotelling, I book a desk before coming in.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng.","Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.","Việc khuân chiếc ghế sofa khổng lồ đó lên lầu thực sự là một nhiệm vụ gian khổ.","Xin vui lòng thông báo cho tôi về bất kỳ thay đổi nào trước thứ Sáu."]'::jsonb, 0, 'With hotelling, I book a desk before coming in. → Với hình thức đặt bàn làm việc linh hoạt, tôi sẽ đặt trước một chỗ ngồi trước khi đến văn phòng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_5', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'scrupulous', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tỉ mỉ; cẩn trọng; chu đáo","thuật luyện kim; phép luyện đan","đọc hoặc xem xét kỹ lưỡng","dẻo quánh; dính"]'::jsonb, 0, 'scrupulous (/ˈskruːpjələs/) → tỉ mỉ; cẩn trọng; chu đáo; liêm khiết; chính trực; cẩn trọng về đạo đức', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_6', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'The shop offered a refund as recompense for the inconvenience.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã rửa từng chiếc cốc một cách thật kỹ lưỡng trước khi mang trà lên.","Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi.","Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.","Cửa hàng đã đề xuất hoàn tiền như một sự đền bù cho sự bất tiện gây ra."]'::jsonb, 3, 'The shop offered a refund as recompense for the inconvenience. → Cửa hàng đã đề xuất hoàn tiền như một sự đền bù cho sự bất tiện gây ra.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_7', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'rectification', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự sửa chữa; sự hiệu chỉnh","gây thiệt hại nặng nề; phá sản","mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm"]'::jsonb, 0, 'rectification (/ˌrektɪfɪˈkeɪʃn/) → sự sửa chữa; sự hiệu chỉnh; sự chỉnh lưu', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_8', 'en-c2-9', NULL, 'comprehensive_test', 'listening', 'An experienced gardener superintended the planting of our trees.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự nổi tiếng vụt sáng của cô ấy đã khiến tất cả mọi người ở nhà hát nhỏ ngạc nhiên.","Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi.","Cửa hàng đã đề xuất hoàn tiền như một sự đền bù cho sự bất tiện gây ra.","Nhà thầu cam kết sẽ khắc phục kịp thời hệ thống dây điện bị lỗi."]'::jsonb, 1, 'An experienced gardener superintended the planting of our trees. → Một người làm vườn giàu kinh nghiệm đã giám sát việc trồng cây của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_9', 'en-c2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “extremely careful to do things correctly and thoroughly”?', '["apprise","scrupulous","hairdress","depute"]'::jsonb, 1, 'scrupulous (/ˈskruːpjələs/) → tỉ mỉ; cẩn trọng; chu đáo', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
