INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_18', 'en-c2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities may depute trained officers to inspect buildings and ensure compliance with safety regulations.', 'Dựa vào câu trên, từ “depute” có nghĩa phù hợp nhất là gì?', '["cuộc đụng độ nhỏ; xung đột ngắn","bệnh bại liệt; bệnh viêm tủy xám","chuyển tải; trung chuyển hàng hóa","ủy quyền; ủy nhiệm; cử"]'::jsonb, 3, 'depute: ủy quyền; ủy nhiệm; cử. Dịch cả câu: Các cơ quan chức năng địa phương có thể cử các sĩ quan đã qua đào tạo đi kiểm tra các tòa nhà và đảm bảo tuân thủ các quy định an toàn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_19', 'en-c2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Retailers can reduce losses from pilferage by improving stock monitoring and providing secure storage for valuable goods.', 'Dựa vào câu trên, từ “pilferage” có nghĩa phù hợp nhất là gì?', '["tỉ mỉ; cẩn trọng; chu đáo","cuộc hành trình dài và nhiều gian nan trắc trở","sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt","cướp bóc, tước đoạt bằng vũ lực"]'::jsonb, 2, 'pilferage: sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt. Dịch cả câu: Các nhà bán lẻ có thể giảm thiểu thiệt hại từ nạn trộm cắp vặt bằng cách cải thiện việc giám sát hàng tồn kho và cung cấp nơi lưu trữ an toàn cho hàng hóa có giá trị.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_20', 'en-c2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Employment contracts should be terminable by either party, provided that reasonable notice is given.', 'Dựa vào câu trên, từ “terminable” có nghĩa phù hợp nhất là gì?', '["chi tiết tinh vi; điểm tế nhị","nhão; mềm nhão (cơ bắp)","làm phồng lên; làm căng ra; trương lên","có thể chấm dứt; có thể hủy bỏ"]'::jsonb, 3, 'terminable: có thể chấm dứt; có thể hủy bỏ. Dịch cả câu: Hợp đồng lao động phải cho phép bất kỳ bên nào cũng có thể chấm dứt, miễn là đưa ra thông báo hợp lý trước.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_21', 'en-c2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Hotelling can reduce office costs, although employees may miss having a permanent space for their belongings.', 'Dựa vào câu trên, từ “hotelling” có nghĩa phù hợp nhất là gì?', '["cho đến nay hoặc cho đến thời điểm đang được bàn tới","tiêu chí chấm điểm; thang điểm","hệ thống nhân viên đặt trước không gian làm việc chung thay vì dùng bàn làm việc cố định","bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu"]'::jsonb, 2, 'hotelling: hệ thống nhân viên đặt trước không gian làm việc chung thay vì dùng bàn làm việc cố định. Dịch cả câu: Hệ thống đặt chỗ làm việc chung có thể giúp giảm chi phí văn phòng, mặc dù nhân viên có thể cảm thấy tiếc vì không có một không gian cố định để cất đồ đạc cá nhân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_22', 'en-c2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cần sức mạnh lớn; gian khổ”', '["delectable","epoch-making","aforesaid","herculean"]'::jsonb, 3, 'cần sức mạnh lớn; gian khổ → herculean (/ˌhɝːkjəˈliːən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_23', 'en-c2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cắt tỉa hoặc tạo kiểu tóc”', '["hairdress","salability","inalienable","paraphernalia"]'::jsonb, 0, 'cắt tỉa hoặc tạo kiểu tóc → hairdress (/ˈherdres/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_9_24', 'en-c2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phát triển nhanh chóng và ngoạn mục; vụt sáng”', '["bridle","panacea","meteoric","adjudicate"]'::jsonb, 2, 'phát triển nhanh chóng và ngoạn mục; vụt sáng → meteoric (/ˌmiːtiˈɔːrɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-10', 'en', 'Bài 10: Kinh tế & Tài chính - CEFR C2', 'CEFR C2', 'C2 · Kinh tế', '15 từ vựng Tiếng Anh CEFR C2 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6010, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bushel', 'en-c2-10', 'bushel', '/ˈbʊʃəl/', 'C2', 'bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)', 'n.', NULL, NULL, 'Đây là đơn vị đo thể tích chất khô; dung tích ở Anh và Mỹ khác nhau, không thể quy đổi trực tiếp thành trọng lượng cố định.', 'The farmer measured out a bushel of wheat.', NULL, 'Người nông dân đong được một bồ lúa mì.', '{"wordId":"bushel","ukIpa":"/ˈbʊʃəl/","usIpa":"/ˈbʊʃəl/","cefr":"C2","topic":"economy","senses":[{"pos":"n.","en":"A unit of dry volume used especially for grain.","vi":"bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)"}],"examples":[{"en":"The farmer measured out a bushel of wheat.","vi":"Người nông dân đong được một bồ lúa mì.","audioKind":"ex"},{"en":"Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.","vi":"Việc báo cáo giá ngũ cốc tính theo mỗi bồ cho phép nông dân so sánh tình hình thị trường trước khi quyết định thời điểm bán nông sản.","audioKind":"ex2"}],"collocations":[{"en":"a bushel of wheat","vi":"một bồ lúa mì"},{"en":"per bushel","vi":"mỗi bồ"},{"en":"a bushel basket","vi":"giỏ đong một bồ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là đơn vị đo thể tích chất khô; dung tích ở Anh và Mỹ khác nhau, không thể quy đổi trực tiếp thành trọng lượng cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_penury', 'en-c2-10', 'penury', '/ˈpenjəri/', 'C2', 'tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng', 'n.', 'penurious (adj.)', 'Đồng nghĩa: destitution, poverty · Trái nghĩa: affluence, wealth', 'Là từ mang tính trang trọng hoặc văn chương, mức độ trầm trọng hơn poverty, thường là danh từ không đếm được.', 'After years of penury, she could finally afford heating.', NULL, 'Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.', '{"wordId":"penury","ukIpa":"/ˈpenjəri/","usIpa":"/ˈpenjəri/","cefr":"C2","topic":"economy","senses":[{"pos":"n.","en":"extreme poverty, with too little money for basic needs","vi":"tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng"}],"examples":[{"en":"After years of penury, she could finally afford heating.","vi":"Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.","audioKind":"ex"},{"en":"Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.","vi":"Nếu không có sự bảo vệ xã hội đầy đủ, tình trạng thất nghiệp kéo dài có thể đẩy các hộ gia đình dễ bị tổn thương vào cảnh bần cùng và tổn hại đến sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"live in penury","vi":"sống trong cảnh túng quẫn"},{"en":"die in penury","vi":"chết trong nghèo đói"},{"en":"reduce someone to penury","vi":"đẩy ai đó vào cảnh bần cùng"}],"wordFamily":["penurious (adj.)"],"synonyms":["destitution","poverty"],"antonyms":["affluence","wealth"],"tipVi":"Là từ mang tính trang trọng hoặc văn chương, mức độ trầm trọng hơn poverty, thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burgeon', 'en-c2-10', 'burgeon', '/ˈbɝːdʒən/', 'C2', 'phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh', 'v.', 'burgeoning (adj.)', 'Đồng nghĩa: grow, flourish, expand · Trái nghĩa: shrink, decline', 'Ngày nay thường đóng vai trò là nội động từ; tính từ burgeoning thường đứng trước danh từ.', 'Her interest in gardening burgeoned after she moved here.', NULL, 'Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.', '{"wordId":"burgeon","ukIpa":"/ˈbɜːdʒən/","usIpa":"/ˈbɝːdʒən/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"To grow or develop rapidly.","vi":"phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh"}],"examples":[{"en":"Her interest in gardening burgeoned after she moved here.","vi":"Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.","audioKind":"ex"},{"en":"Demand for online courses has burgeoned as more adults seek flexible opportunities to develop professional skills.","vi":"Nhu cầu về các khóa học trực tuyến đã tăng trưởng mạnh mẽ khi ngày càng có nhiều người lớn tìm kiếm cơ hội linh hoạt để nâng cao kỹ năng nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"burgeoning demand","vi":"nhu cầu đang tăng nhanh"},{"en":"a burgeoning industry","vi":"một ngành công nghiệp đang phát triển mạnh"},{"en":"a burgeoning population","vi":"dân số tăng trưởng nhanh"}],"wordFamily":["burgeoning (adj.)"],"synonyms":["grow","flourish","expand"],"antonyms":["shrink","decline"],"tipVi":"Ngày nay thường đóng vai trò là nội động từ; tính từ burgeoning thường đứng trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disburse', 'en-c2-10', 'disburse', '/dɪsˈbɝːs/', 'C2', 'chi trả tiền, đặc biệt là tiền từ một quỹ chính thức', 'v.', 'disbursement (n.)', 'Đồng nghĩa: pay out', 'Từ có tính trang trọng, thường đi với các tân ngữ như funds hoặc money.', 'The charity will disburse the funds early next week.', NULL, 'Tổ chức từ thiện sẽ giải ngân số tiền này vào đầu tuần tới.', '{"wordId":"disburse","ukIpa":"/dɪsˈbɜːs/","usIpa":"/dɪsˈbɝːs/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"to pay out money, especially from an official fund","vi":"chi trả tiền, đặc biệt là tiền từ một quỹ chính thức"}],"examples":[{"en":"The charity will disburse the funds early next week.","vi":"Tổ chức từ thiện sẽ giải ngân số tiền này vào đầu tuần tới.","audioKind":"ex"},{"en":"Governments should disburse emergency funds quickly to help communities recover from natural disasters.","vi":"Chính phủ nên nhanh chóng giải ngân các quỹ khẩn cấp để giúp các cộng đồng phục hồi sau thảm họa thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"disburse funds","vi":"giải ngân quỹ"},{"en":"disburse money","vi":"chi trả tiền"},{"en":"disburse a loan","vi":"phát1 khoản vay"}],"wordFamily":["disbursement (n.)"],"synonyms":["pay out"],"antonyms":[],"tipVi":"Từ có tính trang trọng, thường đi với các tân ngữ như funds hoặc money.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defray', 'en-c2-10', 'defray', '/dɪˈfreɪ/', 'C2', 'chi trả; thanh toán (chi phí)', 'v.', NULL, 'Đồng nghĩa: cover, pay', 'Từ vựng mang tính trang trọng, tân ngữ thường là costs hoặcexpenses, không dùng cho con người.', 'The club helped defray the cost of my trip.', NULL, 'Câu lạc bộ đã giúp tôi chi trả một phần chi phí chuyến đi.', '{"wordId":"defray","ukIpa":"/dɪˈfreɪ/","usIpa":"/dɪˈfreɪ/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"to pay all or part of a cost","vi":"chi trả; thanh toán (chi phí)"}],"examples":[{"en":"The club helped defray the cost of my trip.","vi":"Câu lạc bộ đã giúp tôi chi trả một phần chi phí chuyến đi.","audioKind":"ex"},{"en":"Universities could offer additional grants to defray accommodation expenses for students from low-income households.","vi":"Các trường đại học có thể cung cấp thêm các khoản trợ cấp để giúp sinh viên có hoàn cảnh khó khăn thanh toán chi phí chỗ ở.","audioKind":"ex2"}],"collocations":[{"en":"defray costs","vi":"chi trả chi phí"},{"en":"defray expenses","vi":"gánh vác chi phí"}],"wordFamily":[],"synonyms":["cover","pay"],"antonyms":[],"tipVi":"Từ vựng mang tính trang trọng, tân ngữ thường là costs hoặcexpenses, không dùng cho con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_denominate', 'en-c2-10', 'denominate', '/dɪˈnɑːmɪneɪt/', 'C2', 'định giá bằng một loại tiền tệ cụ thể; đặt tên; gọi tên', 'v.', 'denomination (n.)', NULL, 'Trong tài chính thường dùng be denominated in cộng với tên tiền tệ; nghĩa đặt tên ít phổ biến hơn.', 'The bank denominated our overseas loan in euros.', NULL, 'Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro.', '{"wordId":"denominate","ukIpa":"/dɪˈnɒmɪneɪt/","usIpa":"/dɪˈnɑːmɪneɪt/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"express a financial amount in a particular currency","vi":"định giá bằng một loại tiền tệ cụ thể"},{"pos":"v.","en":"give a particular name to something","vi":"đặt tên; gọi tên"}],"examples":[{"en":"The bank denominated our overseas loan in euros.","vi":"Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro.","audioKind":"ex"},{"en":"Loans denominated in foreign currencies can become more expensive when the domestic currency loses value.","vi":"Các khoản vay tính bằng ngoại tệ có thể trở nên tốn kém hơn khi nội tệ rớt giá.","audioKind":"ex2"}],"collocations":[{"en":"denominated in dollars","vi":"được định giá bằng đô la"},{"en":"foreign-currency-denominated debt","vi":"khoản nợ tính bằng ngoại tệ"}],"wordFamily":["denomination (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tài chính thường dùng be denominated in cộng với tên tiền tệ; nghĩa đặt tên ít phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salability', 'en-c2-10', 'salability', '/ˌseɪləˈbɪləti/', 'C2', 'tính dễ bán; khả năng tiêu thụ trên thị trường', 'n.', 'salable (adj.), sale (n.), sell (v.)', 'Đồng nghĩa: saleability, marketability', 'Kiểu chính tả Mỹ; tiếng Anh Anh thường viết là saleability.', 'Fresh paint improved the salability of our old house.', NULL, 'Việc sơn lại ngôi nhà đã giúp cải thiện tính thanh khoản khi bán căn nhà cũ của chúng tôi.', '{"wordId":"salability","ukIpa":"/ˌseɪləˈbɪləti/","usIpa":"/ˌseɪləˈbɪləti/","cefr":"C2","topic":"economy","senses":[{"pos":"n.","en":"The degree to which something can be sold easily.","vi":"tính dễ bán; khả năng tiêu thụ trên thị trường"}],"examples":[{"en":"Fresh paint improved the salability of our old house.","vi":"Việc sơn lại ngôi nhà đã giúp cải thiện tính thanh khoản khi bán căn nhà cũ của chúng tôi.","audioKind":"ex"},{"en":"Manufacturers often adjust packaging to improve the salability of products in highly competitive markets.","vi":"Các nhà sản xuất thường điều chỉnh bao bì để nâng cao khả năng tiêu thụ sản phẩm trên các thị trường cạnh tranh khốc liệt.","audioKind":"ex2"}],"collocations":[{"en":"improve salability","vi":"nâng cao khả năng tiêu thụ"},{"en":"product salability","vi":"tính dễ bán của sản phẩm"},{"en":"affect salability","vi":"ảnh hưởng đến khả năng tiêu thụ"}],"wordFamily":["salable (adj.)","sale (n.)","sell (v.)"],"synonyms":["saleability","marketability"],"antonyms":[],"tipVi":"Kiểu chính tả Mỹ; tiếng Anh Anh thường viết là saleability.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underwriter', 'en-c2-10', 'underwriter', '/ˈʌndɚraɪtɚ/', 'C2', 'người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm; tổ chức bảo lãnh phát hành chứng khoán', 'n.', 'underwrite (v.), underwriting (n.)', NULL, 'Trong lĩnh vực bảo hiểm, từ này chỉ người hoặc cơ quan nhận bảo hiểm, còn trong lĩnh vực chứng khoán, nó chỉ nhà bảo lãnh phát hành.', 'The underwriter checked our roof before approving the insurance.', NULL, 'Bên bảo hiểm đã kiểm tra mái nhà của chúng tôi trước khi phê duyệt hợp đồng bảo hiểm.', '{"wordId":"underwriter","ukIpa":"/ˈʌndəraɪtə/","usIpa":"/ˈʌndɚraɪtɚ/","cefr":"C2","topic":"economy","senses":[{"pos":"n.","en":"A person or organisation that accepts insurance risks.","vi":"người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm"},{"pos":"n.","en":"An institution guaranteeing to buy securities not purchased by investors.","vi":"tổ chức bảo lãnh phát hành chứng khoán"}],"examples":[{"en":"The underwriter checked our roof before approving the insurance.","vi":"Bên bảo hiểm đã kiểm tra mái nhà của chúng tôi trước khi phê duyệt hợp đồng bảo hiểm.","audioKind":"ex"},{"en":"An underwriter assesses potential losses before deciding whether to offer insurance for buildings in areas prone to flooding.","vi":"Nhà bảo hiểm đánh giá các tổn thất tiềm ẩn trước khi quyết định có cung cấp bảo hiểm cho các tòa nhà ở khu vực dễ xảy ra lũ lụt hay không.","audioKind":"ex2"}],"collocations":[{"en":"insurance underwriter","vi":"bên bảo hiểm"},{"en":"lead underwriter","vi":"bên bảo lãnh chính"},{"en":"mortgage underwriter","vi":"nhân viên thẩm định cho vay mua nhà"}],"wordFamily":["underwrite (v.)","underwriting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong lĩnh vực bảo hiểm, từ này chỉ người hoặc cơ quan nhận bảo hiểm, còn trong lĩnh vực chứng khoán, nó chỉ nhà bảo lãnh phát hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transship', 'en-c2-10', 'transship', '/trænˈʃɪp/', 'C2', 'chuyển tải; trung chuyển hàng hóa', 'v.', 'transshipment (n.)', NULL, 'Quá khứ là transshipped, hiện phân từ viết gấp đôi chữ p.', 'Workers transshipped the crates onto a smaller boat.', NULL, 'Các công nhân đã chuyển tải các thùng hàng sang một chiếc thuyền nhỏ hơn.', '{"wordId":"transship","ukIpa":"/trænˈʃɪp/","usIpa":"/trænˈʃɪp/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"Transfer goods from one ship or vehicle to another.","vi":"chuyển tải; trung chuyển hàng hóa"}],"examples":[{"en":"Workers transshipped the crates onto a smaller boat.","vi":"Các công nhân đã chuyển tải các thùng hàng sang một chiếc thuyền nhỏ hơn.","audioKind":"ex"},{"en":"Shipping companies often transship cargo at major ports to reduce costs and reach smaller markets.","vi":"Các công ty vận tải biển thường trung chuyển hàng hóa tại các cảng lớn để giảm chi phí và tiếp cận các thị trường nhỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"transship cargo","vi":"chuyển tải hàng hóa"},{"en":"transship goods","vi":"trung chuyển hàng hóa"},{"en":"transship containers","vi":"chuyển container"}],"wordFamily":["transshipment (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là transshipped, hiện phân từ viết gấp đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indemnify', 'en-c2-10', 'indemnify', '/ɪnˈdemnɪfaɪ/', 'C2', 'bồi thường thiệt hại; đảm bảo bồi thường', 'v.', 'indemnity (n.), indemnification (n.)', 'Đồng nghĩa: compensate, reimburse', 'Thuật ngữ pháp lý trang trọng: giới từ for đi với tổn thất đã xảy ra, against đi với việc phòng ngừa rủi ro.', 'The insurer agreed to indemnify us for the damage.', NULL, 'Công ty bảo hiểm đã đồng ý bồi thường cho chúng tôi về những thiệt hại đã xảy ra.', '{"wordId":"indemnify","ukIpa":"/ɪnˈdemnɪfaɪ/","usIpa":"/ɪnˈdemnɪfaɪ/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"To compensate for loss or provide financial protection against it.","vi":"bồi thường thiệt hại; đảm bảo bồi thường"}],"examples":[{"en":"The insurer agreed to indemnify us for the damage.","vi":"Công ty bảo hiểm đã đồng ý bồi thường cho chúng tôi về những thiệt hại đã xảy ra.","audioKind":"ex"},{"en":"Construction contracts often require companies to indemnify clients against financial losses caused by negligence.","vi":"Các hợp đồng xây dựng thường yêu cầu các công ty phải bồi thường cho khách hàng trước những tổn thất tài chính do sơ suất gây ra.","audioKind":"ex2"}],"collocations":[{"en":"indemnify someone against loss","vi":"bồi thường cho ai khỏi tổn thất"},{"en":"indemnify someone for damage","vi":"bồi thường thiệt hại cho ai"}],"wordFamily":["indemnity (n.)","indemnification (n.)"],"synonyms":["compensate","reimburse"],"antonyms":[],"tipVi":"Thuật ngữ pháp lý trang trọng: giới từ for đi với tổn thất đã xảy ra, against đi với việc phòng ngừa rủi ro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_short-weight', 'en-c2-10', 'short-weight', '/ˌʃɔːrtˈweɪt/', 'C2', 'bán thiếu cân; gian lận trọng lượng', 'v.', NULL, NULL, 'Động từ chỉ hành động cân thiếu; danh từ thường viết tách thành short weight.', 'The shopkeeper short-weighted my rice by using faulty scales.', NULL, 'Người chủ cửa hàng đã bán thiếu gạo cho tôi bằng cách dùng chiếc cân bị hỏng.', '{"wordId":"short-weight","ukIpa":"/ˌʃɔːtˈweɪt/","usIpa":"/ˌʃɔːrtˈweɪt/","cefr":"C2","topic":"economy","senses":[{"pos":"v.","en":"Give a customer less weight of goods than paid for","vi":"bán thiếu cân; gian lận trọng lượng"}],"examples":[{"en":"The shopkeeper short-weighted my rice by using faulty scales.","vi":"Người chủ cửa hàng đã bán thiếu gạo cho tôi bằng cách dùng chiếc cân bị hỏng.","audioKind":"ex"},{"en":"Regular inspections of market scales can prevent traders from short-weighting customers and help maintain confidence in local commerce.","vi":"Việc kiểm tra định kỳ cân tại các khu chợ có thể ngăn chặn tình trạng tiểu thương bán thiếu cân cho người mua và góp phần duy trì niềm tin vào hoạt động thương mại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"short-weight customers","vi":"bán thiếu cân cho khách hàng"},{"en":"short-weight a buyer","vi":"cân thiếu hàng cho người mua"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ chỉ hành động cân thiếu; danh từ thường viết tách thành short weight.","noteVi":"Dạng dùng hiếm gặp; danh từ chỉ trọng lượng thiếu thường viết là short weight.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_promissory', 'en-c2-10', 'promissory', '/ˈprɑːmɪsɔːri/', 'C2', 'mang tính cam kết, đặc biệt là cam kết trả tiền bằng văn bản', 'adj.', 'promise (n.), promise (v.)', NULL, 'Chủ yếu dùng trong ngữ cảnh pháp lý và tài chính, cụm từ phổ biến là promissory note.', 'She signed a promissory note before borrowing the money.', NULL, 'Cô ấy đã ký một giấy nhận nợ trước khi vay tiền.', '{"wordId":"promissory","ukIpa":"/ˈprɒmɪsəri/","usIpa":"/ˈprɑːmɪsɔːri/","cefr":"C2","topic":"economy","senses":[{"pos":"adj.","en":"containing a promise, especially a written promise to pay","vi":"mang tính cam kết, đặc biệt là cam kết trả tiền bằng văn bản"}],"examples":[{"en":"She signed a promissory note before borrowing the money.","vi":"Cô ấy đã ký một giấy nhận nợ trước khi vay tiền.","audioKind":"ex"},{"en":"A promissory note provides written evidence of debt, helping lenders establish their legal right to repayment.","vi":"Một tờ giấy nhận nợ cung cấp bằng chứng bằng văn bản về khoản nợ, giúp cho người cho vay xác lập quyền đòi nợ hợp pháp của họ.","audioKind":"ex2"}],"collocations":[{"en":"promissory note","vi":"giấy hứa trả tiền; kỳ phiếu"},{"en":"promissory obligation","vi":"nghĩa vụ cam kết"}],"wordFamily":["promise (n.)","promise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu dùng trong ngữ cảnh pháp lý và tài chính, cụm từ phổ biến là promissory note.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_annuity', 'en-c2-10', 'annuity', '/əˈnuːəti/', 'C2', 'tiền niên kim; bảo hiểm niên kim', 'n.', NULL, NULL, 'Niên kim có thể được chi trả định kỳ hàng tháng, chứ không nhất thiết chỉ nhận một lần mỗi năm.', 'My grandfather receives an annuity to cover his living costs.', NULL, 'Ông tôi nhận tiền niên kim để trang trải các chi phí sinh hoạt.', '{"wordId":"annuity","ukIpa":"/əˈnjuːəti/","usIpa":"/əˈnuːəti/","cefr":"C2","topic":"economy","senses":[{"pos":"n.","en":"An investment providing regular payments, often throughout retirement.","vi":"tiền niên kim; bảo hiểm niên kim"}],"examples":[{"en":"My grandfather receives an annuity to cover his living costs.","vi":"Ông tôi nhận tiền niên kim để trang trải các chi phí sinh hoạt.","audioKind":"ex"},{"en":"An annuity can provide retirees with a predictable income, although inflation may reduce its purchasing power.","vi":"Tiền niên kim có thể mang lại cho người về hưu một khoản thu nhập có thể dự tính trước, mặc dù lạm phát có thể làm giảm sức mua của nó.","audioKind":"ex2"}],"collocations":[{"en":"buy an annuity","vi":"mua bảo hiểm niên kim"},{"en":"annuity payments","vi":"khoản chi trả niên kim"},{"en":"a lifetime annuity","vi":"niên kim trọn đời"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Niên kim có thể được chi trả định kỳ hàng tháng, chứ không nhất thiết chỉ nhận một lần mỗi năm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impost', 'en-c2-10', 'impost', '/ˈɪmpoʊst/', 'C2', 'thuế; thuế quan; bệ đỡ vòm; đà gối', 'n.', NULL, NULL, 'Nghĩa về thuế mang tính cổ hoặc chuyên ngành; hiện nay thường dùng tax hoặc duty.', 'The guide explained the old impost on imported tea.', NULL, 'Hướng dẫn viên giải thích về loại thuế cũ áp lên trà nhập khẩu.', '{"wordId":"impost","ukIpa":"/ˈɪmpəʊst/","usIpa":"/ˈɪmpoʊst/","cefr":"C2","topic":"economy","senses":[{"pos":"n.","en":"A tax, especially one charged on imported goods.","vi":"thuế; thuế quan"},{"pos":"n.","en":"A projecting support from which an arch rises.","vi":"bệ đỡ vòm; đà gối"}],"examples":[{"en":"The guide explained the old impost on imported tea.","vi":"Hướng dẫn viên giải thích về loại thuế cũ áp lên trà nhập khẩu.","audioKind":"ex"},{"en":"An impost on imported grain could protect domestic farmers while increasing food costs for urban consumers.","vi":"Việc đánh thuế vào ngũ cốc nhập khẩu có thể bảo vệ nông dân trong nước nhưng đồng thời làm tăng chi phí thực phẩm đối với người tiêu dùng thành thị.","audioKind":"ex2"}],"collocations":[{"en":"an impost on imports","vi":"thuế hàng nhập khẩu"},{"en":"levy an impost","vi":"đánh thuế"},{"en":"impost block","vi":"khối đá bệ vòm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa về thuế mang tính cổ hoặc chuyên ngành; hiện nay thường dùng tax hoặc duty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ruinous', 'en-c2-10', 'ruinous', '/ˈruːɪnəs/', 'C2', 'gây thiệt hại nặng nề; phá sản; đổ nát; tiêu điều', 'adj.', 'ruin (v.), ruin (n.), ruined (adj.), ruinously (adv.)', 'Đồng nghĩa: disastrous, devastating', 'Thường nhấn mạnh mức độ thiệt hại tài chính nghiêm trọng, không đơn thuần chỉ là đắt đỏ thông thường.', 'The repairs were so ruinous that we sold the house.', NULL, 'Chi phí sửa chữa tốn kém đến mức chúng tôi đành phải bán ngôi nhà đi.', '{"wordId":"ruinous","ukIpa":"/ˈruːɪnəs/","usIpa":"/ˈruːɪnəs/","cefr":"C2","topic":"economy","senses":[{"pos":"adj.","en":"Causing severe damage, especially financial loss.","vi":"gây thiệt hại nặng nề; phá sản"},{"pos":"adj.","en":"Badly damaged and falling apart.","vi":"đổ nát; tiêu điều"}],"examples":[{"en":"The repairs were so ruinous that we sold the house.","vi":"Chi phí sửa chữa tốn kém đến mức chúng tôi đành phải bán ngôi nhà đi.","audioKind":"ex"},{"en":"Prolonged drought can have ruinous consequences for farming communities that depend entirely on seasonal rainfall.","vi":"Hạn hán kéo dài có thể gây ra hậu quả tàn khốc đối với các cộng đồng nông nghiệp hoàn toàn phụ thuộc vào lượng mưa theo mùa.","audioKind":"ex2"}],"collocations":[{"en":"ruinous costs","vi":"chi phí đắt đỏ khôn lường"},{"en":"ruinous consequences","vi":"hậu quả hủy diệt"},{"en":"financially ruinous","vi":"phá sản về tài chính"}],"wordFamily":["ruin (v.)","ruin (n.)","ruined (adj.)","ruinously (adv.)"],"synonyms":["disastrous","devastating"],"antonyms":[],"tipVi":"Thường nhấn mạnh mức độ thiệt hại tài chính nghiêm trọng, không đơn thuần chỉ là đắt đỏ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_10_1', 'en-c2-10', 'Cách dùng “underwriter” (n.) — người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm', 'insurance underwriter  ·  lead underwriter  ·  mortgage underwriter', 'Trong lĩnh vực bảo hiểm, từ này chỉ người hoặc cơ quan nhận bảo hiểm, còn trong lĩnh vực chứng khoán, nó chỉ nhà bảo lãnh phát hành.', 'Họ từ (Word Family): underwrite (v.), underwriting (n.)', '[{"hanzi":"The underwriter checked our roof before approving the insurance.","pinyin":"","meaning":"Bên bảo hiểm đã kiểm tra mái nhà của chúng tôi trước khi phê duyệt hợp đồng bảo hiểm."},{"hanzi":"An underwriter assesses potential losses before deciding whether to offer insurance for buildings in areas prone to flooding.","pinyin":"","meaning":"Nhà bảo hiểm đánh giá các tổn thất tiềm ẩn trước khi quyết định có cung cấp bảo hiểm cho các tòa nhà ở khu vực dễ xảy ra lũ lụt hay không."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_10_2', 'en-c2-10', 'Cách dùng “bushel” (n.) — bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)', 'a bushel of wheat  ·  per bushel  ·  a bushel basket', 'Đây là đơn vị đo thể tích chất khô; dung tích ở Anh và Mỹ khác nhau, không thể quy đổi trực tiếp thành trọng lượng cố định.', NULL, '[{"hanzi":"The farmer measured out a bushel of wheat.","pinyin":"","meaning":"Người nông dân đong được một bồ lúa mì."},{"hanzi":"Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.","pinyin":"","meaning":"Việc báo cáo giá ngũ cốc tính theo mỗi bồ cho phép nông dân so sánh tình hình thị trường trước khi quyết định thời điểm bán nông sản."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_10_3', 'en-c2-10', 'Cách dùng “penury” (n.) — tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng', 'live in penury  ·  die in penury  ·  reduce someone to penury', 'Là từ mang tính trang trọng hoặc văn chương, mức độ trầm trọng hơn poverty, thường là danh từ không đếm được.', 'Họ từ (Word Family): penurious (adj.) | Đồng nghĩa: destitution, poverty · Trái nghĩa: affluence, wealth', '[{"hanzi":"After years of penury, she could finally afford heating.","pinyin":"","meaning":"Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm."},{"hanzi":"Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.","pinyin":"","meaning":"Nếu không có sự bảo vệ xã hội đầy đủ, tình trạng thất nghiệp kéo dài có thể đẩy các hộ gia đình dễ bị tổn thương vào cảnh bần cùng và tổn hại đến sức khỏe của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_10_4', 'en-c2-10', 'Cách dùng “indemnify” (v.) — bồi thường thiệt hại; đảm bảo bồi thường', 'indemnify someone against loss  ·  indemnify someone for damage', 'Thuật ngữ pháp lý trang trọng: giới từ for đi với tổn thất đã xảy ra, against đi với việc phòng ngừa rủi ro.', 'Họ từ (Word Family): indemnity (n.), indemnification (n.) | Đồng nghĩa: compensate, reimburse', '[{"hanzi":"The insurer agreed to indemnify us for the damage.","pinyin":"","meaning":"Công ty bảo hiểm đã đồng ý bồi thường cho chúng tôi về những thiệt hại đã xảy ra."},{"hanzi":"Construction contracts often require companies to indemnify clients against financial losses caused by negligence.","pinyin":"","meaning":"Các hợp đồng xây dựng thường yêu cầu các công ty phải bồi thường cho khách hàng trước những tổn thất tài chính do sơ suất gây ra."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_10_1', 'en-c2-10', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_1', 'ten_c2_10_1', 'bushel', 'The farmer measured out a bushel of wheat.', 'The farmer measured out a bushel of wheat.', '/ˈbʊʃəl/', 'Người nông dân đong được một bồ lúa mì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_2', 'ten_c2_10_1', 'penury', 'After years of penury, she could finally afford heating.', 'After years of penury, she could finally afford heating.', '/ˈpenjəri/', 'Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_3', 'ten_c2_10_1', 'burgeon', 'Her interest in gardening burgeoned after she moved here.', 'Her interest in gardening burgeoned after she moved here.', '/ˈbɝːdʒən/', 'Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_4', 'ten_c2_10_1', 'disburse', 'The charity will disburse the funds early next week.', 'The charity will disburse the funds early next week.', '/dɪsˈbɝːs/', 'Tổ chức từ thiện sẽ giải ngân số tiền này vào đầu tuần tới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_5', 'ten_c2_10_1', 'defray', 'The club helped defray the cost of my trip.', 'The club helped defray the cost of my trip.', '/dɪˈfreɪ/', 'Câu lạc bộ đã giúp tôi chi trả một phần chi phí chuyến đi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_6', 'ten_c2_10_1', 'denominate', 'The bank denominated our overseas loan in euros.', 'The bank denominated our overseas loan in euros.', '/dɪˈnɑːmɪneɪt/', 'Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_7', 'ten_c2_10_1', 'salability', 'Fresh paint improved the salability of our old house.', 'Fresh paint improved the salability of our old house.', '/ˌseɪləˈbɪləti/', 'Việc sơn lại ngôi nhà đã giúp cải thiện tính thanh khoản khi bán căn nhà cũ của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_1_8', 'ten_c2_10_1', 'underwriter', 'The underwriter checked our roof before approving the insurance.', 'The underwriter checked our roof before approving the insurance.', '/ˈʌndɚraɪtɚ/', 'Bên bảo hiểm đã kiểm tra mái nhà của chúng tôi trước khi phê duyệt hợp đồng bảo hiểm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_10_1_1', 'en-c2-10', 'ten_c2_10_1', 'listening', 'listening', 'The farmer measured out a bushel of wheat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chi phí sửa chữa tốn kém đến mức chúng tôi đành phải bán ngôi nhà đi.","Tổ chức từ thiện sẽ giải ngân số tiền này vào đầu tuần tới.","Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.","Người nông dân đong được một bồ lúa mì."]'::jsonb, 3, 'The farmer measured out a bushel of wheat. → Người nông dân đong được một bồ lúa mì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_10_1_2', 'en-c2-10', 'ten_c2_10_1', 'listening', 'listening', 'After years of penury, she could finally afford heating.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.","Câu lạc bộ đã giúp tôi chi trả một phần chi phí chuyến đi.","Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.","Việc sơn lại ngôi nhà đã giúp cải thiện tính thanh khoản khi bán căn nhà cũ của chúng tôi."]'::jsonb, 0, 'After years of penury, she could finally afford heating. → Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_10_1_3', 'en-c2-10', 'ten_c2_10_1', 'listening', 'listening', 'Her interest in gardening burgeoned after she moved here.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Các công nhân đã chuyển tải các thùng hàng sang một chiếc thuyền nhỏ hơn.","Ông tôi nhận tiền niên kim để trang trải các chi phí sinh hoạt.","Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.","Công ty bảo hiểm đã đồng ý bồi thường cho chúng tôi về những thiệt hại đã xảy ra."]'::jsonb, 2, 'Her interest in gardening burgeoned after she moved here. → Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_10_2', 'en-c2-10', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_2_1', 'ten_c2_10_2', 'bushel', 'Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.', 'Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.', '/ˈbʊʃəl/', 'Việc báo cáo giá ngũ cốc tính theo mỗi bồ cho phép nông dân so sánh tình hình thị trường trước khi quyết định thời điểm bán nông sản.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_2_2', 'ten_c2_10_2', 'penury', 'Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.', 'Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.', '/ˈpenjəri/', 'Nếu không có sự bảo vệ xã hội đầy đủ, tình trạng thất nghiệp kéo dài có thể đẩy các hộ gia đình dễ bị tổn thương vào cảnh bần cùng và tổn hại đến sức khỏe của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_2_3', 'ten_c2_10_2', 'burgeon', 'Demand for online courses has burgeoned as more adults seek flexible opportunities to develop professional skills.', 'Demand for online courses has burgeoned as more adults seek flexible opportunities to develop professional skills.', '/ˈbɝːdʒən/', 'Nhu cầu về các khóa học trực tuyến đã tăng trưởng mạnh mẽ khi ngày càng có nhiều người lớn tìm kiếm cơ hội linh hoạt để nâng cao kỹ năng nghề nghiệp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_2_4', 'ten_c2_10_2', 'disburse', 'Governments should disburse emergency funds quickly to help communities recover from natural disasters.', 'Governments should disburse emergency funds quickly to help communities recover from natural disasters.', '/dɪsˈbɝːs/', 'Chính phủ nên nhanh chóng giải ngân các quỹ khẩn cấp để giúp các cộng đồng phục hồi sau thảm họa thiên nhiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_2_5', 'ten_c2_10_2', 'defray', 'Universities could offer additional grants to defray accommodation expenses for students from low-income households.', 'Universities could offer additional grants to defray accommodation expenses for students from low-income households.', '/dɪˈfreɪ/', 'Các trường đại học có thể cung cấp thêm các khoản trợ cấp để giúp sinh viên có hoàn cảnh khó khăn thanh toán chi phí chỗ ở.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_10_2_6', 'ten_c2_10_2', 'denominate', 'Loans denominated in foreign currencies can become more expensive when the domestic currency loses value.', 'Loans denominated in foreign currencies can become more expensive when the domestic currency loses value.', '/dɪˈnɑːmɪneɪt/', 'Các khoản vay tính bằng ngoại tệ có thể trở nên tốn kém hơn khi nội tệ rớt giá.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_10_2_1', 'en-c2-10', 'ten_c2_10_2', 'listening', 'listening', 'Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.', NULL, 'Trong câu vừa nghe, từ “bushel” mang nghĩa nào sau đây?', '["bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)","danh tiếng; tiếng tăm","của cái đó; thuộc về cái vừa nhắc đến","dễ uốn; dễ gò (kim loại)"]'::jsonb, 0, '“bushel” (/ˈbʊʃəl/): bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc). Câu đầy đủ: Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_10_2_2', 'en-c2-10', 'ten_c2_10_2', 'listening', 'listening', 'Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.', NULL, 'Trong câu vừa nghe, từ “penury” mang nghĩa nào sau đây?', '["chất đẩy; chất phóng","tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng","có sở thích rộng rãi; bao quát; phong phú","sự phô trương; sự khoe khoang; tính chưng diện"]'::jsonb, 1, '“penury” (/ˈpenjəri/): tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng. Câu đầy đủ: Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
