INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_10_1', 'en-c2-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “bushel” (/ˈbʊʃəl/) có nghĩa là gì?', '["phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh","chi trả; thanh toán (chi phí)","bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)","gây thiệt hại nặng nề; phá sản"]'::jsonb, 2, '“bushel” (n.): bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc).', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
