INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_10_6', 'en-c2-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “denominate” (/dɪˈnɑːmɪneɪt/) có nghĩa là gì?', '["tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng","định giá bằng một loại tiền tệ cụ thể","người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm","chuyển tải; trung chuyển hàng hóa"]'::jsonb, 1, '“denominate” (v.): định giá bằng một loại tiền tệ cụ thể; đặt tên; gọi tên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_10_7', 'en-c2-10', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “salability” (/ˌseɪləˈbɪləti/) có nghĩa là gì?', '["người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm","tính dễ bán; khả năng tiêu thụ trên thị trường","tiền niên kim; bảo hiểm niên kim","định giá bằng một loại tiền tệ cụ thể"]'::jsonb, 1, '“salability” (n.): tính dễ bán; khả năng tiêu thụ trên thị trường.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
