INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_1', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'bushel', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bác bỏ; từ chối","bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)","thuốc tiên; giải pháp vạn năng","trọng lượng của bao bì hoặc vật chứa (bì)"]'::jsonb, 1, 'bushel (/ˈbʊʃəl/) → bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_2', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'After years of penury, she could finally afford heating.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.","Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro.","Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.","Chi phí sửa chữa tốn kém đến mức chúng tôi đành phải bán ngôi nhà đi."]'::jsonb, 2, 'After years of penury, she could finally afford heating. → Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_3', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'burgeon', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhão; mềm nhão (cơ bắp)","ảo tưởng; đánh lừa; làm sai lệch thực tế","phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh","biển thủ, thụt quĩ, lén lấy tiền hoặc tài sản được giao phó để sử dụng cho riêng mình"]'::jsonb, 2, 'burgeon (/ˈbɝːdʒən/) → phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_4', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'The charity will disburse the funds early next week.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tổ chức từ thiện sẽ giải ngân số tiền này vào đầu tuần tới.","Việc sơn lại ngôi nhà đã giúp cải thiện tính thanh khoản khi bán căn nhà cũ của chúng tôi.","Cô ấy đã ký một giấy nhận nợ trước khi vay tiền.","Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro."]'::jsonb, 0, 'The charity will disburse the funds early next week. → Tổ chức từ thiện sẽ giải ngân số tiền này vào đầu tuần tới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_5', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'defray', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chi trả; thanh toán (chi phí)","rải; rắc; vứt bừa bãi","có tính cấu thành; tạo nên bản chất","tảo; thực vật phù du"]'::jsonb, 0, 'defray (/dɪˈfreɪ/) → chi trả; thanh toán (chi phí)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_6', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'The bank denominated our overseas loan in euros.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công ty bảo hiểm đã đồng ý bồi thường cho chúng tôi về những thiệt hại đã xảy ra.","Hướng dẫn viên giải thích về loại thuế cũ áp lên trà nhập khẩu.","Sau nhiều năm sống trong cảnh nghèo đói cùng cực, cuối cùng cô ấy cũng có đủ tiền trả tiền sưởi ấm.","Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro."]'::jsonb, 3, 'The bank denominated our overseas loan in euros. → Ngân hàng đã định giá khoản vay nước ngoài của chúng tôi bằng đồng euro.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_7', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'salability', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm phiền; làm bực mình; làm lo lắng","kiến trúc thượng tầng (của công trình, tàu thuyền)","tính dễ bán; khả năng tiêu thụ trên thị trường","danh tiếng; tiếng tăm"]'::jsonb, 2, 'salability (/ˌseɪləˈbɪləti/) → tính dễ bán; khả năng tiêu thụ trên thị trường', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_8', 'en-c2-10', NULL, 'comprehensive_test', 'listening', 'The underwriter checked our roof before approving the insurance.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự quan tâm của cô ấy đối với làm vườn đã phát triển mạnh mẽ sau khi chuyển đến đây.","Ông tôi nhận tiền niên kim để trang trải các chi phí sinh hoạt.","Bên bảo hiểm đã kiểm tra mái nhà của chúng tôi trước khi phê duyệt hợp đồng bảo hiểm.","Câu lạc bộ đã giúp tôi chi trả một phần chi phí chuyến đi."]'::jsonb, 2, 'The underwriter checked our roof before approving the insurance. → Bên bảo hiểm đã kiểm tra mái nhà của chúng tôi trước khi phê duyệt hợp đồng bảo hiểm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_9', 'en-c2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to pay all or part of a cost”?', '["ruinous","annuity","impost","defray"]'::jsonb, 3, 'defray (/dɪˈfreɪ/) → chi trả; thanh toán (chi phí)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_10', 'en-c2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “express a financial amount in a particular currency”?', '["disburse","promissory","denominate","impost"]'::jsonb, 2, 'denominate (/dɪˈnɑːmɪneɪt/) → định giá bằng một loại tiền tệ cụ thể', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_11', 'en-c2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The degree to which something can be sold easily.”?', '["underwriter","salability","denominate","indemnify"]'::jsonb, 1, 'salability (/ˌseɪləˈbɪləti/) → tính dễ bán; khả năng tiêu thụ trên thị trường', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_12', 'en-c2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person or organisation that accepts insurance risks.”?', '["indemnify","underwriter","salability","bushel"]'::jsonb, 1, 'underwriter (/ˈʌndɚraɪtɚ/) → người hoặc tổ chức nhận bảo hiểm; bên bảo hiểm', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_13', 'en-c2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Transfer goods from one ship or vehicle to another.”?', '["short-weight","underwriter","burgeon","transship"]'::jsonb, 3, 'transship (/trænˈʃɪp/) → chuyển tải; trung chuyển hàng hóa', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
