INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_18', 'en-c2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Reporting grain prices per bushel allows farmers to compare market conditions before deciding when to sell their crops.', 'Dựa vào câu trên, từ “bushel” có nghĩa phù hợp nhất là gì?', '["đầu hàng; khuất phục; nhượng bộ","bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc)","bán thiếu cân; gian lận trọng lượng","thấu hiểu; thăm dò sâu; khảo sát kỹ"]'::jsonb, 1, 'bushel: bồ (đơn vị đo lường thể tích chất khô, đặc biệt dùng cho ngũ cốc). Dịch cả câu: Việc báo cáo giá ngũ cốc tính theo mỗi bồ cho phép nông dân so sánh tình hình thị trường trước khi quyết định thời điểm bán nông sản.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_19', 'en-c2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Without adequate social protection, prolonged unemployment can push vulnerable households into penury and damage their health.', 'Dựa vào câu trên, từ “penury” có nghĩa phù hợp nhất là gì?', '["đặc trưng; tiêu biểu","khoáng vật vàng giả, quặng pyrit (một loại khoáng sản màu vàng sáng chứa sắt và lưu huỳnh)","du dương; êm tai; ngọt ngào","tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng"]'::jsonb, 3, 'penury: tình trạng túng quẫn; sự nghèo đói cùng cực; cảnh bần cùng. Dịch cả câu: Nếu không có sự bảo vệ xã hội đầy đủ, tình trạng thất nghiệp kéo dài có thể đẩy các hộ gia đình dễ bị tổn thương vào cảnh bần cùng và tổn hại đến sức khỏe của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_20', 'en-c2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Demand for online courses has burgeoned as more adults seek flexible opportunities to develop professional skills.', 'Dựa vào câu trên, từ “burgeon” có nghĩa phù hợp nhất là gì?', '["đã nói ở trên; kể trên; trước đó","cần sức mạnh lớn; gian khổ","được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh","phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh"]'::jsonb, 3, 'burgeon: phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh. Dịch cả câu: Nhu cầu về các khóa học trực tuyến đã tăng trưởng mạnh mẽ khi ngày càng có nhiều người lớn tìm kiếm cơ hội linh hoạt để nâng cao kỹ năng nghề nghiệp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_21', 'en-c2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should disburse emergency funds quickly to help communities recover from natural disasters.', 'Dựa vào câu trên, từ “disburse” có nghĩa phù hợp nhất là gì?', '["ngành từ điển học; việc biên soạn từ điển","toàn thể; họp toàn thể","bãi bỏ; hủy bỏ (luật, thỏa thuận)","chi trả tiền, đặc biệt là tiền từ một quỹ chính thức"]'::jsonb, 3, 'disburse: chi trả tiền, đặc biệt là tiền từ một quỹ chính thức. Dịch cả câu: Chính phủ nên nhanh chóng giải ngân các quỹ khẩn cấp để giúp các cộng đồng phục hồi sau thảm họa thiên nhiên.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_22', 'en-c2-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiền niên kim; bảo hiểm niên kim”', '["yoke","paraphernalia","annuity","characteristical"]'::jsonb, 2, 'tiền niên kim; bảo hiểm niên kim → annuity (/əˈnuːəti/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_23', 'en-c2-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuế; thuế quan”', '["impost","odyssey","intimation","transship"]'::jsonb, 0, 'thuế; thuế quan → impost (/ˈɪmpoʊst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_10_24', 'en-c2-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gây thiệt hại nặng nề; phá sản”', '["pervert","contemptuous","vehement","ruinous"]'::jsonb, 3, 'gây thiệt hại nặng nề; phá sản → ruinous (/ˈruːɪnəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-11', 'en', 'Bài 11: Chính phủ & Pháp luật - CEFR C2', 'CEFR C2', 'C2 · Chính phủ & Pháp luật', '22 từ vựng Tiếng Anh CEFR C2 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6011, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reactionary', 'en-c2-11', 'reactionary', '/riˈækʃəneri/', 'C2', 'phản động; cực kỳ bảo thủ; kẻ phản động; người theo chủ nghĩa bảo thủ cực đoan', 'adj.', 'reaction (n.), react (v.)', 'Đồng nghĩa: ultraconservative · Trái nghĩa: progressive', 'Thường mang sắc thái chê bai, nhấn mạnh việc muốn khôi phục chế độ cũ; không đồng nghĩa với reactive.', 'My uncle called the proposal reactionary and unfair.', NULL, 'Chú tôi gọi đề xuất đó là phản động và bất công.', '{"wordId":"reactionary","ukIpa":"/riˈækʃənəri/","usIpa":"/riˈækʃəneri/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"opposing social progress and wanting older political arrangements restored","vi":"phản động; cực kỳ bảo thủ"},{"pos":"n.","en":"someone who opposes progress and favours restoring older political arrangements","vi":"kẻ phản động; người theo chủ nghĩa bảo thủ cực đoan"}],"examples":[{"en":"My uncle called the proposal reactionary and unfair.","vi":"Chú tôi gọi đề xuất đó là phản động và bất công.","audioKind":"ex"},{"en":"Critics argue that reactionary policies can reverse social progress by restoring outdated restrictions on individual freedom.","vi":"Các nhà phê bình lập luận rằng các chính sách phản động có thể làm đảo ngược tiến bộ xã hội bằng cách khôi phục lại các hạn chế lỗi thời đối với tự do cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"reactionary policies","vi":"chính sách phản động"},{"en":"reactionary views","vi":"quan điểm cực kỳ bảo thủ"},{"en":"reactionary forces","vi":"lực lượng phản động"}],"wordFamily":["reaction (n.)","react (v.)"],"synonyms":["ultraconservative"],"antonyms":["progressive"],"tipVi":"Thường mang sắc thái chê bai, nhấn mạnh việc muốn khôi phục chế độ cũ; không đồng nghĩa với reactive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adjudicate', 'en-c2-11', 'adjudicate', '/əˈdʒuːdɪkeɪt/', 'C2', 'đưa ra quyết định chính thức về một tranh chấp; làm trọng tài hoặc chấm thi các màn biểu diễn hoặc bài dự thi trong một cuộc thi', 'v.', 'adjudication (n.), adjudicator (n.)', 'Đồng nghĩa: judge, arbitrate', 'Có thể kết hợp trực tiếp với danh từ chỉ tranh chấp hoặc dùng ''adjudicate on''; từ này không chỉ riêng việc tuyên án hình sự.', 'An independent expert will adjudicate our dispute over the repairs.', NULL, 'Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.', '{"wordId":"adjudicate","ukIpa":"/əˈdʒuːdɪkeɪt/","usIpa":"/əˈdʒuːdɪkeɪt/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"To make an official decision about a dispute","vi":"đưa ra quyết định chính thức về một tranh chấp"},{"pos":"v.","en":"To judge performances or entries in a competition","vi":"làm trọng tài hoặc chấm thi các màn biểu diễn hoặc bài dự thi trong một cuộc thi"}],"examples":[{"en":"An independent expert will adjudicate our dispute over the repairs.","vi":"Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.","audioKind":"ex"},{"en":"Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.","vi":"Các cơ quan độc lập nên phân xử các tranh chấp giữa người tiêu dùng và doanh nghiệp để đảm bảo rằng các khiếu nại được xử lý công bằng và nhất quán.","audioKind":"ex2"}],"collocations":[{"en":"adjudicate a dispute","vi":"phân xử một tranh chấp"},{"en":"adjudicate on a claim","vi":"đưa ra phán quyết về một yêu cầu bồi thường"},{"en":"adjudicate a competition","vi":"làm giám khảo một cuộc thi"}],"wordFamily":["adjudication (n.)","adjudicator (n.)"],"synonyms":["judge","arbitrate"],"antonyms":[],"tipVi":"Có thể kết hợp trực tiếp với danh từ chỉ tranh chấp hoặc dùng ''adjudicate on''; từ này không chỉ riêng việc tuyên án hình sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transgress', 'en-c2-11', 'transgress', '/trænzˈɡres/', 'C2', 'phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức', 'v.', 'transgression (n.), transgressor (n.)', 'Đồng nghĩa: violate, infringe · Trái nghĩa: obey', 'Từ mang tính trang trọng, có thể đi trực tiếp với các tân ngữ như law hoặc rules.', 'Players who transgress the rules may leave the game.', NULL, 'Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.', '{"wordId":"transgress","ukIpa":"/trænzˈɡres/","usIpa":"/trænzˈɡres/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"to break a law, rule, or moral boundary","vi":"phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức"}],"examples":[{"en":"Players who transgress the rules may leave the game.","vi":"Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.","audioKind":"ex"},{"en":"Companies that transgress environmental laws should face penalties proportionate to the damage they cause.","vi":"Các công ty vi phạm luật môi trường phải đối mặt với các hình phạt tương xứng với thiệt hại mà họ gây ra.","audioKind":"ex2"}],"collocations":[{"en":"transgress the law","vi":"phạm pháp"},{"en":"transgress moral boundaries","vi":"vượt qua ranh giới đạo đức"},{"en":"transgress social norms","vi":"vi phạm các chuẩn mực xã hội"}],"wordFamily":["transgression (n.)","transgressor (n.)"],"synonyms":["violate","infringe"],"antonyms":["obey"],"tipVi":"Từ mang tính trang trọng, có thể đi trực tiếp với các tân ngữ như law hoặc rules.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aforesaid', 'en-c2-11', 'aforesaid', '/əˈfɔːrsed/', 'C2', 'đã nói ở trên; kể trên; trước đó', 'adj.', NULL, 'Đồng nghĩa: aforementioned', 'Thuộc ngôn ngữ pháp lý hoặc văn bản trang trọng, thường được đặt trước danh từ.', 'The contract says we must pay the aforesaid fee.', NULL, 'Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.', '{"wordId":"aforesaid","ukIpa":"/əˈfɔːsed/","usIpa":"/əˈfɔːrsed/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"previously mentioned in the same document or statement","vi":"đã nói ở trên; kể trên; trước đó"}],"examples":[{"en":"The contract says we must pay the aforesaid fee.","vi":"Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.","audioKind":"ex"},{"en":"The aforesaid conditions must be satisfied before the council can approve any construction within the protected area.","vi":"Các điều kiện đã nêu ở trên phải được đáp ứng trước khi hội đồng có thể phê duyệt bất kỳ công trình xây dựng nào trong khu vực được bảo vệ.","audioKind":"ex2"}],"collocations":[{"en":"the aforesaid conditions","vi":"các điều kiện kể trên"},{"en":"the aforesaid agreement","vi":"thỏa thuận nêu trên"},{"en":"the aforesaid property","vi":"bất động sản nói trên"}],"wordFamily":[],"synonyms":["aforementioned"],"antonyms":[],"tipVi":"Thuộc ngôn ngữ pháp lý hoặc văn bản trang trọng, thường được đặt trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pacific', 'en-c2-11', 'pacific', '/pəˈsɪfɪk/', 'C2', 'ôn hòa; hòa bình; chuộng hòa bình', 'adj.', 'pacify (v.), pacification (n.), pacifist (n.)', 'Đồng nghĩa: peaceful, peaceable · Trái nghĩa: aggressive, belligerent', 'Khi viết chữ thường, pacific là tính từ mang nghĩa ôn hòa, chuộng hòa bình; khi viết hoa the Pacific thì chỉ Thái Bình Dương.', 'Her pacific manner helped calm the argument at dinner.', NULL, 'Thái độ điềm đạm của cô ấy đã giúp xoa dịu cuộc tranh cãi trong bữa tối.', '{"wordId":"pacific","ukIpa":"/pəˈsɪfɪk/","usIpa":"/pəˈsɪfɪk/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"Peaceful in nature or intended to avoid conflict","vi":"ôn hòa; hòa bình; chuộng hòa bình"}],"examples":[{"en":"Her pacific manner helped calm the argument at dinner.","vi":"Thái độ điềm đạm của cô ấy đã giúp xoa dịu cuộc tranh cãi trong bữa tối.","audioKind":"ex"},{"en":"A pacific approach to international disputes prioritises negotiation and cooperation rather than threats or military action.","vi":"Cách tiếp cận hòa bình đối với các tranh chấp quốc tế ưu tiên đàm phán và hợp tác hơn là các biện pháp đe dọa hoặc hành động quân sự.","audioKind":"ex2"}],"collocations":[{"en":"pacific approach","vi":"phương pháp giải quyết hòa bình"},{"en":"pacific settlement","vi":"sự dàn xếp hòa bình"},{"en":"pacific intentions","vi":"ý định hòa bình"}],"wordFamily":["pacify (v.)","pacification (n.)","pacifist (n.)"],"synonyms":["peaceful","peaceable"],"antonyms":["aggressive","belligerent"],"tipVi":"Khi viết chữ thường, pacific là tính từ mang nghĩa ôn hòa, chuộng hòa bình; khi viết hoa the Pacific thì chỉ Thái Bình Dương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tyrannical', 'en-c2-11', 'tyrannical', '/tɪˈrænɪkəl/', 'C2', 'bạo ngược; chuyên quyền; độc đoán', 'adj.', 'tyrant (n.), tyranny (n.), tyrannise (v.), tyrannically (adv.)', 'Đồng nghĩa: despotic, oppressive, dictatorial · Trái nghĩa: benevolent', 'Không chỉ chỉ sự bạo ngược trong chính trị, mà còn có thể dùng để mô tả hành vi độc đoán của sếp hoặc những người khác.', 'The club members finally challenged their tyrannical leader.', NULL, 'Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ.', '{"wordId":"tyrannical","ukIpa":"/tɪˈrænɪkəl/","usIpa":"/tɪˈrænɪkəl/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"Using power cruelly and unfairly to control others.","vi":"bạo ngược; chuyên quyền; độc đoán"}],"examples":[{"en":"The club members finally challenged their tyrannical leader.","vi":"Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ.","audioKind":"ex"},{"en":"Independent courts can help prevent tyrannical rule by limiting government power and protecting basic rights.","vi":"Các tòa án độc lập có thể giúp ngăn chặn sự cai trị bạo ngược bằng cách giới hạn quyền lực của chính phủ và bảo vệ các quyền cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"a tyrannical ruler","vi":"một nhà cai trị bạo ngược"},{"en":"tyrannical rule","vi":"sự cai trị độc đoán"},{"en":"a tyrannical boss","vi":"một người sếp chuyên quyền"}],"wordFamily":["tyrant (n.)","tyranny (n.)","tyrannise (v.)","tyrannically (adv.)"],"synonyms":["despotic","oppressive","dictatorial"],"antonyms":["benevolent"],"tipVi":"Không chỉ chỉ sự bạo ngược trong chính trị, mà còn có thể dùng để mô tả hành vi độc đoán của sếp hoặc những người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pursuant', 'en-c2-11', 'pursuant', '/pərˈsuːənt/', 'C2', 'theo; chiểu theo; dựa theo', 'adj.', NULL, NULL, 'Hầu như luôn đi với pursuant to, thường gặp trong các văn bản pháp lý và trang trọng.', 'Pursuant to our agreement, your deposit will be refunded.', NULL, 'Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.', '{"wordId":"pursuant","ukIpa":"/pəˈsjuːənt/","usIpa":"/pərˈsuːənt/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"in accordance with a law, rule, or agreement","vi":"theo; chiểu theo; dựa theo"}],"examples":[{"en":"Pursuant to our agreement, your deposit will be refunded.","vi":"Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.","audioKind":"ex"},{"en":"Pursuant to environmental regulations, factories must treat wastewater before releasing it into local rivers.","vi":"Theo các quy định về môi trường, các nhà máy phải xử lý nước thải trước khi xả ra các con sông địa phương.","audioKind":"ex2"}],"collocations":[{"en":"pursuant to an agreement","vi":"theo thỏa thuận"},{"en":"pursuant to regulations","vi":"chiểu theo quy định"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Hầu như luôn đi với pursuant to, thường gặp trong các văn bản pháp lý và trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_libertarian', 'en-c2-11', 'libertarian', '/ˌlɪbərˈteriən/', 'C2', 'người theo chủ nghĩa tự do cá nhân; thuộc chủ nghĩa tự do cá nhân', 'n.', 'libertarianism (n.), liberty (n.)', NULL, 'Nhấn mạnh tự do cá nhân và sự can thiệp tối thiểu của nhà nước, không đồng nghĩa với "liberal".', 'My neighbour is a libertarian who values personal choice.', NULL, 'Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.', '{"wordId":"libertarian","ukIpa":"/ˌlɪbəˈteəriən/","usIpa":"/ˌlɪbərˈteriən/","cefr":"C2","topic":"government","senses":[{"pos":"n.","en":"Someone favouring individual freedom and minimal government control","vi":"người theo chủ nghĩa tự do cá nhân"},{"pos":"adj.","en":"Favouring individual freedom and minimal government control","vi":"thuộc chủ nghĩa tự do cá nhân"}],"examples":[{"en":"My neighbour is a libertarian who values personal choice.","vi":"Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.","audioKind":"ex"},{"en":"A libertarian approach to economic policy generally favours reducing government intervention and expanding individual choice.","vi":"Định hướng chính sách kinh tế theo chủ nghĩa tự do cá nhân thường ủng hộ việc giảm thiểu sự can thiệp của chính phủ và mở rộng quyền lựa chọn của cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"libertarian views","vi":"quan điểm tự do cá nhân"},{"en":"libertarian principles","vi":"nguyên tắc tự do cá nhân"},{"en":"a libertarian approach","vi":"tiếp cận theo hướng tự do cá nhân"}],"wordFamily":["libertarianism (n.)","liberty (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh tự do cá nhân và sự can thiệp tối thiểu của nhà nước, không đồng nghĩa với \"liberal\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_therewith', 'en-c2-11', 'therewith', '/ˌðerˈwɪð/', 'C2', 'cùng với vật đó; ngay sau đó', 'adv.', NULL, NULL, 'Là từ cổ hoặc từ dùng trong pháp lý; hàng ngày nên dùng with it hoặc along with it.', 'She handed him the parcel and a ribbon therewith.', NULL, 'Cô ấy đưa cho anh ấy bưu phẩm cùng với một dải ruy băng.', '{"wordId":"therewith","ukIpa":"/ˌðeəˈwɪð/","usIpa":"/ˌðerˈwɪð/","cefr":"C2","topic":"government","senses":[{"pos":"adv.","en":"with that thing or together with it","vi":"cùng với vật đó"},{"pos":"adv.","en":"immediately after that","vi":"ngay sau đó"}],"examples":[{"en":"She handed him the parcel and a ribbon therewith.","vi":"Cô ấy đưa cho anh ấy bưu phẩm cùng với một dải ruy băng.","audioKind":"ex"},{"en":"Applicants must submit the completed form and all supporting documents therewith before the committee considers their request.","vi":"Người nộp đơn phải nộp mẫu đơn đã điền hoàn chỉnh cùng với tất cả các tài liệu minh chứng đi kèm trước khi hội đồng xem xét yêu cầu của họ.","audioKind":"ex2"}],"collocations":[{"en":"documents submitted therewith","vi":"tài liệu nộp kèm theo"},{"en":"costs associated therewith","vi":"chi phí phát sinh liên quan"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là từ cổ hoặc từ dùng trong pháp lý; hàng ngày nên dùng with it hoặc along with it.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irrevocable', 'en-c2-11', 'irrevocable', '/ɪˈrevəkəbl/', 'C2', 'không thể đảo ngược; không thể thay đổi hoặc rút lại', 'adj.', 'irrevocably (adv.), revocable (adj.), revoke (v.), revocation (n.)', 'Đồng nghĩa: irreversible, unalterable · Trái nghĩa: revocable', 'Thường bổ nghĩa cho quyết định, sự đồng thuận hoặc cam kết, nhấn mạnh tính không thể thu hồi.', 'Once you sign, your decision becomes legally irrevocable.', NULL, 'Một khi bạn đã ký, quyết định của bạn sẽ có hiệu lực pháp lý không thể đảo ngược.', '{"wordId":"irrevocable","ukIpa":"/ɪˈrevəkəbl/","usIpa":"/ɪˈrevəkəbl/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"Impossible to change, cancel, or take back.","vi":"không thể đảo ngược; không thể thay đổi hoặc rút lại"}],"examples":[{"en":"Once you sign, your decision becomes legally irrevocable.","vi":"Một khi bạn đã ký, quyết định của bạn sẽ có hiệu lực pháp lý không thể đảo ngược.","audioKind":"ex"},{"en":"Governments should consult local communities before making irrevocable decisions about the destruction of historic buildings.","vi":"Chính phủ nên tham vấn cộng đồng địa phương trước khi đưa ra các quyết định không thể thay đổi về việc phá dỡ các tòa nhà lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"an irrevocable decision","vi":"quyết định không thể đảo ngược"},{"en":"irrevocable consent","vi":"sự đồng thuận không thể rút lại"},{"en":"an irrevocable commitment","vi":"cam kết không thể thay đổi"}],"wordFamily":["irrevocably (adv.)","revocable (adj.)","revoke (v.)","revocation (n.)"],"synonyms":["irreversible","unalterable"],"antonyms":["revocable"],"tipVi":"Thường bổ nghĩa cho quyết định, sự đồng thuận hoặc cam kết, nhấn mạnh tính không thể thu hồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exoneration', 'en-c2-11', 'exoneration', '/ɪɡˌzɑːnəˈreɪʃən/', 'C2', 'sự minh oan, việc chính thức tuyên bố ai đó vô tội hoặc không phải chịu trách nhiệm', 'n.', 'exonerate (v.)', 'Đồng nghĩa: vindication', 'Nhấn mạnh việc chứng minh vô tội hoặc không chịu trách nhiệm; pardon nghĩa là ân xá.', 'Her exoneration brought relief to the whole family.', NULL, 'Việc cô ấy được minh oan đã mang lại sự nhẹ nhõm cho cả gia đình.', '{"wordId":"exoneration","ukIpa":"/ɪɡˌzɒnəˈreɪʃən/","usIpa":"/ɪɡˌzɑːnəˈreɪʃən/","cefr":"C2","topic":"government","senses":[{"pos":"n.","en":"An official finding that someone is not guilty or responsible.","vi":"sự minh oan, việc chính thức tuyên bố ai đó vô tội hoặc không phải chịu trách nhiệm"}],"examples":[{"en":"Her exoneration brought relief to the whole family.","vi":"Việc cô ấy được minh oan đã mang lại sự nhẹ nhõm cho cả gia đình.","audioKind":"ex"},{"en":"The exoneration of wrongly convicted individuals demonstrates why legal systems must allow new evidence to be reviewed.","vi":"Việc minh oan cho những cá nhân bị kết án oan cho thấy lý do tại sao hệ thống pháp luật phải cho phép xem xét lại các bằng chứng mới.","audioKind":"ex2"}],"collocations":[{"en":"complete exoneration","vi":"sự minh oan hoàn toàn"},{"en":"seek exoneration","vi":"tìm kiếm sự minh oan"},{"en":"lead to exoneration","vi":"dẫn đến việc được minh oan"}],"wordFamily":["exonerate (v.)"],"synonyms":["vindication"],"antonyms":[],"tipVi":"Nhấn mạnh việc chứng minh vô tội hoặc không chịu trách nhiệm; pardon nghĩa là ân xá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capitulate', 'en-c2-11', 'capitulate', '/kəˈpɪtʃuleɪt/', 'C2', 'đầu hàng; khuất phục; nhượng bộ', 'v.', 'capitulation (n.)', 'Đồng nghĩa: surrender, yield, submit · Trái nghĩa: resist', 'Động từ không có tân ngữ trực tiếp; khi khuất phục ai hoặc áp lực nào dùng capitulate to.', 'After hours of arguing, we capitulated and ordered pizza.', NULL, 'Sau nhiều giờ tranh luận, cuối cùng chúng tôi đã nhượng bộ và gọi pizza.', '{"wordId":"capitulate","ukIpa":"/kəˈpɪtʃuleɪt/","usIpa":"/kəˈpɪtʃuleɪt/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"to stop resisting and accept another person''s demands","vi":"đầu hàng; khuất phục; nhượng bộ"}],"examples":[{"en":"After hours of arguing, we capitulated and ordered pizza.","vi":"Sau nhiều giờ tranh luận, cuối cùng chúng tôi đã nhượng bộ và gọi pizza.","audioKind":"ex"},{"en":"Governments should not capitulate to commercial pressure when public health and environmental protection are at stake.","vi":"Chính phủ không nên khuất phục trước áp lực thương mại khi sức khỏe cộng đồng và bảo vệ môi trường bị đe dọa.","audioKind":"ex2"}],"collocations":[{"en":"capitulate to pressure","vi":"nhượng bộ trước áp lực"},{"en":"capitulate to demands","vi":"chấp nhận yêu cầu"}],"wordFamily":["capitulation (n.)"],"synonyms":["surrender","yield","submit"],"antonyms":["resist"],"tipVi":"Động từ không có tân ngữ trực tiếp; khi khuất phục ai hoặc áp lực nào dùng capitulate to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accede', 'en-c2-11', 'accede', '/əkˈsiːd/', 'C2', 'đồng ý; ưng thuận (đề nghị, yêu cầu); lên ngôi; nhậm chức (vị trí quyền lực quan trọng)', 'v.', 'accession (n.)', 'Đồng nghĩa: agree, consent · Trái nghĩa: refuse', 'Từ trang trọng, thường đi với giới từ to; tránh nhầm lẫn với exceed (vượt quá).', 'The landlord finally acceded to our request for repairs.', NULL, 'Cuối cùng, chủ nhà cũng đã đồng ý với yêu cầu sửa chữa của chúng tôi.', '{"wordId":"accede","ukIpa":"/əkˈsiːd/","usIpa":"/əkˈsiːd/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"to formally agree to a request, demand, or proposal","vi":"đồng ý; ưng thuận (đề nghị, yêu cầu)"},{"pos":"v.","en":"to take an important official position, especially as a ruler","vi":"lên ngôi; nhậm chức (vị trí quyền lực quan trọng)"}],"examples":[{"en":"The landlord finally acceded to our request for repairs.","vi":"Cuối cùng, chủ nhà cũng đã đồng ý với yêu cầu sửa chữa của chúng tôi.","audioKind":"ex"},{"en":"Governments may accede to public demands for greater transparency when trust in national institutions declines.","vi":"Chính phủ có thể đáp ứng các yêu cầu đòi minh bạch hơn từ công chúng khi niềm tin vào các cơ quan quốc gia suy giảm.","audioKind":"ex2"}],"collocations":[{"en":"accede to a request","vi":"chấp thuận một yêu cầu"},{"en":"accede to demands","vi":"đồng ý với các yêu cầu"},{"en":"accede to the throne","vi":"lên ngôi vua"}],"wordFamily":["accession (n.)"],"synonyms":["agree","consent"],"antonyms":["refuse"],"tipVi":"Từ trang trọng, thường đi với giới từ to; tránh nhầm lẫn với exceed (vượt quá).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thereof', 'en-c2-11', 'thereof', '/ˌðerˈʌv/', 'C2', 'của cái đó; thuộc về cái vừa nhắc đến', 'adv.', NULL, NULL, 'Mang nghĩa of that, thường thấy trong văn bản pháp lý, không giống với từ therefore.', 'We discussed dinner plans, or rather the lack thereof.', NULL, 'Chúng tôi bàn về kế hoạch ăn tối, hoặc đúng hơn là sự thiếu vắng hoàn toàn các kế hoạch đó.', '{"wordId":"thereof","ukIpa":"/ˌðeərˈɒv/","usIpa":"/ˌðerˈʌv/","cefr":"C2","topic":"government","senses":[{"pos":"adv.","en":"of or relating to the thing just mentioned","vi":"của cái đó; thuộc về cái vừa nhắc đến"}],"examples":[{"en":"We discussed dinner plans, or rather the lack thereof.","vi":"Chúng tôi bàn về kế hoạch ăn tối, hoặc đúng hơn là sự thiếu vắng hoàn toàn các kế hoạch đó.","audioKind":"ex"},{"en":"Access to public transport, or the lack thereof, strongly influences employment opportunities in rural communities.","vi":"Việc tiếp cận phương tiện giao thông công cộng, hay sự thiếu vắng các phương tiện ấy, tác động mạnh mẽ đến cơ hội việc làm ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"lack thereof","vi":"sự thiếu vắng cái đó"},{"en":"parts thereof","vi":"các phần của cái đó"},{"en":"any portion thereof","vi":"bất kỳ phần nào của cái đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mang nghĩa of that, thường thấy trong văn bản pháp lý, không giống với từ therefore.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plenary', 'en-c2-11', 'plenary', '/ˈpliːnəri/', 'C2', 'toàn thể; họp toàn thể; buổi họp toàn thể; toàn quyền; hoàn toàn không hạn chế', 'adj.', NULL, NULL, 'Trong ngữ cảnh hội họp, từ này chỉ sự tham gia của tất cả thành viên; plenary powers nghĩa là toàn quyền.', 'All workshop groups joined the plenary session after lunch.', NULL, 'Tất cả các nhóm hội thảo đã tham gia phiên họp toàn thể sau bữa trưa.', '{"wordId":"plenary","ukIpa":"/ˈpliːnəri/","usIpa":"/ˈpliːnəri/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"Involving all members of a group or meeting.","vi":"toàn thể; họp toàn thể"},{"pos":"n.","en":"A meeting attended by all participants in a larger event.","vi":"buổi họp toàn thể"},{"pos":"adj.","en":"Complete or unrestricted, especially concerning official power.","vi":"toàn quyền; hoàn toàn không hạn chế"}],"examples":[{"en":"All workshop groups joined the plenary session after lunch.","vi":"Tất cả các nhóm hội thảo đã tham gia phiên họp toàn thể sau bữa trưa.","audioKind":"ex"},{"en":"During the plenary debate, delegates discussed how international cooperation could improve access to clean drinking water.","vi":"Trong phiên thảo luận toàn thể, các đại biểu đã bàn luận về việc hợp tác quốc tế có thể cải thiện khả năng tiếp cận nguồn nước sạch như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"plenary session","vi":"phiên họp toàn thể"},{"en":"plenary debate","vi":"cuộc tranh luận toàn thể"},{"en":"plenary powers","vi":"quyền hạn toàn quyền"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh hội họp, từ này chỉ sự tham gia của tất cả thành viên; plenary powers nghĩa là toàn quyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prerogative', 'en-c2-11', 'prerogative', '/prɪˈrɑːɡətɪv/', 'C2', 'đặc quyền; quyền riêng', 'n.', NULL, 'Đồng nghĩa: privilege, entitlement', 'Chỉ quyền lợi gắn liền với địa vị riêng, không phải quyền chung của mọi người.', 'Choosing the final design is the team leader''s prerogative.', NULL, 'Việc lựa chọn thiết kế cuối cùng là đặc quyền của nhóm trưởng.', '{"wordId":"prerogative","ukIpa":"/prɪˈrɒɡətɪv/","usIpa":"/prɪˈrɑːɡətɪv/","cefr":"C2","topic":"government","senses":[{"pos":"n.","en":"a special right belonging to a particular person or group","vi":"đặc quyền; quyền riêng"}],"examples":[{"en":"Choosing the final design is the team leader''s prerogative.","vi":"Việc lựa chọn thiết kế cuối cùng là đặc quyền của nhóm trưởng.","audioKind":"ex"},{"en":"Decisions about public spending should not be the exclusive prerogative of a small group of officials.","vi":"Các quyết định về chi tiêu công không nên trở thành đặc quyền độc tôn của một nhóm nhỏ quan chức.","audioKind":"ex2"}],"collocations":[{"en":"royal prerogative","vi":"đặc quyền hoàng gia"},{"en":"exclusive prerogative","vi":"đặc quyền riêng"},{"en":"exercise a prerogative","vi":"thực thi đặc quyền"}],"wordFamily":[],"synonyms":["privilege","entitlement"],"antonyms":[],"tipVi":"Chỉ quyền lợi gắn liền với địa vị riêng, không phải quyền chung của mọi người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inalienable', 'en-c2-11', 'inalienable', '/ɪnˈeɪliənəbl/', 'C2', 'không thể tước đoạt hoặc chuyển nhượng cho người khác', 'adj.', 'inalienably (adv.), alienable (adj.)', 'Trái nghĩa: alienable', 'Từ trang trọng, chủ yếu bổ nghĩa cho rights, nhấn mạnh bản chất không thể bị tước đoạt hay chuyển giao.', 'Our teacher explained why everyone has certain inalienable rights.', NULL, 'Giáo viên của chúng tôi giải thích lý do tại sao mọi người đều có những quyền không thể tước đoạt.', '{"wordId":"inalienable","ukIpa":"/ɪnˈeɪliənəbl/","usIpa":"/ɪnˈeɪliənəbl/","cefr":"C2","topic":"government","senses":[{"pos":"adj.","en":"impossible to take away or transfer to someone else","vi":"không thể tước đoạt hoặc chuyển nhượng cho người khác"}],"examples":[{"en":"Our teacher explained why everyone has certain inalienable rights.","vi":"Giáo viên của chúng tôi giải thích lý do tại sao mọi người đều có những quyền không thể tước đoạt.","audioKind":"ex"},{"en":"Access to basic education should be recognised as an inalienable right, regardless of a child''s background.","vi":"Quyền tiếp cận giáo dục cơ bản cần phải được công nhận là một quyền không thể tước đoạt, bất kể hoàn cảnh xuất thân của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"inalienable rights","vi":"các quyền không thể tước đoạt"},{"en":"an inalienable right to freedom","vi":"quyền tự do không thể tước đoạt"}],"wordFamily":["inalienably (adv.)","alienable (adj.)"],"synonyms":[],"antonyms":["alienable"],"tipVi":"Từ trang trọng, chủ yếu bổ nghĩa cho rights, nhấn mạnh bản chất không thể bị tước đoạt hay chuyển giao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misappropriate', 'en-c2-11', 'misappropriate', '/ˌmɪsəˈproʊprieɪt/', 'C2', 'biển thủ, thụt quĩ, lén lấy tiền hoặc tài sản được giao phó để sử dụng cho riêng mình', 'v.', 'misappropriation (n.)', 'Đồng nghĩa: embezzle', 'Từ trang trọng, thường đi với funds, nhấn mạnh việc tự ý lấy dùng cho mục đích cá nhân.', 'The treasurer misappropriated club funds to pay personal bills.', NULL, 'Thủ quỹ đã biển thủ quỹ của câu lạc bộ để thanh toán các hóa đơn cá nhân.', '{"wordId":"misappropriate","ukIpa":"/ˌmɪsəˈprəʊprieɪt/","usIpa":"/ˌmɪsəˈproʊprieɪt/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"To dishonestly take entrusted money or property for your own use.","vi":"biển thủ, thụt quĩ, lén lấy tiền hoặc tài sản được giao phó để sử dụng cho riêng mình"}],"examples":[{"en":"The treasurer misappropriated club funds to pay personal bills.","vi":"Thủ quỹ đã biển thủ quỹ của câu lạc bộ để thanh toán các hóa đơn cá nhân.","audioKind":"ex"},{"en":"Independent audits help prevent officials from misappropriating public funds intended for essential services such as healthcare and education.","vi":"Các cuộc kiểm toán độc lập giúp ngăn chặn các quan chức biển thủ công quỹ vốn dành cho các dịch vụ thiết yếu như y tế và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"misappropriate funds","vi":"biển thủ quỹ"},{"en":"misappropriate public money","vi":"biển thủ công quỹ"},{"en":"misappropriate assets","vi":"chiếm đoạt tài sản"}],"wordFamily":["misappropriation (n.)"],"synonyms":["embezzle"],"antonyms":[],"tipVi":"Từ trang trọng, thường đi với funds, nhấn mạnh việc tự ý lấy dùng cho mục đích cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_countermand', 'en-c2-11', 'countermand', '/ˌkaʊntɚˈmænd/', 'C2', 'hủy bỏ lệnh; thu hồi chỉ thị', 'v.', NULL, 'Đồng nghĩa: revoke, rescind, cancel · Trái nghĩa: issue', 'Là từ mang phong cách trang trọng, đi kèm với tân ngữ thường là "order" hoặc "instruction".', 'The manager countermanded the order to close the shop.', NULL, 'Người quản lý đã thu hồi lệnh đóng cửa cửa hàng.', '{"wordId":"countermand","ukIpa":"/ˌkaʊntəˈmɑːnd/","usIpa":"/ˌkaʊntɚˈmænd/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"to officially cancel an earlier order","vi":"hủy bỏ lệnh; thu hồi chỉ thị"}],"examples":[{"en":"The manager countermanded the order to close the shop.","vi":"Người quản lý đã thu hồi lệnh đóng cửa cửa hàng.","audioKind":"ex"},{"en":"Local officials may countermand evacuation orders only when reliable evidence shows that the danger has passed.","vi":"Các quan chức địa phương chỉ có thể hủy bỏ lệnh sơ tán khi có bằng chứng đáng tin cậy cho thấy nguy cơ đã qua đi.","audioKind":"ex2"}],"collocations":[{"en":"countermand an order","vi":"hủy bỏ một mệnh lệnh"},{"en":"countermand an instruction","vi":"thu hồi một chỉ thị"}],"wordFamily":[],"synonyms":["revoke","rescind","cancel"],"antonyms":["issue"],"tipVi":"Là từ mang phong cách trang trọng, đi kèm với tân ngữ thường là \"order\" hoặc \"instruction\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hereof', 'en-c2-11', 'hereof', '/ˌhɪrˈʌv/', 'C2', 'của văn bản này; liên quan đến tài liệu này', 'adv.', NULL, NULL, 'Từ dùng trong văn phong pháp lý, tương đương với of this, không đồng nghĩa với here.', 'Our lease says, “Keep a copy hereof for your records.”', NULL, 'Hợp đồng thuê nhà của chúng tôi ghi rằng: “Hãy giữ một bản sao của văn bản này để làm hồ sơ lưu trữ.”', '{"wordId":"hereof","ukIpa":"/ˌhɪərˈɒv/","usIpa":"/ˌhɪrˈʌv/","cefr":"C2","topic":"government","senses":[{"pos":"adv.","en":"Of this document, statement, or matter.","vi":"của văn bản này; liên quan đến tài liệu này"}],"examples":[{"en":"Our lease says, “Keep a copy hereof for your records.”","vi":"Hợp đồng thuê nhà của chúng tôi ghi rằng: “Hãy giữ một bản sao của văn bản này để làm hồ sơ lưu trữ.”","audioKind":"ex"},{"en":"The housing agreement states that the provisions hereof apply equally to all tenants in the building.","vi":"Thỏa thuận nhà ở quy định rằng các điều khoản của văn bản này áp dụng công bằng cho tất cả các cư dân trong tòa nhà.","audioKind":"ex2"}],"collocations":[{"en":"the provisions hereof","vi":"các điều khoản của văn bản này"},{"en":"a copy hereof","vi":"một bản sao của tài liệu này"},{"en":"the terms hereof","vi":"các điều kiện của văn bản này"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ dùng trong văn phong pháp lý, tương đương với of this, không đồng nghĩa với here.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abrogate', 'en-c2-11', 'abrogate', '/ˈæbrəɡeɪt/', 'C2', 'bãi bỏ; hủy bỏ (luật, thỏa thuận)', 'v.', 'abrogation (n.)', 'Đồng nghĩa: repeal, revoke, annul', 'Từ mang tính trang trọng, thường có tân ngữ là luật pháp, hiệp ước hoặc thỏa thuận.', 'The council voted to abrogate the outdated parking regulation.', NULL, 'Hội đồng đã bỏ phiếu bãi bỏ quy định đỗ xe đã lỗi thời.', '{"wordId":"abrogate","ukIpa":"/ˈæbrəɡeɪt/","usIpa":"/ˈæbrəɡeɪt/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"To officially end a law, agreement, or established right.","vi":"bãi bỏ; hủy bỏ (luật, thỏa thuận)"}],"examples":[{"en":"The council voted to abrogate the outdated parking regulation.","vi":"Hội đồng đã bỏ phiếu bãi bỏ quy định đỗ xe đã lỗi thời.","audioKind":"ex"},{"en":"Governments should not abrogate international agreements without carefully considering the consequences for regional stability and public trust.","vi":"Chính phủ không nên đơn phương bãi bỏ các hiệp định quốc tế khi chưa cân nhắc kỹ lưỡng hệ quả đối với sự ổn định khu vực và lòng tin công chúng.","audioKind":"ex2"}],"collocations":[{"en":"abrogate a treaty","vi":"bãi bỏ một hiệp ước"},{"en":"abrogate an agreement","vi":"hủy bỏ một thỏa thuận"},{"en":"abrogate a law","vi":"bãi bỏ đạo luật"}],"wordFamily":["abrogation (n.)"],"synonyms":["repeal","revoke","annul"],"antonyms":[],"tipVi":"Từ mang tính trang trọng, thường có tân ngữ là luật pháp, hiệp ước hoặc thỏa thuận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rescind', 'en-c2-11', 'rescind', '/rɪˈsɪnd/', 'C2', 'thu hồi; hủy bỏ; thủ tiêu (quyết định, quy tắc)', 'v.', 'rescission (n.)', 'Đồng nghĩa: revoke, cancel, annul', 'Là động từ mang tính trang trọng, thông thường không dùng với nghĩa hoàn tiền.', 'The club rescinded its decision to close the pool.', NULL, 'Câu lạc bộ đã hủy bỏ quyết định đóng cửa hồ bơi.', '{"wordId":"rescind","ukIpa":"/rɪˈsɪnd/","usIpa":"/rɪˈsɪnd/","cefr":"C2","topic":"government","senses":[{"pos":"v.","en":"Officially cancel a decision, agreement, or rule.","vi":"thu hồi; hủy bỏ; thủ tiêu (quyết định, quy tắc)"}],"examples":[{"en":"The club rescinded its decision to close the pool.","vi":"Câu lạc bộ đã hủy bỏ quyết định đóng cửa hồ bơi.","audioKind":"ex"},{"en":"The council agreed to rescind the parking restrictions after residents raised concerns about access to local shops.","vi":"Hội đồng đã đồng ý thu hồi các hạn chế đỗ xe sau khi cư dân bày tỏ lo ngại về việc tiếp cận các cửa hàng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"rescind a decision","vi":"thu hồi quyết định"},{"en":"rescind an offer","vi":"rút lại lời đề nghị"},{"en":"rescind a contract","vi":"hủy bỏ hợp đồng"}],"wordFamily":["rescission (n.)"],"synonyms":["revoke","cancel","annul"],"antonyms":[],"tipVi":"Là động từ mang tính trang trọng, thông thường không dùng với nghĩa hoàn tiền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_11_1', 'en-c2-11', 'Cách dùng “pacific” (adj.) — ôn hòa; hòa bình; chuộng hòa bình', 'pacific approach  ·  pacific settlement  ·  pacific intentions', 'Khi viết chữ thường, pacific là tính từ mang nghĩa ôn hòa, chuộng hòa bình; khi viết hoa the Pacific thì chỉ Thái Bình Dương.', 'Họ từ (Word Family): pacify (v.), pacification (n.), pacifist (n.) | Đồng nghĩa: peaceful, peaceable · Trái nghĩa: aggressive, belligerent', '[{"hanzi":"Her pacific manner helped calm the argument at dinner.","pinyin":"","meaning":"Thái độ điềm đạm của cô ấy đã giúp xoa dịu cuộc tranh cãi trong bữa tối."},{"hanzi":"A pacific approach to international disputes prioritises negotiation and cooperation rather than threats or military action.","pinyin":"","meaning":"Cách tiếp cận hòa bình đối với các tranh chấp quốc tế ưu tiên đàm phán và hợp tác hơn là các biện pháp đe dọa hoặc hành động quân sự."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_11_2', 'en-c2-11', 'Cách dùng “adjudicate” (v.) — đưa ra quyết định chính thức về một tranh chấp', 'adjudicate a dispute  ·  adjudicate on a claim  ·  adjudicate a competition', 'Có thể kết hợp trực tiếp với danh từ chỉ tranh chấp hoặc dùng ''adjudicate on''; từ này không chỉ riêng việc tuyên án hình sự.', 'Họ từ (Word Family): adjudication (n.), adjudicator (n.) | Đồng nghĩa: judge, arbitrate', '[{"hanzi":"An independent expert will adjudicate our dispute over the repairs.","pinyin":"","meaning":"Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa."},{"hanzi":"Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.","pinyin":"","meaning":"Các cơ quan độc lập nên phân xử các tranh chấp giữa người tiêu dùng và doanh nghiệp để đảm bảo rằng các khiếu nại được xử lý công bằng và nhất quán."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_11_3', 'en-c2-11', 'Cách dùng “tyrannical” (adj.) — bạo ngược; chuyên quyền; độc đoán', 'a tyrannical ruler  ·  tyrannical rule  ·  a tyrannical boss', 'Không chỉ chỉ sự bạo ngược trong chính trị, mà còn có thể dùng để mô tả hành vi độc đoán của sếp hoặc những người khác.', 'Họ từ (Word Family): tyrant (n.), tyranny (n.), tyrannise (v.), tyrannically (adv.) | Đồng nghĩa: despotic, oppressive, dictatorial · Trái nghĩa: benevolent', '[{"hanzi":"The club members finally challenged their tyrannical leader.","pinyin":"","meaning":"Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ."},{"hanzi":"Independent courts can help prevent tyrannical rule by limiting government power and protecting basic rights.","pinyin":"","meaning":"Các tòa án độc lập có thể giúp ngăn chặn sự cai trị bạo ngược bằng cách giới hạn quyền lực của chính phủ và bảo vệ các quyền cơ bản."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_11_4', 'en-c2-11', 'Cách dùng “plenary” (adj.) — toàn thể; họp toàn thể', 'plenary session  ·  plenary debate  ·  plenary powers', 'Trong ngữ cảnh hội họp, từ này chỉ sự tham gia của tất cả thành viên; plenary powers nghĩa là toàn quyền.', NULL, '[{"hanzi":"All workshop groups joined the plenary session after lunch.","pinyin":"","meaning":"Tất cả các nhóm hội thảo đã tham gia phiên họp toàn thể sau bữa trưa."},{"hanzi":"During the plenary debate, delegates discussed how international cooperation could improve access to clean drinking water.","pinyin":"","meaning":"Trong phiên thảo luận toàn thể, các đại biểu đã bàn luận về việc hợp tác quốc tế có thể cải thiện khả năng tiếp cận nguồn nước sạch như thế nào."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_11_1', 'en-c2-11', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
