INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_1_3', 'ten_c2_11_1', 'transgress', 'Players who transgress the rules may leave the game.', 'Players who transgress the rules may leave the game.', '/trænzˈɡres/', 'Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_1_4', 'ten_c2_11_1', 'aforesaid', 'The contract says we must pay the aforesaid fee.', 'The contract says we must pay the aforesaid fee.', '/əˈfɔːrsed/', 'Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_1_5', 'ten_c2_11_1', 'pacific', 'Her pacific manner helped calm the argument at dinner.', 'Her pacific manner helped calm the argument at dinner.', '/pəˈsɪfɪk/', 'Thái độ điềm đạm của cô ấy đã giúp xoa dịu cuộc tranh cãi trong bữa tối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_1_6', 'ten_c2_11_1', 'tyrannical', 'The club members finally challenged their tyrannical leader.', 'The club members finally challenged their tyrannical leader.', '/tɪˈrænɪkəl/', 'Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_1_7', 'ten_c2_11_1', 'pursuant', 'Pursuant to our agreement, your deposit will be refunded.', 'Pursuant to our agreement, your deposit will be refunded.', '/pərˈsuːənt/', 'Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_1_8', 'ten_c2_11_1', 'libertarian', 'My neighbour is a libertarian who values personal choice.', 'My neighbour is a libertarian who values personal choice.', '/ˌlɪbərˈteriən/', 'Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_11_1_1', 'en-c2-11', 'ten_c2_11_1', 'listening', 'listening', 'My uncle called the proposal reactionary and unfair.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người quản lý đã thu hồi lệnh đóng cửa cửa hàng.","Việc lựa chọn thiết kế cuối cùng là đặc quyền của nhóm trưởng.","Cô ấy đưa cho anh ấy bưu phẩm cùng với một dải ruy băng.","Chú tôi gọi đề xuất đó là phản động và bất công."]'::jsonb, 3, 'My uncle called the proposal reactionary and unfair. → Chú tôi gọi đề xuất đó là phản động và bất công.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_11_1_2', 'en-c2-11', 'ten_c2_11_1', 'listening', 'listening', 'An independent expert will adjudicate our dispute over the repairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.","Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.","Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.","Sau nhiều giờ tranh luận, cuối cùng chúng tôi đã nhượng bộ và gọi pizza."]'::jsonb, 1, 'An independent expert will adjudicate our dispute over the repairs. → Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_11_1_3', 'en-c2-11', 'ten_c2_11_1', 'listening', 'listening', 'Players who transgress the rules may leave the game.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hợp đồng thuê nhà của chúng tôi ghi rằng: “Hãy giữ một bản sao của văn bản này để làm hồ sơ lưu trữ.”","Câu lạc bộ đã hủy bỏ quyết định đóng cửa hồ bơi.","Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.","Thái độ điềm đạm của cô ấy đã giúp xoa dịu cuộc tranh cãi trong bữa tối."]'::jsonb, 2, 'Players who transgress the rules may leave the game. → Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_11_2', 'en-c2-11', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_2_1', 'ten_c2_11_2', 'reactionary', 'Critics argue that reactionary policies can reverse social progress by restoring outdated restrictions on individual freedom.', 'Critics argue that reactionary policies can reverse social progress by restoring outdated restrictions on individual freedom.', '/riˈækʃəneri/', 'Các nhà phê bình lập luận rằng các chính sách phản động có thể làm đảo ngược tiến bộ xã hội bằng cách khôi phục lại các hạn chế lỗi thời đối với tự do cá nhân.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_2_2', 'ten_c2_11_2', 'adjudicate', 'Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.', 'Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.', '/əˈdʒuːdɪkeɪt/', 'Các cơ quan độc lập nên phân xử các tranh chấp giữa người tiêu dùng và doanh nghiệp để đảm bảo rằng các khiếu nại được xử lý công bằng và nhất quán.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_2_3', 'ten_c2_11_2', 'transgress', 'Companies that transgress environmental laws should face penalties proportionate to the damage they cause.', 'Companies that transgress environmental laws should face penalties proportionate to the damage they cause.', '/trænzˈɡres/', 'Các công ty vi phạm luật môi trường phải đối mặt với các hình phạt tương xứng với thiệt hại mà họ gây ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_2_4', 'ten_c2_11_2', 'aforesaid', 'The aforesaid conditions must be satisfied before the council can approve any construction within the protected area.', 'The aforesaid conditions must be satisfied before the council can approve any construction within the protected area.', '/əˈfɔːrsed/', 'Các điều kiện đã nêu ở trên phải được đáp ứng trước khi hội đồng có thể phê duyệt bất kỳ công trình xây dựng nào trong khu vực được bảo vệ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_2_5', 'ten_c2_11_2', 'pacific', 'A pacific approach to international disputes prioritises negotiation and cooperation rather than threats or military action.', 'A pacific approach to international disputes prioritises negotiation and cooperation rather than threats or military action.', '/pəˈsɪfɪk/', 'Cách tiếp cận hòa bình đối với các tranh chấp quốc tế ưu tiên đàm phán và hợp tác hơn là các biện pháp đe dọa hoặc hành động quân sự.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_11_2_6', 'ten_c2_11_2', 'tyrannical', 'Independent courts can help prevent tyrannical rule by limiting government power and protecting basic rights.', 'Independent courts can help prevent tyrannical rule by limiting government power and protecting basic rights.', '/tɪˈrænɪkəl/', 'Các tòa án độc lập có thể giúp ngăn chặn sự cai trị bạo ngược bằng cách giới hạn quyền lực của chính phủ và bảo vệ các quyền cơ bản.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_11_2_1', 'en-c2-11', 'ten_c2_11_2', 'listening', 'listening', 'Critics argue that reactionary policies can reverse social progress by restoring outdated restrictions on individual freedom.', NULL, 'Trong câu vừa nghe, từ “reactionary” mang nghĩa nào sau đây?', '["phản động; cực kỳ bảo thủ","kiêu ngạo; kiêu kỳ; trịch thượng","gây thiệt hại nặng nề; phá sản","tấm đá lát; phiến đá lát đường"]'::jsonb, 0, '“reactionary” (/riˈækʃəneri/): phản động; cực kỳ bảo thủ. Câu đầy đủ: Critics argue that reactionary policies can reverse social progress by restoring outdated restrictions on individual freedom.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_11_2_2', 'en-c2-11', 'ten_c2_11_2', 'listening', 'listening', 'Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.', NULL, 'Trong câu vừa nghe, từ “adjudicate” mang nghĩa nào sau đây?', '["rải; rắc; vứt bừa bãi","thấu hiểu; thăm dò sâu; khảo sát kỹ","sự đền bù; thù lao","đưa ra quyết định chính thức về một tranh chấp"]'::jsonb, 3, '“adjudicate” (/əˈdʒuːdɪkeɪt/): đưa ra quyết định chính thức về một tranh chấp. Câu đầy đủ: Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_1', 'en-c2-11', 'My uncle called the proposal reactionary and unfair', 'Chú tôi gọi đề xuất đó là phản động và bất công.', 'reactionary /riˈækʃəneri/', '["and","My","called","proposal","uncle","unfair","the","reactionary"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_2', 'en-c2-11', 'An independent expert will adjudicate our dispute over the repairs', 'Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.', 'adjudicate /əˈdʒuːdɪkeɪt/', '["will","An","the","adjudicate","over","expert","independent","dispute","repairs","our"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_3', 'en-c2-11', 'Players who transgress the rules may leave the game', 'Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.', 'transgress /trænzˈɡres/', '["rules","game","transgress","who","may","the","the","Players","leave"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_4', 'en-c2-11', 'The contract says we must pay the aforesaid fee', 'Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.', 'aforesaid /əˈfɔːrsed/', '["contract","pay","The","says","must","we","the","fee","aforesaid"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_5', 'en-c2-11', 'Her pacific manner helped calm the argument at dinner', 'Thái độ điềm đạm của cô ấy đã giúp xoa dịu cuộc tranh cãi trong bữa tối.', 'pacific /pəˈsɪfɪk/', '["Her","manner","pacific","helped","dinner","calm","argument","at","the"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_6', 'en-c2-11', 'The club members finally challenged their tyrannical leader', 'Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ.', 'tyrannical /tɪˈrænɪkəl/', '["members","club","leader","tyrannical","The","challenged","finally","their"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_7', 'en-c2-11', 'Pursuant to our agreement, your deposit will be refunded', 'Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.', 'pursuant /pərˈsuːənt/', '["refunded","Pursuant","be","your","will","deposit","our","to","agreement"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_8', 'en-c2-11', 'My neighbour is a libertarian who values personal choice', 'Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.', 'libertarian /ˌlɪbərˈteriən/', '["My","who","libertarian","a","personal","values","choice","neighbour","is"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_9', 'en-c2-11', 'She handed him the parcel and a ribbon therewith', 'Cô ấy đưa cho anh ấy bưu phẩm cùng với một dải ruy băng.', 'therewith /ˌðerˈwɪð/', '["a","him","the","handed","ribbon","parcel","She","and","therewith"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_11_10', 'en-c2-11', 'Once you sign, your decision becomes legally irrevocable', 'Một khi bạn đã ký, quyết định của bạn sẽ có hiệu lực pháp lý không thể đảo ngược.', 'irrevocable /ɪˈrevəkəbl/', '["sign","you","Once","irrevocable","your","legally","decision","becomes"]'::jsonb, NULL, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
