INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_11_1', 'en-c2-11', 'en_to_vi', 'Pursuant to our agreement, your deposit will be refunded.', 'Pursuant to our agreement, your deposit will be refunded.', '/pərˈsuːənt/', NULL, 'Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.', NULL, '["theo","thỏa","thuận","của","chúng","ta","khoản","tiền"]'::jsonb, 'Từ trọng tâm: pursuant (theo; chiểu theo; dựa theo)', 'Pursuant to our agreement, your deposit will be refunded. → Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_11_2', 'en-c2-11', 'en_to_vi', 'My neighbour is a libertarian who values personal choice.', 'My neighbour is a libertarian who values personal choice.', '/ˌlɪbərˈteriən/', NULL, 'Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.', NULL, '["hàng","xóm","của","tôi","là","một","người","theo"]'::jsonb, 'Từ trọng tâm: libertarian (người theo chủ nghĩa tự do cá nhân)', 'My neighbour is a libertarian who values personal choice. → Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_11_3', 'en-c2-11', 'en_to_vi', 'She handed him the parcel and a ribbon therewith.', 'She handed him the parcel and a ribbon therewith.', '/ˌðerˈwɪð/', NULL, 'Cô ấy đưa cho anh ấy bưu phẩm cùng với một dải ruy băng.', NULL, '["cô","ấy","đưa","cho","anh","ấy","bưu","phẩm"]'::jsonb, 'Từ trọng tâm: therewith (cùng với vật đó)', 'She handed him the parcel and a ribbon therewith. → Cô ấy đưa cho anh ấy bưu phẩm cùng với một dải ruy băng.', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_11_4', 'en-c2-11', 'en_to_vi', 'Once you sign, your decision becomes legally irrevocable.', 'Once you sign, your decision becomes legally irrevocable.', '/ɪˈrevəkəbl/', NULL, 'Một khi bạn đã ký, quyết định của bạn sẽ có hiệu lực pháp lý không thể đảo ngược.', NULL, '["một","khi","bạn","đã","ký","quyết","định","của"]'::jsonb, 'Từ trọng tâm: irrevocable (không thể đảo ngược; không thể thay đổi hoặc rút lại)', 'Once you sign, your decision becomes legally irrevocable. → Một khi bạn đã ký, quyết định của bạn sẽ có hiệu lực pháp lý không thể đảo ngược.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_11_5', 'en-c2-11', 'en_to_vi', 'Her exoneration brought relief to the whole family.', 'Her exoneration brought relief to the whole family.', '/ɪɡˌzɑːnəˈreɪʃən/', NULL, 'Việc cô ấy được minh oan đã mang lại sự nhẹ nhõm cho cả gia đình.', NULL, '["việc","cô","ấy","được","minh","oan","đã","mang"]'::jsonb, 'Từ trọng tâm: exoneration (sự minh oan, việc chính thức tuyên bố ai đó vô tội hoặc không phải chịu trách nhiệm)', 'Her exoneration brought relief to the whole family. → Việc cô ấy được minh oan đã mang lại sự nhẹ nhõm cho cả gia đình.', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_11_6', 'en-c2-11', 'en_to_vi', 'After hours of arguing, we capitulated and ordered pizza.', 'After hours of arguing, we capitulated and ordered pizza.', '/kəˈpɪtʃuleɪt/', NULL, 'Sau nhiều giờ tranh luận, cuối cùng chúng tôi đã nhượng bộ và gọi pizza.', NULL, '["sau","nhiều","giờ","tranh","luận","cuối","cùng","chúng"]'::jsonb, 'Từ trọng tâm: capitulate (đầu hàng; khuất phục; nhượng bộ)', 'After hours of arguing, we capitulated and ordered pizza. → Sau nhiều giờ tranh luận, cuối cùng chúng tôi đã nhượng bộ và gọi pizza.', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
