INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_11_12', 'en-c2-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “capitulate” (/kəˈpɪtʃuleɪt/) có nghĩa là gì?', '["ôn hòa; hòa bình; chuộng hòa bình","bạo ngược; chuyên quyền; độc đoán","không thể tước đoạt hoặc chuyển nhượng cho người khác","đầu hàng; khuất phục; nhượng bộ"]'::jsonb, 3, '“capitulate” (v.): đầu hàng; khuất phục; nhượng bộ.', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_11_13', 'en-c2-11', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “accede” (/əkˈsiːd/) có nghĩa là gì?', '["đồng ý; ưng thuận (đề nghị, yêu cầu)","ôn hòa; hòa bình; chuộng hòa bình","biển thủ, thụt quĩ, lén lấy tiền hoặc tài sản được giao phó để sử dụng cho riêng mình","đặc quyền; quyền riêng"]'::jsonb, 0, '“accede” (v.): đồng ý; ưng thuận (đề nghị, yêu cầu); lên ngôi; nhậm chức (vị trí quyền lực quan trọng).', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_11_14', 'en-c2-11', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “of or relating to the thing just mentioned”', '["misappropriate","thereof","irrevocable","aforesaid"]'::jsonb, 1, '“thereof” (/ˌðerˈʌv/) nghĩa là: của cái đó; thuộc về cái vừa nhắc đến.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
