INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_1', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'reactionary', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kẻ ám sát; kẻ thủ ác","du dương; êm tai; ngọt ngào","sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt","phản động; cực kỳ bảo thủ"]'::jsonb, 3, 'reactionary (/riˈækʃəneri/) → phản động; cực kỳ bảo thủ; kẻ phản động; người theo chủ nghĩa bảo thủ cực đoan', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_2', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'An independent expert will adjudicate our dispute over the repairs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các cầu thủ vi phạm quy tắc có thể phải rời trận đấu.","Người quản lý đã thu hồi lệnh đóng cửa cửa hàng.","Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.","Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ."]'::jsonb, 2, 'An independent expert will adjudicate our dispute over the repairs. → Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_3', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'transgress', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chuỗi con; dãy con","sự tiếp tục; sự duy trì","giám sát; quản lý","phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức"]'::jsonb, 3, 'transgress (/trænzˈɡres/) → phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_4', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'The contract says we must pay the aforesaid fee.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.","Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.","Việc lựa chọn thiết kế cuối cùng là đặc quyền của nhóm trưởng.","Hợp đồng thuê nhà của chúng tôi ghi rằng: “Hãy giữ một bản sao của văn bản này để làm hồ sơ lưu trữ.”"]'::jsonb, 0, 'The contract says we must pay the aforesaid fee. → Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_5', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'pacific', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ôn hòa; hòa bình; chuộng hòa bình","lịch lãm; tao nhã; khéo ứng xử","rùng rợn; kinh dị (do có liên quan đến cái chết)","minh oan; chứng minh là đúng; bảo vệ chính đáng"]'::jsonb, 0, 'pacific (/pəˈsɪfɪk/) → ôn hòa; hòa bình; chuộng hòa bình', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_6', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'The club members finally challenged their tyrannical leader.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một khi bạn đã ký, quyết định của bạn sẽ có hiệu lực pháp lý không thể đảo ngược.","Một chuyên gia độc lập sẽ phân xử tranh chấp của chúng tôi về vấn đề sửa chữa.","Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ.","Việc cô ấy được minh oan đã mang lại sự nhẹ nhõm cho cả gia đình."]'::jsonb, 2, 'The club members finally challenged their tyrannical leader. → Các thành viên câu lạc bộ cuối cùng đã lên tiếng thách thức người lãnh đạo độc đoán của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_7', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'pursuant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["theo; chiểu theo; dựa theo","chuyển tải; trung chuyển hàng hóa","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm","rải; rắc; vứt bừa bãi"]'::jsonb, 0, 'pursuant (/pərˈsuːənt/) → theo; chiểu theo; dựa theo', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_8', 'en-c2-11', NULL, 'comprehensive_test', 'listening', 'My neighbour is a libertarian who values personal choice.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Theo thỏa thuận của chúng ta, khoản tiền đặt cọc của bạn sẽ được hoàn lại.","Câu lạc bộ đã hủy bỏ quyết định đóng cửa hồ bơi.","Hợp đồng quy định rằng chúng tôi phải thanh toán khoản phí đã nêu ở trên.","Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân."]'::jsonb, 3, 'My neighbour is a libertarian who values personal choice. → Hàng xóm của tôi là một người theo chủ nghĩa tự do cá nhân, rất coi trọng quyền lựa chọn của bản thân.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_9', 'en-c2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Peaceful in nature or intended to avoid conflict”?', '["prerogative","exoneration","misappropriate","pacific"]'::jsonb, 3, 'pacific (/pəˈsɪfɪk/) → ôn hòa; hòa bình; chuộng hòa bình', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_10', 'en-c2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Using power cruelly and unfairly to control others.”?', '["hereof","tyrannical","countermand","misappropriate"]'::jsonb, 1, 'tyrannical (/tɪˈrænɪkəl/) → bạo ngược; chuyên quyền; độc đoán', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_11', 'en-c2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “in accordance with a law, rule, or agreement”?', '["aforesaid","libertarian","abrogate","pursuant"]'::jsonb, 3, 'pursuant (/pərˈsuːənt/) → theo; chiểu theo; dựa theo', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_12', 'en-c2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone favouring individual freedom and minimal government control”?', '["pacific","libertarian","pursuant","aforesaid"]'::jsonb, 1, 'libertarian (/ˌlɪbərˈteriən/) → người theo chủ nghĩa tự do cá nhân', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_13', 'en-c2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “with that thing or together with it”?', '["irrevocable","reactionary","hereof","therewith"]'::jsonb, 3, 'therewith (/ˌðerˈwɪð/) → cùng với vật đó', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
