INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_18', 'en-c2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Critics argue that reactionary policies can reverse social progress by restoring outdated restrictions on individual freedom.', 'Dựa vào câu trên, từ “reactionary” có nghĩa phù hợp nhất là gì?', '["phản động; cực kỳ bảo thủ","có tính cấu thành; tạo nên bản chất","vùng nội địa; vùng sâu vùng xa","hệ số"]'::jsonb, 0, 'reactionary: phản động; cực kỳ bảo thủ; kẻ phản động; người theo chủ nghĩa bảo thủ cực đoan. Dịch cả câu: Các nhà phê bình lập luận rằng các chính sách phản động có thể làm đảo ngược tiến bộ xã hội bằng cách khôi phục lại các hạn chế lỗi thời đối với tự do cá nhân.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_19', 'en-c2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Independent bodies should adjudicate disputes between consumers and businesses to ensure that complaints receive fair and consistent treatment.', 'Dựa vào câu trên, từ “adjudicate” có nghĩa phù hợp nhất là gì?', '["nấm mốc; bệnh mốc sương","đưa ra quyết định chính thức về một tranh chấp","tách biệt; cho ở ẩn; cô lập","giám sát; quản lý"]'::jsonb, 1, 'adjudicate: đưa ra quyết định chính thức về một tranh chấp; làm trọng tài hoặc chấm thi các màn biểu diễn hoặc bài dự thi trong một cuộc thi. Dịch cả câu: Các cơ quan độc lập nên phân xử các tranh chấp giữa người tiêu dùng và doanh nghiệp để đảm bảo rằng các khiếu nại được xử lý công bằng và nhất quán.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_20', 'en-c2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Companies that transgress environmental laws should face penalties proportionate to the damage they cause.', 'Dựa vào câu trên, từ “transgress” có nghĩa phù hợp nhất là gì?', '["ai oán, thê thiết, buồn bã và mang tính than van","trêu ngươi; khơi gợi khao khát nhưng khó với tới","phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức","trong tài liệu này; ở đây; trong này"]'::jsonb, 2, 'transgress: phạm luật, quy tắc hoặc vượt qua ranh giới đạo đức. Dịch cả câu: Các công ty vi phạm luật môi trường phải đối mặt với các hình phạt tương xứng với thiệt hại mà họ gây ra.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_21', 'en-c2-11', NULL, 'comprehensive_test', 'reading', NULL, 'The aforesaid conditions must be satisfied before the council can approve any construction within the protected area.', 'Dựa vào câu trên, từ “aforesaid” có nghĩa phù hợp nhất là gì?', '["tràn ngập; lúc nhúc (sinh vật, người)","đã nói ở trên; kể trên; trước đó","nấm mốc; bệnh mốc sương","hệ thống hoặc máy truyền bản tài liệu qua đường dây điện thoại; máy fax"]'::jsonb, 1, 'aforesaid: đã nói ở trên; kể trên; trước đó. Dịch cả câu: Các điều kiện đã nêu ở trên phải được đáp ứng trước khi hội đồng có thể phê duyệt bất kỳ công trình xây dựng nào trong khu vực được bảo vệ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_22', 'en-c2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “của văn bản này; liên quan đến tài liệu này”', '["hereof","terminable","glutinous","occident"]'::jsonb, 0, 'của văn bản này; liên quan đến tài liệu này → hereof (/ˌhɪrˈʌv/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_23', 'en-c2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bãi bỏ; hủy bỏ (luật, thỏa thuận)”', '["surmise","misconceive","maim","abrogate"]'::jsonb, 3, 'bãi bỏ; hủy bỏ (luật, thỏa thuận) → abrogate (/ˈæbrəɡeɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_11_24', 'en-c2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thu hồi; hủy bỏ; thủ tiêu (quyết định, quy tắc)”', '["ramify","slay","continuance","rescind"]'::jsonb, 3, 'thu hồi; hủy bỏ; thủ tiêu (quyết định, quy tắc) → rescind (/rɪˈsɪnd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-12', 'en', 'Bài 12: Lịch sử & Văn hóa - CEFR C2', 'CEFR C2', 'C2 · Lịch sử', '13 từ vựng Tiếng Anh CEFR C2 chủ đề lịch sử & văn hóa kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6012, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_avenge', 'en-c2-12', 'avenge', '/əˈvendʒ/', 'C2', 'trả thù; rửa hận; phục thù', 'v.', 'avenger (n.)', NULL, 'avenge là động từ, thường đi liền với đối tượng hoặc sự việc bị tổn hại; revenge thường đóng vai trò danh từ.', 'Our team hopes to avenge last year''s defeat.', NULL, 'Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.', '{"wordId":"avenge","ukIpa":"/əˈvendʒ/","usIpa":"/əˈvendʒ/","cefr":"C2","topic":"history","senses":[{"pos":"v.","en":"to punish someone for harm done to yourself or others","vi":"trả thù; rửa hận; phục thù"}],"examples":[{"en":"Our team hopes to avenge last year''s defeat.","vi":"Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.","audioKind":"ex"},{"en":"Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.","vi":"Các biên niên sử lịch sử thường miêu tả các nhà lãnh đạo tìm cách trả thù cho những thất bại trong quá khứ hơn là đàm phán để đạt được hòa bình lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"avenge a defeat","vi":"rửa hận một trận thua"},{"en":"avenge a wrong","vi":"báo thù cho một bất công"}],"wordFamily":["avenger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"avenge là động từ, thường đi liền với đối tượng hoặc sự việc bị tổn hại; revenge thường đóng vai trò danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infantry', 'en-c2-12', 'infantry', '/ˈɪnfəntri/', 'C2', 'bộ binh', 'n.', 'infantryman (n.)', NULL, 'Là danh từ tập hợp chỉ lực lượng bộ binh nói chung, không dùng ''an infantry'' cho một cá nhân.', 'The infantry marched past our village early this morning.', NULL, 'Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.', '{"wordId":"infantry","ukIpa":"/ˈɪnfəntri/","usIpa":"/ˈɪnfəntri/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"soldiers trained to fight on foot","vi":"bộ binh"}],"examples":[{"en":"The infantry marched past our village early this morning.","vi":"Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.","audioKind":"ex"},{"en":"Although military technology has changed considerably, infantry still play an important role in many countries'' defence forces.","vi":"Mặc dù công nghệ quân sự đã thay đổi đáng kể, bộ binh vẫn đóng vai trò quan trọng trong lực lượng quốc phòng của nhiều quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"infantry unit","vi":"đơn vị bộ binh"},{"en":"infantry division","vi":"sư đoàn bộ binh"},{"en":"infantry training","vi":"huấn luyện bộ binh"}],"wordFamily":["infantryman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ tập hợp chỉ lực lượng bộ binh nói chung, không dùng ''an infantry'' cho một cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prophesy', 'en-c2-12', 'prophesy', '/ˈprɑːfəsaɪ/', 'C2', 'tiên tri; báo trước', 'v.', 'prophecy (n.), prophet (n.), prophetic (adj.)', 'Đồng nghĩa: predict, foretell', 'prophesy là động từ, phần cuối phát âm là /saɪ/; danh từ tương ứng là prophecy.', 'The old storyteller prophesied that the kingdom would prosper.', NULL, 'Người kể chuyện già nua tiên tri rằng vương quốc sẽ hưng thịnh.', '{"wordId":"prophesy","ukIpa":"/ˈprɒfəsaɪ/","usIpa":"/ˈprɑːfəsaɪ/","cefr":"C2","topic":"history","senses":[{"pos":"v.","en":"say what will happen, especially through claimed spiritual knowledge","vi":"tiên tri; báo trước"}],"examples":[{"en":"The old storyteller prophesied that the kingdom would prosper.","vi":"Người kể chuyện già nua tiên tri rằng vương quốc sẽ hưng thịnh.","audioKind":"ex"},{"en":"Some early commentators prophesied that television would replace books, but reading has remained an important cultural activity.","vi":"Một số nhà bình luận thời kỳ đầu từng tiên tri rằng truyền hình sẽ thay thế sách, nhưng việc đọc sách vẫn tiếp tục là một hoạt động văn hóa quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"prophesy that","vi":"tiên tri rằng"},{"en":"prophesy disaster","vi":"báo trước thảm họa"},{"en":"prophesy the future","vi":"tiên tri tương lai"}],"wordFamily":["prophecy (n.)","prophet (n.)","prophetic (adj.)"],"synonyms":["predict","foretell"],"antonyms":[],"tipVi":"prophesy là động từ, phần cuối phát âm là /saɪ/; danh từ tương ứng là prophecy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assassinator', 'en-c2-12', 'assassinator', '/əˈsæsɪneɪtər/', 'C2', 'kẻ ám sát; kẻ thủ ác', 'n.', 'assassinate (v.), assassination (n.), assassin (n.)', 'Đồng nghĩa: assassin', 'Từ này khá hiếm gặp; thông thường người ta dùng assassin để chỉ kẻ ám sát.', 'The film''s assassinator hid behind a heavy curtain.', NULL, 'Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.', '{"wordId":"assassinator","ukIpa":"/əˈsæsɪneɪtə/","usIpa":"/əˈsæsɪneɪtər/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"Someone who murders an important person, often for political reasons.","vi":"kẻ ám sát; kẻ thủ ác"}],"examples":[{"en":"The film''s assassinator hid behind a heavy curtain.","vi":"Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.","audioKind":"ex"},{"en":"The historical account examines the assassinator''s motives and the political instability that followed the killing.","vi":"Tài liệu lịch sử xem xét động cơ của kẻ ám sát và tình trạng bất ổn chính trị diễn ra sau vụ ám sát đó.","audioKind":"ex2"}],"collocations":[{"en":"a would-be assassinator","vi":"kẻ mưu sát"},{"en":"the assassinator''s motives","vi":"động cơ của kẻ ám sát"}],"wordFamily":["assassinate (v.)","assassination (n.)","assassin (n.)"],"synonyms":["assassin"],"antonyms":[],"tipVi":"Từ này khá hiếm gặp; thông thường người ta dùng assassin để chỉ kẻ ám sát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hitherto', 'en-c2-12', 'hitherto', '/ˌhɪðərˈtuː/', 'C2', 'cho đến nay hoặc cho đến thời điểm đang được bàn tới', 'adv.', NULL, 'Đồng nghĩa: previously, until now', 'Từ mang văn phong trang trọng, thường gặp trong các cụm từ như hitherto unknown.', 'The repair revealed a hitherto hidden cupboard upstairs.', NULL, 'Việc sửa chữa đã làm lộ ra một chiếc tủ âm tường vốn bị che khuất ở trên lầu từ trước đến nay.', '{"wordId":"hitherto","ukIpa":"/ˌhɪðəˈtuː/","usIpa":"/ˌhɪðərˈtuː/","cefr":"C2","topic":"history","senses":[{"pos":"adv.","en":"Until now or until the time being discussed.","vi":"cho đến nay hoặc cho đến thời điểm đang được bàn tới"}],"examples":[{"en":"The repair revealed a hitherto hidden cupboard upstairs.","vi":"Việc sửa chữa đã làm lộ ra một chiếc tủ âm tường vốn bị che khuất ở trên lầu từ trước đến nay.","audioKind":"ex"},{"en":"Recent archaeological discoveries have revealed hitherto unknown details about trade between ancient coastal communities.","vi":"Những phát hiện khảo cổ gần đây đã hé lộ những chi tiết chưa từng được biết đến trước đó về hoạt động thương mại giữa các cộng đồng ven biển cổ xưa.","audioKind":"ex2"}],"collocations":[{"en":"hitherto unknown","vi":"chưa từng được biết đến trước đây"},{"en":"hitherto unseen","vi":"chưa từng thấy trước đó"},{"en":"hitherto neglected","vi":"từ trước đến nay bị bỏ quên"}],"wordFamily":[],"synonyms":["previously","until now"],"antonyms":[],"tipVi":"Từ mang văn phong trang trọng, thường gặp trong các cụm từ như hitherto unknown.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antecedent', 'en-c2-12', 'antecedent', '/ˌæntɪˈsiːdənt/', 'C2', 'tiền đề; tiền thân; tiền lệ; từ quy chiếu; từ đi trước; tiền nhiệm; đi trước', 'n.', 'antecedence (n.)', 'Đồng nghĩa: precursor, forerunner', 'Trong ngữ pháp, từ này chỉ từ mà đại từ thay thế; không nên dịch thô là tổ tiên.', 'This simple wooden tool is an antecedent of modern machines.', NULL, 'Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.', '{"wordId":"antecedent","ukIpa":"/ˌæntɪˈsiːdənt/","usIpa":"/ˌæntɪˈsiːdənt/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"Something earlier that influenced or resembled a later thing.","vi":"tiền đề; tiền thân; tiền lệ"},{"pos":"n.","en":"A word or phrase that a later pronoun refers to.","vi":"từ quy chiếu; từ đi trước"},{"pos":"adj.","en":"Existing or happening before something else.","vi":"tiền nhiệm; đi trước"}],"examples":[{"en":"This simple wooden tool is an antecedent of modern machines.","vi":"Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.","audioKind":"ex"},{"en":"Researchers examine the historical antecedents of urban inequality to understand why certain communities remain disadvantaged.","vi":"Các nhà nghiên cứu nghiên cứu các tiền lệ lịch sử về sự bất bình đẳng đô thị để hiểu tại sao một số cộng đồng vẫn chịu thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"historical antecedents","vi":"tiền lệ lịch sử; nguồn gốc lịch sử"},{"en":"antecedent conditions","vi":"các điều kiện tiền đề"},{"en":"a pronoun''s antecedent","vi":"từ quy chiếu của đại từ"}],"wordFamily":["antecedence (n.)"],"synonyms":["precursor","forerunner"],"antonyms":[],"tipVi":"Trong ngữ pháp, từ này chỉ từ mà đại từ thay thế; không nên dịch thô là tổ tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occident', 'en-c2-12', 'occident', '/ˈɑːksɪdənt/', 'C2', 'phương Tây; thế giới phương Tây', 'n.', 'occidental (adj.)', 'Đồng nghĩa: the West · Trái nghĩa: the Orient', 'Thuật ngữ cũ, thường viết hoa là the Occident; ngày nay thường dùng the West.', 'This old atlas describes the occident in great detail.', NULL, 'Tập bản đồ cũ này mô tả rất chi tiết về thế giới phương Tây.', '{"wordId":"occident","ukIpa":"/ˈɒksɪdənt/","usIpa":"/ˈɑːksɪdənt/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"the Western world, especially Europe and North America","vi":"phương Tây; thế giới phương Tây"}],"examples":[{"en":"This old atlas describes the occident in great detail.","vi":"Tập bản đồ cũ này mô tả rất chi tiết về thế giới phương Tây.","audioKind":"ex"},{"en":"Historical accounts often contrasted the occident with the orient, overlooking the considerable diversity within both regions.","vi":"Các bản ghi chép lịch sử thường đối lập phương Tây với phương Đông, qua đó bỏ quên sự đa dạng đáng kể bên trong cả hai khu vực.","audioKind":"ex2"}],"collocations":[{"en":"the Occident","vi":"thế giới phương Tây"},{"en":"the Orient and the Occident","vi":"phương Đông và phương Tây"}],"wordFamily":["occidental (adj.)"],"synonyms":["the West"],"antonyms":["the Orient"],"tipVi":"Thuật ngữ cũ, thường viết hoa là the Occident; ngày nay thường dùng the West.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yoke', 'en-c2-12', 'yoke', '/joʊk/', 'C2', 'cái ách (gỗ để trói buộc hai con vật kéo cày); sự áp bức; ách thống trị; đóng ách; gắn kết bằng vũ lực', 'n.', NULL, NULL, 'Phát âm giống với yolk (lòng đỏ trứng); nghĩa bóng thường chỉ xiềng xích áp bức.', 'The farmer placed a wooden yoke across the oxen''s necks.', NULL, 'Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.', '{"wordId":"yoke","ukIpa":"/jəʊk/","usIpa":"/joʊk/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"A wooden frame joining two animals to pull a load.","vi":"cái ách (gỗ để trói buộc hai con vật kéo cày)"},{"pos":"n.","en":"A condition of being controlled or oppressed.","vi":"sự áp bức; ách thống trị"},{"pos":"v.","en":"Join animals with a frame, or force things together.","vi":"đóng ách; gắn kết bằng vũ lực"}],"examples":[{"en":"The farmer placed a wooden yoke across the oxen''s necks.","vi":"Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.","audioKind":"ex"},{"en":"Many communities struggled for generations to free themselves from the yoke of colonial rule.","vi":"Nhiều cộng đồng đã đấu tranh qua nhiều thế hệ để giải phóng bản thân khỏi ách thống trị thực dân.","audioKind":"ex2"}],"collocations":[{"en":"a wooden yoke","vi":"cái ách bằng gỗ"},{"en":"the yoke of oppression","vi":"ách áp bức"},{"en":"yoke together","vi":"kết nối với nhau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Phát âm giống với yolk (lòng đỏ trứng); nghĩa bóng thường chỉ xiềng xích áp bức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_facsimile', 'en-c2-12', 'facsimile', '/fækˈsɪməli/', 'C2', 'bản sao chính xác; bản in y hệt; bản truyền fax', 'n.', NULL, 'Đồng nghĩa: replica, reproduction · Trái nghĩa: original', 'Chỉ bản sao chính xác; khi nói về bản truyền qua máy điện thoại thường dùng từ viết tắt fax.', 'The museum shop sells a facsimile of this ancient map.', NULL, 'Cửa hàng bảo tàng bán một bản sao y hệt của tấm bản đồ cổ này.', '{"wordId":"facsimile","ukIpa":"/fækˈsɪməli/","usIpa":"/fækˈsɪməli/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"An exact copy of a document, book, or picture","vi":"bản sao chính xác; bản in y hệt"},{"pos":"n.","en":"A copy of a document sent electronically over telephone lines","vi":"bản truyền fax"}],"examples":[{"en":"The museum shop sells a facsimile of this ancient map.","vi":"Cửa hàng bảo tàng bán một bản sao y hệt của tấm bản đồ cổ này.","audioKind":"ex"},{"en":"A high-quality facsimile allows researchers to examine historical documents without damaging the fragile originals.","vi":"Một bản sao chất lượng cao cho phép các nhà nghiên cứu kiểm tra tài liệu lịch sử mà không làm hư hại bản gốc mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"a facsimile edition","vi":"phiên bản in lại"},{"en":"an exact facsimile","vi":"bản sao chính xác"},{"en":"send by facsimile","vi":"gửi qua đường truyền fax"}],"wordFamily":[],"synonyms":["replica","reproduction"],"antonyms":["original"],"tipVi":"Chỉ bản sao chính xác; khi nói về bản truyền qua máy điện thoại thường dùng từ viết tắt fax.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leninism', 'en-c2-12', 'Leninism', '/ˈlenɪnɪzəm/', 'C2', 'chủ nghĩa Lênin (các học thuyết chính trị của Lênin, đặc biệt về cách mạng và sự lãnh đạo của đảng)', 'n.', 'Leninist (n.), Leninist (adj.)', NULL, 'Tên tư tưởng chuyên ngành, viết hoa chữ cái đầu; thường là danh từ không đếm được.', 'Our history teacher explained Leninism during today''s afternoon lesson.', NULL, 'Giáo viên lịch sử của chúng tôi đã giảng về chủ nghĩa Lênin trong tiết học chiều nay.', '{"wordId":"leninism","ukIpa":"/ˈlenɪnɪzəm/","usIpa":"/ˈlenɪnɪzəm/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"Lenin''s political theories, particularly concerning revolution and leadership by a party.","vi":"chủ nghĩa Lênin (các học thuyết chính trị của Lênin, đặc biệt về cách mạng và sự lãnh đạo của đảng)"}],"examples":[{"en":"Our history teacher explained Leninism during today''s afternoon lesson.","vi":"Giáo viên lịch sử của chúng tôi đã giảng về chủ nghĩa Lênin trong tiết học chiều nay.","audioKind":"ex"},{"en":"Students studying Leninism often examine its influence on revolutionary movements and political institutions during the twentieth century.","vi":"Học sinh nghiên cứu chủ nghĩa Lênin thường tìm hiểu tầm ảnh hưởng của nó đối với các phong trào cách mạng và thể chế chính trị trong thế kỷ 20.","audioKind":"ex2"}],"collocations":[{"en":"the principles of Leninism","vi":"các nguyên lý của chủ nghĩa Lênin"},{"en":"the influence of Leninism","vi":"tầm ảnh hưởng của chủ nghĩa Lênin"},{"en":"Marxism-Leninism","vi":"chủ nghĩa Mác - Lênin"}],"wordFamily":["Leninist (n.)","Leninist (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên tư tưởng chuyên ngành, viết hoa chữ cái đầu; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plunder', 'en-c2-12', 'plunder', '/ˈplʌndɚ/', 'C2', 'cướp bóc, tước đoạt bằng vũ lực; của cải cướp được, chiến lợi phẩm chiến tranh', 'v.', 'plunderer (n.)', 'Đồng nghĩa: loot, pillage', 'Thường chỉ hành vi cướp bóc trong chiến tranh; cũng có thể chỉ việc khai thác, tước đoạt tài nguyên bừa bãi.', 'The pirates plundered the ship and took its silver.', NULL, 'Bọn hải tặc đã cướp phá con tàu và lấy đi số bạc trên đó.', '{"wordId":"plunder","ukIpa":"/ˈplʌndə/","usIpa":"/ˈplʌndɚ/","cefr":"C2","topic":"history","senses":[{"pos":"v.","en":"To steal goods by force, especially during war.","vi":"cướp bóc, tước đoạt bằng vũ lực"},{"pos":"n.","en":"Goods stolen by force, especially during war.","vi":"của cải cướp được, chiến lợi phẩm chiến tranh"}],"examples":[{"en":"The pirates plundered the ship and took its silver.","vi":"Bọn hải tặc đã cướp phá con tàu và lấy đi số bạc trên đó.","audioKind":"ex"},{"en":"Invading armies often plunder historic sites, causing permanent damage to the cultural heritage of affected communities.","vi":"Quân đội xâm lược thường cướp bóc các di tích lịch sử, gây ra tổn hại vĩnh viễn cho di sản văn hóa của các cộng đồng bị ảnh hưởng.","audioKind":"ex2"}],"collocations":[{"en":"plunder a city","vi":"cướp phá một thành phố"},{"en":"plunder resources","vi":"cướp bóc tài nguyên"},{"en":"stolen plunder","vi":"chiến lợi phẩm bị cướp"}],"wordFamily":["plunderer (n.)"],"synonyms":["loot","pillage"],"antonyms":[],"tipVi":"Thường chỉ hành vi cướp bóc trong chiến tranh; cũng có thể chỉ việc khai thác, tước đoạt tài nguyên bừa bãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alchemy', 'en-c2-12', 'alchemy', '/ˈælkəmi/', 'C2', 'thuật luyện kim; phép luyện đan; quá trình biến đổi kỳ diệu', 'n.', 'alchemist (n.), alchemical (adj.)', NULL, 'Thường là danh từ không đếm được; nghĩa bóng nhấn mạnh sự biến đổi kỳ diệu chứ không chỉ ma thuật thông thường.', 'The exhibition explored alchemy through old jars and furnaces.', NULL, 'Triển lãm đã khai thác chủ đề thuật luyện kim thông qua những chiếc lọ và lò nung cổ.', '{"wordId":"alchemy","ukIpa":"/ˈælkəmi/","usIpa":"/ˈælkəmi/","cefr":"C2","topic":"history","senses":[{"pos":"n.","en":"An ancient practice seeking to turn ordinary metals into gold","vi":"thuật luyện kim; phép luyện đan"},{"pos":"n.","en":"A mysterious process that transforms ordinary things into something special","vi":"quá trình biến đổi kỳ diệu"}],"examples":[{"en":"The exhibition explored alchemy through old jars and furnaces.","vi":"Triển lãm đã khai thác chủ đề thuật luyện kim thông qua những chiếc lọ và lò nung cổ.","audioKind":"ex"},{"en":"Although alchemy lacked a modern scientific framework, its experimental techniques contributed to the development of chemistry.","vi":"Mặc dù thuật luyện kim thiếu khung khoa học hiện đại, các kỹ thuật thực nghiệm của nó đã góp phần quan trọng vào sự phát triển của ngành hóa học.","audioKind":"ex2"}],"collocations":[{"en":"medieval alchemy","vi":"thuật luyện kim thời Trung Cổ"},{"en":"practise alchemy","vi":"hành nghề luyện kim"},{"en":"the alchemy of creativity","vi":"sức mạnh biến hóa kỳ diệu của sự sáng tạo"}],"wordFamily":["alchemist (n.)","alchemical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nghĩa bóng nhấn mạnh sự biến đổi kỳ diệu chứ không chỉ ma thuật thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_epoch-making', 'en-c2-12', 'epoch-making', '/ˈep.əkˌmeɪ.kɪŋ/', 'C2', 'mang tính bước ngoặt; mở ra thời đại mới; vĩ đại', 'adj.', 'epoch (n.)', 'Đồng nghĩa: historic, groundbreaking', 'Từ này có sắc thái mạnh, dùng để chỉ việc mở ra một thời đại mới, không dùng chung chung cho các sự kiện quan trọng thông thường.', 'We watched a documentary about that epoch-making scientific discovery.', NULL, 'Chúng tôi đã xem một bộ phim tài liệu về khám phá khoa học mang tính bước ngoặt đó.', '{"wordId":"epoch-making","ukIpa":"/ˈiː.pɒkˌmeɪ.kɪŋ/","usIpa":"/ˈep.əkˌmeɪ.kɪŋ/","cefr":"C2","topic":"history","senses":[{"pos":"adj.","en":"So important that it begins a new historical period","vi":"mang tính bước ngoặt; mở ra thời đại mới; vĩ đại"}],"examples":[{"en":"We watched a documentary about that epoch-making scientific discovery.","vi":"Chúng tôi đã xem một bộ phim tài liệu về khám phá khoa học mang tính bước ngoặt đó.","audioKind":"ex"},{"en":"The development of printing was an epoch-making advance that transformed education and widened access to knowledge.","vi":"Sự phát triển của ngành in ấn là một bước tiến mang tính lịch sử, đã thay đổi nền giáo dục và mở rộng khả năng tiếp cận tri thức của con người.","audioKind":"ex2"}],"collocations":[{"en":"an epoch-making discovery","vi":"một phátوَri mang tính bước ngoặt"},{"en":"an epoch-making invention","vi":"một phát minh mang tính bước ngoặt"},{"en":"an epoch-making event","vi":"một sự kiện mang tính bước ngoặt"}],"wordFamily":["epoch (n.)"],"synonyms":["historic","groundbreaking"],"antonyms":[],"tipVi":"Từ này có sắc thái mạnh, dùng để chỉ việc mở ra một thời đại mới, không dùng chung chung cho các sự kiện quan trọng thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_12_1', 'en-c2-12', 'Cách dùng “epoch-making” (adj.) — mang tính bước ngoặt; mở ra thời đại mới; vĩ đại', 'an epoch-making discovery  ·  an epoch-making invention  ·  an epoch-making event', 'Từ này có sắc thái mạnh, dùng để chỉ việc mở ra một thời đại mới, không dùng chung chung cho các sự kiện quan trọng thông thường.', 'Họ từ (Word Family): epoch (n.) | Đồng nghĩa: historic, groundbreaking', '[{"hanzi":"We watched a documentary about that epoch-making scientific discovery.","pinyin":"","meaning":"Chúng tôi đã xem một bộ phim tài liệu về khám phá khoa học mang tính bước ngoặt đó."},{"hanzi":"The development of printing was an epoch-making advance that transformed education and widened access to knowledge.","pinyin":"","meaning":"Sự phát triển của ngành in ấn là một bước tiến mang tính lịch sử, đã thay đổi nền giáo dục và mở rộng khả năng tiếp cận tri thức của con người."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_12_2', 'en-c2-12', 'Cách dùng “alchemy” (n.) — thuật luyện kim; phép luyện đan', 'medieval alchemy  ·  practise alchemy  ·  the alchemy of creativity', 'Thường là danh từ không đếm được; nghĩa bóng nhấn mạnh sự biến đổi kỳ diệu chứ không chỉ ma thuật thông thường.', 'Họ từ (Word Family): alchemist (n.), alchemical (adj.)', '[{"hanzi":"The exhibition explored alchemy through old jars and furnaces.","pinyin":"","meaning":"Triển lãm đã khai thác chủ đề thuật luyện kim thông qua những chiếc lọ và lò nung cổ."},{"hanzi":"Although alchemy lacked a modern scientific framework, its experimental techniques contributed to the development of chemistry.","pinyin":"","meaning":"Mặc dù thuật luyện kim thiếu khung khoa học hiện đại, các kỹ thuật thực nghiệm của nó đã góp phần quan trọng vào sự phát triển của ngành hóa học."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_12_3', 'en-c2-12', 'Cách dùng “avenge” (v.) — trả thù; rửa hận; phục thù', 'avenge a defeat  ·  avenge a wrong', 'avenge là động từ, thường đi liền với đối tượng hoặc sự việc bị tổn hại; revenge thường đóng vai trò danh từ.', 'Họ từ (Word Family): avenger (n.)', '[{"hanzi":"Our team hopes to avenge last year''s defeat.","pinyin":"","meaning":"Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái."},{"hanzi":"Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.","pinyin":"","meaning":"Các biên niên sử lịch sử thường miêu tả các nhà lãnh đạo tìm cách trả thù cho những thất bại trong quá khứ hơn là đàm phán để đạt được hòa bình lâu dài."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_12_4', 'en-c2-12', 'Cách dùng “plunder” (v.) — cướp bóc, tước đoạt bằng vũ lực', 'plunder a city  ·  plunder resources  ·  stolen plunder', 'Thường chỉ hành vi cướp bóc trong chiến tranh; cũng có thể chỉ việc khai thác, tước đoạt tài nguyên bừa bãi.', 'Họ từ (Word Family): plunderer (n.) | Đồng nghĩa: loot, pillage', '[{"hanzi":"The pirates plundered the ship and took its silver.","pinyin":"","meaning":"Bọn hải tặc đã cướp phá con tàu và lấy đi số bạc trên đó."},{"hanzi":"Invading armies often plunder historic sites, causing permanent damage to the cultural heritage of affected communities.","pinyin":"","meaning":"Quân đội xâm lược thường cướp bóc các di tích lịch sử, gây ra tổn hại vĩnh viễn cho di sản văn hóa của các cộng đồng bị ảnh hưởng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_12_1', 'en-c2-12', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_1', 'ten_c2_12_1', 'avenge', 'Our team hopes to avenge last year''s defeat.', 'Our team hopes to avenge last year''s defeat.', '/əˈvendʒ/', 'Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_2', 'ten_c2_12_1', 'infantry', 'The infantry marched past our village early this morning.', 'The infantry marched past our village early this morning.', '/ˈɪnfəntri/', 'Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_3', 'ten_c2_12_1', 'prophesy', 'The old storyteller prophesied that the kingdom would prosper.', 'The old storyteller prophesied that the kingdom would prosper.', '/ˈprɑːfəsaɪ/', 'Người kể chuyện già nua tiên tri rằng vương quốc sẽ hưng thịnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_4', 'ten_c2_12_1', 'assassinator', 'The film''s assassinator hid behind a heavy curtain.', 'The film''s assassinator hid behind a heavy curtain.', '/əˈsæsɪneɪtər/', 'Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_5', 'ten_c2_12_1', 'hitherto', 'The repair revealed a hitherto hidden cupboard upstairs.', 'The repair revealed a hitherto hidden cupboard upstairs.', '/ˌhɪðərˈtuː/', 'Việc sửa chữa đã làm lộ ra một chiếc tủ âm tường vốn bị che khuất ở trên lầu từ trước đến nay.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_6', 'ten_c2_12_1', 'antecedent', 'This simple wooden tool is an antecedent of modern machines.', 'This simple wooden tool is an antecedent of modern machines.', '/ˌæntɪˈsiːdənt/', 'Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_7', 'ten_c2_12_1', 'occident', 'This old atlas describes the occident in great detail.', 'This old atlas describes the occident in great detail.', '/ˈɑːksɪdənt/', 'Tập bản đồ cũ này mô tả rất chi tiết về thế giới phương Tây.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_1_8', 'ten_c2_12_1', 'yoke', 'The farmer placed a wooden yoke across the oxen''s necks.', 'The farmer placed a wooden yoke across the oxen''s necks.', '/joʊk/', 'Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_12_1_1', 'en-c2-12', 'ten_c2_12_1', 'listening', 'listening', 'Our team hopes to avenge last year''s defeat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.","Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.","Việc sửa chữa đã làm lộ ra một chiếc tủ âm tường vốn bị che khuất ở trên lầu từ trước đến nay.","Giáo viên lịch sử của chúng tôi đã giảng về chủ nghĩa Lênin trong tiết học chiều nay."]'::jsonb, 1, 'Our team hopes to avenge last year''s defeat. → Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_12_1_2', 'en-c2-12', 'ten_c2_12_1', 'listening', 'listening', 'The infantry marched past our village early this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.","Bọn hải tặc đã cướp phá con tàu và lấy đi số bạc trên đó.","Triển lãm đã khai thác chủ đề thuật luyện kim thông qua những chiếc lọ và lò nung cổ.","Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay."]'::jsonb, 3, 'The infantry marched past our village early this morning. → Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_12_1_3', 'en-c2-12', 'ten_c2_12_1', 'listening', 'listening', 'The old storyteller prophesied that the kingdom would prosper.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.","Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.","Người kể chuyện già nua tiên tri rằng vương quốc sẽ hưng thịnh.","Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái."]'::jsonb, 2, 'The old storyteller prophesied that the kingdom would prosper. → Người kể chuyện già nua tiên tri rằng vương quốc sẽ hưng thịnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_12_2', 'en-c2-12', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_2_1', 'ten_c2_12_2', 'avenge', 'Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.', 'Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.', '/əˈvendʒ/', 'Các biên niên sử lịch sử thường miêu tả các nhà lãnh đạo tìm cách trả thù cho những thất bại trong quá khứ hơn là đàm phán để đạt được hòa bình lâu dài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_2_2', 'ten_c2_12_2', 'infantry', 'Although military technology has changed considerably, infantry still play an important role in many countries'' defence forces.', 'Although military technology has changed considerably, infantry still play an important role in many countries'' defence forces.', '/ˈɪnfəntri/', 'Mặc dù công nghệ quân sự đã thay đổi đáng kể, bộ binh vẫn đóng vai trò quan trọng trong lực lượng quốc phòng của nhiều quốc gia.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_2_3', 'ten_c2_12_2', 'prophesy', 'Some early commentators prophesied that television would replace books, but reading has remained an important cultural activity.', 'Some early commentators prophesied that television would replace books, but reading has remained an important cultural activity.', '/ˈprɑːfəsaɪ/', 'Một số nhà bình luận thời kỳ đầu từng tiên tri rằng truyền hình sẽ thay thế sách, nhưng việc đọc sách vẫn tiếp tục là một hoạt động văn hóa quan trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_2_4', 'ten_c2_12_2', 'assassinator', 'The historical account examines the assassinator''s motives and the political instability that followed the killing.', 'The historical account examines the assassinator''s motives and the political instability that followed the killing.', '/əˈsæsɪneɪtər/', 'Tài liệu lịch sử xem xét động cơ của kẻ ám sát và tình trạng bất ổn chính trị diễn ra sau vụ ám sát đó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_2_5', 'ten_c2_12_2', 'hitherto', 'Recent archaeological discoveries have revealed hitherto unknown details about trade between ancient coastal communities.', 'Recent archaeological discoveries have revealed hitherto unknown details about trade between ancient coastal communities.', '/ˌhɪðərˈtuː/', 'Những phát hiện khảo cổ gần đây đã hé lộ những chi tiết chưa từng được biết đến trước đó về hoạt động thương mại giữa các cộng đồng ven biển cổ xưa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_12_2_6', 'ten_c2_12_2', 'antecedent', 'Researchers examine the historical antecedents of urban inequality to understand why certain communities remain disadvantaged.', 'Researchers examine the historical antecedents of urban inequality to understand why certain communities remain disadvantaged.', '/ˌæntɪˈsiːdənt/', 'Các nhà nghiên cứu nghiên cứu các tiền lệ lịch sử về sự bất bình đẳng đô thị để hiểu tại sao một số cộng đồng vẫn chịu thiệt thòi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_12_2_1', 'en-c2-12', 'ten_c2_12_2', 'listening', 'listening', 'Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.', NULL, 'Trong câu vừa nghe, từ “avenge” mang nghĩa nào sau đây?', '["xơ hóa; chứng xơ cứng","chi (đơn vị phân loại sinh học bao gồm các loài có họ hàng gần)","trả thù; rửa hận; phục thù","giết; tiêu diệt"]'::jsonb, 2, '“avenge” (/əˈvendʒ/): trả thù; rửa hận; phục thù. Câu đầy đủ: Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_12_2_2', 'en-c2-12', 'ten_c2_12_2', 'listening', 'listening', 'Although military technology has changed considerably, infantry still play an important role in many countries'' defence forces.', NULL, 'Trong câu vừa nghe, từ “infantry” mang nghĩa nào sau đây?', '["sự sửa chữa; sự hiệu chỉnh","lịch lãm; tao nhã; khéo ứng xử","bộ binh","cuộc hành trình dài và nhiều gian nan trắc trở"]'::jsonb, 2, '“infantry” (/ˈɪnfəntri/): bộ binh. Câu đầy đủ: Although military technology has changed considerably, infantry still play an important role in many countries'' defence forces.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
