INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_12_4', 'en-c2-12', 'The film''s assassinator hid behind a heavy curtain', 'Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.', 'assassinator /əˈsæsɪneɪtər/', '["assassinator","hid","The","heavy","curtain","a","behind","film''s"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
