INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_12_6', 'en-c2-12', 'This simple wooden tool is an antecedent of modern machines', 'Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.', 'antecedent /ˌæntɪˈsiːdənt/', '["modern","an","machines","wooden","of","antecedent","simple","This","is","tool"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
