INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c2_12_13', 'en-c2-12', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “epoch-making” (/ˈep.əkˌmeɪ.kɪŋ/) có nghĩa là gì?', '["bản sao chính xác; bản in y hệt","mang tính bước ngoặt; mở ra thời đại mới; vĩ đại","tiền đề; tiền thân; tiền lệ","bộ binh"]'::jsonb, 1, '“epoch-making” (adj.): mang tính bước ngoặt; mở ra thời đại mới; vĩ đại.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_1', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'avenge', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phân; chất thải","trả thù; rửa hận; phục thù","nằm hoặc ngồi ngả ngớn, lười biếng; thõng xuống","cướp bóc, tước đoạt bằng vũ lực"]'::jsonb, 1, 'avenge (/əˈvendʒ/) → trả thù; rửa hận; phục thù', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_2', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'The infantry marched past our village early this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.","Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.","Bọn hải tặc đã cướp phá con tàu và lấy đi số bạc trên đó.","Tập bản đồ cũ này mô tả rất chi tiết về thế giới phương Tây."]'::jsonb, 0, 'The infantry marched past our village early this morning. → Đội ngũ bộ binh đã hành quân qua ngôi làng của chúng tôi vào sáng sớm nay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_3', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'prophesy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không thể tước đoạt hoặc chuyển nhượng cho người khác","cây khuynh diệp; cây bạch đàn","tiên tri; báo trước","nữ nam tước; phu nhân nam tước"]'::jsonb, 2, 'prophesy (/ˈprɑːfəsaɪ/) → tiên tri; báo trước', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_4', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'The film''s assassinator hid behind a heavy curtain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.","Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.","Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.","Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái."]'::jsonb, 2, 'The film''s assassinator hid behind a heavy curtain. → Kẻ ám sát trong phim ẩn nấp sau tấm rèm dày.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_5', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'hitherto', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thực tế; thực trạng","bộ binh","cho đến nay hoặc cho đến thời điểm đang được bàn tới","sốt sắng; nhiệt huyết; tận tụy"]'::jsonb, 2, 'hitherto (/ˌhɪðərˈtuː/) → cho đến nay hoặc cho đến thời điểm đang được bàn tới', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_6', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'This simple wooden tool is an antecedent of modern machines.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một bộ phim tài liệu về khám phá khoa học mang tính bước ngoặt đó.","Đội của chúng tôi hy vọng sẽ rửa hận được trận thua vào năm ngoái.","Người kể chuyện già nua tiên tri rằng vương quốc sẽ hưng thịnh.","Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại."]'::jsonb, 3, 'This simple wooden tool is an antecedent of modern machines. → Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_7', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'occident', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cây khuynh diệp; cây bạch đàn","ai oán, thê thiết, buồn bã và mang tính than van","sự tôn kính; lòng kính trọng sâu sắc","phương Tây; thế giới phương Tây"]'::jsonb, 3, 'occident (/ˈɑːksɪdənt/) → phương Tây; thế giới phương Tây', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_8', 'en-c2-12', NULL, 'comprehensive_test', 'listening', 'The farmer placed a wooden yoke across the oxen''s necks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.","Công cụ bằng gỗ đơn giản này là tiền thân của những cỗ máy hiện đại.","Việc sửa chữa đã làm lộ ra một chiếc tủ âm tường vốn bị che khuất ở trên lầu từ trước đến nay.","Triển lãm đã khai thác chủ đề thuật luyện kim thông qua những chiếc lọ và lò nung cổ."]'::jsonb, 0, 'The farmer placed a wooden yoke across the oxen''s necks. → Người nông dân đặt chiếc ách gỗ lên cổ hai con bò.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_9', 'en-c2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Until now or until the time being discussed.”?', '["hitherto","avenge","antecedent","Leninism"]'::jsonb, 0, 'hitherto (/ˌhɪðərˈtuː/) → cho đến nay hoặc cho đến thời điểm đang được bàn tới', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_10', 'en-c2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Something earlier that influenced or resembled a later thing.”?', '["antecedent","plunder","avenge","yoke"]'::jsonb, 0, 'antecedent (/ˌæntɪˈsiːdənt/) → tiền đề; tiền thân; tiền lệ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_11', 'en-c2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the Western world, especially Europe and North America”?', '["antecedent","assassinator","plunder","occident"]'::jsonb, 3, 'occident (/ˈɑːksɪdənt/) → phương Tây; thế giới phương Tây', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_12', 'en-c2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A wooden frame joining two animals to pull a load.”?', '["yoke","Leninism","infantry","alchemy"]'::jsonb, 0, 'yoke (/joʊk/) → cái ách (gỗ để trói buộc hai con vật kéo cày)', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_13', 'en-c2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An exact copy of a document, book, or picture”?', '["epoch-making","yoke","facsimile","prophesy"]'::jsonb, 2, 'facsimile (/fækˈsɪməli/) → bản sao chính xác; bản in y hệt', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
