INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_18', 'en-c2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Historical narratives often portray leaders seeking to avenge past defeats rather than negotiate lasting peace.', 'Dựa vào câu trên, từ “avenge” có nghĩa phù hợp nhất là gì?', '["mang lại; góp phần đem lại (kết quả, tín nhiệm hoặc lợi ích)","trả thù; rửa hận; phục thù","cần sức mạnh lớn; gian khổ","làm phiền; làm bực mình; làm lo lắng"]'::jsonb, 1, 'avenge: trả thù; rửa hận; phục thù. Dịch cả câu: Các biên niên sử lịch sử thường miêu tả các nhà lãnh đạo tìm cách trả thù cho những thất bại trong quá khứ hơn là đàm phán để đạt được hòa bình lâu dài.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_19', 'en-c2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Although military technology has changed considerably, infantry still play an important role in many countries'' defence forces.', 'Dựa vào câu trên, từ “infantry” có nghĩa phù hợp nhất là gì?', '["sẩy thai","cùng với vật đó","bộ binh","gây thiệt hại nặng nề; phá sản"]'::jsonb, 2, 'infantry: bộ binh. Dịch cả câu: Mặc dù công nghệ quân sự đã thay đổi đáng kể, bộ binh vẫn đóng vai trò quan trọng trong lực lượng quốc phòng của nhiều quốc gia.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_20', 'en-c2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Some early commentators prophesied that television would replace books, but reading has remained an important cultural activity.', 'Dựa vào câu trên, từ “prophesy” có nghĩa phù hợp nhất là gì?', '["sự ngây ngất; niềm vui sướng tột độ; sự cuồng nhiệt","không thể đảo ngược; không thể thay đổi hoặc rút lại","tiên tri; báo trước","tiền niên kim; bảo hiểm niên kim"]'::jsonb, 2, 'prophesy: tiên tri; báo trước. Dịch cả câu: Một số nhà bình luận thời kỳ đầu từng tiên tri rằng truyền hình sẽ thay thế sách, nhưng việc đọc sách vẫn tiếp tục là một hoạt động văn hóa quan trọng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_21', 'en-c2-12', NULL, 'comprehensive_test', 'reading', NULL, 'The historical account examines the assassinator''s motives and the political instability that followed the killing.', 'Dựa vào câu trên, từ “assassinator” có nghĩa phù hợp nhất là gì?', '["thuế; thuế quan","tách biệt; cho ở ẩn; cô lập","kẻ ám sát; kẻ thủ ác","hiểu lầm; nhận thức sai"]'::jsonb, 2, 'assassinator: kẻ ám sát; kẻ thủ ác. Dịch cả câu: Tài liệu lịch sử xem xét động cơ của kẻ ám sát và tình trạng bất ổn chính trị diễn ra sau vụ ám sát đó.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_22', 'en-c2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cướp bóc, tước đoạt bằng vũ lực”', '["virile","plunder","ulcer","urbane"]'::jsonb, 1, 'cướp bóc, tước đoạt bằng vũ lực → plunder (/ˈplʌndɚ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_23', 'en-c2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuật luyện kim; phép luyện đan”', '["clasp","alchemy","scrupulous","multifarious"]'::jsonb, 1, 'thuật luyện kim; phép luyện đan → alchemy (/ˈælkəmi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_12_24', 'en-c2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mang tính bước ngoặt; mở ra thời đại mới; vĩ đại”', '["shamble","treatise","epoch-making","loth"]'::jsonb, 2, 'mang tính bước ngoặt; mở ra thời đại mới; vĩ đại → epoch-making (/ˈep.əkˌmeɪ.kɪŋ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-13', 'en', 'Bài 13: Khoa học & Nghiên cứu - CEFR C2', 'CEFR C2', 'C2 · Khoa học', '22 từ vựng Tiếng Anh CEFR C2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6013, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_malleable', 'en-c2-13', 'malleable', '/ˈmæliəbəl/', 'C2', 'dễ uốn; dễ gò (kim loại); dễ bảo; dễ bị ảnh hưởng; dễ uốn nắn', 'adj.', 'malleability (n.)', 'Đồng nghĩa: pliable, impressionable · Trái nghĩa: rigid', 'Nghĩa kim loại nhấn mạnh khả năng đập búa thành hình; ductile nhấn mạnh khả năng kéo sợi.', 'The warm metal was malleable enough to bend easily.', NULL, 'Miếng kim loại còn ấm có tính dẻo đủ để uốn cong dễ dàng.', '{"wordId":"malleable","ukIpa":"/ˈmæliəbəl/","usIpa":"/ˈmæliəbəl/","cefr":"C2","topic":"science","senses":[{"pos":"adj.","en":"Able to be hammered or pressed into a different shape.","vi":"dễ uốn; dễ gò (kim loại)"},{"pos":"adj.","en":"Easily influenced or changed by other people or circumstances.","vi":"dễ bảo; dễ bị ảnh hưởng; dễ uốn nắn"}],"examples":[{"en":"The warm metal was malleable enough to bend easily.","vi":"Miếng kim loại còn ấm có tính dẻo đủ để uốn cong dễ dàng.","audioKind":"ex"},{"en":"Young people''s attitudes are often malleable, making schools important environments for developing respect and social responsibility.","vi":"Thái độ của giới trẻ thường rất dễ uốn nắn, biến trường học thành môi trường quan trọng để bồi dưỡng lòng tôn trọng và trách nhiệm xã hội.","audioKind":"ex2"}],"collocations":[{"en":"malleable metal","vi":"kim loại dễ uốn"},{"en":"highly malleable","vi":"có tính dẻo cao"},{"en":"malleable minds","vi":"tâm trí dễ bị ảnh hưởng"}],"wordFamily":["malleability (n.)"],"synonyms":["pliable","impressionable"],"antonyms":["rigid"],"tipVi":"Nghĩa kim loại nhấn mạnh khả năng đập búa thành hình; ductile nhấn mạnh khả năng kéo sợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infinitesimal', 'en-c2-13', 'infinitesimal', '/ˌɪnfɪnɪˈtesɪməl/', 'C2', 'vô cùng nhỏ; cực kỳ nhỏ bé; đại lượng vô cùng nhỏ', 'adj.', 'infinitesimally (adv.)', 'Đồng nghĩa: minute, tiny · Trái nghĩa: enormous', 'Mức độ mạnh hơn rất nhiều so với "small"; cách dùng danh từ chủ yếu xuất hiện trong toán học.', 'The scratch made an infinitesimal difference to the table''s appearance.', NULL, 'Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn.', '{"wordId":"infinitesimal","ukIpa":"/ˌɪnfɪnɪˈtesɪml/","usIpa":"/ˌɪnfɪnɪˈtesɪməl/","cefr":"C2","topic":"science","senses":[{"pos":"adj.","en":"so small that it is almost impossible to measure","vi":"vô cùng nhỏ; cực kỳ nhỏ bé"},{"pos":"n.","en":"a mathematical quantity smaller in magnitude than any positive real number","vi":"đại lượng vô cùng nhỏ"}],"examples":[{"en":"The scratch made an infinitesimal difference to the table''s appearance.","vi":"Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn.","audioKind":"ex"},{"en":"Even infinitesimal changes in ocean temperature can become significant when measured across vast areas over decades.","vi":"Ngay cả những thay đổi nhỏ đến vô cùng trong nhiệt độ đại dương cũng có thể trở nên đáng kể khi được đo đạc trên các vùng rộng lớn trong suốt nhiều thập kỷ.","audioKind":"ex2"}],"collocations":[{"en":"infinitesimal amount","vi":"lượng vô cùng nhỏ"},{"en":"infinitesimal difference","vi":"sự khác biệt cực nhỏ"},{"en":"infinitesimal change","vi":"sự thay đổi vô cùng nhỏ"}],"wordFamily":["infinitesimally (adv.)"],"synonyms":["minute","tiny"],"antonyms":["enormous"],"tipVi":"Mức độ mạnh hơn rất nhiều so với \"small\"; cách dùng danh từ chủ yếu xuất hiện trong toán học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sulphide', 'en-c2-13', 'sulphide', '/ˈsʌlfaɪd/', 'C2', 'hợp chất sun-fua; muối sun-fua', 'n.', 'sulphur (n.)', NULL, 'Trong tiếng Anh Mỹ và danh pháp quốc tế, từ này thường được viết là sulfide; cần tránh nhầm lẫn với sulfate (sun-fat).', 'Our teacher showed us a sample of iron sulphide.', NULL, 'Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua.', '{"wordId":"sulphide","ukIpa":"/ˈsʌlfaɪd/","usIpa":"/ˈsʌlfaɪd/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A compound containing sulphur combined with another element or group","vi":"hợp chất sun-fua; muối sun-fua"}],"examples":[{"en":"Our teacher showed us a sample of iron sulphide.","vi":"Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua.","audioKind":"ex"},{"en":"When exposed to air and water, some sulphide minerals can generate acidic drainage that damages nearby ecosystems.","vi":"Khi tiếp xúc với không khí và nước, một số khoáng vật sun-fua có thể tạo ra nước thải axit gây hại cho các hệ sinh thái gần đó.","audioKind":"ex2"}],"collocations":[{"en":"iron sulphide","vi":"sắt sun-fua"},{"en":"hydrogen sulphide","vi":"khí sun-fua-hít; hy-đrô sun-fua"},{"en":"sulphide minerals","vi":"khoáng vật sun-fua"}],"wordFamily":["sulphur (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Mỹ và danh pháp quốc tế, từ này thường được viết là sulfide; cần tránh nhầm lẫn với sulfate (sun-fat).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_genus', 'en-c2-13', 'genus', '/ˈdʒiːnəs/', 'C2', 'chi (đơn vị phân loại sinh học bao gồm các loài có họ hàng gần)', 'n.', NULL, NULL, 'Dạng số nhiều là genera; bậc phân loại chi nằm dưới họ và trên loài.', 'These two garden plants belong to the same genus.', NULL, 'Hai loài thực vật cảnh này thuộc cùng một chi.', '{"wordId":"genus","ukIpa":"/ˈdʒiːnəs/","usIpa":"/ˈdʒiːnəs/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"a biological group containing closely related species","vi":"chi (đơn vị phân loại sinh học bao gồm các loài có họ hàng gần)"}],"examples":[{"en":"These two garden plants belong to the same genus.","vi":"Hai loài thực vật cảnh này thuộc cùng một chi.","audioKind":"ex"},{"en":"Scientists classified the newly discovered frog within an existing genus after comparing its genetic characteristics with related species.","vi":"Các nhà khoa học đã xếp loài ếch mới phát hiện vào một chi đã có sẵn sau khi so sánh các đặc điểm di truyền của nó với các loài họ hàng.","audioKind":"ex2"}],"collocations":[{"en":"belong to a genus","vi":"thuộc một chi"},{"en":"the same genus","vi":"cùng một chi"},{"en":"a new genus","vi":"một chi mới"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là genera; bậc phân loại chi nằm dưới họ và trên loài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_axial', 'en-c2-13', 'axial', '/ˈæksiəl/', 'C2', 'thuộc trục; theo trục', 'adj.', 'axis (n.), axially (adv.)', NULL, 'axial liên quan đến trục; radial chỉ hướng theo bán kính.', 'The mechanic checked the shaft for excessive axial movement.', NULL, 'Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không.', '{"wordId":"axial","ukIpa":"/ˈæksiəl/","usIpa":"/ˈæksiəl/","cefr":"C2","topic":"science","senses":[{"pos":"adj.","en":"relating to an axis or extending along it","vi":"thuộc trục; theo trục"}],"examples":[{"en":"The mechanic checked the shaft for excessive axial movement.","vi":"Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không.","audioKind":"ex"},{"en":"Changes in the Earth''s axial tilt influence how solar energy is distributed across the planet.","vi":"Sự thay đổi về độ nghiêng trục của Trái Đất ảnh hưởng đến cách phân bố năng lượng mặt trời trên hành tinh.","audioKind":"ex2"}],"collocations":[{"en":"axial tilt","vi":"độ nghiêng trục"},{"en":"axial rotation","vi":"sự quay quanh trục"},{"en":"axial load","vi":"tải trọng dọc trục"}],"wordFamily":["axis (n.)","axially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"axial liên quan đến trục; radial chỉ hướng theo bán kính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elemental', 'en-c2-13', 'elemental', '/ˌelɪˈmentəl/', 'C2', 'cơ bản; bản chất; thuộc về tự nhiên (mạnh mẽ); thuộc nguyên tố (hóa học)', 'adj.', 'element (n.), elementally (adv.)', 'Đồng nghĩa: fundamental, basic', 'elemental nhấn mạnh tính căn bản hoặc sức mạnh tự nhiên; elementary thường chỉ mức độ vỡ lòng, sơ cấp.', 'The storm awakened an elemental fear deep inside me.', NULL, 'Cơn bão đánh thức một nỗi sợ bản năng sâu thẳm bên trong tôi.', '{"wordId":"elemental","ukIpa":"/ˌelɪˈmentəl/","usIpa":"/ˌelɪˈmentəl/","cefr":"C2","topic":"science","senses":[{"pos":"adj.","en":"Relating to the most basic features or forces of something.","vi":"cơ bản; bản chất"},{"pos":"adj.","en":"Relating to powerful natural forces such as wind and water.","vi":"thuộc về tự nhiên (mạnh mẽ)"},{"pos":"adj.","en":"Consisting of a chemical element rather than a compound.","vi":"thuộc nguyên tố (hóa học)"}],"examples":[{"en":"The storm awakened an elemental fear deep inside me.","vi":"Cơn bão đánh thức một nỗi sợ bản năng sâu thẳm bên trong tôi.","audioKind":"ex"},{"en":"Access to food and shelter addresses elemental human needs that economic policy should never overlook.","vi":"Việc tiếp cận với thực phẩm và nơi ở đáp ứng các nhu cầu cơ bản của con người mà chính sách kinh tế không bao giờ được phớt lờ.","audioKind":"ex2"}],"collocations":[{"en":"elemental forces","vi":"lực lượng tự nhiên"},{"en":"an elemental fear","vi":"nỗi sợ bản năng"},{"en":"elemental carbon","vi":"cácbon nguyên tố"}],"wordFamily":["element (n.)","elementally (adv.)"],"synonyms":["fundamental","basic"],"antonyms":[],"tipVi":"elemental nhấn mạnh tính căn bản hoặc sức mạnh tự nhiên; elementary thường chỉ mức độ vỡ lòng, sơ cấp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radium', 'en-c2-13', 'radium', '/ˈreɪdiəm/', 'C2', 'nguyên tố ra-đi; chất ra-đi', 'n.', NULL, NULL, 'radium là danh từ không đếm được, ký hiệu hóa học là Ra.', 'We learned about radium during our science lesson today.', NULL, 'Chúng tôi đã học về nguyên tố ra-đi trong giờ học khoa học hôm nay.', '{"wordId":"radium","ukIpa":"/ˈreɪdiəm/","usIpa":"/ˈreɪdiəm/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A radioactive metallic chemical element","vi":"nguyên tố ra-đi; chất ra-đi"}],"examples":[{"en":"We learned about radium during our science lesson today.","vi":"Chúng tôi đã học về nguyên tố ra-đi trong giờ học khoa học hôm nay.","audioKind":"ex"},{"en":"The discovery of radium advanced scientific understanding of radioactivity, although its health risks were initially underestimated.","vi":"Việc phát hiện ra nguyên tố ra-đi đã thúc đẩy sự hiểu biết khoa học về hiện tượng phóng xạ, mặc dù các rủi ro sức khỏe của nó ban đầu bị đánh giá thấp.","audioKind":"ex2"}],"collocations":[{"en":"radium decay","vi":"sự phân rã ra-đi"},{"en":"radium exposure","vi":"sự phơi nhiễm ra-đi"},{"en":"radium isotopes","vi":"đồng vị ra-đi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"radium là danh từ không đếm được, ký hiệu hóa học là Ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pyrite', 'en-c2-13', 'pyrite', '/ˈpaɪraɪt/', 'C2', 'khoáng vật vàng giả, quặng pyrit (một loại khoáng sản màu vàng sáng chứa sắt và lưu huỳnh)', 'n.', NULL, NULL, 'Do ngoại hình giống vàng nên còn được gọi là fool’s gold (vàng của kẻ ngốc).', 'The tiny piece of pyrite glittered in her palm.', NULL, 'Mẩu quặng pyrit nhỏ xíu lấp lánh trong lòng bàn tay cô ấy.', '{"wordId":"pyrite","ukIpa":"/ˈpaɪraɪt/","usIpa":"/ˈpaɪraɪt/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"a shiny yellow mineral containing iron and sulphur","vi":"khoáng vật vàng giả, quặng pyrit (một loại khoáng sản màu vàng sáng chứa sắt và lưu huỳnh)"}],"examples":[{"en":"The tiny piece of pyrite glittered in her palm.","vi":"Mẩu quặng pyrit nhỏ xíu lấp lánh trong lòng bàn tay cô ấy.","audioKind":"ex"},{"en":"Although pyrite resembles gold, its chemical composition and commercial value are very different from those of gold.","vi":"Mặc dù pyrit trông rất giống vàng, nhưng thành phần hóa học và giá trị thương mại của nó lại hoàn toàn khác biệt so với vàng.","audioKind":"ex2"}],"collocations":[{"en":"pyrite crystals","vi":"tinh thể quặng pyrit"},{"en":"pyrite deposits","vi":"mỏ quặng pyrit"},{"en":"iron pyrite","vi":"quặng sắt pyrit"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Do ngoại hình giống vàng nên còn được gọi là fool’s gold (vàng của kẻ ngốc).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alga', 'en-c2-13', 'alga', '/ˈælɡə/', 'C2', 'tảo; thực vật phù du', 'n.', 'algae (n.), algal (adj.)', NULL, 'alga là danh từ số ít, dạng số nhiều là algae; khi nói chung về tảo, người ta thường dùng dạng số nhiều.', 'Under the microscope, the tiny green alga looked beautiful.', NULL, 'Dưới kính hiển vi, tế bào tảo xanh nhỏ xíu trông rất đẹp.', '{"wordId":"alga","ukIpa":"/ˈælɡə/","usIpa":"/ˈælɡə/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A simple organism that photosynthesises, usually living in water.","vi":"tảo; thực vật phù du"}],"examples":[{"en":"Under the microscope, the tiny green alga looked beautiful.","vi":"Dưới kính hiển vi, tế bào tảo xanh nhỏ xíu trông rất đẹp.","audioKind":"ex"},{"en":"Researchers are investigating whether this freshwater alga can remove pollutants from wastewater while producing material suitable for biofuel.","vi":"Các nhà nghiên cứu đang tìm hiểu xem loài tảo nước ngọt này có thể loại bỏ chất ô nhiễm khỏi nước thải đồng thời tạo ra nguyên liệu thích hợp cho nhiên liệu sinh học hay không.","audioKind":"ex2"}],"collocations":[{"en":"a freshwater alga","vi":"một loài tảo nước ngọt"},{"en":"green algae","vi":"tảo xanh"},{"en":"algal growth","vi":"sự phát triển của tảo"}],"wordFamily":["algae (n.)","algal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"alga là danh từ số ít, dạng số nhiều là algae; khi nói chung về tảo, người ta thường dùng dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tetrad', 'en-c2-13', 'tetrad', '/ˈtetræd/', 'C2', 'một nhóm gồm bốn thứ; bốn chromatid (tứ phân thể) hình thành khi các nhiễm sắc thể tương đồng bắt cặp trong giảm phân', 'n.', 'tetradic (adj.)', NULL, 'Thuật ngữ chuyên ngành; tứ phân thể trong sinh học bao gồm bốn nhiễm sắc thể đơn.', 'Under the microscope, we spotted a tetrad of cells.', NULL, 'Dưới kính hiển vi, chúng tôi đã phát hiện một nhóm gồm bốn tế bào.', '{"wordId":"tetrad","ukIpa":"/ˈtetræd/","usIpa":"/ˈtetræd/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A group or set of four things.","vi":"một nhóm gồm bốn thứ"},{"pos":"n.","en":"Four chromatids formed when homologous chromosomes pair during meiosis.","vi":"bốn chromatid (tứ phân thể) hình thành khi các nhiễm sắc thể tương đồng bắt cặp trong giảm phân"}],"examples":[{"en":"Under the microscope, we spotted a tetrad of cells.","vi":"Dưới kính hiển vi, chúng tôi đã phát hiện một nhóm gồm bốn tế bào.","audioKind":"ex"},{"en":"During meiosis, each tetrad allows genetic material to be exchanged between paired chromosomes, contributing to biological diversity.","vi":"Trong quá trình giảm phân, mỗi tứ phân thể cho phép vật liệu di truyền được trao đổi giữa các nhiễm sắc thể đã bắt cặp, góp phần tạo nên sự đa dạng sinh học.","audioKind":"ex2"}],"collocations":[{"en":"a tetrad of cells","vi":"một nhóm bốn tế bào"},{"en":"tetrad formation","vi":"sự hình thành tứ phân thể"},{"en":"tetrad analysis","vi":"phân tích tứ phân thể"}],"wordFamily":["tetradic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ chuyên ngành; tứ phân thể trong sinh học bao gồm bốn nhiễm sắc thể đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coefficient', 'en-c2-13', 'coefficient', '/ˌkoʊɪˈfɪʃənt/', 'C2', 'hệ số', 'n.', NULL, NULL, 'Trong toán học và khoa học, từ này chỉ hệ số; hệ số tương quan cao không có nghĩa là chắc chắn có quan hệ nhân quả.', 'Our teacher explained how the coefficient changes the curve.', NULL, 'Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong.', '{"wordId":"coefficient","ukIpa":"/ˌkəʊɪˈfɪʃənt/","usIpa":"/ˌkoʊɪˈfɪʃənt/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A numerical factor multiplying a variable or measuring a property.","vi":"hệ số"}],"examples":[{"en":"Our teacher explained how the coefficient changes the curve.","vi":"Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong.","audioKind":"ex"},{"en":"A high correlation coefficient indicates a strong statistical relationship, but it does not necessarily establish causation.","vi":"Hệ số tương quan cao cho thấy mối liên hệ thống kê chặt chẽ, nhưng điều đó không nhất thiết chứng minh được quan hệ nhân quả.","audioKind":"ex2"}],"collocations":[{"en":"correlation coefficient","vi":"hệ số tương quan"},{"en":"coefficient of friction","vi":"hệ số ma sát"},{"en":"thermal expansion coefficient","vi":"hệ số giãn nở nhiệt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong toán học và khoa học, từ này chỉ hệ số; hệ số tương quan cao không có nghĩa là chắc chắn có quan hệ nhân quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oscillation', 'en-c2-13', 'oscillation', '/ˌɑːsɪˈleɪʃən/', 'C2', 'sự dao động; sự đu đưa; sự biến động', 'n.', 'oscillate (v.), oscillator (n.), oscillatory (adj.)', NULL, 'Vừa chỉ chuyển động qua lại của vật thể, vừa chỉ sự thay đổi lặp đi lặp lại của giá trị hoặc quan điểm.', 'We watched the slow oscillation of the clock''s pendulum.', NULL, 'Chúng tôi ngắm nhìn nhịp dao động chậm rãi qua lại của quả lắc đồng hồ.', '{"wordId":"oscillation","ukIpa":"/ˌɒsɪˈleɪʃən/","usIpa":"/ˌɑːsɪˈleɪʃən/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"Repeated movement backwards and forwards around a central position.","vi":"sự dao động; sự đu đưa"},{"pos":"n.","en":"Repeated change between different values, states, or opinions.","vi":"sự biến động; sự dao động"}],"examples":[{"en":"We watched the slow oscillation of the clock''s pendulum.","vi":"Chúng tôi ngắm nhìn nhịp dao động chậm rãi qua lại của quả lắc đồng hồ.","audioKind":"ex"},{"en":"Regular oscillations in ocean temperatures can influence rainfall patterns and agricultural productivity across large regions.","vi":"Sự biến động đều đặn của nhiệt độ đại dương có thể ảnh hưởng đến quy luật mưa và năng suất nông nghiệp ở nhiều vùng rộng lớn.","audioKind":"ex2"}],"collocations":[{"en":"pendulum oscillation","vi":"dao động của con lắc"},{"en":"frequency of oscillation","vi":"tần số dao động"},{"en":"temperature oscillations","vi":"sự biến động nhiệt độ"}],"wordFamily":["oscillate (v.)","oscillator (n.)","oscillatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa chỉ chuyển động qua lại của vật thể, vừa chỉ sự thay đổi lặp đi lặp lại của giá trị hoặc quan điểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slag', 'en-c2-13', 'slag', '/slæɡ/', 'C2', 'xỉ lò; xỉ quặng', 'n.', NULL, NULL, 'Nghĩa công nghiệp thường không đếm được; còn có nghĩa tiếng lóng Anh mang ý lăng mạ phụ nữ, tránh dùng.', 'Dark heaps of slag stood beside the old factory.', NULL, 'Những đống xỉ đen nằm ngổn ngang cạnh nhà máy cũ.', '{"wordId":"slag","ukIpa":"/slæɡ/","usIpa":"/slæɡ/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"Waste material separated from metal during smelting","vi":"xỉ lò; xỉ quặng"}],"examples":[{"en":"Dark heaps of slag stood beside the old factory.","vi":"Những đống xỉ đen nằm ngổn ngang cạnh nhà máy cũ.","audioKind":"ex"},{"en":"Reusing slag in road construction can reduce industrial waste and demand for newly quarried materials.","vi":"Việc tái sử dụng xỉ trong xây dựng đường sá có thể giảm chất thải công nghiệp và nhu cầu khai thác vật liệu mới.","audioKind":"ex2"}],"collocations":[{"en":"blast furnace slag","vi":"xỉ lò cao"},{"en":"slag heap","vi":"đống xỉ quặng"},{"en":"steel slag","vi":"xỉ thép"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa công nghiệp thường không đếm được; còn có nghĩa tiếng lóng Anh mang ý lăng mạ phụ nữ, tránh dùng.","noteVi":"Còn có nghĩa lóng Anh lăng mạ phụ nữ; ở đây chỉ dùng nghĩa công nghiệp.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tare', 'en-c2-13', 'tare', '/ter/', 'C2', 'trọng lượng của bao bì hoặc vật chứa (bì); điều chỉnh cái cân để trừ đi trọng lượng của vật chứa (đưa về số không)', 'n.', NULL, NULL, 'Tare là khối lượng vỏ hộp; trọng lượng tịnh bằng tổng trọng lượng trừ đi trọng lượng bì.', 'Tare the scale before adding flour to the bowl.', NULL, 'Hãy trừ bì cái cân trước khi cho bột vào tô.', '{"wordId":"tare","ukIpa":"/teə/","usIpa":"/ter/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"the weight of packaging or a container without its contents","vi":"trọng lượng của bao bì hoặc vật chứa (bì)"},{"pos":"v.","en":"adjust a scale to exclude the weight of a container","vi":"điều chỉnh cái cân để trừ đi trọng lượng của vật chứa (đưa về số không)"}],"examples":[{"en":"Tare the scale before adding flour to the bowl.","vi":"Hãy trừ bì cái cân trước khi cho bột vào tô.","audioKind":"ex"},{"en":"Accurate tare measurements allow food producers to calculate product weight without including the packaging.","vi":"Việc đo lường trọng lượng bì chính xác giúp các nhà sản xuất thực phẩm tính toán được khối lượng sản phẩm mà không tính phần bao bì.","audioKind":"ex2"}],"collocations":[{"en":"tare weight","vi":"trọng lượng bì"},{"en":"tare the scale","vi":"đưa cân về số không để trừ bì"},{"en":"deduct the tare","vi":"khấu trừ trọng lượng bì"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tare là khối lượng vỏ hộp; trọng lượng tịnh bằng tổng trọng lượng trừ đi trọng lượng bì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ingot', 'en-c2-13', 'ingot', '/ˈɪŋɡət/', 'C2', 'thỏi kim loại được đúc khối để lưu trữ hoặc gia công', 'n.', NULL, NULL, 'Chỉ khối kim loại được đúc thành thỏi, không chỉ riêng sắt hoặc sắt nguyên chất.', 'The worker lifted a shiny ingot with heavy tongs.', NULL, 'Người công nhân dùng chiếc kẹp lớn để nhấc một thỏi kim loại sáng bóng lên.', '{"wordId":"ingot","ukIpa":"/ˈɪŋɡət/","usIpa":"/ˈɪŋɡət/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A solid block of metal cast for storage or processing.","vi":"thỏi kim loại được đúc khối để lưu trữ hoặc gia công"}],"examples":[{"en":"The worker lifted a shiny ingot with heavy tongs.","vi":"Người công nhân dùng chiếc kẹp lớn để nhấc một thỏi kim loại sáng bóng lên.","audioKind":"ex"},{"en":"Recycled aluminium can be cast into ingots before being processed into components for vehicles and buildings.","vi":"Nhôm tái chế có thể được đúc thành các thỏi trước khi đem đi chế tạo thành các linh kiện cho xe cộ và công trình xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"a gold ingot","vi":"thỏi vàng"},{"en":"an aluminium ingot","vi":"thỏi nhôm"},{"en":"cast into ingots","vi":"đúc thành các thỏi kim loại"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ khối kim loại được đúc thành thỏi, không chỉ riêng sắt hoặc sắt nguyên chất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subsequence', 'en-c2-13', 'subsequence', '/ˈsʌbsɪkwəns/', 'C2', 'chuỗi con; dãy con', 'n.', 'sequence (n.)', NULL, 'Chủ yếu là thuật ngữ toán học và máy tính; "hậu quả" dùng consequence.', 'We selected alternate beads to create a subsequence.', NULL, 'Chúng tôi đã chọn các hạt cườm cách quãng để tạo thành một chuỗi con.', '{"wordId":"subsequence","ukIpa":"/ˈsʌbsɪkwəns/","usIpa":"/ˈsʌbsɪkwəns/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A sequence formed by selecting elements without changing their original order.","vi":"chuỗi con; dãy con"}],"examples":[{"en":"We selected alternate beads to create a subsequence.","vi":"Chúng tôi đã chọn các hạt cườm cách quãng để tạo thành một chuỗi con.","audioKind":"ex"},{"en":"Researchers can analyse a subsequence of genetic data to identify patterns associated with inherited diseases.","vi":"Các nhà nghiên cứu có thể phân tích một dãy con của dữ liệu di truyền để xác định các mẫu liên quan đến các bệnh di truyền.","audioKind":"ex2"}],"collocations":[{"en":"common subsequence","vi":"dãy con chung"},{"en":"convergent subsequence","vi":"dãy con hội tụ"},{"en":"increasing subsequence","vi":"dãy con tăng"}],"wordFamily":["sequence (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu là thuật ngữ toán học và máy tính; \"hậu quả\" dùng consequence.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glycerin', 'en-c2-13', 'glycerin', '/ˈɡlɪsərɪn/', 'C2', 'glycerin; glixerin', 'n.', NULL, 'Đồng nghĩa: glycerol, glycerine', 'Là danh từ không đếm được; cũng được viết là glycerine, tên hóa học là glycerol.', 'This hand cream contains glycerin to keep skin soft.', NULL, 'Kem dưỡng da tay này chứa glycerin giúp da mềm mại.', '{"wordId":"glycerin","ukIpa":"/ˈɡlɪsərɪn/","usIpa":"/ˈɡlɪsərɪn/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"a thick clear liquid used in medicines, foods, and skincare products","vi":"glycerin; glixerin"}],"examples":[{"en":"This hand cream contains glycerin to keep skin soft.","vi":"Kem dưỡng da tay này chứa glycerin giúp da mềm mại.","audioKind":"ex"},{"en":"Manufacturers often add glycerin to skincare products because it helps retain moisture and prevent dryness.","vi":"Các nhà sản xuất thường thêm glycerin vào các sản phẩm chăm sóc da vì nó giúp giữ độ ẩm và ngăn ngừa khô da.","audioKind":"ex2"}],"collocations":[{"en":"vegetable glycerin","vi":"glycerin thực vật"},{"en":"pure glycerin","vi":"glycerin nguyên chất"},{"en":"glycerin soap","vi":"xà phòng glycerin"}],"wordFamily":[],"synonyms":["glycerol","glycerine"],"antonyms":[],"tipVi":"Là danh từ không đếm được; cũng được viết là glycerine, tên hóa học là glycerol.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metallurgy', 'en-c2-13', 'metallurgy', '/ˈmetəlɜːrdʒi/', 'C2', 'luyện kim học', 'n.', 'metallurgical (adj.), metallurgist (n.)', NULL, 'Là danh từ không đếm được; chuyên gia trong lĩnh vực này gọi là metallurgist.', 'My cousin studies metallurgy and tests metals in a laboratory.', NULL, 'Anh họ tôi học ngành luyện kim và tiến hành kiểm tra kim loại trong phòng thí nghiệm.', '{"wordId":"metallurgy","ukIpa":"/məˈtælədʒi/","usIpa":"/ˈmetəlɜːrdʒi/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"The science of extracting metals and studying their properties.","vi":"luyện kim học"}],"examples":[{"en":"My cousin studies metallurgy and tests metals in a laboratory.","vi":"Anh họ tôi học ngành luyện kim và tiến hành kiểm tra kim loại trong phòng thí nghiệm.","audioKind":"ex"},{"en":"Advances in metallurgy have enabled manufacturers to develop lighter materials for more fuel-efficient vehicles.","vi":"Những tiến bộ trong công nghệ luyện kim đã giúp các nhà sản xuất phát triển các vật liệu nhẹ hơn nhằm tạo ra những dòng xe tiết kiệm nhiên liệu hơn.","audioKind":"ex2"}],"collocations":[{"en":"physical metallurgy","vi":"luyện kim vật lý"},{"en":"powder metallurgy","vi":"luyện kim bột"},{"en":"advances in metallurgy","vi":"những tiến bộ trong ngành luyện kim"}],"wordFamily":["metallurgical (adj.)","metallurgist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; chuyên gia trong lĩnh vực này gọi là metallurgist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_benzene', 'en-c2-13', 'benzene', '/ˈbenziːn/', 'C2', 'benzen', 'n.', NULL, NULL, 'Benzen là hợp chất hóa học có độc tính cao; cần tránh nhầm lẫn với từ petrol chỉ xăng theo tiếng Anh-Anh.', 'The technician tested the water for traces of benzene.', NULL, 'Kỹ thuật viên đã kiểm tra nguồn nước xem có chứa dấu vết của benzen hay không.', '{"wordId":"benzene","ukIpa":"/ˈbenziːn/","usIpa":"/ˈbenziːn/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"A toxic, flammable liquid hydrocarbon used in chemical manufacturing.","vi":"benzen"}],"examples":[{"en":"The technician tested the water for traces of benzene.","vi":"Kỹ thuật viên đã kiểm tra nguồn nước xem có chứa dấu vết của benzen hay không.","audioKind":"ex"},{"en":"Strict controls on industrial emissions can reduce workers'' exposure to benzene and other harmful chemicals.","vi":"Việc kiểm soát chặt chẽ lượng khí thải công nghiệp có thể làm giảm nguy cơ công nhân tiếp xúc với benzen và các hóa chất độc hại khác.","audioKind":"ex2"}],"collocations":[{"en":"benzene exposure","vi":"sự phơi nhiễm benzen"},{"en":"benzene emissions","vi":"lượng phát thải benzen"},{"en":"benzene ring","vi":"vòng benzen"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Benzen là hợp chất hóa học có độc tính cao; cần tránh nhầm lẫn với từ petrol chỉ xăng theo tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superstructure', 'en-c2-13', 'superstructure', '/ˈsuːpərstrʌktʃər/', 'C2', 'kiến trúc thượng tầng (của công trình, tàu thuyền); kiến trúc thượng tầng (các thể chế và hệ tư tưởng dựa trên nền tảng kinh tế xã hội)', 'n.', 'structure (n.), structural (adj.)', 'Trái nghĩa: substructure', 'Trong xây dựng chỉ phần nằm trên móng; trong hàng hải chỉ phần nằm trên boong tàu.', 'Workers painted the ship''s superstructure white before its departure.', NULL, 'Các công nhân đã sơn màu trắng phần kiến trúc thượng tầng của con tàu trước khi nó khởi hành.', '{"wordId":"superstructure","ukIpa":"/ˈsuːpəstrʌktʃə/","usIpa":"/ˈsuːpərstrʌktʃər/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"The part of a structure built above its base or deck.","vi":"kiến trúc thượng tầng (của công trình, tàu thuyền)"},{"pos":"n.","en":"Institutions and beliefs supported by a society''s economic system.","vi":"kiến trúc thượng tầng (các thể chế và hệ tư tưởng dựa trên nền tảng kinh tế xã hội)"}],"examples":[{"en":"Workers painted the ship''s superstructure white before its departure.","vi":"Các công nhân đã sơn màu trắng phần kiến trúc thượng tầng của con tàu trước khi nó khởi hành.","audioKind":"ex"},{"en":"Engineers must ensure that a building''s foundations can safely support its entire superstructure under varying environmental conditions.","vi":"Các kỹ sư phải đảm bảo rằng phần móng của một tòa nhà có thể chống đỡ an toàn cho toàn bộ phần kết cấu phía trên dưới các điều kiện môi trường thay đổi khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"ship''s superstructure","vi":"cấu trúc thượng tầng của tàu"},{"en":"steel superstructure","vi":"kết cấu thượng tầng bằng thép"},{"en":"ideological superstructure","vi":"kiến trúc thượng tầng tư tưởng"}],"wordFamily":["structure (n.)","structural (adj.)"],"synonyms":[],"antonyms":["substructure"],"tipVi":"Trong xây dựng chỉ phần nằm trên móng; trong hàng hải chỉ phần nằm trên boong tàu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peroxide', 'en-c2-13', 'peroxide', '/pəˈrɑːksaɪd/', 'C2', 'chất/dung dịch nước ô-xy già (hydrogen peroxide); hợp chất chứa liên kết ô-xy - ô-xy; tẩy trắng tóc bằng nước ô-xy già', 'n.', 'peroxided (adj.)', NULL, 'Trong ngữ cảnh đời thường thường chỉ hydro peroxide, trong hóa học còn dùng chung cho các hợp chất peroxide.', 'The hairdresser used peroxide to lighten her hair.', NULL, 'Thợ làm tóc đã dùng dung dịch ô-xy già để làm sáng màu tóc của cô ấy.', '{"wordId":"peroxide","ukIpa":"/pəˈrɒksaɪd/","usIpa":"/pəˈrɑːksaɪd/","cefr":"C2","topic":"science","senses":[{"pos":"n.","en":"Hydrogen peroxide, or a compound containing an oxygen–oxygen bond","vi":"chất/dung dịch nước ô-xy già (hydrogen peroxide); hợp chất chứa liên kết ô-xy - ô-xy"},{"pos":"v.","en":"To bleach hair using hydrogen peroxide","vi":"tẩy trắng tóc bằng nước ô-xy già"}],"examples":[{"en":"The hairdresser used peroxide to lighten her hair.","vi":"Thợ làm tóc đã dùng dung dịch ô-xy già để làm sáng màu tóc của cô ấy.","audioKind":"ex"},{"en":"Hydrogen peroxide is used in some industrial processes to bleach paper and treat wastewater.","vi":"Hydrogen peroxide được sử dụng trong một số quy trình công nghiệp để tẩy trắng giấy và xử lý nước thải.","audioKind":"ex2"}],"collocations":[{"en":"hydrogen peroxide","vi":"nước ô-xy già"},{"en":"peroxide solution","vi":"dung dịch chứa peroxide"},{"en":"peroxide blonde","vi":"mái tóc vàng do tẩy thuốc"}],"wordFamily":["peroxided (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh đời thường thường chỉ hydro peroxide, trong hóa học còn dùng chung cho các hợp chất peroxide.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pliable', 'en-c2-13', 'pliable', '/ˈplaɪəbl/', 'C2', 'dẻo dai; dễ uốn; dễ gập; dễ bị ảnh hưởng; dễ sai khiến; dễ bảo', 'adj.', 'pliability (n.), pliably (adv.)', 'Đồng nghĩa: flexible, supple · Trái nghĩa: rigid, inflexible', 'Khi mô tả vật liệu, từ này chỉ tính linh hoạt, mềm dẻo; khi mô tả con người, nó thường chỉ sự dễ bị thao túng, sai khiến.', 'Warm the clay until it becomes soft and pliable.', NULL, 'Hãy hâm nóng đất sét cho đến khi nó trở nên mềm và dễ uốn nắn.', '{"wordId":"pliable","ukIpa":"/ˈplaɪəbl/","usIpa":"/ˈplaɪəbl/","cefr":"C2","topic":"science","senses":[{"pos":"adj.","en":"Easy to bend or shape without breaking.","vi":"dẻo dai; dễ uốn; dễ gập"},{"pos":"adj.","en":"Easily influenced or controlled by other people.","vi":"dễ bị ảnh hưởng; dễ sai khiến; dễ bảo"}],"examples":[{"en":"Warm the clay until it becomes soft and pliable.","vi":"Hãy hâm nóng đất sét cho đến khi nó trở nên mềm và dễ uốn nắn.","audioKind":"ex"},{"en":"Pliable materials allow designers to create lightweight products that can be folded for easier storage and transport.","vi":"Các vật liệu dẻo dai giúp các nhà thiết kế tạo ra những sản phẩm trọng lượng nhẹ, có thể gấp gọn để dễ dàng cất giữ và vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"soft and pliable","vi":"mềm và dẻo dai"},{"en":"pliable materials","vi":"vật liệu dẻo dai"},{"en":"keep something pliable","vi":"giữ cho vật gì đó mềm dẻo"}],"wordFamily":["pliability (n.)","pliably (adv.)"],"synonyms":["flexible","supple"],"antonyms":["rigid","inflexible"],"tipVi":"Khi mô tả vật liệu, từ này chỉ tính linh hoạt, mềm dẻo; khi mô tả con người, nó thường chỉ sự dễ bị thao túng, sai khiến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_13_1', 'en-c2-13', 'Cách dùng “pliable” (adj.) — dẻo dai; dễ uốn; dễ gập', 'soft and pliable  ·  pliable materials  ·  keep something pliable', 'Khi mô tả vật liệu, từ này chỉ tính linh hoạt, mềm dẻo; khi mô tả con người, nó thường chỉ sự dễ bị thao túng, sai khiến.', 'Họ từ (Word Family): pliability (n.), pliably (adv.) | Đồng nghĩa: flexible, supple · Trái nghĩa: rigid, inflexible', '[{"hanzi":"Warm the clay until it becomes soft and pliable.","pinyin":"","meaning":"Hãy hâm nóng đất sét cho đến khi nó trở nên mềm và dễ uốn nắn."},{"hanzi":"Pliable materials allow designers to create lightweight products that can be folded for easier storage and transport.","pinyin":"","meaning":"Các vật liệu dẻo dai giúp các nhà thiết kế tạo ra những sản phẩm trọng lượng nhẹ, có thể gấp gọn để dễ dàng cất giữ và vận chuyển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_13_2', 'en-c2-13', 'Cách dùng “sulphide” (n.) — hợp chất sun-fua; muối sun-fua', 'iron sulphide  ·  hydrogen sulphide  ·  sulphide minerals', 'Trong tiếng Anh Mỹ và danh pháp quốc tế, từ này thường được viết là sulfide; cần tránh nhầm lẫn với sulfate (sun-fat).', 'Họ từ (Word Family): sulphur (n.)', '[{"hanzi":"Our teacher showed us a sample of iron sulphide.","pinyin":"","meaning":"Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua."},{"hanzi":"When exposed to air and water, some sulphide minerals can generate acidic drainage that damages nearby ecosystems.","pinyin":"","meaning":"Khi tiếp xúc với không khí và nước, một số khoáng vật sun-fua có thể tạo ra nước thải axit gây hại cho các hệ sinh thái gần đó."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_13_3', 'en-c2-13', 'Cách dùng “coefficient” (n.) — hệ số', 'correlation coefficient  ·  coefficient of friction  ·  thermal expansion coefficient', 'Trong toán học và khoa học, từ này chỉ hệ số; hệ số tương quan cao không có nghĩa là chắc chắn có quan hệ nhân quả.', NULL, '[{"hanzi":"Our teacher explained how the coefficient changes the curve.","pinyin":"","meaning":"Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong."},{"hanzi":"A high correlation coefficient indicates a strong statistical relationship, but it does not necessarily establish causation.","pinyin":"","meaning":"Hệ số tương quan cao cho thấy mối liên hệ thống kê chặt chẽ, nhưng điều đó không nhất thiết chứng minh được quan hệ nhân quả."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_13_4', 'en-c2-13', 'Cách dùng “peroxide” (n.) — chất/dung dịch nước ô-xy già (hydrogen peroxide); hợp chất chứa liên kết ô-xy - ô-xy', 'hydrogen peroxide  ·  peroxide solution  ·  peroxide blonde', 'Trong ngữ cảnh đời thường thường chỉ hydro peroxide, trong hóa học còn dùng chung cho các hợp chất peroxide.', 'Họ từ (Word Family): peroxided (adj.)', '[{"hanzi":"The hairdresser used peroxide to lighten her hair.","pinyin":"","meaning":"Thợ làm tóc đã dùng dung dịch ô-xy già để làm sáng màu tóc của cô ấy."},{"hanzi":"Hydrogen peroxide is used in some industrial processes to bleach paper and treat wastewater.","pinyin":"","meaning":"Hydrogen peroxide được sử dụng trong một số quy trình công nghiệp để tẩy trắng giấy và xử lý nước thải."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_13_1', 'en-c2-13', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_1', 'ten_c2_13_1', 'malleable', 'The warm metal was malleable enough to bend easily.', 'The warm metal was malleable enough to bend easily.', '/ˈmæliəbəl/', 'Miếng kim loại còn ấm có tính dẻo đủ để uốn cong dễ dàng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_2', 'ten_c2_13_1', 'infinitesimal', 'The scratch made an infinitesimal difference to the table''s appearance.', 'The scratch made an infinitesimal difference to the table''s appearance.', '/ˌɪnfɪnɪˈtesɪməl/', 'Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_3', 'ten_c2_13_1', 'sulphide', 'Our teacher showed us a sample of iron sulphide.', 'Our teacher showed us a sample of iron sulphide.', '/ˈsʌlfaɪd/', 'Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_4', 'ten_c2_13_1', 'genus', 'These two garden plants belong to the same genus.', 'These two garden plants belong to the same genus.', '/ˈdʒiːnəs/', 'Hai loài thực vật cảnh này thuộc cùng một chi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_5', 'ten_c2_13_1', 'axial', 'The mechanic checked the shaft for excessive axial movement.', 'The mechanic checked the shaft for excessive axial movement.', '/ˈæksiəl/', 'Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_6', 'ten_c2_13_1', 'elemental', 'The storm awakened an elemental fear deep inside me.', 'The storm awakened an elemental fear deep inside me.', '/ˌelɪˈmentəl/', 'Cơn bão đánh thức một nỗi sợ bản năng sâu thẳm bên trong tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_7', 'ten_c2_13_1', 'radium', 'We learned about radium during our science lesson today.', 'We learned about radium during our science lesson today.', '/ˈreɪdiəm/', 'Chúng tôi đã học về nguyên tố ra-đi trong giờ học khoa học hôm nay.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_1_8', 'ten_c2_13_1', 'pyrite', 'The tiny piece of pyrite glittered in her palm.', 'The tiny piece of pyrite glittered in her palm.', '/ˈpaɪraɪt/', 'Mẩu quặng pyrit nhỏ xíu lấp lánh trong lòng bàn tay cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_13_1_1', 'en-c2-13', 'ten_c2_13_1', 'listening', 'listening', 'The warm metal was malleable enough to bend easily.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã chọn các hạt cườm cách quãng để tạo thành một chuỗi con.","Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong.","Miếng kim loại còn ấm có tính dẻo đủ để uốn cong dễ dàng.","Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không."]'::jsonb, 2, 'The warm metal was malleable enough to bend easily. → Miếng kim loại còn ấm có tính dẻo đủ để uốn cong dễ dàng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_13_1_2', 'en-c2-13', 'ten_c2_13_1', 'listening', 'listening', 'The scratch made an infinitesimal difference to the table''s appearance.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong.","Các công nhân đã sơn màu trắng phần kiến trúc thượng tầng của con tàu trước khi nó khởi hành.","Kỹ thuật viên đã kiểm tra nguồn nước xem có chứa dấu vết của benzen hay không.","Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn."]'::jsonb, 3, 'The scratch made an infinitesimal difference to the table''s appearance. → Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_13_1_3', 'en-c2-13', 'ten_c2_13_1', 'listening', 'listening', 'Our teacher showed us a sample of iron sulphide.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong.","Kem dưỡng da tay này chứa glycerin giúp da mềm mại.","Dưới kính hiển vi, tế bào tảo xanh nhỏ xíu trông rất đẹp.","Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua."]'::jsonb, 3, 'Our teacher showed us a sample of iron sulphide. → Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_13_2', 'en-c2-13', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_2_1', 'ten_c2_13_2', 'malleable', 'Young people''s attitudes are often malleable, making schools important environments for developing respect and social responsibility.', 'Young people''s attitudes are often malleable, making schools important environments for developing respect and social responsibility.', '/ˈmæliəbəl/', 'Thái độ của giới trẻ thường rất dễ uốn nắn, biến trường học thành môi trường quan trọng để bồi dưỡng lòng tôn trọng và trách nhiệm xã hội.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_2_2', 'ten_c2_13_2', 'infinitesimal', 'Even infinitesimal changes in ocean temperature can become significant when measured across vast areas over decades.', 'Even infinitesimal changes in ocean temperature can become significant when measured across vast areas over decades.', '/ˌɪnfɪnɪˈtesɪməl/', 'Ngay cả những thay đổi nhỏ đến vô cùng trong nhiệt độ đại dương cũng có thể trở nên đáng kể khi được đo đạc trên các vùng rộng lớn trong suốt nhiều thập kỷ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_2_3', 'ten_c2_13_2', 'sulphide', 'When exposed to air and water, some sulphide minerals can generate acidic drainage that damages nearby ecosystems.', 'When exposed to air and water, some sulphide minerals can generate acidic drainage that damages nearby ecosystems.', '/ˈsʌlfaɪd/', 'Khi tiếp xúc với không khí và nước, một số khoáng vật sun-fua có thể tạo ra nước thải axit gây hại cho các hệ sinh thái gần đó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_2_4', 'ten_c2_13_2', 'genus', 'Scientists classified the newly discovered frog within an existing genus after comparing its genetic characteristics with related species.', 'Scientists classified the newly discovered frog within an existing genus after comparing its genetic characteristics with related species.', '/ˈdʒiːnəs/', 'Các nhà khoa học đã xếp loài ếch mới phát hiện vào một chi đã có sẵn sau khi so sánh các đặc điểm di truyền của nó với các loài họ hàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_2_5', 'ten_c2_13_2', 'axial', 'Changes in the Earth''s axial tilt influence how solar energy is distributed across the planet.', 'Changes in the Earth''s axial tilt influence how solar energy is distributed across the planet.', '/ˈæksiəl/', 'Sự thay đổi về độ nghiêng trục của Trái Đất ảnh hưởng đến cách phân bố năng lượng mặt trời trên hành tinh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_13_2_6', 'ten_c2_13_2', 'elemental', 'Access to food and shelter addresses elemental human needs that economic policy should never overlook.', 'Access to food and shelter addresses elemental human needs that economic policy should never overlook.', '/ˌelɪˈmentəl/', 'Việc tiếp cận với thực phẩm và nơi ở đáp ứng các nhu cầu cơ bản của con người mà chính sách kinh tế không bao giờ được phớt lờ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_13_2_1', 'en-c2-13', 'ten_c2_13_2', 'listening', 'listening', 'Young people''s attitudes are often malleable, making schools important environments for developing respect and social responsibility.', NULL, 'Trong câu vừa nghe, từ “malleable” mang nghĩa nào sau đây?', '["suy đoán; phỏng đoán","đánh bại hoàn toàn một đối thủ","dễ uốn; dễ gò (kim loại)","thu hồi; hủy bỏ; thủ tiêu (quyết định, quy tắc)"]'::jsonb, 2, '“malleable” (/ˈmæliəbəl/): dễ uốn; dễ gò (kim loại). Câu đầy đủ: Young people''s attitudes are often malleable, making schools important environments for developing respect and social responsibility.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_13_2_2', 'en-c2-13', 'ten_c2_13_2', 'listening', 'listening', 'Even infinitesimal changes in ocean temperature can become significant when measured across vast areas over decades.', NULL, 'Trong câu vừa nghe, từ “infinitesimal” mang nghĩa nào sau đây?', '["khoáng vật vàng giả, quặng pyrit (một loại khoáng sản màu vàng sáng chứa sắt và lưu huỳnh)","vô cùng nhỏ; cực kỳ nhỏ bé","trọng lượng của bao bì hoặc vật chứa (bì)","định giá bằng một loại tiền tệ cụ thể"]'::jsonb, 1, '“infinitesimal” (/ˌɪnfɪnɪˈtesɪməl/): vô cùng nhỏ; cực kỳ nhỏ bé. Câu đầy đủ: Even infinitesimal changes in ocean temperature can become significant when measured across vast areas over decades.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
