INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_1', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'malleable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dễ uốn; dễ gò (kim loại)","vững chắc; có thể đứng vững được","la ó, chế nhạo hoặc cười nhạo ai đó theo cách ác ý","của văn bản này; liên quan đến tài liệu này"]'::jsonb, 0, 'malleable (/ˈmæliəbəl/) → dễ uốn; dễ gò (kim loại); dễ bảo; dễ bị ảnh hưởng; dễ uốn nắn', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_2', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'The scratch made an infinitesimal difference to the table''s appearance.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hai loài thực vật cảnh này thuộc cùng một chi.","Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn.","Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không.","Hãy trừ bì cái cân trước khi cho bột vào tô."]'::jsonb, 1, 'The scratch made an infinitesimal difference to the table''s appearance. → Vết xước đó tạo ra sự khác biệt vô cùng nhỏ đối với vẻ bề ngoài của chiếc bàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_3', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'sulphide', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành","sự giải thoát; sự cứu rỗi","hợp chất sun-fua; muối sun-fua","sự minh oan, việc chính thức tuyên bố ai đó vô tội hoặc không phải chịu trách nhiệm"]'::jsonb, 2, 'sulphide (/ˈsʌlfaɪd/) → hợp chất sun-fua; muối sun-fua', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_4', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'These two garden plants belong to the same genus.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã học về nguyên tố ra-đi trong giờ học khoa học hôm nay.","Hai loài thực vật cảnh này thuộc cùng một chi.","Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không.","Dưới kính hiển vi, chúng tôi đã phát hiện một nhóm gồm bốn tế bào."]'::jsonb, 1, 'These two garden plants belong to the same genus. → Hai loài thực vật cảnh này thuộc cùng một chi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_5', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'axial', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ôn hòa; hòa bình; chuộng hòa bình","sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt","thuộc trục; theo trục","chủ nghĩa Lênin (các học thuyết chính trị của Lênin, đặc biệt về cách mạng và sự lãnh đạo của đảng)"]'::jsonb, 2, 'axial (/ˈæksiəl/) → thuộc trục; theo trục', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_6', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'The storm awakened an elemental fear deep inside me.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn bão đánh thức một nỗi sợ bản năng sâu thẳm bên trong tôi.","Người công nhân dùng chiếc kẹp lớn để nhấc một thỏi kim loại sáng bóng lên.","Dưới kính hiển vi, chúng tôi đã phát hiện một nhóm gồm bốn tế bào.","Thợ máy đã kiểm tra xem trục quay có bị chuyển động dọc trục quá mức hay không."]'::jsonb, 0, 'The storm awakened an elemental fear deep inside me. → Cơn bão đánh thức một nỗi sợ bản năng sâu thẳm bên trong tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_7', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'radium', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nguyên tố ra-đi; chất ra-đi","sự ăn cắp vặt; nạn trộm cắp nhỏ nhặt","dồi dào; vô kể; tuôn trào","bước đi chậm chạp và lững thững; lê bước"]'::jsonb, 0, 'radium (/ˈreɪdiəm/) → nguyên tố ra-đi; chất ra-đi', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_8', 'en-c2-13', NULL, 'comprehensive_test', 'listening', 'The tiny piece of pyrite glittered in her palm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên của chúng tôi đã giải thích cách hệ số làm thay đổi hình dáng của đường cong.","Mẩu quặng pyrit nhỏ xíu lấp lánh trong lòng bàn tay cô ấy.","Giáo viên của chúng tôi đã cho xem một mẫu sắt sun-fua.","Những đống xỉ đen nằm ngổn ngang cạnh nhà máy cũ."]'::jsonb, 1, 'The tiny piece of pyrite glittered in her palm. → Mẩu quặng pyrit nhỏ xíu lấp lánh trong lòng bàn tay cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
