INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_17', 'en-c2-13', NULL, 'comprehensive_test', 'fill_blank', NULL, NULL, 'Điền từ thích hợp vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_18', 'en-c2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Young people''s attitudes are often malleable, making schools important environments for developing respect and social responsibility.', 'Dựa vào câu trên, từ “malleable” có nghĩa phù hợp nhất là gì?', '["hình ảnh phản chiếu; sự phản chiếu","dễ uốn; dễ gò (kim loại)","vùng rìa rừng; bìa rừng","thủy thủ; hải thủ"]'::jsonb, 1, 'malleable: dễ uốn; dễ gò (kim loại); dễ bảo; dễ bị ảnh hưởng; dễ uốn nắn. Dịch cả câu: Thái độ của giới trẻ thường rất dễ uốn nắn, biến trường học thành môi trường quan trọng để bồi dưỡng lòng tôn trọng và trách nhiệm xã hội.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_19', 'en-c2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Even infinitesimal changes in ocean temperature can become significant when measured across vast areas over decades.', 'Dựa vào câu trên, từ “infinitesimal” có nghĩa phù hợp nhất là gì?', '["vô cùng nhỏ; cực kỳ nhỏ bé","chân chất; ngây thơ; thật thà","nhỏ nhắn và tinh xảo; xinh xắn","đeo kính"]'::jsonb, 0, 'infinitesimal: vô cùng nhỏ; cực kỳ nhỏ bé; đại lượng vô cùng nhỏ. Dịch cả câu: Ngay cả những thay đổi nhỏ đến vô cùng trong nhiệt độ đại dương cũng có thể trở nên đáng kể khi được đo đạc trên các vùng rộng lớn trong suốt nhiều thập kỷ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_20', 'en-c2-13', NULL, 'comprehensive_test', 'reading', NULL, 'When exposed to air and water, some sulphide minerals can generate acidic drainage that damages nearby ecosystems.', 'Dựa vào câu trên, từ “sulphide” có nghĩa phù hợp nhất là gì?', '["cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết","ân hận; hối lỗi; ăn năn","hợp chất sun-fua; muối sun-fua","thời kỳ thuyên giảm, giai đoạn bệnh tình thuyên giảm hoặc ngừng phát triển"]'::jsonb, 2, 'sulphide: hợp chất sun-fua; muối sun-fua. Dịch cả câu: Khi tiếp xúc với không khí và nước, một số khoáng vật sun-fua có thể tạo ra nước thải axit gây hại cho các hệ sinh thái gần đó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_21', 'en-c2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Scientists classified the newly discovered frog within an existing genus after comparing its genetic characteristics with related species.', 'Dựa vào câu trên, từ “genus” có nghĩa phù hợp nhất là gì?', '["chi (đơn vị phân loại sinh học bao gồm các loài có họ hàng gần)","ngon lành; thơm ngon; hấp dẫn","tuyên bố; khẳng định (cảm xúc hoặc niềm tin), đôi khi không chân thành","xương chày"]'::jsonb, 0, 'genus: chi (đơn vị phân loại sinh học bao gồm các loài có họ hàng gần). Dịch cả câu: Các nhà khoa học đã xếp loài ếch mới phát hiện vào một chi đã có sẵn sau khi so sánh các đặc điểm di truyền của nó với các loài họ hàng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_22', 'en-c2-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kiến trúc thượng tầng (của công trình, tàu thuyền)”', '["vehement","countenance","superstructure","reflexion"]'::jsonb, 2, 'kiến trúc thượng tầng (của công trình, tàu thuyền) → superstructure (/ˈsuːpərstrʌktʃər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_23', 'en-c2-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chất/dung dịch nước ô-xy già (hydrogen peroxide); hợp chất chứa liên kết ô-xy - ô-xy”', '["peroxide","goad","superintend","learned"]'::jsonb, 0, 'chất/dung dịch nước ô-xy già (hydrogen peroxide); hợp chất chứa liên kết ô-xy - ô-xy → peroxide (/pəˈrɑːksaɪd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_13_24', 'en-c2-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dẻo dai; dễ uốn; dễ gập”', '["treatise","terminable","pliable","depute"]'::jsonb, 2, 'dẻo dai; dễ uốn; dễ gập → pliable (/ˈplaɪəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-14', 'en', 'Bài 14: Đời sống hằng ngày - CEFR C2', 'CEFR C2', 'C2 · Đời sống', '28 từ vựng Tiếng Anh CEFR C2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6014, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profuse', 'en-c2-14', 'profuse', '/prəˈfjuːs/', 'C2', 'dồi dào; vô kể; tuôn trào', 'adj.', 'profusely (adv.), profusion (n.)', 'Đồng nghĩa: abundant, copious · Trái nghĩa: scant', 'Thường đi kèm với các từ chỉ mồ hôi, lời xin lỗi hoặc lòng biết ơn, nhằm nhấn mạnh số lượng lớn hoặc sự lặp đi lặp lại.', 'He offered profuse apologies for spilling my tea.', NULL, 'Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi.', '{"wordId":"profuse","ukIpa":"/prəˈfjuːs/","usIpa":"/prəˈfjuːs/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Produced or expressed in very large amounts","vi":"dồi dào; vô kể; tuôn trào"}],"examples":[{"en":"He offered profuse apologies for spilling my tea.","vi":"Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi.","audioKind":"ex"},{"en":"Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.","vi":"Đổ mồ hôi nhiều khi tập thể dục ngoài trời có thể làm mất nước, vì vậy việc bổ sung nước thường xuyên trở nên đặc biệt quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"profuse apologies","vi":"lời xin lỗi chân thành; xin lỗi rối rít"},{"en":"profuse sweating","vi":"ra nhiều mồ hôi; đổ mồ hôi đầm đìa"},{"en":"profuse thanks","vi":"cảm ơn chân thành; vô cùng biết ơn"}],"wordFamily":["profusely (adv.)","profusion (n.)"],"synonyms":["abundant","copious"],"antonyms":["scant"],"tipVi":"Thường đi kèm với các từ chỉ mồ hôi, lời xin lỗi hoặc lòng biết ơn, nhằm nhấn mạnh số lượng lớn hoặc sự lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glutinous', 'en-c2-14', 'glutinous', '/ˈɡluːtənəs/', 'C2', 'dẻo quánh; dính', 'adj.', NULL, 'Đồng nghĩa: sticky, 粘稠', 'glutinous chỉ độ dẻo/dính; bản thân gạo nếp không chứa gluten (gluten-free).', 'The glutinous rice stuck firmly to my wooden spoon.', NULL, 'Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi.', '{"wordId":"glutinous","ukIpa":"/ˈɡluːtɪnəs/","usIpa":"/ˈɡluːtənəs/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Thick and sticky, especially when cooked","vi":"dẻo quánh; dính"}],"examples":[{"en":"The glutinous rice stuck firmly to my wooden spoon.","vi":"Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi.","audioKind":"ex"},{"en":"Glutinous rice is used in many traditional dishes, reflecting the importance of texture in regional cuisines.","vi":"Gạo nếp được dùng trong nhiều món ăn truyền thống, thể hiện tầm quan trọng của kết cấu món ăn trong ẩm thực vùng miền.","audioKind":"ex2"}],"collocations":[{"en":"glutinous rice","vi":"gạo nếp"},{"en":"a glutinous texture","vi":"kết cấu dẻo quánh"}],"wordFamily":[],"synonyms":["sticky","粘稠"],"antonyms":[],"tipVi":"glutinous chỉ độ dẻo/dính; bản thân gạo nếp không chứa gluten (gluten-free).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_needful', 'en-c2-14', 'needful', '/ˈniːdfəl/', 'C2', 'cần thiết; thiết yếu', 'adj.', 'need (n.), need (v.), needy (adj.)', 'Đồng nghĩa: necessary, essential · Trái nghĩa: unnecessary', 'Từ này mang tính cổ hoặc trang trọng hơn; trong văn viết IELTS thường dùng necessary.', 'They packed everything needful for the long winter journey.', NULL, 'Họ đã đóng gói mọi thứ cần thiết cho chuyến hành trình dài ngày trong mùa đông.', '{"wordId":"needful","ukIpa":"/ˈniːdfəl/","usIpa":"/ˈniːdfəl/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"necessary for a particular purpose","vi":"cần thiết; thiết yếu"}],"examples":[{"en":"They packed everything needful for the long winter journey.","vi":"Họ đã đóng gói mọi thứ cần thiết cho chuyến hành trình dài ngày trong mùa đông.","audioKind":"ex"},{"en":"Reliable access to clean water is needful for maintaining public health in isolated rural communities.","vi":"Việc tiếp cận nguồn nước sạch đáng tin cậy là điều thiết yếu để duy trì sức khỏe cộng đồng ở các vùng nông thôn cô lập.","audioKind":"ex2"}],"collocations":[{"en":"needful supplies","vi":"vật tư thiết yếu"},{"en":"everything needful","vi":"mọi thứ cần thiết"},{"en":"do the needful","vi":"làm những việc cần thiết"}],"wordFamily":["need (n.)","need (v.)","needy (adj.)"],"synonyms":["necessary","essential"],"antonyms":["unnecessary"],"tipVi":"Từ này mang tính cổ hoặc trang trọng hơn; trong văn viết IELTS thường dùng necessary.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mincer', 'en-c2-14', 'mincer', '/ˈmɪnsər/', 'C2', 'máy xay thịt; máy băm thịt', 'n.', 'mince (v.), minced (adj.)', 'Đồng nghĩa: meat grinder', 'Tiếng Anh-Anh thường dùng mincer, trong khi tiếng Anh-Mỹ dùng meat grinder.', 'We used a mincer to prepare meat for dumplings.', NULL, 'Chúng tôi dùng máy xay thịt để chuẩn bị nguyên liệu làm sủi cảo.', '{"wordId":"mincer","ukIpa":"/ˈmɪnsə/","usIpa":"/ˈmɪnsər/","cefr":"C2","topic":"daily","senses":[{"pos":"n.","en":"A machine that cuts meat into very small pieces.","vi":"máy xay thịt; máy băm thịt"}],"examples":[{"en":"We used a mincer to prepare meat for dumplings.","vi":"Chúng tôi dùng máy xay thịt để chuẩn bị nguyên liệu làm sủi cảo.","audioKind":"ex"},{"en":"Small food businesses can improve efficiency by using an electric mincer rather than chopping meat by hand.","vi":"Các doanh nghiệp thực phẩm nhỏ có thể nâng cao hiệu quả bằng cách sử dụng máy xay thịt điện thay vì băm thịt bằng tay.","audioKind":"ex2"}],"collocations":[{"en":"electric mincer","vi":"máy xay thịt điện"},{"en":"meat mincer","vi":"máy xay thịt"},{"en":"manual mincer","vi":"máy xay thịt cầm tay"}],"wordFamily":["mince (v.)","minced (adj.)"],"synonyms":["meat grinder"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng mincer, trong khi tiếng Anh-Mỹ dùng meat grinder.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pervade', 'en-c2-14', 'pervade', '/pɚˈveɪd/', 'C2', 'lan tỏa; bao trùm; thấm đượm khắp nơi', 'v.', 'pervasive (adj.), pervasiveness (n.)', 'Đồng nghĩa: permeate', 'Là ngoại động từ, đi trực tiếp với địa điểm hoặc lĩnh vực mà không cần giới từ.', 'The smell of fresh bread pervaded the kitchen.', NULL, 'Mùi thơm của bánh mì mới nướng lan tỏa khắp căn bếp.', '{"wordId":"pervade","ukIpa":"/pəˈveɪd/","usIpa":"/pɚˈveɪd/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"to spread throughout a place or affect every part","vi":"lan tỏa; bao trùm; thấm đượm khắp nơi"}],"examples":[{"en":"The smell of fresh bread pervaded the kitchen.","vi":"Mùi thơm của bánh mì mới nướng lan tỏa khắp căn bếp.","audioKind":"ex"},{"en":"Digital technology now pervades everyday life, changing how people communicate, study, and access public services.","vi":"Công nghệ kỹ thuật số giờ đây đã thấm sâu vào đời sống hàng ngày, thay đổi cách con người giao tiếp, học tập và tiếp cận dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"pervade society","vi":"trùm khắp xã hội"},{"en":"pervade the atmosphere","vi":"bao trùm bầu không khí"},{"en":"a sense of unease pervades","vi":"cảm giác bất an lan tỏa"}],"wordFamily":["pervasive (adj.)","pervasiveness (n.)"],"synonyms":["permeate"],"antonyms":[],"tipVi":"Là ngoại động từ, đi trực tiếp với địa điểm hoặc lĩnh vực mà không cần giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_raucous', 'en-c2-14', 'raucous', '/ˈrɔːkəs/', 'C2', 'chói tai; ồn ào', 'adj.', 'raucously (adv.), raucousness (n.)', 'Đồng nghĩa: noisy, harsh · Trái nghĩa: quiet', 'Nhấn mạnh âm thanh thô ráp, chói tai hoặc náo động, không chỉ đơn thuần là khàn giọng.', 'Raucous laughter from the kitchen woke the sleeping cat.', NULL, 'Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.', '{"wordId":"raucous","ukIpa":"/ˈrɔːkəs/","usIpa":"/ˈrɔːkəs/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Unpleasantly loud and harsh in sound.","vi":"chói tai; ồn ào"}],"examples":[{"en":"Raucous laughter from the kitchen woke the sleeping cat.","vi":"Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.","audioKind":"ex"},{"en":"Residents argue that raucous nightlife disrupts sleep and reduces the appeal of otherwise attractive urban neighbourhoods.","vi":"Cư dân lập luận rằng đời sống về đêm ồn ào làm gián đoạn giấc ngủ và giảm đi sức hấp dẫn vốn có của các khu phố đô thị.","audioKind":"ex2"}],"collocations":[{"en":"raucous laughter","vi":"tiếng cười chói tai"},{"en":"raucous crowd","vi":"đám đông ồn ào"},{"en":"raucous voice","vi":"giọng nói thô ráp, chói tai"}],"wordFamily":["raucously (adv.)","raucousness (n.)"],"synonyms":["noisy","harsh"],"antonyms":["quiet"],"tipVi":"Nhấn mạnh âm thanh thô ráp, chói tai hoặc náo động, không chỉ đơn thuần là khàn giọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strew', 'en-c2-14', 'strew', '/struː/', 'C2', 'rải; rắc; vứt bừa bãi', 'v.', NULL, 'Đồng nghĩa: scatter · Trái nghĩa: gather', 'Dạng quá khứ là strewed, còn phân từ thường dùng là strewn; hay xuất hiện ở dạng câu bị động.', 'The children strew flower petals along the garden path.', NULL, 'Bọn trẻ rải những cánh hoa dọc theo lối đi trong vườn.', '{"wordId":"strew","ukIpa":"/struː/","usIpa":"/struː/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To scatter things loosely across a surface or area","vi":"rải; rắc; vứt bừa bãi"}],"examples":[{"en":"The children strew flower petals along the garden path.","vi":"Bọn trẻ rải những cánh hoa dọc theo lối đi trong vườn.","audioKind":"ex"},{"en":"Visitors who strew litter across beaches threaten marine wildlife and increase the cost of coastal maintenance.","vi":"Những du khách vứt rác bừa bãi trên bãi biển đe dọa động vật hoang dã biển và làm tăng chi phí dọn dẹp vùng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"strew flowers","vi":"rải hoa"},{"en":"be strewn with litter","vi":"đầy rác vứt bừa"},{"en":"debris strewn across a road","vi":"mảnh vỡ vương vãi khắp mặt đường"}],"wordFamily":[],"synonyms":["scatter"],"antonyms":["gather"],"tipVi":"Dạng quá khứ là strewed, còn phân từ thường dùng là strewn; hay xuất hiện ở dạng câu bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delectable', 'en-c2-14', 'delectable', '/dɪˈlektəbəl/', 'C2', 'ngon lành; thơm ngon; hấp dẫn', 'adj.', NULL, 'Đồng nghĩa: delicious, scrumptious · Trái nghĩa: unappetising', 'Trang trọng hơn hoặc mang tính miêu tả nhiều hơn từ delicious, thường dùng để tả đồ ăn.', 'The bakery sells delectable pastries filled with fresh fruit.', NULL, 'Tiệm bánh bán những chiếc bánh nướng thơm ngon nhân trái cây tươi.', '{"wordId":"delectable","ukIpa":"/dɪˈlektəbəl/","usIpa":"/dɪˈlektəbəl/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely pleasant to taste or eat.","vi":"ngon lành; thơm ngon; hấp dẫn"}],"examples":[{"en":"The bakery sells delectable pastries filled with fresh fruit.","vi":"Tiệm bánh bán những chiếc bánh nướng thơm ngon nhân trái cây tươi.","audioKind":"ex"},{"en":"Local markets attract visitors with delectable regional dishes, helping small food businesses benefit from tourism.","vi":"Các khu chợ địa phương thu hút du khách bằng những món ăn đặc sản ngon lành, giúp các doanh nghiệp ẩm thực nhỏ hưởng lợi từ ngành du lịch.","audioKind":"ex2"}],"collocations":[{"en":"delectable dishes","vi":"món ăn ngon lành"},{"en":"a delectable dessert","vi":"món tráng miệng thơm ngon"},{"en":"delectable treats","vi":"đồ ăn vặt ngon miệng"}],"wordFamily":[],"synonyms":["delicious","scrumptious"],"antonyms":["unappetising"],"tipVi":"Trang trọng hơn hoặc mang tính miêu tả nhiều hơn từ delicious, thường dùng để tả đồ ăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bespectacled', 'en-c2-14', 'bespectacled', '/bɪˈspektəkəld/', 'C2', 'đeo kính', 'adj.', 'spectacles (n.)', NULL, 'Thiên về văn viết miêu tả; trong giao tiếp hàng ngày thường dùng wearing glasses.', 'A bespectacled librarian helped me find the missing book.', NULL, 'Một nhân viên thư viện đeo kính đã giúp tôi tìm cuốn sách bị thất lạc.', '{"wordId":"bespectacled","ukIpa":"/bɪˈspektəkəld/","usIpa":"/bɪˈspektəkəld/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"wearing glasses","vi":"đeo kính"}],"examples":[{"en":"A bespectacled librarian helped me find the missing book.","vi":"Một nhân viên thư viện đeo kính đã giúp tôi tìm cuốn sách bị thất lạc.","audioKind":"ex"},{"en":"Films often portray scientists as bespectacled figures in laboratories, reinforcing a narrow image of scientific careers.","vi":"Phim ảnh thường khắc họa các nhà khoa học là những nhân vật đeo kính trong phòng thí nghiệm, củng cố thêm góc nhìn phiến diện về nghề nghiệp nghiên cứu khoa học.","audioKind":"ex2"}],"collocations":[{"en":"a bespectacled man","vi":"một người đàn ông đeo kính"},{"en":"a bespectacled professor","vi":"một vị giáo sư đeo kính"}],"wordFamily":["spectacles (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thiên về văn viết miêu tả; trong giao tiếp hàng ngày thường dùng wearing glasses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mackintosh', 'en-c2-14', 'mackintosh', '/ˈmækɪntɑːʃ/', 'C2', 'áo mưa', 'n.', NULL, 'Đồng nghĩa: raincoat', 'Từ dùng trong tiếng Anh-Anh, hơi mang phong cách cũ; không chỉ máy tính Apple.', 'She pulled on her mackintosh before walking into the rain.', NULL, 'Cô ấy khoác chiếc áo mưa lên người trước khi bước ra trời mưa.', '{"wordId":"mackintosh","ukIpa":"/ˈmækɪntɒʃ/","usIpa":"/ˈmækɪntɑːʃ/","cefr":"C2","topic":"daily","senses":[{"pos":"n.","en":"A coat made from waterproof material.","vi":"áo mưa"}],"examples":[{"en":"She pulled on her mackintosh before walking into the rain.","vi":"Cô ấy khoác chiếc áo mưa lên người trước khi bước ra trời mưa.","audioKind":"ex"},{"en":"A durable mackintosh can encourage people to walk rather than drive in wet weather.","vi":"Một chiếc áo mưa bền bỉ có thể khuyến khích mọi người đi bộ thay vì lái xe trong thời tiết ẩm ướt.","audioKind":"ex2"}],"collocations":[{"en":"wear a mackintosh","vi":"mặc áo mưa"},{"en":"a waterproof mackintosh","vi":"chiếc áo mưa chống nước"}],"wordFamily":[],"synonyms":["raincoat"],"antonyms":[],"tipVi":"Từ dùng trong tiếng Anh-Anh, hơi mang phong cách cũ; không chỉ máy tính Apple.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cosset', 'en-c2-14', 'cosset', '/ˈkɑːsɪt/', 'C2', 'cưng chiều; âu yếm; chăm sóc quá kỹ', 'v.', NULL, 'Đồng nghĩa: pamper, coddle, spoil · Trái nghĩa: neglect', 'Là ngoại động từ, thường mang hàm ý chăm sóc thái quá; cách dùng làm danh từ hiện đã hiếm gặp.', 'They cosset their elderly dog with blankets and treats.', NULL, 'Họ đắp chăn và cho chú chó già ăn quà vặt, cưng chiều nó vô cùng.', '{"wordId":"cosset","ukIpa":"/ˈkɒsɪt/","usIpa":"/ˈkɑːsɪt/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"to give someone excessive care, comfort, and protection","vi":"cưng chiều; âu yếm; chăm sóc quá kỹ"}],"examples":[{"en":"They cosset their elderly dog with blankets and treats.","vi":"Họ đắp chăn và cho chú chó già ăn quà vặt, cưng chiều nó vô cùng.","audioKind":"ex"},{"en":"Parents who cosset their children may unintentionally limit opportunities for them to develop independence and cope with everyday challenges.","vi":"Những bậc cha mẹ cưng chiều con cái quá mức có thể vô tình hạn chế cơ hội phát triển tính tự lập và khả năng đối phó với những thử thách thường ngày của trẻ.","audioKind":"ex2"}],"collocations":[{"en":"cosset a child","vi":"nuông chiều một đứa trẻ"},{"en":"a cosseted upbringing","vi":"quá trình nuôi dưỡng được nuông chiều"},{"en":"cosseted guests","vi":"những vị khách được chăm sóc chu đáo"}],"wordFamily":[],"synonyms":["pamper","coddle","spoil"],"antonyms":["neglect"],"tipVi":"Là ngoại động từ, thường mang hàm ý chăm sóc thái quá; cách dùng làm danh từ hiện đã hiếm gặp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_murmur', 'en-c2-14', 'murmur', '/ˈmɝːmɚ/', 'C2', 'nói nhỏ; thì thầm; tiếng thì thầm; âm thanh nhỏ liên tục; tiếng phàn nàn nhỏ; lời bất bình', 'v.', NULL, 'Đồng nghĩa: mutter', 'Nhấn mạnh sự nhẹ nhàng, nhỏ tiếng; mutter thường mang ý bất bình hoặc không rõ ràng.', 'She murmured a quiet thank you and smiled.', NULL, 'Cô ấy nói nhỏ một lời cảm ơn rồi mỉm cười.', '{"wordId":"murmur","ukIpa":"/ˈmɜːmə/","usIpa":"/ˈmɝːmɚ/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To speak in a quiet, gentle voice.","vi":"nói nhỏ; thì thầm"},{"pos":"n.","en":"A quiet, continuous sound or softly spoken words.","vi":"tiếng thì thầm; âm thanh nhỏ liên tục"},{"pos":"n.","en":"A quiet expression of dissatisfaction or disagreement.","vi":"tiếng phàn nàn nhỏ; lời bất bình"}],"examples":[{"en":"She murmured a quiet thank you and smiled.","vi":"Cô ấy nói nhỏ một lời cảm ơn rồi mỉm cười.","audioKind":"ex"},{"en":"A murmur of concern spread through the audience as the proposed library closures were announced.","vi":"Một tiếng xôn xao lo lắng lan truyền khắp khán phòng khi thông báo về kế hoạch đóng cửa thư viện được đưa ra.","audioKind":"ex2"}],"collocations":[{"en":"murmur softly","vi":"nói nhẹ nhàng"},{"en":"a murmur of approval","vi":"tiếng tán thành nhỏ"},{"en":"without a murmur","vi":"không một lời phàn nàn"}],"wordFamily":[],"synonyms":["mutter"],"antonyms":[],"tipVi":"Nhấn mạnh sự nhẹ nhàng, nhỏ tiếng; mutter thường mang ý bất bình hoặc không rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shamble', 'en-c2-14', 'shamble', '/ˈʃæm.bəl/', 'C2', 'bước đi chậm chạp và lững thững; lê bước; dáng đi lững thững; bước đi lê lết', 'v.', 'shambling (adj.)', 'Đồng nghĩa: shuffle', 'Nhấn mạnh dáng đi lê lết, nặng nề, không nhất thiết là mất thăng bằng.', 'Still half asleep, he shambled into the kitchen.', NULL, 'Vẫn còn ngái ngủ, anh ấy lê bước vào nhà bếp.', '{"wordId":"shamble","ukIpa":"/ˈʃæm.bəl/","usIpa":"/ˈʃæm.bəl/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To walk slowly and awkwardly, dragging your feet","vi":"bước đi chậm chạp và lững thững; lê bước"},{"pos":"n.","en":"A slow, awkward walk with dragging feet","vi":"dáng đi lững thững; bước đi lê lết"}],"examples":[{"en":"Still half asleep, he shambled into the kitchen.","vi":"Vẫn còn ngái ngủ, anh ấy lê bước vào nhà bếp.","audioKind":"ex"},{"en":"After hours of physical work, exhausted labourers may shamble home rather than walk briskly.","vi":"Sau nhiều giờ lao động chân tay, những người thợ mệt mỏi có thể lết bộ về nhà thay vì bước đi nhanh nhẹn.","audioKind":"ex2"}],"collocations":[{"en":"shamble along","vi":"lê bước đi"},{"en":"shamble into","vi":"lê bước đi vào"},{"en":"shamble across","vi":"lê bước băng qua"}],"wordFamily":["shambling (adj.)"],"synonyms":["shuffle"],"antonyms":[],"tipVi":"Nhấn mạnh dáng đi lê lết, nặng nề, không nhất thiết là mất thăng bằng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scum', 'en-c2-14', 'scum', '/skʌm/', 'C2', 'lớp bọt bẩn; váng bẩn; đồ cặn bã; kẻ đốn mạt (từ mang tính lăng mạ)', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; khi dùng để chỉ người, từ này mang tính lăng mạ rất nặng nên tránh dùng.', 'He skimmed the scum off the simmering soup.', NULL, 'Anh ấy vớt lớp bọt bẩn trên bề mặt nồi canh đang sôi.', '{"wordId":"scum","ukIpa":"/skʌm/","usIpa":"/skʌm/","cefr":"C2","topic":"daily","senses":[{"pos":"n.","en":"An unpleasant layer of waste or bubbles on a liquid.","vi":"lớp bọt bẩn; váng bẩn"},{"pos":"n.","en":"An insulting word for people considered extremely unpleasant or immoral.","vi":"đồ cặn bã; kẻ đốn mạt (từ mang tính lăng mạ)"}],"examples":[{"en":"He skimmed the scum off the simmering soup.","vi":"Anh ấy vớt lớp bọt bẩn trên bề mặt nồi canh đang sôi.","audioKind":"ex"},{"en":"A thick layer of scum on a pond may indicate excessive nutrient levels caused by agricultural runoff.","vi":"Một lớp váng bẩn dày trên mặt ao có thể cho thấy hàm lượng chất dinh dưỡng quá mức do nước thải nông nghiệp chảy vào.","audioKind":"ex2"}],"collocations":[{"en":"skim off the scum","vi":"vớt bọt bẩn"},{"en":"a layer of scum","vi":"một lớp váng bẩn"},{"en":"soap scum","vi":"váng xà phòng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; khi dùng để chỉ người, từ này mang tính lăng mạ rất nặng nên tránh dùng.","noteVi":"Khi chỉ người, đây là từ lăng mạ mạnh","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_averagely', 'en-c2-14', 'averagely', '/ˈævərɪdʒli/', 'C2', 'ở mức độ trung bình; bình thường', 'adv.', 'average (adj.), average (n.), average (v.)', 'Đồng nghĩa: moderately', 'Từ này ít khi được sử dụng; để diễn đạt ý "tính trung bình", người ta thường dùng cụm on average.', 'The team played averagely but still won the match.', NULL, 'Đội bóng chơi ở mức trung bình nhưng vẫn giành chiến thắng trong trận đấu.', '{"wordId":"averagely","ukIpa":"/ˈævərɪdʒli/","usIpa":"/ˈævərɪdʒli/","cefr":"C2","topic":"daily","senses":[{"pos":"adv.","en":"To an ordinary degree, rather than exceptionally well or badly.","vi":"ở mức độ trung bình; bình thường"}],"examples":[{"en":"The team played averagely but still won the match.","vi":"Đội bóng chơi ở mức trung bình nhưng vẫn giành chiến thắng trong trận đấu.","audioKind":"ex"},{"en":"Students who perform averagely in examinations may still demonstrate considerable creativity through practical classroom projects.","vi":"Những học sinh có kết quả thi ở mức trung bình vẫn có thể thể hiện sự sáng tạo đáng kể thông qua các dự án thực hành trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"perform averagely","vi":"thể hiện ở mức trung bình"},{"en":"averagely talented","vi":"có năng lực bình thường"}],"wordFamily":["average (adj.)","average (n.)","average (v.)"],"synonyms":["moderately"],"antonyms":[],"tipVi":"Từ này ít khi được sử dụng; để diễn đạt ý \"tính trung bình\", người ta thường dùng cụm on average.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intersperse', 'en-c2-14', 'intersperse', '/ˌɪntərˈspɜːrs/', 'C2', 'xen kẽ, điểm xuyết, rải rác những thứ khác vào khoảng giữa', 'v.', 'interspersion (n.)', 'Đồng nghĩa: scatter, distribute', 'Cấu trúc intersperse A with B: xen kẽ A với B.', 'She interspersed bright flowers among the herbs on her balcony.', NULL, 'Cô ấy xen kẽ những bông hoa rực rỡ giữa đám thảo mộc trên ban công.', '{"wordId":"intersperse","ukIpa":"/ˌɪntəˈspɜːs/","usIpa":"/ˌɪntərˈspɜːrs/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"to place things among others at intervals","vi":"xen kẽ, điểm xuyết, rải rác những thứ khác vào khoảng giữa"}],"examples":[{"en":"She interspersed bright flowers among the herbs on her balcony.","vi":"Cô ấy xen kẽ những bông hoa rực rỡ giữa đám thảo mộc trên ban công.","audioKind":"ex"},{"en":"Teachers can intersperse short discussions throughout lectures to maintain attention and encourage students to participate.","vi":"Giáo viên có thể lồng ghép các buổi thảo luận ngắn trong suốt bài giảng để duy trì sự tập trung và khuyến khích học sinh tham gia.","audioKind":"ex2"}],"collocations":[{"en":"intersperse A with B","vi":"xen kẽ A với B"},{"en":"be interspersed with","vi":"được đan xen với"},{"en":"intersperse throughout","vi":"phân tán khắp nơi"}],"wordFamily":["interspersion (n.)"],"synonyms":["scatter","distribute"],"antonyms":[],"tipVi":"Cấu trúc intersperse A with B: xen kẽ A với B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paraphernalia', 'en-c2-14', 'paraphernalia', '/ˌpærəfərˈneɪliə/', 'C2', 'đồ đạc lỉnh kỉnh, toàn bộ dụng cụ cần thiết cho một hoạt động cụ thể', 'n.', NULL, 'Đồng nghĩa: equipment, gear', 'Thường đóng vai trò danh từ không đếm được, không đi kèm mạo định a hay thêm đuôi số nhiều s.', 'Our camping paraphernalia filled every corner of the garage.', NULL, 'Toàn bộ dụng cụ cắm trại của chúng tôi đã chiếm kín mọi góc của nhà xe.', '{"wordId":"paraphernalia","ukIpa":"/ˌpærəfəˈneɪliə/","usIpa":"/ˌpærəfərˈneɪliə/","cefr":"C2","topic":"daily","senses":[{"pos":"n.","en":"The various objects needed for a particular activity.","vi":"đồ đạc lỉnh kỉnh, toàn bộ dụng cụ cần thiết cho một hoạt động cụ thể"}],"examples":[{"en":"Our camping paraphernalia filled every corner of the garage.","vi":"Toàn bộ dụng cụ cắm trại của chúng tôi đã chiếm kín mọi góc của nhà xe.","audioKind":"ex"},{"en":"Schools need adequate storage for sports paraphernalia to keep shared spaces safe and equipment accessible to students.","vi":"Các trường học cần có không gian lưu trữ đầy đủ cho các dụng cụ thể thao nhằm đảm bảo khu vực sinh hoạt chung an toàn và giúp học sinh dễ dàng lấy thiết bị.","audioKind":"ex2"}],"collocations":[{"en":"camping paraphernalia","vi":"dụng cụ cắm trại"},{"en":"sports paraphernalia","vi":"thiết bị thể thao"},{"en":"all the paraphernalia","vi":"tất cả đồ đạc lỉnh kỉnh"}],"wordFamily":[],"synonyms":["equipment","gear"],"antonyms":[],"tipVi":"Thường đóng vai trò danh từ không đếm được, không đi kèm mạo định a hay thêm đuôi số nhiều s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upholster', 'en-c2-14', 'upholster', '/ʌpˈhoʊlstər/', 'C2', 'bọc nệm ghế; làm ghế nệm', 'v.', 'upholstery (n.), upholsterer (n.)', NULL, 'Chỉ riêng việc làm đệm và bọc vải cho đồ nội thất, không dùng chung chung cho việc trang trí nội thất.', 'They upholstered the old chair in soft blue velvet.', NULL, 'Họ đã bọc lại chiếc ghế cũ bằng vải nhung màu xanh mềm mại.', '{"wordId":"upholster","ukIpa":"/ʌpˈhəʊlstə/","usIpa":"/ʌpˈhoʊlstər/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To cover furniture with padding and fabric or leather.","vi":"bọc nệm ghế; làm ghế nệm"}],"examples":[{"en":"They upholstered the old chair in soft blue velvet.","vi":"Họ đã bọc lại chiếc ghế cũ bằng vải nhung màu xanh mềm mại.","audioKind":"ex"},{"en":"Learning to upholster furniture can help people extend its useful life and reduce household waste.","vi":"Học cách bọc nệm đồ nội thất có thể giúp kéo dài tuổi thọ của chúng và giảm rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"upholster a chair","vi":"bọc ghế"},{"en":"upholstered in leather","vi":"được bọc bằng da"},{"en":"upholstered furniture","vi":"đồ nội thất bọc nệm"}],"wordFamily":["upholstery (n.)","upholsterer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ riêng việc làm đệm và bọc vải cho đồ nội thất, không dùng chung chung cho việc trang trí nội thất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inveterate', 'en-c2-14', 'inveterate', '/ɪnˈvetərət/', 'C2', 'thâm căn cố đế; nghiện ngập lâu năm', 'adj.', NULL, 'Đồng nghĩa: habitual, confirmed', 'Thường đứng trước danh từ, nhấn mạnh thói quen lâu ngày khó thay đổi.', 'My uncle is an inveterate collector of old maps.', NULL, 'Chú tôi là một người sưu tầm bản đồ cũ lâu năm.', '{"wordId":"inveterate","ukIpa":"/ɪnˈvetərət/","usIpa":"/ɪnˈvetərət/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Having a long-established habit that is unlikely to change.","vi":"thâm căn cố đế; nghiện ngập lâu năm"}],"examples":[{"en":"My uncle is an inveterate collector of old maps.","vi":"Chú tôi là một người sưu tầm bản đồ cũ lâu năm.","audioKind":"ex"},{"en":"Inveterate car users may resist public transport initiatives unless services become substantially more convenient and reliable.","vi":"Những người đã quen lái xe ô tô lâu năm có thể phản đối các sáng kiến giao thông công cộng trừ khi dịch vụ trở nên thuận tiện và đáng tin cậy hơn nhiều.","audioKind":"ex2"}],"collocations":[{"en":"inveterate liar","vi":"kẻ nói dối chuyên nghiệp"},{"en":"inveterate gambler","vi":"con bạc thâm niên"},{"en":"inveterate traveller","vi":"người đam mê du lịch lâu năm"}],"wordFamily":[],"synonyms":["habitual","confirmed"],"antonyms":[],"tipVi":"Thường đứng trước danh từ, nhấn mạnh thói quen lâu ngày khó thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clasp', 'en-c2-14', 'clasp', '/klæsp/', 'C2', 'nắm chặt, ôm chặt; khóa cài, móc cài; cái ôm chặt, cái bắt tay chặt', 'v.', NULL, 'Đồng nghĩa: grip, clutch · Trái nghĩa: release', 'Clasp khi làm động từ nhấn mạnh hành động nắm thật chắc; khi làm danh từ còn chỉ khóa trang sức.', 'She clasped my hand as we crossed the bridge.', NULL, 'Cô ấy siết chặt tay tôi khi chúng tôi băng qua cầu.', '{"wordId":"clasp","ukIpa":"/klɑːsp/","usIpa":"/klæsp/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To hold someone or something firmly.","vi":"nắm chặt, ôm chặt"},{"pos":"n.","en":"A small fastening that holds something closed.","vi":"khóa cài, móc cài"},{"pos":"n.","en":"A firm hold with the hands or arms.","vi":"cái ôm chặt, cái bắt tay chặt"}],"examples":[{"en":"She clasped my hand as we crossed the bridge.","vi":"Cô ấy siết chặt tay tôi khi chúng tôi băng qua cầu.","audioKind":"ex"},{"en":"Young children may clasp a familiar toy during medical appointments because it provides comfort in unfamiliar surroundings.","vi":"Trẻ nhỏ có thể ôm chặt một món đồ chơi quen thuộc khi đi khám bệnh vì nó mang lại cảm giác an ủi trong môi trường xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"clasp someone''s hand","vi":"nắm chặt tay ai đó"},{"en":"clasp your hands together","vi":"hai tay đan chặt vào nhau"},{"en":"a necklace clasp","vi":"khóa cài dây chuyền"}],"wordFamily":[],"synonyms":["grip","clutch"],"antonyms":["release"],"tipVi":"Clasp khi làm động từ nhấn mạnh hành động nắm thật chắc; khi làm danh từ còn chỉ khóa trang sức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loll', 'en-c2-14', 'loll', '/lɑːl/', 'C2', 'nằm hoặc ngồi ngả ngớn, lười biếng; thõng xuống; thõng xuống lỏng lẻo, đặc biệt là đầu hoặc lưỡi', 'v.', NULL, 'Đồng nghĩa: lounge, sprawl', 'Thường đi với about hoặc around, nhấn mạnh tư thế thả lỏng, lười biếng.', 'We lolled on the sofa after our long walk.', NULL, 'Chúng tôi nằm ngả ngớn trên sofa sau chuyến đi bộ dài.', '{"wordId":"loll","ukIpa":"/lɒl/","usIpa":"/lɑːl/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To sit or lie in a relaxed, lazy way.","vi":"nằm hoặc ngồi ngả ngớn, lười biếng; thõng xuống"},{"pos":"v.","en":"To hang loosely, especially the head or tongue.","vi":"thõng xuống lỏng lẻo, đặc biệt là đầu hoặc lưỡi"}],"examples":[{"en":"We lolled on the sofa after our long walk.","vi":"Chúng tôi nằm ngả ngớn trên sofa sau chuyến đi bộ dài.","audioKind":"ex"},{"en":"Comfortable public seating encourages visitors to loll in the shade rather than leave parks during hot weather.","vi":"Ghế ngồi công cộng thoải mái khuyến khích du khách ngồi thư thái dưới bóng râm thay vì rời khỏi công viên trong thời tiết oi bức.","audioKind":"ex2"}],"collocations":[{"en":"loll about","vi":"nằm dài thườn thượt"},{"en":"loll on the sofa","vi":"ngả ngớn trên ghế sofa"},{"en":"tongue lolling out","vi":"lưỡi thõng ra"}],"wordFamily":[],"synonyms":["lounge","sprawl"],"antonyms":[],"tipVi":"Thường đi với about hoặc around, nhấn mạnh tư thế thả lỏng, lười biếng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toddle', 'en-c2-14', 'toddle', '/ˈtɑːdəl/', 'C2', 'chập chững tập đi; bước đi lững thững; đi thong thả; đi dạo', 'v.', 'toddler (n.)', NULL, 'Chủ yếu dùng làm nội động từ; trẻ em đang tập đi được gọi là toddler.', 'The baby toddled across the rug towards her father.', NULL, 'Em bé chập chững bước qua tấm thảm để tiến về phía bố.', '{"wordId":"toddle","ukIpa":"/ˈtɒdəl/","usIpa":"/ˈtɑːdəl/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To walk with short, unsteady steps, especially as a young child.","vi":"chập chững tập đi; bước đi lững thững"},{"pos":"v.","en":"To walk somewhere casually and without hurrying.","vi":"đi thong thả; đi dạo"}],"examples":[{"en":"The baby toddled across the rug towards her father.","vi":"Em bé chập chững bước qua tấm thảm để tiến về phía bố.","audioKind":"ex"},{"en":"As children begin to toddle, safe spaces allow them to develop balance and explore their surroundings independently.","vi":"Khi trẻ bắt đầu tập đi chập chững, không gian an toàn giúp các em phát triển khả năng giữ thăng bằng và tự mình khám phá xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"toddle across the room","vi":"chập chững bước qua phòng"},{"en":"toddle towards someone","vi":"chập chững tiến về phía ai đó"},{"en":"toddle off","vi":"thong thả bước đi"}],"wordFamily":["toddler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu dùng làm nội động từ; trẻ em đang tập đi được gọi là toddler.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drowse', 'en-c2-14', 'drowse', '/draʊz/', 'C2', 'gật gà gật gù; thiu thiu ngủ; trạng thái thiu thiu ngủ', 'v.', 'drowsy (adj.), drowsiness (n.), drowsily (adv.)', 'Đồng nghĩa: doze', 'Mang tính văn phong trang trọng hơn; trong đời sống hàng ngày, từ doze được dùng phổ biến hơn để chỉ việc ngủ gật.', 'Grandfather drowsed in his chair beside the sunny window.', NULL, 'Người ông thiu thiu ngủ trên chiếc ghế bành cạnh ô cửa sổ đầy nắng.', '{"wordId":"drowse","ukIpa":"/draʊz/","usIpa":"/draʊz/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To sleep lightly or be almost asleep.","vi":"gật gà gật gù; thiu thiu ngủ"},{"pos":"n.","en":"A state of being partly asleep.","vi":"trạng thái thiu thiu ngủ"}],"examples":[{"en":"Grandfather drowsed in his chair beside the sunny window.","vi":"Người ông thiu thiu ngủ trên chiếc ghế bành cạnh ô cửa sổ đầy nắng.","audioKind":"ex"},{"en":"Passengers may drowse during long journeys, making comfortable seating an important consideration for transport providers.","vi":"Hành khách có thể thiu thiu ngủ trong những chuyến hành trình dài, do đó ghế ngồi thoải mái là một yếu tố quan trọng cần cân nhắc đối với các nhà cung cấp dịch vụ vận tải.","audioKind":"ex2"}],"collocations":[{"en":"drowse in a chair","vi":"ngủ gật trên ghế"},{"en":"drowse off","vi":"thiu thiu ngủ"},{"en":"in a drowse","vi":"trong trạng thái nửa tỉnh nửa mê"}],"wordFamily":["drowsy (adj.)","drowsiness (n.)","drowsily (adv.)"],"synonyms":["doze"],"antonyms":[],"tipVi":"Mang tính văn phong trang trọng hơn; trong đời sống hàng ngày, từ doze được dùng phổ biến hơn để chỉ việc ngủ gật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wring', 'en-c2-14', 'wring', '/rɪŋ/', 'C2', 'vươn; vắt; ép (nhất là để loại bỏ nước)', 'v.', NULL, 'Đồng nghĩa: twist, squeeze', 'Quá khứ và phân từ quá khứ đều là wrung; vắt khô thường dùng wring out.', 'Wring out the wet towel before hanging it up.', NULL, 'Vắt khô khăn ướt trước khi đem phơi.', '{"wordId":"wring","ukIpa":"/rɪŋ/","usIpa":"/rɪŋ/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To twist and squeeze something, especially to remove liquid.","vi":"vươn; vắt; ép (nhất là để loại bỏ nước)"}],"examples":[{"en":"Wring out the wet towel before hanging it up.","vi":"Vắt khô khăn ướt trước khi đem phơi.","audioKind":"ex"},{"en":"Where washing machines are unavailable, residents must wring out heavy clothes by hand after washing.","vi":"Ở những nơi không có máy giặt, người dân sau khi giặt phải dùng tay vắt khô những bộ quần áo dày.","audioKind":"ex2"}],"collocations":[{"en":"wring out a towel","vi":"vắt khô khăn"},{"en":"wring your hands","vi":"lo lắng xoắn xuýt đôi tay"},{"en":"wring water from clothes","vi":"vắt nước khỏi quần áo"}],"wordFamily":[],"synonyms":["twist","squeeze"],"antonyms":[],"tipVi":"Quá khứ và phân từ quá khứ đều là wrung; vắt khô thường dùng wring out.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ungainly', 'en-c2-14', 'ungainly', '/ʌnˈɡeɪnli/', 'C2', 'về dáng vẻ: vụng về; lóng ngóng; không uyển chuyển', 'adj.', 'ungainliness (n.)', 'Đồng nghĩa: awkward, clumsy · Trái nghĩa: graceful', 'Mặc dù tận cùng bằng -ly, trong tiếng Anh hiện đại đây là tính từ.', 'The young camel rose slowly on its ungainly legs.', NULL, 'Chú lạc đà con từ từ đứng lên bằng đôi chân lóng ngóng của mình.', '{"wordId":"ungainly","ukIpa":"/ʌnˈɡeɪnli/","usIpa":"/ʌnˈɡeɪnli/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Awkward in movement, shape or appearance.","vi":"về dáng vẻ: vụng về; lóng ngóng; không uyển chuyển"}],"examples":[{"en":"The young camel rose slowly on its ungainly legs.","vi":"Chú lạc đà con từ từ đứng lên bằng đôi chân lóng ngóng của mình.","audioKind":"ex"},{"en":"Although early electric vehicles appeared ungainly, improvements in design have made them more attractive to consumers.","vi":"Mặc dù những chiếc xe điện đời đầu trông có vẻ cồng kềnh vụng về, nhưng những cải tiến về thiết kế đã làm chúng thu hút người tiêu dùng hơn.","audioKind":"ex2"}],"collocations":[{"en":"an ungainly movement","vi":"một động tác vụng về"},{"en":"an ungainly figure","vi":"dáng điệu vụng về"},{"en":"an ungainly shape","vi":"hình dáng không cân đối"}],"wordFamily":["ungainliness (n.)"],"synonyms":["awkward","clumsy"],"antonyms":["graceful"],"tipVi":"Mặc dù tận cùng bằng -ly, trong tiếng Anh hiện đại đây là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mildew', 'en-c2-14', 'mildew', '/ˈmɪlduː/', 'C2', 'nấm mốc; bệnh mốc sương; làm cho mốc; bị mốc', 'n.', 'mildewed (adj.)', NULL, 'Khi là danh từ thường không đếm được, chủ yếu chỉ lớp mốc trên bề mặt ẩm ướt hoặc bệnh ở thực vật.', 'We found mildew on the bathroom ceiling after our holiday.', NULL, 'Chúng tôi phát hiện trần phòng tắm bị mốc sau chuyến đi nghỉ.', '{"wordId":"mildew","ukIpa":"/ˈmɪldjuː/","usIpa":"/ˈmɪlduː/","cefr":"C2","topic":"daily","senses":[{"pos":"n.","en":"A thin fungal growth on damp surfaces or plants.","vi":"nấm mốc; bệnh mốc sương"},{"pos":"v.","en":"Develop mildew, or cause something to develop mildew.","vi":"làm cho mốc; bị mốc"}],"examples":[{"en":"We found mildew on the bathroom ceiling after our holiday.","vi":"Chúng tôi phát hiện trần phòng tắm bị mốc sau chuyến đi nghỉ.","audioKind":"ex"},{"en":"Improved ventilation in poorly maintained housing can limit mildew growth and create healthier living conditions for residents.","vi":"Cải thiện sự thông thoáng trong những ngôi nhà kém bảo dưỡng có thể hạn chế sự phát triển của nấm mốc và tạo ra điều kiện sống lành mạnh hơn cho cư dân.","audioKind":"ex2"}],"collocations":[{"en":"powdery mildew","vi":"bệnh phấn trắng"},{"en":"mildew growth","vi":"sự phát triển của nấm mốc"},{"en":"prevent mildew","vi":"chống nấm mốc"}],"wordFamily":["mildewed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ thường không đếm được, chủ yếu chỉ lớp mốc trên bề mặt ẩm ướt hoặc bệnh ở thực vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seclude', 'en-c2-14', 'seclude', '/sɪˈkluːd/', 'C2', 'tách biệt; cho ở ẩn; cô lập', 'v.', 'secluded (adj.), seclusion (n.)', 'Đồng nghĩa: isolate', 'Thường dùng cấu trúc seclude oneself, mang ý nghĩa tự làm cho mình tách biệt khỏi người khác.', 'She secluded herself in the cottage to finish painting.', NULL, 'Cô ấy tự cô lập mình trong ngôi nhà nhỏ ở nông thôn để hoàn thành bức tranh.', '{"wordId":"seclude","ukIpa":"/sɪˈkluːd/","usIpa":"/sɪˈkluːd/","cefr":"C2","topic":"daily","senses":[{"pos":"v.","en":"To keep someone away from other people.","vi":"tách biệt; cho ở ẩn; cô lập"}],"examples":[{"en":"She secluded herself in the cottage to finish painting.","vi":"Cô ấy tự cô lập mình trong ngôi nhà nhỏ ở nông thôn để hoàn thành bức tranh.","audioKind":"ex"},{"en":"Some writers seclude themselves in remote locations to avoid distractions and concentrate on their work.","vi":"Một số nhà văn tự giam mình ở những nơi hẻo lánh để tránh bị phân tâm và tập trung vào công việc sáng tác.","audioKind":"ex2"}],"collocations":[{"en":"seclude oneself","vi":"tự cô lập; ẩn dật"},{"en":"seclude oneself from others","vi":"tránh xa mọi người"}],"wordFamily":["secluded (adj.)","seclusion (n.)"],"synonyms":["isolate"],"antonyms":[],"tipVi":"Thường dùng cấu trúc seclude oneself, mang ý nghĩa tự làm cho mình tách biệt khỏi người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fastidious', 'en-c2-14', 'fastidious', '/fæˈstɪdiəs/', 'C2', 'cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết', 'adj.', 'fastidiously (adv.), fastidiousness (n.)', 'Đồng nghĩa: meticulous, particular, fussy · Trái nghĩa: careless', 'Mang sắc thái tích cực hoặc tiêu cực tùy ngữ cảnh: vừa chỉ sự cẩn trọng nghiêm ngặt, vừa chỉ tính quá mức soi mói, khó chiều.', 'My brother is fastidious about keeping his shoes spotless.', NULL, 'Anh trai tôi rất kỹ tính trong việc giữ cho giày của mình không một hạt bụi.', '{"wordId":"fastidious","ukIpa":"/fæˈstɪdiəs/","usIpa":"/fæˈstɪdiəs/","cefr":"C2","topic":"daily","senses":[{"pos":"adj.","en":"Very attentive to detail and difficult to satisfy.","vi":"cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết"}],"examples":[{"en":"My brother is fastidious about keeping his shoes spotless.","vi":"Anh trai tôi rất kỹ tính trong việc giữ cho giày của mình không một hạt bụi.","audioKind":"ex"},{"en":"Fastidious attention to hygiene in food preparation can reduce contamination risks and help maintain public confidence in restaurants.","vi":"Sự chú ý tỉ mỉ đến từng chi tiết vệ sinh trong khâu chuẩn bị thực phẩm có thể giảm thiểu nguy cơ nhiễm bẩn và củng cố niềm tin của công chúng đối với nhà hàng.","audioKind":"ex2"}],"collocations":[{"en":"fastidious about cleanliness","vi":"kỹ tính về vấn đề sạch sẽ"},{"en":"fastidious attention to detail","vi":"sự chú ý tỉ mỉ đến từng chi tiết"},{"en":"a fastidious eater","vi":"người kén ăn"}],"wordFamily":["fastidiously (adv.)","fastidiousness (n.)"],"synonyms":["meticulous","particular","fussy"],"antonyms":["careless"],"tipVi":"Mang sắc thái tích cực hoặc tiêu cực tùy ngữ cảnh: vừa chỉ sự cẩn trọng nghiêm ngặt, vừa chỉ tính quá mức soi mói, khó chiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_14_1', 'en-c2-14', 'Cách dùng “fastidious” (adj.) — cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết', 'fastidious about cleanliness  ·  fastidious attention to detail  ·  a fastidious eater', 'Mang sắc thái tích cực hoặc tiêu cực tùy ngữ cảnh: vừa chỉ sự cẩn trọng nghiêm ngặt, vừa chỉ tính quá mức soi mói, khó chiều.', 'Họ từ (Word Family): fastidiously (adv.), fastidiousness (n.) | Đồng nghĩa: meticulous, particular, fussy · Trái nghĩa: careless', '[{"hanzi":"My brother is fastidious about keeping his shoes spotless.","pinyin":"","meaning":"Anh trai tôi rất kỹ tính trong việc giữ cho giày của mình không một hạt bụi."},{"hanzi":"Fastidious attention to hygiene in food preparation can reduce contamination risks and help maintain public confidence in restaurants.","pinyin":"","meaning":"Sự chú ý tỉ mỉ đến từng chi tiết vệ sinh trong khâu chuẩn bị thực phẩm có thể giảm thiểu nguy cơ nhiễm bẩn và củng cố niềm tin của công chúng đối với nhà hàng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_14_2', 'en-c2-14', 'Cách dùng “profuse” (adj.) — dồi dào; vô kể; tuôn trào', 'profuse apologies  ·  profuse sweating  ·  profuse thanks', 'Thường đi kèm với các từ chỉ mồ hôi, lời xin lỗi hoặc lòng biết ơn, nhằm nhấn mạnh số lượng lớn hoặc sự lặp đi lặp lại.', 'Họ từ (Word Family): profusely (adv.), profusion (n.) | Đồng nghĩa: abundant, copious · Trái nghĩa: scant', '[{"hanzi":"He offered profuse apologies for spilling my tea.","pinyin":"","meaning":"Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi."},{"hanzi":"Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.","pinyin":"","meaning":"Đổ mồ hôi nhiều khi tập thể dục ngoài trời có thể làm mất nước, vì vậy việc bổ sung nước thường xuyên trở nên đặc biệt quan trọng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_14_3', 'en-c2-14', 'Cách dùng “drowse” (v.) — gật gà gật gù; thiu thiu ngủ', 'drowse in a chair  ·  drowse off  ·  in a drowse', 'Mang tính văn phong trang trọng hơn; trong đời sống hàng ngày, từ doze được dùng phổ biến hơn để chỉ việc ngủ gật.', 'Họ từ (Word Family): drowsy (adj.), drowsiness (n.), drowsily (adv.) | Đồng nghĩa: doze', '[{"hanzi":"Grandfather drowsed in his chair beside the sunny window.","pinyin":"","meaning":"Người ông thiu thiu ngủ trên chiếc ghế bành cạnh ô cửa sổ đầy nắng."},{"hanzi":"Passengers may drowse during long journeys, making comfortable seating an important consideration for transport providers.","pinyin":"","meaning":"Hành khách có thể thiu thiu ngủ trong những chuyến hành trình dài, do đó ghế ngồi thoải mái là một yếu tố quan trọng cần cân nhắc đối với các nhà cung cấp dịch vụ vận tải."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_14_4', 'en-c2-14', 'Cách dùng “scum” (n.) — lớp bọt bẩn; váng bẩn', 'skim off the scum  ·  a layer of scum  ·  soap scum', 'Thường là danh từ không đếm được; khi dùng để chỉ người, từ này mang tính lăng mạ rất nặng nên tránh dùng.', NULL, '[{"hanzi":"He skimmed the scum off the simmering soup.","pinyin":"","meaning":"Anh ấy vớt lớp bọt bẩn trên bề mặt nồi canh đang sôi."},{"hanzi":"A thick layer of scum on a pond may indicate excessive nutrient levels caused by agricultural runoff.","pinyin":"","meaning":"Một lớp váng bẩn dày trên mặt ao có thể cho thấy hàm lượng chất dinh dưỡng quá mức do nước thải nông nghiệp chảy vào."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_14_1', 'en-c2-14', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_1', 'ten_c2_14_1', 'profuse', 'He offered profuse apologies for spilling my tea.', 'He offered profuse apologies for spilling my tea.', '/prəˈfjuːs/', 'Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_2', 'ten_c2_14_1', 'glutinous', 'The glutinous rice stuck firmly to my wooden spoon.', 'The glutinous rice stuck firmly to my wooden spoon.', '/ˈɡluːtənəs/', 'Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_3', 'ten_c2_14_1', 'needful', 'They packed everything needful for the long winter journey.', 'They packed everything needful for the long winter journey.', '/ˈniːdfəl/', 'Họ đã đóng gói mọi thứ cần thiết cho chuyến hành trình dài ngày trong mùa đông.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_4', 'ten_c2_14_1', 'mincer', 'We used a mincer to prepare meat for dumplings.', 'We used a mincer to prepare meat for dumplings.', '/ˈmɪnsər/', 'Chúng tôi dùng máy xay thịt để chuẩn bị nguyên liệu làm sủi cảo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_5', 'ten_c2_14_1', 'pervade', 'The smell of fresh bread pervaded the kitchen.', 'The smell of fresh bread pervaded the kitchen.', '/pɚˈveɪd/', 'Mùi thơm của bánh mì mới nướng lan tỏa khắp căn bếp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_6', 'ten_c2_14_1', 'raucous', 'Raucous laughter from the kitchen woke the sleeping cat.', 'Raucous laughter from the kitchen woke the sleeping cat.', '/ˈrɔːkəs/', 'Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
