INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_1_8', 'ten_c2_14_1', 'delectable', 'The bakery sells delectable pastries filled with fresh fruit.', 'The bakery sells delectable pastries filled with fresh fruit.', '/dɪˈlektəbəl/', 'Tiệm bánh bán những chiếc bánh nướng thơm ngon nhân trái cây tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_14_1_1', 'en-c2-14', 'ten_c2_14_1', 'listening', 'listening', 'He offered profuse apologies for spilling my tea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.","Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi.","Họ đắp chăn và cho chú chó già ăn quà vặt, cưng chiều nó vô cùng.","Anh trai tôi rất kỹ tính trong việc giữ cho giày của mình không một hạt bụi."]'::jsonb, 1, 'He offered profuse apologies for spilling my tea. → Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_14_1_2', 'en-c2-14', 'ten_c2_14_1', 'listening', 'listening', 'The glutinous rice stuck firmly to my wooden spoon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vắt khô khăn ướt trước khi đem phơi.","Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi.","Cô ấy khoác chiếc áo mưa lên người trước khi bước ra trời mưa.","Cô ấy siết chặt tay tôi khi chúng tôi băng qua cầu."]'::jsonb, 1, 'The glutinous rice stuck firmly to my wooden spoon. → Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_14_1_3', 'en-c2-14', 'ten_c2_14_1', 'listening', 'listening', 'They packed everything needful for the long winter journey.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy đã liên tục nói lời xin lỗi vì làm đổ cốc trà của tôi.","Vắt khô khăn ướt trước khi đem phơi.","Anh ấy vớt lớp bọt bẩn trên bề mặt nồi canh đang sôi.","Họ đã đóng gói mọi thứ cần thiết cho chuyến hành trình dài ngày trong mùa đông."]'::jsonb, 3, 'They packed everything needful for the long winter journey. → Họ đã đóng gói mọi thứ cần thiết cho chuyến hành trình dài ngày trong mùa đông.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_14_2', 'en-c2-14', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_2_1', 'ten_c2_14_2', 'profuse', 'Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.', 'Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.', '/prəˈfjuːs/', 'Đổ mồ hôi nhiều khi tập thể dục ngoài trời có thể làm mất nước, vì vậy việc bổ sung nước thường xuyên trở nên đặc biệt quan trọng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_2_2', 'ten_c2_14_2', 'glutinous', 'Glutinous rice is used in many traditional dishes, reflecting the importance of texture in regional cuisines.', 'Glutinous rice is used in many traditional dishes, reflecting the importance of texture in regional cuisines.', '/ˈɡluːtənəs/', 'Gạo nếp được dùng trong nhiều món ăn truyền thống, thể hiện tầm quan trọng của kết cấu món ăn trong ẩm thực vùng miền.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_2_3', 'ten_c2_14_2', 'needful', 'Reliable access to clean water is needful for maintaining public health in isolated rural communities.', 'Reliable access to clean water is needful for maintaining public health in isolated rural communities.', '/ˈniːdfəl/', 'Việc tiếp cận nguồn nước sạch đáng tin cậy là điều thiết yếu để duy trì sức khỏe cộng đồng ở các vùng nông thôn cô lập.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_2_4', 'ten_c2_14_2', 'mincer', 'Small food businesses can improve efficiency by using an electric mincer rather than chopping meat by hand.', 'Small food businesses can improve efficiency by using an electric mincer rather than chopping meat by hand.', '/ˈmɪnsər/', 'Các doanh nghiệp thực phẩm nhỏ có thể nâng cao hiệu quả bằng cách sử dụng máy xay thịt điện thay vì băm thịt bằng tay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_2_5', 'ten_c2_14_2', 'pervade', 'Digital technology now pervades everyday life, changing how people communicate, study, and access public services.', 'Digital technology now pervades everyday life, changing how people communicate, study, and access public services.', '/pɚˈveɪd/', 'Công nghệ kỹ thuật số giờ đây đã thấm sâu vào đời sống hàng ngày, thay đổi cách con người giao tiếp, học tập và tiếp cận dịch vụ công.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_14_2_6', 'ten_c2_14_2', 'raucous', 'Residents argue that raucous nightlife disrupts sleep and reduces the appeal of otherwise attractive urban neighbourhoods.', 'Residents argue that raucous nightlife disrupts sleep and reduces the appeal of otherwise attractive urban neighbourhoods.', '/ˈrɔːkəs/', 'Cư dân lập luận rằng đời sống về đêm ồn ào làm gián đoạn giấc ngủ và giảm đi sức hấp dẫn vốn có của các khu phố đô thị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_14_2_1', 'en-c2-14', 'ten_c2_14_2', 'listening', 'listening', 'Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.', NULL, 'Trong câu vừa nghe, từ “profuse” mang nghĩa nào sau đây?', '["luống cày; rãnh cày","dồi dào; vô kể; tuôn trào","của văn bản này; liên quan đến tài liệu này","bệnh quai bị"]'::jsonb, 1, '“profuse” (/prəˈfjuːs/): dồi dào; vô kể; tuôn trào. Câu đầy đủ: Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_14_2_2', 'en-c2-14', 'ten_c2_14_2', 'listening', 'listening', 'Glutinous rice is used in many traditional dishes, reflecting the importance of texture in regional cuisines.', NULL, 'Trong câu vừa nghe, từ “glutinous” mang nghĩa nào sau đây?', '["cuộc đụng độ nhỏ; xung đột ngắn","phù sa; do phù sa bồi đắp","dẻo quánh; dính","nằm sấp; phủ phục"]'::jsonb, 2, '“glutinous” (/ˈɡluːtənəs/): dẻo quánh; dính. Câu đầy đủ: Glutinous rice is used in many traditional dishes, reflecting the importance of texture in regional cuisines.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
