INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_1', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'profuse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thỏi kim loại được đúc khối để lưu trữ hoặc gia công","hình ảnh phản chiếu; sự phản chiếu","dồi dào; vô kể; tuôn trào","làm phấn chấn; làm hưng phấn; làm vui sướng"]'::jsonb, 2, 'profuse (/prəˈfjuːs/) → dồi dào; vô kể; tuôn trào', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_2', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'The glutinous rice stuck firmly to my wooden spoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người ông thiu thiu ngủ trên chiếc ghế bành cạnh ô cửa sổ đầy nắng.","Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.","Cô ấy xen kẽ những bông hoa rực rỡ giữa đám thảo mộc trên ban công.","Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi."]'::jsonb, 3, 'The glutinous rice stuck firmly to my wooden spoon. → Hạt gạo nếp dính chặt vào chiếc thìa gỗ của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_3', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'needful', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự gợi ý; lời ám chỉ; dấu hiệu","cần thiết; thiết yếu","tấm đá lát; phiến đá lát đường","chế giễu; mỉa mai"]'::jsonb, 1, 'needful (/ˈniːdfəl/) → cần thiết; thiết yếu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_4', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'We used a mincer to prepare meat for dumplings.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi dùng máy xay thịt để chuẩn bị nguyên liệu làm sủi cảo.","Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.","Mùi thơm của bánh mì mới nướng lan tỏa khắp căn bếp.","Bọn trẻ rải những cánh hoa dọc theo lối đi trong vườn."]'::jsonb, 0, 'We used a mincer to prepare meat for dumplings. → Chúng tôi dùng máy xay thịt để chuẩn bị nguyên liệu làm sủi cảo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_5', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'pervade', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lan tỏa; bao trùm; thấm đượm khắp nơi","gật gà gật gù; thiu thiu ngủ","thực tế; thực trạng","đeo kính"]'::jsonb, 0, 'pervade (/pɚˈveɪd/) → lan tỏa; bao trùm; thấm đượm khắp nơi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_6', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'Raucous laughter from the kitchen woke the sleeping cat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.","Toàn bộ dụng cụ cắm trại của chúng tôi đã chiếm kín mọi góc của nhà xe.","Mùi thơm của bánh mì mới nướng lan tỏa khắp căn bếp.","Cô ấy siết chặt tay tôi khi chúng tôi băng qua cầu."]'::jsonb, 0, 'Raucous laughter from the kitchen woke the sleeping cat. → Tiếng cười chói tai từ nhà bếp đã làm con mèo đang ngủ thức giấc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_7', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'strew', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự vận chuyển; sự chuyên chở","kiên định, kiên cường, không bỏ cuộc dù gặp khó khăn","minh oan; chứng minh là đúng; bảo vệ chính đáng","rải; rắc; vứt bừa bãi"]'::jsonb, 3, 'strew (/struː/) → rải; rắc; vứt bừa bãi', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_8', 'en-c2-14', NULL, 'comprehensive_test', 'listening', 'The bakery sells delectable pastries filled with fresh fruit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Họ đã bọc lại chiếc ghế cũ bằng vải nhung màu xanh mềm mại.","Tiệm bánh bán những chiếc bánh nướng thơm ngon nhân trái cây tươi.","Chú tôi là một người sưu tầm bản đồ cũ lâu năm.","Chúng tôi nằm ngả ngớn trên sofa sau chuyến đi bộ dài."]'::jsonb, 1, 'The bakery sells delectable pastries filled with fresh fruit. → Tiệm bánh bán những chiếc bánh nướng thơm ngon nhân trái cây tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_9', 'en-c2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to spread throughout a place or affect every part”?', '["loll","pervade","shamble","mincer"]'::jsonb, 1, 'pervade (/pɚˈveɪd/) → lan tỏa; bao trùm; thấm đượm khắp nơi', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
