INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_18', 'en-c2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Profuse sweating during outdoor exercise can increase fluid loss, making regular water intake particularly important.', 'Dựa vào câu trên, từ “profuse” có nghĩa phù hợp nhất là gì?', '["của cái đó; thuộc về cái vừa nhắc đến","người biên soạn hoặc biên tập từ điển","theo; chiểu theo; dựa theo","dồi dào; vô kể; tuôn trào"]'::jsonb, 3, 'profuse: dồi dào; vô kể; tuôn trào. Dịch cả câu: Đổ mồ hôi nhiều khi tập thể dục ngoài trời có thể làm mất nước, vì vậy việc bổ sung nước thường xuyên trở nên đặc biệt quan trọng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_19', 'en-c2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Glutinous rice is used in many traditional dishes, reflecting the importance of texture in regional cuisines.', 'Dựa vào câu trên, từ “glutinous” có nghĩa phù hợp nhất là gì?', '["dẻo quánh; dính","phương Tây; thế giới phương Tây","vui vẻ; hoạt bát","vũng lầy; tình trạng khó khăn phức tạp; hoàn cảnh tiến thối lưỡng nan"]'::jsonb, 0, 'glutinous: dẻo quánh; dính. Dịch cả câu: Gạo nếp được dùng trong nhiều món ăn truyền thống, thể hiện tầm quan trọng của kết cấu món ăn trong ẩm thực vùng miền.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_20', 'en-c2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable access to clean water is needful for maintaining public health in isolated rural communities.', 'Dựa vào câu trên, từ “needful” có nghĩa phù hợp nhất là gì?', '["cần thiết; thiết yếu","đọc hoặc xem xét kỹ lưỡng","cưng chiều; âu yếm; chăm sóc quá kỹ","cái ách (gỗ để trói buộc hai con vật kéo cày)"]'::jsonb, 0, 'needful: cần thiết; thiết yếu. Dịch cả câu: Việc tiếp cận nguồn nước sạch đáng tin cậy là điều thiết yếu để duy trì sức khỏe cộng đồng ở các vùng nông thôn cô lập.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_21', 'en-c2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Small food businesses can improve efficiency by using an electric mincer rather than chopping meat by hand.', 'Dựa vào câu trên, từ “mincer” có nghĩa phù hợp nhất là gì?', '["áo mưa","làm phồng lên; làm căng ra; trương lên","uy bác; có học thức sâu rộng; mang tính học thuật","máy xay thịt; máy băm thịt"]'::jsonb, 3, 'mincer: máy xay thịt; máy băm thịt. Dịch cả câu: Các doanh nghiệp thực phẩm nhỏ có thể nâng cao hiệu quả bằng cách sử dụng máy xay thịt điện thay vì băm thịt bằng tay.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_22', 'en-c2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nấm mốc; bệnh mốc sương”', '["pliable","mildew","ingenuous","unaccommodating"]'::jsonb, 1, 'nấm mốc; bệnh mốc sương → mildew (/ˈmɪlduː/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_23', 'en-c2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tách biệt; cho ở ẩn; cô lập”', '["eucalyptus","pervade","seclude","abrogate"]'::jsonb, 2, 'tách biệt; cho ở ẩn; cô lập → seclude (/sɪˈkluːd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_14_24', 'en-c2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết”', '["rectification","inexorable","aforesaid","fastidious"]'::jsonb, 3, 'cực kỳ kỹ tính; khắt khe; đòi hỏi sự hoàn hảo đến từng chi tiết → fastidious (/fæˈstɪdiəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c2-15', 'en', 'Bài 15: Từ vựng Tổng hợp - CEFR C2', 'CEFR C2', 'C2 · Tổng hợp', '18 từ vựng Tiếng Anh CEFR C2 chủ đề tổng hợp đa chủ đề kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 6015, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vanquish', 'en-c2-15', 'vanquish', '/ˈvæŋkwɪʃ/', 'C2', 'đánh bại hoàn toàn một đối thủ; khắc phục hoặc vượt qua một nỗi sợ, vấn đề hay khó khăn khác', 'v.', 'vanquisher (n.)', 'Đồng nghĩa: defeat, overcome, conquer', 'Mang sắc thái mạnh và có phần trang trọng; trong các cuộc thi đấu thông thường, dùng ''defeat'' sẽ tự nhiên hơn.', 'Our chess club finally vanquished its strongest rival yesterday.', NULL, 'Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.', '{"wordId":"vanquish","ukIpa":"/ˈvæŋkwɪʃ/","usIpa":"/ˈvæŋkwɪʃ/","cefr":"C2","topic":"sport","senses":[{"pos":"v.","en":"to defeat an opponent completely","vi":"đánh bại hoàn toàn một đối thủ"},{"pos":"v.","en":"to overcome a fear, problem, or other difficulty","vi":"khắc phục hoặc vượt qua một nỗi sợ, vấn đề hay khó khăn khác"}],"examples":[{"en":"Our chess club finally vanquished its strongest rival yesterday.","vi":"Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.","audioKind":"ex"},{"en":"Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.","vi":"Các chiến dịch y tế công cộng không thể chiến thắng được những thông tin sai lệch lan rộng nếu thiếu sự hợp tác bền bỉ giữa các nhà giáo dục, nhà nghiên cứu và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"vanquish an enemy","vi":"đánh bại hoàn toàn kẻ thù"},{"en":"vanquish an opponent","vi":"chiến thắng đối thủ"},{"en":"vanquish your fears","vi":"vượt qua nỗi sợ hãi của bạn"}],"wordFamily":["vanquisher (n.)"],"synonyms":["defeat","overcome","conquer"],"antonyms":[],"tipVi":"Mang sắc thái mạnh và có phần trang trọng; trong các cuộc thi đấu thông thường, dùng ''defeat'' sẽ tự nhiên hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bridle', 'en-c2-15', 'bridle', '/ˈbraɪdəl/', 'C2', 'dây cương ngựa; đầu cương; đeo dây cương cho ngựa; tỏ thái độ bất mãn; tỏ ý giận dỗi', 'n.', 'unbridled (adj.)', NULL, 'Chỉ dây cương ngựa, không phải cái chuồng; phát âm đồng âm với bridal (thuộc về cô dâu).', 'She checked the horse''s bridle before climbing into the saddle.', NULL, 'Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.', '{"wordId":"bridle","ukIpa":"/ˈbraɪdəl/","usIpa":"/ˈbraɪdəl/","cefr":"C2","topic":"sport","senses":[{"pos":"n.","en":"Straps fitted around a horse''s head to control it.","vi":"dây cương ngựa; đầu cương"},{"pos":"v.","en":"To put a bridle on a horse.","vi":"đeo dây cương cho ngựa"},{"pos":"v.","en":"To react angrily because something seems insulting or unfair.","vi":"tỏ thái độ bất mãn; tỏ ý giận dỗi"}],"examples":[{"en":"She checked the horse''s bridle before climbing into the saddle.","vi":"Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.","audioKind":"ex"},{"en":"Some employees bridle at strict monitoring policies because they feel their professional judgement is being questioned.","vi":"Một số nhân viên tỏ ra bất mãn với các chính sách giám sát nghiêm ngặt vì họ cảm thấy phán đoán chuyên môn của mình bị hoài nghi.","audioKind":"ex2"}],"collocations":[{"en":"a leather bridle","vi":"dây cương bằng da"},{"en":"put a bridle on","vi":"đeo dây cương cho"},{"en":"bridle at criticism","vi":"tỏ thái độ phật ý trước lời chỉ trích"}],"wordFamily":["unbridled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ dây cương ngựa, không phải cái chuồng; phát âm đồng âm với bridal (thuộc về cô dâu).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noxious', 'en-c2-15', 'noxious', '/ˈnɑːkʃəs/', 'C2', 'độc hại, gây hại cho con người hoặc các sinh vật khác', 'adj.', 'noxiousness (n.)', 'Đồng nghĩa: harmful, toxic, poisonous · Trái nghĩa: harmless', 'Thường dùng để mô tả khí hoặc chất; không chỉ giới hạn ở mùi khó chịu.', 'Noxious fumes from the spill forced everyone to leave.', NULL, 'Khói độc từ vụ tràn hóa chất buộc mọi người phải rời đi ngay lập tức.', '{"wordId":"noxious","ukIpa":"/ˈnɒkʃəs/","usIpa":"/ˈnɑːkʃəs/","cefr":"C2","topic":"environment","senses":[{"pos":"adj.","en":"harmful or poisonous to people or other living things","vi":"độc hại, gây hại cho con người hoặc các sinh vật khác"}],"examples":[{"en":"Noxious fumes from the spill forced everyone to leave.","vi":"Khói độc từ vụ tràn hóa chất buộc mọi người phải rời đi ngay lập tức.","audioKind":"ex"},{"en":"Stricter controls on industrial emissions are needed to protect nearby communities from exposure to noxious gases.","vi":"Cần phải kiểm soát chặt chẽ hơn lượng khí thải công nghiệp để bảo vệ các cộng đồng lân cận khỏi việc phơi nhiễm với khí độc.","audioKind":"ex2"}],"collocations":[{"en":"noxious fumes","vi":"khói độc"},{"en":"noxious gases","vi":"khí độc"},{"en":"noxious substances","vi":"chất độc hại"}],"wordFamily":["noxiousness (n.)"],"synonyms":["harmful","toxic","poisonous"],"antonyms":["harmless"],"tipVi":"Thường dùng để mô tả khí hoặc chất; không chỉ giới hạn ở mùi khó chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sluice', 'en-c2-15', 'sluice', '/sluːs/', 'C2', 'hệ thống dẫn nước có cửa điều tiết dòng chảy; dùng dòng nước mạnh để xối rửa cái gì đó; chảy xiết và tuôn trào với lưu lượng lớn', 'n.', NULL, NULL, 'Động từ có thể chỉ hành động xối rửa; sluice gate chỉ cửa điều tiết dòng nước.', 'We sluiced the mud off our boots outside.', NULL, 'Chúng tôi xối nước rửa sạch bùn bám trên đôi bốt ở ngoài trời.', '{"wordId":"sluice","ukIpa":"/sluːs/","usIpa":"/sluːs/","cefr":"C2","topic":"environment","senses":[{"pos":"n.","en":"A water channel with a gate that controls flow.","vi":"hệ thống dẫn nước có cửa điều tiết dòng chảy"},{"pos":"v.","en":"To wash something with a strong flow of water.","vi":"dùng dòng nước mạnh để xối rửa cái gì đó"},{"pos":"v.","en":"To flow quickly and in large amounts.","vi":"chảy xiết và tuôn trào với lưu lượng lớn"}],"examples":[{"en":"We sluiced the mud off our boots outside.","vi":"Chúng tôi xối nước rửa sạch bùn bám trên đôi bốt ở ngoài trời.","audioKind":"ex"},{"en":"Engineers opened the sluice to release excess water and reduce pressure on the reservoir walls.","vi":"Các kỹ sư đã mở cửa xả nước để thoát lượng nước dư thừa và giảm áp lực lên các bức tường của hồ chứa.","audioKind":"ex2"}],"collocations":[{"en":"sluice gate","vi":"cửa xả nước"},{"en":"open the sluice","vi":"mở cửa xả nước"},{"en":"sluice down the floor","vi":"xối nước rửa sàn nhà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ có thể chỉ hành động xối rửa; sluice gate chỉ cửa điều tiết dòng nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obliterate', 'en-c2-15', 'obliterate', '/əˈblɪtəreɪt/', 'C2', 'xóa sạch; phá hủy hoàn toàn; làm biến mất không dấu vết', 'v.', 'obliteration (n.)', 'Đồng nghĩa: eradicate, erase, destroy · Trái nghĩa: preserve', 'Là động từ, nhấn mạnh mức độ xóa bỏ hoàn toàn, mang sắc thái mạnh mẽ hơn từ remove thông thường.', 'Heavy snowfall had obliterated every footprint on the garden path.', NULL, 'Trận tuyết lớn đã xóa sạch mọi dấu chân trên lối đi trong vườn.', '{"wordId":"obliterate","ukIpa":"/əˈblɪtəreɪt/","usIpa":"/əˈblɪtəreɪt/","cefr":"C2","topic":"environment","senses":[{"pos":"v.","en":"Destroy or remove something completely, leaving little or no trace.","vi":"xóa sạch; phá hủy hoàn toàn; làm biến mất không dấu vết"}],"examples":[{"en":"Heavy snowfall had obliterated every footprint on the garden path.","vi":"Trận tuyết lớn đã xóa sạch mọi dấu chân trên lối đi trong vườn.","audioKind":"ex"},{"en":"Rapid urban development can obliterate historic neighbourhoods unless effective conservation measures are introduced early in the planning process.","vi":"Quá trình phát triển đô thị nhanh chóng có thể xóa sổ các khu phố cổ kính trừ khi các biện pháp bảo tồn hiệu quả được đưa ra từ giai đoạn đầu của quá trình quy hoạch.","audioKind":"ex2"}],"collocations":[{"en":"obliterate all traces","vi":"xóa sạch mọi dấu vết"},{"en":"completely obliterate","vi":"phá hủy hoàn toàn"},{"en":"obliterate evidence","vi":"tiêu hủy chứng cứ"}],"wordFamily":["obliteration (n.)"],"synonyms":["eradicate","erase","destroy"],"antonyms":["preserve"],"tipVi":"Là động từ, nhấn mạnh mức độ xóa bỏ hoàn toàn, mang sắc thái mạnh mẽ hơn từ remove thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_telefax', 'en-c2-15', 'telefax', '/ˈteləfæks/', 'C2', 'hệ thống hoặc máy truyền bản tài liệu qua đường dây điện thoại; máy fax; gửi tài liệu bằng máy fax', 'n.', 'fax (n.), fax (v.)', 'Đồng nghĩa: fax, facsimile', 'Đây là cách gọi cũ; trong tiếng Anh hiện đại, người ta thường dùng trực tiếp từ fax.', 'The office still has a telefax beside the printer.', NULL, 'Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in.', '{"wordId":"telefax","ukIpa":"/ˈtelɪfæks/","usIpa":"/ˈteləfæks/","cefr":"C2","topic":"technology","senses":[{"pos":"n.","en":"A system or machine sending document copies over telephone lines.","vi":"hệ thống hoặc máy truyền bản tài liệu qua đường dây điện thoại; máy fax"},{"pos":"v.","en":"To send a document using a fax machine.","vi":"gửi tài liệu bằng máy fax"}],"examples":[{"en":"The office still has a telefax beside the printer.","vi":"Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in.","audioKind":"ex"},{"en":"Before email became widespread, companies relied on telefax to exchange documents quickly across national borders.","vi":"Trước khi thư điện tử trở nên phổ biến, các công ty phải dựa vào máy fax để trao đổi tài liệu nhanh chóng qua biên giới các quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"send by telefax","vi":"gửi qua fax"},{"en":"telefax machine","vi":"máy fax"},{"en":"telefax number","vi":"số fax"}],"wordFamily":["fax (n.)","fax (v.)"],"synonyms":["fax","facsimile"],"antonyms":[],"tipVi":"Đây là cách gọi cũ; trong tiếng Anh hiện đại, người ta thường dùng trực tiếp từ fax.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_propellent', 'en-c2-15', 'propellent', '/prəˈpelənt/', 'C2', 'chất đẩy; chất phóng; có tác dụng đẩy; tạo lực đẩy', 'n.', 'propel (v.), propulsion (n.), propellant (n.)', 'Đồng nghĩa: propellant', 'Đây là cách viết ít phổ biến hơn của propellant; văn viết nên ưu tiên dùng từ propellant.', 'This spray can uses compressed air as its propellent.', NULL, 'Bình xịt này sử dụng khí nén làm chất đẩy.', '{"wordId":"propellent","ukIpa":"/prəˈpelənt/","usIpa":"/prəˈpelənt/","cefr":"C2","topic":"technology","senses":[{"pos":"n.","en":"A substance that drives something forward or forces liquid out","vi":"chất đẩy; chất phóng"},{"pos":"adj.","en":"Providing the force that moves something forward","vi":"có tác dụng đẩy; tạo lực đẩy"}],"examples":[{"en":"This spray can uses compressed air as its propellent.","vi":"Bình xịt này sử dụng khí nén làm chất đẩy.","audioKind":"ex"},{"en":"Developing cleaner rocket propellents could reduce the environmental impact of the growing commercial space industry.","vi":"Việc phát triển các loại chất đẩy tên lửa sạch hơn có thể làm giảm tác động môi trường của ngành công nghiệp không gian thương mại đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"rocket propellent","vi":"chất đẩy tên lửa"},{"en":"liquid propellent","vi":"chất đẩy dạng lỏng"},{"en":"propellent gas","vi":"khí đẩy"}],"wordFamily":["propel (v.)","propulsion (n.)","propellant (n.)"],"synonyms":["propellant"],"antonyms":[],"tipVi":"Đây là cách viết ít phổ biến hơn của propellant; văn viết nên ưu tiên dùng từ propellant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photostatic', 'en-c2-15', 'photostatic', '/ˌfoʊtoʊˈstætɪk/', 'C2', 'được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh', 'adj.', 'photostat (n.)', NULL, 'Thuật ngữ kỹ thuật cũ, chỉ việc sao chụp bằng phương pháp quang học/nhiếp ảnh, không phải là sao chụp tĩnh điện hiện đại.', 'The archive kept a photostatic copy of her certificate.', NULL, 'Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.', '{"wordId":"photostatic","ukIpa":"/ˌfəʊtəʊˈstætɪk/","usIpa":"/ˌfoʊtoʊˈstætɪk/","cefr":"C2","topic":"technology","senses":[{"pos":"adj.","en":"Relating to copies of documents made by a photographic process.","vi":"được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh"}],"examples":[{"en":"The archive kept a photostatic copy of her certificate.","vi":"Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.","audioKind":"ex"},{"en":"Before digital scanning became widespread, photostatic reproduction allowed libraries to share rare documents without transporting the originals.","vi":"Trước khi kỹ thuật quét kỹ thuật số trở nên phổ biến, phương pháp sao chụp ảnh cho phép các thư viện chia sẻ các tài liệu quý hiếm mà không cần vận chuyển bản gốc.","audioKind":"ex2"}],"collocations":[{"en":"a photostatic copy","vi":"bản sao chụp ảnh"},{"en":"photostatic reproduction","vi":"quá trình sao chụp ảnh"}],"wordFamily":["photostat (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ kỹ thuật cũ, chỉ việc sao chụp bằng phương pháp quang học/nhiếp ảnh, không phải là sao chụp tĩnh điện hiện đại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pneumatic', 'en-c2-15', 'pneumatic', '/nuːˈmætɪk/', 'C2', 'chạy bằng khí nén; dùng khí nén', 'adj.', 'pneumatically (adv.), pneumatics (n.)', NULL, 'Chữ "p" ở đầu từ không phát âm; thường chỉ các thiết bị hoạt động nhờ áp lực khí nén.', 'Workers used a pneumatic drill to break the pavement.', NULL, 'Công nhân đã sử dụng máy khoan hơi để phá vỡ mặt đường.', '{"wordId":"pneumatic","ukIpa":"/njuːˈmætɪk/","usIpa":"/nuːˈmætɪk/","cefr":"C2","topic":"technology","senses":[{"pos":"adj.","en":"operated by compressed air or filled with air","vi":"chạy bằng khí nén; dùng khí nén"}],"examples":[{"en":"Workers used a pneumatic drill to break the pavement.","vi":"Công nhân đã sử dụng máy khoan hơi để phá vỡ mặt đường.","audioKind":"ex"},{"en":"Pneumatic systems are widely used in manufacturing because compressed air can power tools safely and efficiently.","vi":"Hệ thống khí nén được sử dụng rộng rãi trong ngành sản xuất vì không khí nén có thể vận hành các công cụ một cách an toàn và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"a pneumatic drill","vi":"máy khoan khí nén"},{"en":"pneumatic tyres","vi":"lốp xe bơm hơi"},{"en":"a pneumatic system","vi":"hệ thống khí nén"}],"wordFamily":["pneumatically (adv.)","pneumatics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ \"p\" ở đầu từ không phát âm; thường chỉ các thiết bị hoạt động nhờ áp lực khí nén.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reportage', 'en-c2-15', 'reportage', '/rɪˈpɔːrtɪdʒ/', 'C2', 'ngành báo chí tường thuật; phóng sự', 'n.', 'report (v.), report (n.), reporter (n.)', 'Đồng nghĩa: reporting, coverage', 'Thường không đếm được, mang tính trang trọng hơn reporting và nhấn mạnh thông tin ghi nhận thực tế tại hiện trường.', 'Her vivid reportage brought the remote village to life.', NULL, 'Những bài phóng sự sinh động của cô ấy đã làm cho ngôi làng hẻo lánh trở nên sống động.', '{"wordId":"reportage","ukIpa":"/rɪˈpɔːtɪdʒ/","usIpa":"/rɪˈpɔːrtɪdʒ/","cefr":"C2","topic":"media","senses":[{"pos":"n.","en":"News reporting, especially detailed accounts based on direct observation","vi":"ngành báo chí tường thuật; phóng sự"}],"examples":[{"en":"Her vivid reportage brought the remote village to life.","vi":"Những bài phóng sự sinh động của cô ấy đã làm cho ngôi làng hẻo lánh trở nên sống động.","audioKind":"ex"},{"en":"Independent reportage can reveal environmental damage that might otherwise escape public attention and government scrutiny.","vi":"Các phóng sự độc lập có thể vạch trần những tổn hại môi trường mà nếu không có chúng, công chúng và sự giám sát của chính phủ có thể đã bỏ qua.","audioKind":"ex2"}],"collocations":[{"en":"investigative reportage","vi":"phóng sự điều tra"},{"en":"literary reportage","vi":"thể Loại văn học phóng sự"},{"en":"first-hand reportage","vi":"bài tường thuật tận mắt chứng kiến"}],"wordFamily":["report (v.)","report (n.)","reporter (n.)"],"synonyms":["reporting","coverage"],"antonyms":[],"tipVi":"Thường không đếm được, mang tính trang trọng hơn reporting và nhấn mạnh thông tin ghi nhận thực tế tại hiện trường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subliminal', 'en-c2-15', 'subliminal', '/sʌbˈlɪmənəl/', 'C2', 'thuộc về tiềm thức; dưới ngưỡng ý thức', 'adj.', 'subliminally (adv.)', NULL, 'Chỉ các tác động nằm dưới ngưỡng nhận thức ý thức, không mang ý nghĩa là hành vi vô thức thông thường.', 'The film used subliminal images that viewers barely noticed.', NULL, 'Bộ phim đã sử dụng những hình ảnh mang tính tiềm thức mà người xem hầu như không nhận ra.', '{"wordId":"subliminal","ukIpa":"/sʌbˈlɪmɪnəl/","usIpa":"/sʌbˈlɪmənəl/","cefr":"C2","topic":"media","senses":[{"pos":"adj.","en":"affecting your mind without you consciously noticing it","vi":"thuộc về tiềm thức; dưới ngưỡng ý thức"}],"examples":[{"en":"The film used subliminal images that viewers barely noticed.","vi":"Bộ phim đã sử dụng những hình ảnh mang tính tiềm thức mà người xem hầu như không nhận ra.","audioKind":"ex"},{"en":"Researchers continue to investigate whether subliminal cues can influence consumer choices under ordinary shopping conditions.","vi":"Các nhà nghiên cứu tiếp tục tìm hiểu xem liệu các tín hiệu tiềm thức có thể ảnh hưởng đến lựa chọn của người tiêu dùng trong điều kiện mua sắm thông thường hay không.","audioKind":"ex2"}],"collocations":[{"en":"subliminal message","vi":"thông điệp tiềm thức"},{"en":"subliminal advertising","vi":"quảng cáo tiềm thức"},{"en":"subliminal perception","vi":"nhận thức tiềm thức"}],"wordFamily":["subliminally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ các tác động nằm dưới ngưỡng nhận thức ý thức, không mang ý nghĩa là hành vi vô thức thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_throng', 'en-c2-15', 'throng', '/θrɔːŋ/', 'C2', 'đông đảo người; đám đông; tụ tập đông đúc; đổ xô', 'n.', NULL, 'Đồng nghĩa: crowd', 'Mang tính văn phong trang trọng; cụm từ a throng of đi với danh từ số nhiều.', 'We pushed through the throng to reach the exit.', NULL, 'Chúng tôi chen chúc qua đám đông để ra đến cửa thoát hiểm.', '{"wordId":"throng","ukIpa":"/θrɒŋ/","usIpa":"/θrɔːŋ/","cefr":"C2","topic":"city","senses":[{"pos":"n.","en":"a large crowd of people gathered closely together","vi":"đông đảo người; đám đông"},{"pos":"v.","en":"to gather somewhere in large numbers","vi":"tụ tập đông đúc; đổ xô"}],"examples":[{"en":"We pushed through the throng to reach the exit.","vi":"Chúng tôi chen chúc qua đám đông để ra đến cửa thoát hiểm.","audioKind":"ex"},{"en":"Throngs of visitors can place considerable pressure on historic sites during the peak tourist season.","vi":"Đông đảo du khách có thể gây áp lực đáng kể lên các di tích lịch sử trong mùa cao điểm du lịch.","audioKind":"ex2"}],"collocations":[{"en":"a throng of people","vi":"một đám đông người"},{"en":"throngs of tourists","vi":"đông đảo khách du lịch"},{"en":"throng the streets","vi":"đổ xô ra đường phố"}],"wordFamily":[],"synonyms":["crowd"],"antonyms":[],"tipVi":"Mang tính văn phong trang trọng; cụm từ a throng of đi với danh từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flagstone', 'en-c2-15', 'flagstone', '/ˈflæɡstoʊn/', 'C2', 'tấm đá lát; phiến đá lát đường', 'n.', NULL, NULL, 'Chỉ riêng các phiến đá phẳng dùng để lát đường hoặc sàn nhà, không dùng chỉ chung chung tất cả các loại đá.', 'Rainwater collected in the cracks between the old flagstones.', NULL, 'Nước mưa đọng lại trong các khe hở giữa những tấm đá lát cũ.', '{"wordId":"flagstone","ukIpa":"/ˈflæɡstəʊn/","usIpa":"/ˈflæɡstoʊn/","cefr":"C2","topic":"city","senses":[{"pos":"n.","en":"A flat stone slab used for paths or floors.","vi":"tấm đá lát; phiến đá lát đường"}],"examples":[{"en":"Rainwater collected in the cracks between the old flagstones.","vi":"Nước mưa đọng lại trong các khe hở giữa những tấm đá lát cũ.","audioKind":"ex"},{"en":"Using locally sourced flagstones for public paths can preserve regional character while reducing transport emissions.","vi":"Việc sử dụng các tấm đá lát có nguồn gốc địa phương cho các lối đi công cộng có thể giữ gìn bản sắc vùng miền đồng thời giảm lượng khí thải do vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"a flagstone floor","vi":"sân lát đá"},{"en":"a flagstone path","vi":"lối đi lát đá"},{"en":"lay flagstones","vi":"lát đá phiến"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ riêng các phiến đá phẳng dùng để lát đường hoặc sàn nhà, không dùng chỉ chung chung tất cả các loại đá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_odyssey', 'en-c2-15', 'odyssey', '/ˈɑːdəsi/', 'C2', 'cuộc hành trình dài và nhiều gian nan trắc trở', 'n.', NULL, 'Đồng nghĩa: journey, quest', 'Mang màu sắc văn học mạnh, cũng có thể dùng ẩn dụ cho hành trình khám phá cuộc đời; số nhiều là odysseys.', 'Their cycling odyssey took them across deserts and mountains.', NULL, 'Hành trình đạp xe dài đằng đẵng đã đưa họ băng qua những sa mạc và dãy núi.', '{"wordId":"odyssey","ukIpa":"/ˈɒdəsi/","usIpa":"/ˈɑːdəsi/","cefr":"C2","topic":"travel","senses":[{"pos":"n.","en":"a long journey involving many difficult or exciting experiences","vi":"cuộc hành trình dài và nhiều gian nan trắc trở"}],"examples":[{"en":"Their cycling odyssey took them across deserts and mountains.","vi":"Hành trình đạp xe dài đằng đẵng đã đưa họ băng qua những sa mạc và dãy núi.","audioKind":"ex"},{"en":"The documentary follows one family''s odyssey across several continents, exploring how migration reshapes identity and belonging.","vi":"Bộ phim tài liệu theo chân hành trình xuyên qua nhiều châu lục của một gia đình, khám phá cách thức di cư tái định hình bản sắc và cảm giác thuộc về.","audioKind":"ex2"}],"collocations":[{"en":"epic odyssey","vi":"hành trình sử thi hoành tráng"},{"en":"personal odyssey","vi":"hành trình khám phá bản thân"},{"en":"spiritual odyssey","vi":"hành trình tìm kiếm tâm linh"}],"wordFamily":[],"synonyms":["journey","quest"],"antonyms":[],"tipVi":"Mang màu sắc văn học mạnh, cũng có thể dùng ẩn dụ cho hành trình khám phá cuộc đời; số nhiều là odysseys.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_odometer', 'en-c2-15', 'odometer', '/oʊˈdɑːmɪtər/', 'C2', 'đồng hồ đo quãng đường; công-tơ-mét (đo khoảng cách xe chạy)', 'n.', NULL, 'Đồng nghĩa: mileometer', 'Ghi lại tổng quãng đường đã đi; trong khi speedometer hiển thị tốc độ tức thời.', 'The odometer showed how far we had driven.', NULL, 'Đồng hồ đo quãng đường cho biết chúng tôi đã lái xe được bao xa.', '{"wordId":"odometer","ukIpa":"/əʊˈdɒmɪtə/","usIpa":"/oʊˈdɑːmɪtər/","cefr":"C2","topic":"travel","senses":[{"pos":"n.","en":"a device measuring the total distance a vehicle has travelled","vi":"đồng hồ đo quãng đường; công-tơ-mét (đo khoảng cách xe chạy)"}],"examples":[{"en":"The odometer showed how far we had driven.","vi":"Đồng hồ đo quãng đường cho biết chúng tôi đã lái xe được bao xa.","audioKind":"ex"},{"en":"When purchasing a used vehicle, consumers should check its odometer reading alongside its maintenance records.","vi":"Khi mua xe đã qua sử dụng, người tiêu dùng nên kiểm tra số chỉ trên đồng hồ đo quãng đường cùng với hồ sơ bảo dưỡng của xe.","audioKind":"ex2"}],"collocations":[{"en":"odometer reading","vi":"số đọc trên công-tơ-mét"},{"en":"check the odometer","vi":"kiểm tra đồng hồ đo quãng đường"}],"wordFamily":[],"synonyms":["mileometer"],"antonyms":[],"tipVi":"Ghi lại tổng quãng đường đã đi; trong khi speedometer hiển thị tốc độ tức thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conveyance', 'en-c2-15', 'conveyance', '/kənˈveɪəns/', 'C2', 'sự vận chuyển; sự chuyên chở; phương tiện vận chuyển; phương tiện giao thông; sự chuyển nhượng tài sản (pháp lý)', 'n.', 'convey (v.), conveyancing (n.), conveyancer (n.)', 'Đồng nghĩa: transport, transportation', 'Là từ trang trọng; vận chuyển thông thường dùng transport, trong luật pháp có thể chỉ việc sang tên tài sản.', 'The hotel arranged conveyance of our luggage by boat.', NULL, 'Khách sạn đã bố trí tàu thuyền để vận chuyển hành lý cho chúng tôi.', '{"wordId":"conveyance","ukIpa":"/kənˈveɪəns/","usIpa":"/kənˈveɪəns/","cefr":"C2","topic":"travel","senses":[{"pos":"n.","en":"the act of transporting people or goods","vi":"sự vận chuyển; sự chuyên chở"},{"pos":"n.","en":"a vehicle used for carrying people or goods","vi":"phương tiện vận chuyển; phương tiện giao thông"},{"pos":"n.","en":"the legal transfer of property from one owner to another","vi":"sự chuyển nhượng tài sản (pháp lý)"}],"examples":[{"en":"The hotel arranged conveyance of our luggage by boat.","vi":"Khách sạn đã bố trí tàu thuyền để vận chuyển hành lý cho chúng tôi.","audioKind":"ex"},{"en":"Efficient conveyance of agricultural goods depends on reliable roads, suitable vehicles, and accessible regional markets.","vi":"Việc vận chuyển hàng hóa nông nghiệp hiệu quả phụ thuộc vào hệ thống đường xá đáng tin cậy, phương tiện phù hợp và các thị trường khu vực thuận tiện.","audioKind":"ex2"}],"collocations":[{"en":"conveyance of goods","vi":"vận chuyển hàng hóa"},{"en":"means of conveyance","vi":"phương tiện giao thông"},{"en":"conveyance of property","vi":"chuyển nhượng quyền sở hữu tài sản"}],"wordFamily":["convey (v.)","conveyancing (n.)","conveyancer (n.)"],"synonyms":["transport","transportation"],"antonyms":[],"tipVi":"Là từ trang trọng; vận chuyển thông thường dùng transport, trong luật pháp có thể chỉ việc sang tên tài sản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hinterland', 'en-c2-15', 'hinterland', '/ˈhɪntərlænd/', 'C2', 'vùng nội địa; vùng sâu vùng xa', 'n.', NULL, NULL, 'Thường chỉ cảng biển, vùng ven biển hoặc khu vực nội địa nằm phía sau các thành phố lớn.', 'We drove into the hinterland and found quiet villages.', NULL, 'Chúng tôi lái xe vào sâu trong vùng nội địa và tìm thấy những ngôi làng yên bình.', '{"wordId":"hinterland","ukIpa":"/ˈhɪntəlænd/","usIpa":"/ˈhɪntərlænd/","cefr":"C2","topic":"travel","senses":[{"pos":"n.","en":"the inland area beyond a coast or major city","vi":"vùng nội địa; vùng sâu vùng xa"}],"examples":[{"en":"We drove into the hinterland and found quiet villages.","vi":"Chúng tôi lái xe vào sâu trong vùng nội địa và tìm thấy những ngôi làng yên bình.","audioKind":"ex"},{"en":"Improved transport links between ports and their hinterlands can support regional trade and agricultural development.","vi":"Cải thiện kết nối giao thông giữa các cảng biển và vùng nội địa có thể thúc đẩy thương mại khu vực và phát triển nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"rural hinterland","vi":"vùng nông thôn sâu"},{"en":"coastal hinterland","vi":"vùng nội địa ven biển"},{"en":"vast hinterland","vi":"vùng nội địa rộng lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ cảng biển, vùng ven biển hoặc khu vực nội địa nằm phía sau các thành phố lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mariner', 'en-c2-15', 'mariner', '/ˈmærɪnər/', 'C2', 'thủy thủ; hải thủ', 'n.', 'marine (adj.)', 'Đồng nghĩa: sailor, seafarer', 'Mang tính trang trọng hơn từ sailor, thường xuất hiện trong ngữ cảnh hàng hải hoặc lịch sử.', 'The experienced mariner guided our boat safely into harbour.', NULL, 'Người thủy thủ dày dặn kinh nghiệm đã lái con thuyền của chúng tôi vào bến an toàn.', '{"wordId":"mariner","ukIpa":"/ˈmærɪnə/","usIpa":"/ˈmærɪnər/","cefr":"C2","topic":"travel","senses":[{"pos":"n.","en":"Someone who sails or works on a ship at sea.","vi":"thủy thủ; hải thủ"}],"examples":[{"en":"The experienced mariner guided our boat safely into harbour.","vi":"Người thủy thủ dày dặn kinh nghiệm đã lái con thuyền của chúng tôi vào bến an toàn.","audioKind":"ex"},{"en":"Before modern navigation systems existed, mariners relied on stars and coastal landmarks to determine their position.","vi":"Trước khi hệ thống định vị hiện đại ra đời, các thủy thủ phải dựa vào các vì sao và mốc địa lý ven bờ để xác định vị trí của họ.","audioKind":"ex2"}],"collocations":[{"en":"an experienced mariner","vi":"một thủy thủ giàu kinh nghiệm"},{"en":"a merchant mariner","vi":"một thủy thủ tàu buôn"},{"en":"a master mariner","vi":"một thuyền trưởng viễn dương"}],"wordFamily":["marine (adj.)"],"synonyms":["sailor","seafarer"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn từ sailor, thường xuất hiện trong ngữ cảnh hàng hải hoặc lịch sử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_15_1', 'en-c2-15', 'Cách dùng “photostatic” (adj.) — được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh', 'a photostatic copy  ·  photostatic reproduction', 'Thuật ngữ kỹ thuật cũ, chỉ việc sao chụp bằng phương pháp quang học/nhiếp ảnh, không phải là sao chụp tĩnh điện hiện đại.', 'Họ từ (Word Family): photostat (n.)', '[{"hanzi":"The archive kept a photostatic copy of her certificate.","pinyin":"","meaning":"Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy."},{"hanzi":"Before digital scanning became widespread, photostatic reproduction allowed libraries to share rare documents without transporting the originals.","pinyin":"","meaning":"Trước khi kỹ thuật quét kỹ thuật số trở nên phổ biến, phương pháp sao chụp ảnh cho phép các thư viện chia sẻ các tài liệu quý hiếm mà không cần vận chuyển bản gốc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_15_2', 'en-c2-15', 'Cách dùng “reportage” (n.) — ngành báo chí tường thuật; phóng sự', 'investigative reportage  ·  literary reportage  ·  first-hand reportage', 'Thường không đếm được, mang tính trang trọng hơn reporting và nhấn mạnh thông tin ghi nhận thực tế tại hiện trường.', 'Họ từ (Word Family): report (v.), report (n.), reporter (n.) | Đồng nghĩa: reporting, coverage', '[{"hanzi":"Her vivid reportage brought the remote village to life.","pinyin":"","meaning":"Những bài phóng sự sinh động của cô ấy đã làm cho ngôi làng hẻo lánh trở nên sống động."},{"hanzi":"Independent reportage can reveal environmental damage that might otherwise escape public attention and government scrutiny.","pinyin":"","meaning":"Các phóng sự độc lập có thể vạch trần những tổn hại môi trường mà nếu không có chúng, công chúng và sự giám sát của chính phủ có thể đã bỏ qua."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_15_3', 'en-c2-15', 'Cách dùng “vanquish” (v.) — đánh bại hoàn toàn một đối thủ', 'vanquish an enemy  ·  vanquish an opponent  ·  vanquish your fears', 'Mang sắc thái mạnh và có phần trang trọng; trong các cuộc thi đấu thông thường, dùng ''defeat'' sẽ tự nhiên hơn.', 'Họ từ (Word Family): vanquisher (n.) | Đồng nghĩa: defeat, overcome, conquer', '[{"hanzi":"Our chess club finally vanquished its strongest rival yesterday.","pinyin":"","meaning":"Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua."},{"hanzi":"Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.","pinyin":"","meaning":"Các chiến dịch y tế công cộng không thể chiến thắng được những thông tin sai lệch lan rộng nếu thiếu sự hợp tác bền bỉ giữa các nhà giáo dục, nhà nghiên cứu và cộng đồng địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c2_15_4', 'en-c2-15', 'Cách dùng “conveyance” (n.) — sự vận chuyển; sự chuyên chở', 'conveyance of goods  ·  means of conveyance  ·  conveyance of property', 'Là từ trang trọng; vận chuyển thông thường dùng transport, trong luật pháp có thể chỉ việc sang tên tài sản.', 'Họ từ (Word Family): convey (v.), conveyancing (n.), conveyancer (n.) | Đồng nghĩa: transport, transportation', '[{"hanzi":"The hotel arranged conveyance of our luggage by boat.","pinyin":"","meaning":"Khách sạn đã bố trí tàu thuyền để vận chuyển hành lý cho chúng tôi."},{"hanzi":"Efficient conveyance of agricultural goods depends on reliable roads, suitable vehicles, and accessible regional markets.","pinyin":"","meaning":"Việc vận chuyển hàng hóa nông nghiệp hiệu quả phụ thuộc vào hệ thống đường xá đáng tin cậy, phương tiện phù hợp và các thị trường khu vực thuận tiện."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_15_1', 'en-c2-15', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
