INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_2', 'ten_c2_15_1', 'bridle', 'She checked the horse''s bridle before climbing into the saddle.', 'She checked the horse''s bridle before climbing into the saddle.', '/ˈbraɪdəl/', 'Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_3', 'ten_c2_15_1', 'noxious', 'Noxious fumes from the spill forced everyone to leave.', 'Noxious fumes from the spill forced everyone to leave.', '/ˈnɑːkʃəs/', 'Khói độc từ vụ tràn hóa chất buộc mọi người phải rời đi ngay lập tức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_4', 'ten_c2_15_1', 'sluice', 'We sluiced the mud off our boots outside.', 'We sluiced the mud off our boots outside.', '/sluːs/', 'Chúng tôi xối nước rửa sạch bùn bám trên đôi bốt ở ngoài trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_5', 'ten_c2_15_1', 'obliterate', 'Heavy snowfall had obliterated every footprint on the garden path.', 'Heavy snowfall had obliterated every footprint on the garden path.', '/əˈblɪtəreɪt/', 'Trận tuyết lớn đã xóa sạch mọi dấu chân trên lối đi trong vườn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_6', 'ten_c2_15_1', 'telefax', 'The office still has a telefax beside the printer.', 'The office still has a telefax beside the printer.', '/ˈteləfæks/', 'Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_7', 'ten_c2_15_1', 'propellent', 'This spray can uses compressed air as its propellent.', 'This spray can uses compressed air as its propellent.', '/prəˈpelənt/', 'Bình xịt này sử dụng khí nén làm chất đẩy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_1_8', 'ten_c2_15_1', 'photostatic', 'The archive kept a photostatic copy of her certificate.', 'The archive kept a photostatic copy of her certificate.', '/ˌfoʊtoʊˈstætɪk/', 'Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_15_1_1', 'en-c2-15', 'ten_c2_15_1', 'listening', 'listening', 'Our chess club finally vanquished its strongest rival yesterday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.","Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.","Hành trình đạp xe dài đằng đẵng đã đưa họ băng qua những sa mạc và dãy núi.","Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên."]'::jsonb, 0, 'Our chess club finally vanquished its strongest rival yesterday. → Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_15_1_2', 'en-c2-15', 'ten_c2_15_1', 'listening', 'listening', 'She checked the horse''s bridle before climbing into the saddle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi chen chúc qua đám đông để ra đến cửa thoát hiểm.","Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in.","Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.","Bộ phim đã sử dụng những hình ảnh mang tính tiềm thức mà người xem hầu như không nhận ra."]'::jsonb, 2, 'She checked the horse''s bridle before climbing into the saddle. → Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_15_1_3', 'en-c2-15', 'ten_c2_15_1', 'listening', 'listening', 'Noxious fumes from the spill forced everyone to leave.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trận tuyết lớn đã xóa sạch mọi dấu chân trên lối đi trong vườn.","Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.","Công nhân đã sử dụng máy khoan hơi để phá vỡ mặt đường.","Khói độc từ vụ tràn hóa chất buộc mọi người phải rời đi ngay lập tức."]'::jsonb, 3, 'Noxious fumes from the spill forced everyone to leave. → Khói độc từ vụ tràn hóa chất buộc mọi người phải rời đi ngay lập tức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c2_15_2', 'en-c2-15', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_2_1', 'ten_c2_15_2', 'vanquish', 'Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.', 'Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.', '/ˈvæŋkwɪʃ/', 'Các chiến dịch y tế công cộng không thể chiến thắng được những thông tin sai lệch lan rộng nếu thiếu sự hợp tác bền bỉ giữa các nhà giáo dục, nhà nghiên cứu và cộng đồng địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_2_2', 'ten_c2_15_2', 'bridle', 'Some employees bridle at strict monitoring policies because they feel their professional judgement is being questioned.', 'Some employees bridle at strict monitoring policies because they feel their professional judgement is being questioned.', '/ˈbraɪdəl/', 'Một số nhân viên tỏ ra bất mãn với các chính sách giám sát nghiêm ngặt vì họ cảm thấy phán đoán chuyên môn của mình bị hoài nghi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_2_3', 'ten_c2_15_2', 'noxious', 'Stricter controls on industrial emissions are needed to protect nearby communities from exposure to noxious gases.', 'Stricter controls on industrial emissions are needed to protect nearby communities from exposure to noxious gases.', '/ˈnɑːkʃəs/', 'Cần phải kiểm soát chặt chẽ hơn lượng khí thải công nghiệp để bảo vệ các cộng đồng lân cận khỏi việc phơi nhiễm với khí độc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_2_4', 'ten_c2_15_2', 'sluice', 'Engineers opened the sluice to release excess water and reduce pressure on the reservoir walls.', 'Engineers opened the sluice to release excess water and reduce pressure on the reservoir walls.', '/sluːs/', 'Các kỹ sư đã mở cửa xả nước để thoát lượng nước dư thừa và giảm áp lực lên các bức tường của hồ chứa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_2_5', 'ten_c2_15_2', 'obliterate', 'Rapid urban development can obliterate historic neighbourhoods unless effective conservation measures are introduced early in the planning process.', 'Rapid urban development can obliterate historic neighbourhoods unless effective conservation measures are introduced early in the planning process.', '/əˈblɪtəreɪt/', 'Quá trình phát triển đô thị nhanh chóng có thể xóa sổ các khu phố cổ kính trừ khi các biện pháp bảo tồn hiệu quả được đưa ra từ giai đoạn đầu của quá trình quy hoạch.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c2_15_2_6', 'ten_c2_15_2', 'telefax', 'Before email became widespread, companies relied on telefax to exchange documents quickly across national borders.', 'Before email became widespread, companies relied on telefax to exchange documents quickly across national borders.', '/ˈteləfæks/', 'Trước khi thư điện tử trở nên phổ biến, các công ty phải dựa vào máy fax để trao đổi tài liệu nhanh chóng qua biên giới các quốc gia.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_15_2_1', 'en-c2-15', 'ten_c2_15_2', 'listening', 'listening', 'Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.', NULL, 'Trong câu vừa nghe, từ “vanquish” mang nghĩa nào sau đây?', '["đưa ra quyết định chính thức về một tranh chấp","đánh bại hoàn toàn một đối thủ","khinh miệt; coi thường; tỏ thái độ khinh bỉ","ngành từ điển học; việc biên soạn từ điển"]'::jsonb, 1, '“vanquish” (/ˈvæŋkwɪʃ/): đánh bại hoàn toàn một đối thủ. Câu đầy đủ: Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c2_15_2_2', 'en-c2-15', 'ten_c2_15_2', 'listening', 'listening', 'Some employees bridle at strict monitoring policies because they feel their professional judgement is being questioned.', NULL, 'Trong câu vừa nghe, từ “bridle” mang nghĩa nào sau đây?', '["dây cương ngựa; đầu cương","thuộc trục; theo trục","không thích, không muốn hoặc miễn cưỡng làm điều gì đó","hình ảnh phản chiếu; sự phản chiếu"]'::jsonb, 0, '“bridle” (/ˈbraɪdəl/): dây cương ngựa; đầu cương. Câu đầy đủ: Some employees bridle at strict monitoring policies because they feel their professional judgement is being questioned.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_15_1', 'en-c2-15', 'Our chess club finally vanquished its strongest rival yesterday', 'Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.', 'vanquish /ˈvæŋkwɪʃ/', '["strongest","club","yesterday","vanquished","Our","chess","rival","its","finally"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_15_2', 'en-c2-15', 'She checked the horse''s bridle before climbing into the saddle', 'Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.', 'bridle /ˈbraɪdəl/', '["saddle","into","climbing","the","bridle","before","horse''s","She","checked","the"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_15_3', 'en-c2-15', 'Noxious fumes from the spill forced everyone to leave', 'Khói độc từ vụ tràn hóa chất buộc mọi người phải rời đi ngay lập tức.', 'noxious /ˈnɑːkʃəs/', '["to","from","leave","the","Noxious","everyone","forced","spill","fumes"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_15_4', 'en-c2-15', 'We sluiced the mud off our boots outside', 'Chúng tôi xối nước rửa sạch bùn bám trên đôi bốt ở ngoài trời.', 'sluice /sluːs/', '["mud","boots","sluiced","our","outside","the","off","We"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_15_5', 'en-c2-15', 'Heavy snowfall had obliterated every footprint on the garden path', 'Trận tuyết lớn đã xóa sạch mọi dấu chân trên lối đi trong vườn.', 'obliterate /əˈblɪtəreɪt/', '["obliterated","garden","on","snowfall","every","footprint","had","path","Heavy","the"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c2_15_6', 'en-c2-15', 'The office still has a telefax beside the printer', 'Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in.', 'telefax /ˈteləfæks/', '["still","office","has","The","telefax","printer","a","beside","the"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
