INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c2_15_2', 'en-c2-15', 'en_to_vi', 'The archive kept a photostatic copy of her certificate.', 'The archive kept a photostatic copy of her certificate.', '/ˌfoʊtoʊˈstætɪk/', NULL, 'Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.', NULL, '["khu","lưu","trữ","vẫn","giữ","một","bản","sao"]'::jsonb, 'Từ trọng tâm: photostatic (được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh)', 'The archive kept a photostatic copy of her certificate. → Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
