INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_1', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'vanquish', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đánh bại hoàn toàn một đối thủ","gây thiệt hại nặng nề; phá sản","khinh miệt; coi thường; tỏ thái độ khinh bỉ","cá bơn lớn; thịt cá bơn lớn"]'::jsonb, 0, 'vanquish (/ˈvæŋkwɪʃ/) → đánh bại hoàn toàn một đối thủ; khắc phục hoặc vượt qua một nỗi sợ, vấn đề hay khó khăn khác', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_2', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'She checked the horse''s bridle before climbing into the saddle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khách sạn đã bố trí tàu thuyền để vận chuyển hành lý cho chúng tôi.","Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.","Chúng tôi lái xe vào sâu trong vùng nội địa và tìm thấy những ngôi làng yên bình.","Những bài phóng sự sinh động của cô ấy đã làm cho ngôi làng hẻo lánh trở nên sống động."]'::jsonb, 1, 'She checked the horse''s bridle before climbing into the saddle. → Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_3', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'noxious', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["về dáng vẻ: vụng về; lóng ngóng; không uyển chuyển","chất/dung dịch nước ô-xy già (hydrogen peroxide); hợp chất chứa liên kết ô-xy - ô-xy","phát triển nhanh chóng; đâm chồi nảy lộc; tăng trưởng mạnh","độc hại, gây hại cho con người hoặc các sinh vật khác"]'::jsonb, 3, 'noxious (/ˈnɑːkʃəs/) → độc hại, gây hại cho con người hoặc các sinh vật khác', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_4', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'We sluiced the mud off our boots outside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công nhân đã sử dụng máy khoan hơi để phá vỡ mặt đường.","Câu lạc bộ cờ vua của chúng tôi cuối cùng đã đánh bại hoàn toàn đối thủ mạnh nhất vào ngày hôm qua.","Chúng tôi xối nước rửa sạch bùn bám trên đôi bốt ở ngoài trời.","Bình xịt này sử dụng khí nén làm chất đẩy."]'::jsonb, 2, 'We sluiced the mud off our boots outside. → Chúng tôi xối nước rửa sạch bùn bám trên đôi bốt ở ngoài trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_5', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'obliterate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ủy quyền; ủy nhiệm; cử","phát triển nhanh chóng và ngoạn mục; vụt sáng","kịch liệt phản đối; vô cùng đau xót","xóa sạch; phá hủy hoàn toàn; làm biến mất không dấu vết"]'::jsonb, 3, 'obliterate (/əˈblɪtəreɪt/) → xóa sạch; phá hủy hoàn toàn; làm biến mất không dấu vết', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_6', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'The office still has a telefax beside the printer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.","Bộ phim đã sử dụng những hình ảnh mang tính tiềm thức mà người xem hầu như không nhận ra.","Công nhân đã sử dụng máy khoan hơi để phá vỡ mặt đường.","Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in."]'::jsonb, 3, 'The office still has a telefax beside the printer. → Văn phòng vẫn còn một chiếc máy fax đặt cạnh máy in.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_7', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'propellent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hào phóng và bao dung, đặc biệt là đối với đối thủ hoặc người yếu thế hơn","tràn ngập; lúc nhúc (sinh vật, người)","chất đẩy; chất phóng","chế giễu; mỉa mai"]'::jsonb, 2, 'propellent (/prəˈpelənt/) → chất đẩy; chất phóng; có tác dụng đẩy; tạo lực đẩy', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_8', 'en-c2-15', NULL, 'comprehensive_test', 'listening', 'The archive kept a photostatic copy of her certificate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi chen chúc qua đám đông để ra đến cửa thoát hiểm.","Khách sạn đã bố trí tàu thuyền để vận chuyển hành lý cho chúng tôi.","Cô ấy kiểm tra dây cương của ngựa trước khi bước lên yên.","Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy."]'::jsonb, 3, 'The archive kept a photostatic copy of her certificate. → Khu lưu trữ vẫn giữ một bản sao chụp ảnh giấy chứng nhận của cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_9', 'en-c2-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Destroy or remove something completely, leaving little or no trace.”?', '["pneumatic","throng","obliterate","flagstone"]'::jsonb, 2, 'obliterate (/əˈblɪtəreɪt/) → xóa sạch; phá hủy hoàn toàn; làm biến mất không dấu vết', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_10', 'en-c2-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A system or machine sending document copies over telephone lines.”?', '["reportage","telefax","sluice","vanquish"]'::jsonb, 1, 'telefax (/ˈteləfæks/) → hệ thống hoặc máy truyền bản tài liệu qua đường dây điện thoại; máy fax', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_11', 'en-c2-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A substance that drives something forward or forces liquid out”?', '["propellent","pneumatic","reportage","vanquish"]'::jsonb, 0, 'propellent (/prəˈpelənt/) → chất đẩy; chất phóng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_12', 'en-c2-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Relating to copies of documents made by a photographic process.”?', '["propellent","reportage","photostatic","flagstone"]'::jsonb, 2, 'photostatic (/ˌfoʊtoʊˈstætɪk/) → được sao chụp bằng máy ảnh (tài liệu); thuộc bản sao chụp ảnh', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_13', 'en-c2-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “operated by compressed air or filled with air”?', '["odyssey","bridle","pneumatic","photostatic"]'::jsonb, 2, 'pneumatic (/nuːˈmætɪk/) → chạy bằng khí nén; dùng khí nén', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
