INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_18', 'en-c2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Public health campaigns cannot vanquish widespread misinformation without sustained cooperation between educators, researchers, and local communities.', 'Dựa vào câu trên, từ “vanquish” có nghĩa phù hợp nhất là gì?', '["trái nghĩa; có nghĩa đối lập","đánh bại hoàn toàn một đối thủ","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm","bãi bỏ; hủy bỏ (luật, thỏa thuận)"]'::jsonb, 1, 'vanquish: đánh bại hoàn toàn một đối thủ; khắc phục hoặc vượt qua một nỗi sợ, vấn đề hay khó khăn khác. Dịch cả câu: Các chiến dịch y tế công cộng không thể chiến thắng được những thông tin sai lệch lan rộng nếu thiếu sự hợp tác bền bỉ giữa các nhà giáo dục, nhà nghiên cứu và cộng đồng địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_19', 'en-c2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Some employees bridle at strict monitoring policies because they feel their professional judgement is being questioned.', 'Dựa vào câu trên, từ “bridle” có nghĩa phù hợp nhất là gì?', '["chân chất; ngây thơ; thật thà","bài luận khảo; chuyên khảo; tác phẩm nghiên cứu chuyên sâu","sức gợi cảm; nỗi niềm xót xa; tính bi cảm","dây cương ngựa; đầu cương"]'::jsonb, 3, 'bridle: dây cương ngựa; đầu cương; đeo dây cương cho ngựa; tỏ thái độ bất mãn; tỏ ý giận dỗi. Dịch cả câu: Một số nhân viên tỏ ra bất mãn với các chính sách giám sát nghiêm ngặt vì họ cảm thấy phán đoán chuyên môn của mình bị hoài nghi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_20', 'en-c2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Stricter controls on industrial emissions are needed to protect nearby communities from exposure to noxious gases.', 'Dựa vào câu trên, từ “noxious” có nghĩa phù hợp nhất là gì?', '["độc hại, gây hại cho con người hoặc các sinh vật khác","cuộc đụng độ nhỏ; xung đột ngắn","cành lớn; nhánh cây chính","sự giải thoát; sự cứu rỗi"]'::jsonb, 0, 'noxious: độc hại, gây hại cho con người hoặc các sinh vật khác. Dịch cả câu: Cần phải kiểm soát chặt chẽ hơn lượng khí thải công nghiệp để bảo vệ các cộng đồng lân cận khỏi việc phơi nhiễm với khí độc.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_21', 'en-c2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Engineers opened the sluice to release excess water and reduce pressure on the reservoir walls.', 'Dựa vào câu trên, từ “sluice” có nghĩa phù hợp nhất là gì?', '["xỉ lò; xỉ quặng","biển thủ, thụt quĩ, lén lấy tiền hoặc tài sản được giao phó để sử dụng cho riêng mình","hệ thống dẫn nước có cửa điều tiết dòng chảy","sáo rỗng; cũ rích; nhàm chán; lặp lại nhàm"]'::jsonb, 2, 'sluice: hệ thống dẫn nước có cửa điều tiết dòng chảy; dùng dòng nước mạnh để xối rửa cái gì đó; chảy xiết và tuôn trào với lưu lượng lớn. Dịch cả câu: Các kỹ sư đã mở cửa xả nước để thoát lượng nước dư thừa và giảm áp lực lên các bức tường của hồ chứa.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_22', 'en-c2-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự vận chuyển; sự chuyên chở”', '["oscillation","conveyance","bushel","clasp"]'::jsonb, 1, 'sự vận chuyển; sự chuyên chở → conveyance (/kənˈveɪəns/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_23', 'en-c2-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vùng nội địa; vùng sâu vùng xa”', '["virile","peroxide","oscillation","hinterland"]'::jsonb, 3, 'vùng nội địa; vùng sâu vùng xa → hinterland (/ˈhɪntərlænd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c2_15_24', 'en-c2-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thủy thủ; hải thủ”', '["inapt","peruse","mariner","disposition"]'::jsonb, 2, 'thủy thủ; hải thủ → mariner (/ˈmærɪnər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
